"""Standalone Google Colab runner for the final fresh-ELCD, protocol-locked LLM-assisted A1-A3 LCA workflow.

The Qwen matching protocol is identical to the selected four-model benchmark
(model/revision, prompt, TF-IDF, candidate presentation, seed, greedy decoding,
Top-5/Top-3, 256 tokens, parser). The ELCD data are regenerated once for the
final production run and hash-frozen in the uploaded payload.

No material-specific GWP factor, density, correction factor, plausible range, or
commercial-LCA target value is embedded in this runner.
"""
from pathlib import Path
import importlib.util

FINAL_RUNNER_VERSION = "16.0-fresh-elcd-protocol-locked"
RUNTIME_SOURCE = '"""Native ipywidgets interface for the full-Colab LLM-LCA workflow.\n\nNo Gradio server/share link is used. The UI renders directly inside Google Colab.\nThe Qwen model is loaded once and reused for repeated BOM and single-material jobs.\n"""\nfrom __future__ import annotations\n\nimport io\nimport json\nimport pathlib\nimport time\nimport traceback\nimport zipfile\nfrom datetime import datetime\nfrom typing import Any\n\nimport pandas as pd\n\nWIDGET_UI_VERSION = "16.0-fresh-elcd-protocol-locked"\n\n\ndef _safe_stem(name: str) -> str:\n    return pathlib.Path(str(name)).stem.replace(" ", "_")\n\n\ndef _uploaded_items(value: Any) -> list[dict[str, Any]]:\n    """Normalize ipywidgets 7/8 FileUpload.value into name/content dicts."""\n    if not value:\n        return []\n    if isinstance(value, dict):\n        rows = []\n        for name, meta in value.items():\n            rec = dict(meta) if isinstance(meta, dict) else {"content": meta}\n            rec.setdefault("name", name)\n            rows.append(rec)\n        return rows\n    return [dict(x) for x in list(value)]\n\n\ndef _bytes_from_upload(rec: dict[str, Any]) -> bytes:\n    content = rec.get("content", b"")\n    if isinstance(content, memoryview):\n        return content.tobytes()\n    if isinstance(content, bytearray):\n        return bytes(content)\n    return content\n\n\ndef _gpu_info() -> tuple[str, str]:\n    try:\n        import torch\n        if not torch.cuda.is_available():\n            return "CPU only", "CUDA unavailable"\n        name = torch.cuda.get_device_name(0)\n        total = torch.cuda.get_device_properties(0).total_memory / 1024**3\n        allocated = torch.cuda.memory_allocated(0) / 1024**3\n        return name, f"CUDA available · {allocated:.1f}/{total:.1f} GB allocated"\n    except Exception as exc:\n        return "Unknown", f"GPU check failed: {exc}"\n\n\nclass NativeColabLCAApp:\n    def __init__(self, work_dir: str | pathlib.Path = "/content/qwen_lca"):\n        import ipywidgets as widgets\n        from IPython.display import display, HTML\n        import torch\n        from qwen_matcher import QwenMatcher, align_formal_case_study_ids\n        from external_ef_resolver import ExternalEFResolver\n        from property_resolver import WebPropertyResolver\n        from colab_calculate import load_factor_snapshot, process_selection_dataframe\n        from material_taxonomy import classify_material, BIOGENIC_STORAGE_EXCLUDED_FAMILIES\n\n        self.widgets = widgets\n        self.display = display\n        self.HTML = HTML\n        self.ExternalEFResolver = ExternalEFResolver\n        self.align_formal_case_study_ids = align_formal_case_study_ids\n        self.WebPropertyResolver = WebPropertyResolver\n        self.process_selection_dataframe = process_selection_dataframe\n        self.classify_material = classify_material\n        self.biogenic_families = set(BIOGENIC_STORAGE_EXCLUDED_FAMILIES)\n\n        self.work = pathlib.Path(work_dir)\n        self.snapshot = load_factor_snapshot(self.work / "process_gwp_snapshot.json")\n        self.session_root = pathlib.Path("/content/LLM_LCA_Results")\n        self.session_root.mkdir(parents=True, exist_ok=True)\n        self.upload_root = pathlib.Path("/content/LLM_LCA_Uploads")\n        self.upload_root.mkdir(parents=True, exist_ok=True)\n        # Generated only from successfully retrieved evidence; the codebase ships\n        # with no material-specific GWP/density cache. Kept outside /content/qwen_lca\n        # so rerunning the launcher in the same Colab runtime can reuse it.\n        self.evidence_cache_path = pathlib.Path("/content/LLM_LCA_Runtime_Evidence_Cache.json")\n        self.processed_log: list[dict[str, Any]] = []\n        self.latest_batch_zip: pathlib.Path | None = None\n        self.latest_files: list[pathlib.Path] = []\n        # BOM files staged through a browser-native HTML <input type="file">.\n        # This avoids both ipywidgets.FileUpload rendering problems and the\n        # google.colab.files.upload() limitation inside widget callbacks.\n        self.pending_uploads: list[pathlib.Path] = []\n\n        if not torch.cuda.is_available():\n            raise RuntimeError(\n                "CUDA is unavailable. In Colab choose Runtime > Change runtime type > T4 GPU, then restart."\n            )\n\n        print("Loading Qwen2.5-7B-Instruct once for this Colab session...")\n        self.matcher = QwenMatcher(\n            self.work / "ELCD_Process_Catalog.xlsx",\n            reference_map_path=self.work / "process_reference_units.json",\n        ).load_model()\n\n        # Retrieval and calculation snapshots intentionally use different semantic\n        # hash schemes, but both are freshly generated from the same active ELCD\n        # database and frozen into one payload. Their UUID universes must be\n        # identical, and the local catalog metadata must match the factor snapshot.\n        local_meta = json.loads(\n            (self.work / "openlca_catalog_metadata.json").read_text(encoding="utf-8")\n        )\n        if str(local_meta.get("catalog_content_sha256")) != str(self.snapshot.get("catalog_content_sha256")):\n            raise RuntimeError("Live catalog/factor snapshot mismatch in payload.")\n        retrieval_uuids = set(self.matcher.by_uuid)\n        factor_uuids = set((self.snapshot.get("factors") or {}).keys())\n        if retrieval_uuids != factor_uuids:\n            missing = sorted(retrieval_uuids - factor_uuids)[:10]\n            extra = sorted(factor_uuids - retrieval_uuids)[:10]\n            raise RuntimeError(\n                "Frozen final ELCD retrieval catalog and factor snapshot do not use "\n                f"the same UUID universe. Missing factors={missing}; extra factors={extra}."\n            )\n        print("Qwen loaded. Building native Colab interface...")\n\n        self._build_ui()\n        self._refresh_system_status()\n\n    def _build_ui(self):\n        w = self.widgets\n        title = w.HTML(\n            "<div style=\'text-align:center\'>"\n            "<h2 style=\'margin-bottom:2px\'>LLM-Assisted A1–A3 Embodied Carbon Screening</h2>"\n            "<div style=\'color:#666\'>Qwen2.5 + frozen ELCD/openLCA snapshot · Native Colab interface</div>"\n            "</div>"\n        )\n        self.system_status = w.HTML()\n        self.stage = w.HTML("<b>Status:</b> Ready")\n        self.file_progress = w.IntProgress(value=0, min=0, max=1, description="BOMs:", bar_style="")\n        self.item_progress = w.IntProgress(value=0, min=0, max=1, description="Items:", bar_style="")\n        self.timer = w.HTML("<b>Elapsed:</b> 0.0 s")\n\n        self.geography = w.Text(value="Nepal", description="Geography:", style={"description_width":"110px"})\n        settings_box = w.VBox([\n            self.geography,\n            w.HTML(\n                "<small><b>Result design:</b> verified subtotal and complete exploratory estimate are reported separately. "\n                "Final hierarchy: Class 1 ELCD Direct → Class 2 ELCD Proxy → Class 3 External Verified → Class 4 Unverified Fallback Estimate. "\n                "Class 3 uses two sequential evidence phases: Phase A first searches strict target-geography/direct-product evidence (up to 60 s), then Phase B starts a fresh clock (up to 120 s) and broadens geography and technically relevant source-supported evidence. Both accepted phases are reported as External Verified while their phase/tier remains auditable. "\n                "GWP is the only environmental impact indicator extracted; structured EPD GWP tables are parsed deterministically by Python first, including direct A1+A2+A3 summation. Explicit GWP-biogenic, GWP-LULUC, and fossil-component rows cannot be substituted for ordinary GWP-total, and Qwen is used only when the deterministic route cannot validate the source. "\n                "Class 4 is used only after ELCD and both External Verified phases fail. It first re-searches the frozen ELCD/openLCA catalog using dynamically generated same-family technical terminology, then a dynamically inferred nearby semantic analog if needed. Only if both database-anchored routes fail may one terminal model-only value be retained. Class 4 is excluded from the verified subtotal. No material-specific GWP/property value, density, correction factor, or plausible range is encoded.<br>"\n                "<b>Uncertainty:</b> GSD is assigned automatically from source uncertainty, accepted-source dispersion, or a documented pedigree method. "\n                "Monte Carlo runs are selected automatically by convergence using a fixed reproducible seed.<br>"\n                "<b>Biogenic policy:</b> timber, plywood, and bamboo exclude carbon-storage/sequestration credits.</small>"\n            ),\n        ])\n        settings = w.VBox([\n            w.HTML("<h3 style=\'margin:12px 0 4px 0\'>Assessment settings</h3>"),\n            settings_box,\n        ], layout=w.Layout(border="1px solid #666", padding="10px", margin="6px 0"))\n\n        # BOM upload: browser-native HTML file input + Colab kernel callback.\n        # IMPORTANT: google.colab.files.upload() cannot reliably open its chooser\n        # when called from an ipywidgets Button callback. A real HTML file input\n        # is therefore used and file bytes are sent to Python through\n        # google.colab.kernel.invokeFunction().\n        self.upload_html = w.Output(layout=w.Layout(width="100%"))\n        self.process_bom_btn = w.Button(\n            description="PROCESS SELECTED BOM(S)",\n            button_style="primary",\n            icon="play",\n            layout=w.Layout(width="300px", height="44px"),\n        )\n        self.clear_upload_btn = w.Button(description="Clear selected files", icon="trash")\n        self.selected_files = w.HTML(\n            "<div style=\'padding:8px;border:1px dashed #bbb;border-radius:6px\'>"\n            "<b>Selected BOMs:</b> None</div>"\n        )\n        self.process_bom_btn.on_click(self._on_process_boms)\n        self.clear_upload_btn.on_click(self._on_clear_uploads)\n\n        # Register browser -> Python file-transfer callback before rendering HTML.\n        try:\n            from google.colab import output as colab_output\n            self._upload_callback_name = "llm_lca.upload_boms"\n            colab_output.register_callback(self._upload_callback_name, self._receive_browser_upload)\n        except Exception as exc:\n            raise RuntimeError(f"Could not register Colab upload callback: {exc}") from exc\n\n        upload_markup = r"""\n<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:2px 0 6px 0;">\n  <input id="llm-lca-bom-file-input" type="file"\n         accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"\n         multiple style="display:none;" />\n  <button id="llm-lca-bom-upload-button" type="button"\n          style="background:#36b85c;color:white;border:0;border-radius:4px;padding:12px 20px;\n                 font-size:14px;font-weight:600;cursor:pointer;min-width:300px;height:44px;">\n    ⬆ CHOOSE / UPLOAD EXCEL BOM(S)\n  </button>\n  <span id="llm-lca-bom-browser-status" style="font-size:13px;">No browser files selected.</span>\n</div>\n<script>\n(function(){\n  const input = document.getElementById(\'llm-lca-bom-file-input\');\n  const button = document.getElementById(\'llm-lca-bom-upload-button\');\n  const status = document.getElementById(\'llm-lca-bom-browser-status\');\n  if (!input || !button || !status) return;\n\n  button.onclick = function(){\n    input.click();\n  };\n\n  function toBase64(file) {\n    return new Promise((resolve, reject) => {\n      const reader = new FileReader();\n      reader.onload = () => {\n        const result = String(reader.result || \'\');\n        const comma = result.indexOf(\',\');\n        resolve(comma >= 0 ? result.slice(comma + 1) : result);\n      };\n      reader.onerror = reject;\n      reader.readAsDataURL(file);\n    });\n  }\n\n  input.onchange = async function(){\n    const selected = Array.from(input.files || []);\n    if (!selected.length) {\n      status.textContent = \'No files selected.\';\n      return;\n    }\n    const bad = selected.filter(f => !f.name.toLowerCase().endsWith(\'.xlsx\'));\n    if (bad.length) {\n      status.textContent = \'Only .xlsx files are accepted.\';\n      input.value = \'\';\n      return;\n    }\n    button.disabled = true;\n    button.style.opacity = \'0.65\';\n    status.textContent = \'Uploading \' + selected.length + \' file(s) to the Colab runtime...\';\n    try {\n      const payload = [];\n      for (const f of selected) {\n        payload.push({name: f.name, data: await toBase64(f), size: f.size});\n      }\n      const result = await google.colab.kernel.invokeFunction(\n        \'llm_lca.upload_boms\', [payload], {}\n      );\n      let message = selected.length + \' file(s) uploaded to Colab.\';\n      try {\n        const j = result.data[\'application/json\'];\n        if (j && j.message) message = j.message;\n      } catch (e) {}\n      status.textContent = message + \' Now click PROCESS SELECTED BOM(S).\';\n    } catch (err) {\n      console.error(err);\n      status.textContent = \'Upload failed: \' + (err && err.message ? err.message : String(err));\n    } finally {\n      button.disabled = false;\n      button.style.opacity = \'1\';\n      input.value = \'\';\n    }\n  };\n})();\n</script>\n"""\n        with self.upload_html:\n            self.display(self.HTML(upload_markup))\n\n        bom_tab = w.VBox([\n            w.HTML(\n                "<b>Step 1:</b> Click the green browser upload control and select one or more Excel BOMs.<br>"\n                "<b>Step 2:</b> Confirm the filenames below, then click PROCESS SELECTED BOM(S).<br>"\n                "<b>Required columns:</b> Material, Quantity, Unit. <b>Recommended:</b> ID."\n            ),\n            self.upload_html,\n            self.process_bom_btn,\n            self.selected_files,\n            self.clear_upload_btn,\n        ])\n\n        # Single material tab\n        self.item_id = w.Text(value="SINGLE-001", description="ID:")\n        self.material = w.Text(placeholder="e.g., Portland cement 43 grade", description="Material:", layout=w.Layout(width="600px"))\n        self.quantity = w.FloatText(value=0.0, description="Quantity:")\n        self.unit = w.Text(placeholder="kg, m3, m2, Nos.", description="Unit:")\n        self.density = w.FloatText(value=0.0, description="Density kg/m³:")\n        self.thickness = w.FloatText(value=0.0, description="Thickness mm:")\n        self.item_mass = w.FloatText(value=0.0, description="Mass/item kg:")\n        self.conv_factor = w.FloatText(value=0.0, description="Conv. factor:")\n        self.notes = w.Textarea(description="Notes:", layout=w.Layout(width="800px", height="70px"))\n        self.process_single_btn = w.Button(description="Calculate material", button_style="primary", icon="calculator")\n        self.process_single_btn.on_click(self._on_process_single)\n        single_tab = w.VBox([\n            w.HBox([self.item_id, self.material]),\n            w.HBox([self.quantity, self.unit]),\n            w.HBox([self.density, self.thickness]),\n            w.HBox([self.item_mass, self.conv_factor]),\n            self.notes,\n            self.process_single_btn,\n        ])\n\n        bom_section = w.VBox([\n            w.HTML("<h3 style=\\\'margin:12px 0 4px 0\\\'>1. Upload BOM Excel</h3>"),\n            bom_tab,\n        ], layout=w.Layout(border="2px solid #3a9d5d", padding="12px", margin="8px 0"))\n\n        single_section = w.VBox([\n            w.HTML("<h3 style=\\\'margin:12px 0 4px 0\\\'>2. Single Material</h3>"),\n            single_tab,\n        ], layout=w.Layout(border="1px solid #666", padding="12px", margin="8px 0"))\n\n        self.download_batch_btn = w.Button(description="Download latest batch ZIP", button_style="success", icon="download", disabled=True)\n        self.download_batch_btn.on_click(self._on_download_batch)\n        self.result_summary = w.HTML("<b>Results:</b> Nothing processed yet.")\n        self.history = w.HTML("<b>Session history:</b> None")\n        self.log = w.Output(layout=w.Layout(border="1px solid #ddd", max_height="260px", overflow_y="auto"))\n        self.chart_out = w.Output()\n\n        status_box = w.VBox([\n            self.system_status,\n            self.stage,\n            w.HBox([self.file_progress, self.item_progress, self.timer]),\n        ])\n        results_box = w.VBox([\n            self.result_summary,\n            self.download_batch_btn,\n            self.history,\n            w.HTML("<b>Latest contribution chart</b>"),\n            self.chart_out,\n            w.HTML("<b>Processing log</b>"),\n            self.log,\n        ])\n\n        self.root = w.VBox([\n            title,\n            status_box,\n            settings,\n            bom_section,\n            single_section,\n            results_box,\n        ], layout=w.Layout(width="100%"))\n\n    def show(self):\n        self.display(self.root)\n        return self\n\n    def _refresh_system_status(self):\n        gpu, cuda = _gpu_info()\n        count = len(self.snapshot.get("factors", {})) if isinstance(self.snapshot.get("factors"), dict) else self.snapshot.get("process_count", "?")\n        self.system_status.value = (\n            "<div style=\'padding:8px;border:1px solid #ddd;border-radius:6px\'>"\n            f"<b>Runtime:</b> Google Colab &nbsp; | &nbsp; <b>GPU:</b> {gpu} &nbsp; | &nbsp; "\n            f"<b>CUDA:</b> {cuda} &nbsp; | &nbsp; <b>Qwen:</b> Loaded ✓ &nbsp; | &nbsp; "\n            f"<b>Protocol lock:</b> Four-model Qwen settings ✓ &nbsp; | &nbsp; <b>ELCD lock:</b> Final catalog frozen ✓ &nbsp; | &nbsp; "\n            f"<b>Factor snapshot:</b> Loaded ✓ &nbsp; | &nbsp; <b>Processes:</b> {count}"\n            "</div>"\n        )\n\n    def _set_stage(self, text: str):\n        self.stage.value = f"<b>Status:</b> {text}"\n        self._refresh_system_status()\n\n    def _log(self, text: str):\n        stamp = datetime.now().strftime("%H:%M:%S")\n        with self.log:\n            print(f"[{stamp}] {text}")\n\n    def _set_busy(self, busy: bool):\n        self.process_bom_btn.disabled = busy\n        self.process_single_btn.disabled = busy\n        self.clear_upload_btn.disabled = busy\n\n    @staticmethod\n    def _display_upload_name(path: pathlib.Path) -> str:\n        # Stored names are YYYYMMDD_HHMMSS_microseconds_original.xlsx.\n        parts = path.name.split("_", 3)\n        return parts[3] if len(parts) == 4 else path.name\n\n    def _refresh_selected_files(self):\n        if not self.pending_uploads:\n            self.selected_files.value = (\n                "<div style=\'padding:8px;border:1px dashed #bbb;border-radius:6px\'>"\n                "<b>Selected BOMs:</b> None</div>"\n            )\n            return\n        names = [self._display_upload_name(p) for p in self.pending_uploads]\n        lines = "<br>".join(f"✅ {name}" for name in names)\n        self.selected_files.value = (\n            "<div style=\'padding:8px;border:1px solid #9ccc9c;border-radius:6px\'>"\n            f"<b>Selected BOMs ({len(names)}):</b><br>{lines}</div>"\n        )\n\n    def _receive_browser_upload(self, payload):\n        """Receive .xlsx bytes sent by the browser-native Colab file input."""\n        import base64\n\n        if not isinstance(payload, list):\n            raise ValueError("Upload payload must be a list of files.")\n        accepted = 0\n        skipped = []\n        for rec in payload:\n            if not isinstance(rec, dict):\n                continue\n            safe_name = pathlib.Path(str(rec.get("name", ""))).name\n            if not safe_name.lower().endswith(".xlsx"):\n                skipped.append(safe_name or "unnamed file")\n                continue\n            encoded = rec.get("data") or ""\n            try:\n                content = base64.b64decode(encoded, validate=True)\n            except Exception as exc:\n                raise ValueError(f"Could not decode {safe_name}: {exc}") from exc\n            if not content:\n                raise ValueError(f"Uploaded file is empty: {safe_name}")\n            stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")\n            target = self.upload_root / f"{stamp}_{safe_name}"\n            target.write_bytes(content)\n            self.pending_uploads.append(target)\n            accepted += 1\n            self._log(f"Staged BOM in Colab runtime: {safe_name}")\n\n        self._refresh_selected_files()\n        if accepted:\n            msg = f"{accepted} BOM file(s) uploaded and ready"\n            self._set_stage(msg + " — click PROCESS SELECTED BOM(S)")\n        else:\n            msg = "No valid .xlsx BOM files were uploaded"\n            self._set_stage(msg)\n        if skipped:\n            self._log("Skipped non-XLSX files: " + ", ".join(skipped))\n        return {"accepted": accepted, "skipped": skipped, "message": msg}\n\n    def _on_clear_uploads(self, _=None):\n        self.pending_uploads.clear()\n        self._refresh_selected_files()\n        self._set_stage("Ready — selected BOM list cleared")\n\n    def _save_uploads(self) -> list[pathlib.Path]:\n        # Files are already staged by the browser-native HTML uploader.\n        return [p for p in self.pending_uploads if p.exists() and p.suffix.lower() == ".xlsx"]\n\n    def _match_with_progress(self, df: pd.DataFrame) -> pd.DataFrame:\n        from dataclasses import asdict\n        required = {"Material", "Quantity", "Unit"}\n        missing = sorted(required - set(df.columns))\n        if missing:\n            raise ValueError(f"BOM is missing required columns: {missing}")\n        rows = []\n        records = df.to_dict(orient="records")\n        self.item_progress.max = max(1, len(records))\n        self.item_progress.value = 0\n        for i, rec in enumerate(records, start=1):\n            if not str(rec.get("ID", "")).strip() or str(rec.get("ID")).lower() == "nan":\n                rec["ID"] = f"ITEM-{i:03d}"\n            self._set_stage(f"Qwen process selection · item {i}/{len(records)} · {rec.get(\'Material\',\'\')}")\n            rows.append(asdict(self.matcher.match_item(rec)))\n            self.item_progress.value = i\n        return pd.DataFrame(rows)\n\n    def _apply_biogenic_reporting_policy(self, batch: pd.DataFrame) -> pd.DataFrame:\n        """Route bio-based rows away from ELCD GWP-total when storage may be included.\n\n        The frozen openLCA snapshot uses the selected LCIA category and may include\n        biogenic carbon uptake/storage. For the manuscript\'s harmonized screening\n        comparison we exclude that storage credit for timber, plywood, and bamboo.\n        These rows therefore proceed to the same live external-evidence resolver as\n        rows that leave ELCD matching without an approved database factor. No material-specific factor or source is encoded;\n        an accepted source must explicitly support positive A1-A3 GWP-GHG (preferred)\n        or GWP-fossil. Raw Qwen/openLCA selections remain in the audit columns.\n        """\n        out = batch.copy()\n        families = []\n        overridden = []\n        reasons = []\n        for idx, rec in out.iterrows():\n            material = rec.get("normalized_material") or rec.get("original_material") or ""\n            family = self.classify_material(material)\n            families.append(family)\n            is_bio = family in self.biogenic_families\n            overridden.append(bool(is_bio))\n            if not is_bio:\n                reasons.append(None)\n                continue\n            reasons.append(\n                "Biogenic carbon storage/sequestration excluded from screening; "\n                "use positive A1-A3 GWP-GHG (or GWP-fossil if explicitly documented) "\n                "instead of an ELCD/openLCA GWP-total value."\n            )\n            if bool(rec.get("structured_output_valid", False)):\n                # Preserve Qwen\'s Direct/Proxy/Review Required classification and\n                # selected UUID. This is a reporting/factor-use policy only: the\n                # ELCD GWP-total factor is bypassed so storage/sequestration credit\n                # is not included in the harmonized bio-based result.\n                out.at[idx, "production_approved"] = False\n        out["material_family_final"] = families\n        out["biogenic_reporting_override"] = overridden\n        out["biogenic_reporting_policy"] = reasons\n        return out\n\n    def _resolve_and_calculate(self, df: pd.DataFrame, base_name: str) -> dict[str, Any]:\n        df, id_alignment = self.align_formal_case_study_ids(df, base_name)\n        if id_alignment.get("prefix"):\n            self._log(\n                "Benchmark ID alignment · "\n                f"prefix {id_alignment[\'prefix\']} · "\n                f"aligned {id_alignment[\'aligned\']}/{len(df)} row(s) · "\n                f"changed {id_alignment[\'changed\']} ID(s)"\n            )\n        self._set_stage("Qwen material normalization and process selection")\n        batch = self._match_with_progress(df)\n        batch = self._apply_biogenic_reporting_policy(batch)\n        bio_count = int(batch.get("biogenic_reporting_override", pd.Series(dtype=bool)).fillna(False).astype(bool).sum())\n        if bio_count:\n            self._log(\n                f"Biogenic reporting policy applied to {bio_count} row(s): "\n                "storage/sequestration credit excluded; positive GWP-GHG/GWP-fossil evidence is sought first, with any terminal model-only estimate isolated if source-supported pathways fail."\n            )\n\n        self._set_stage("Resolving Review Required emission factors")\n        ef_resolver = self.ExternalEFResolver(\n            self.matcher,\n            factor_snapshot=self.snapshot,\n            target_geography=self.geography.value.strip() or "Nepal",\n            allow_source_supported_provisional=True,\n            allow_llm_unverified_estimate=True,\n            allow_conservative_analog_estimate=True,\n            class3_source_budget=3,\n            class4_total_source_budget=10,\n            max_search_queries_per_material=6,\n            adaptive_max_search_queries_per_material=12,\n            adaptive_total_source_budget=10,\n            timeout=8,\n            max_external_seconds_per_material=60.0,\n            adaptive_external_seconds_per_material=120.0,\n            progress_callback=self._log,\n            evidence_cache_path=str(self.evidence_cache_path),\n        )\n        batch, ef_evidence = ef_resolver.resolve_batch(batch)\n\n        self._set_stage("Checking and resolving only required conversion properties")\n        prop_resolver = self.WebPropertyResolver(\n            self.matcher,\n            target_geography=self.geography.value.strip() or "Nepal",\n            allow_source_supported_provisional=True,\n            allow_llm_unverified_estimate=True,\n            allow_conservative_analog_estimate=True,\n            class3_source_budget=3,\n            class4_total_source_budget=10,\n            max_search_queries_per_property=5,\n            adaptive_max_search_queries_per_property=10,\n            adaptive_total_source_budget=9,\n            timeout=8,\n            max_external_seconds_per_property=60.0,\n            adaptive_external_seconds_per_property=120.0,\n            progress_callback=self._log,\n            evidence_cache_path=str(self.evidence_cache_path),\n        )\n        batch, prop_evidence = prop_resolver.resolve_batch(batch)\n        if "property_lookup_needed" in batch.columns:\n            needed = int(batch["property_lookup_needed"].fillna(False).astype(bool).sum())\n            self._log(f"Conversion-property lookup needed for {needed}/{len(batch)} row(s); direct/unit-only conversions skipped property searching for {len(batch)-needed} row(s).")\n\n        self._set_stage("Calculating A1–A3 GWP and uncertainty")\n        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n        outdir = self.session_root / f"{base_name}_{stamp}"\n        result = self.process_selection_dataframe(\n            batch,\n            self.snapshot,\n            outdir,\n            base_name,\n            property_evidence=prop_evidence,\n            external_evidence=ef_evidence,\n        )\n        return result\n\n    def _summary_dict(self, result: dict[str, Any]) -> dict[str, Any]:\n        return result["summary"].set_index("metric")["value"].to_dict()\n\n    def _primary_gwp(self, summary: dict[str, Any]) -> tuple[float, float, bool]:\n        verified = float(summary.get("Verified A1-A3 GWP subtotal (classes 1-3)", 0) or 0)\n        complete_key = "Complete exploratory GWP estimate (classes 1-4)"\n        partial_key = "Calculated exploratory subtotal (input/model failures remain)"\n        if complete_key in summary:\n            return verified, float(summary.get(complete_key, 0) or 0), True\n        if partial_key in summary:\n            return verified, float(summary.get(partial_key, 0) or 0), False\n        return verified, 0.0, False\n\n    def _make_batch_zip(self, result_files: list[pathlib.Path]) -> pathlib.Path:\n        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n        target = self.session_root / f"LLM_LCA_Batch_Results_{stamp}.zip"\n        with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED) as z:\n            for p in result_files:\n                if p and pathlib.Path(p).exists():\n                    z.write(p, arcname=pathlib.Path(p).name)\n        return target\n\n    def _show_chart(self, png: pathlib.Path | str | None):\n        from IPython.display import Image, display, clear_output\n        with self.chart_out:\n            clear_output(wait=True)\n            if png and pathlib.Path(png).exists():\n                display(Image(filename=str(png)))\n            else:\n                print("No chart generated.")\n\n    def _update_history(self):\n        if not self.processed_log:\n            self.history.value = "<b>Session history:</b> None"\n            return\n        df = pd.DataFrame(self.processed_log)\n        self.history.value = "<b>Session history</b>" + df.to_html(index=False, border=0)\n\n    def _on_process_boms(self, _=None):\n        paths = self._save_uploads()\n        if not paths:\n            self._set_stage("No Excel BOM selected — click UPLOAD EXCEL BOM(S) first")\n            self._log("Click the green UPLOAD EXCEL BOM(S) button, choose at least one .xlsx file, then process.")\n            return\n        self._set_busy(True)\n        self.file_progress.max = max(1, len(paths))\n        self.file_progress.value = 0\n        started = time.time()\n        generated: list[pathlib.Path] = []\n        messages = []\n        last_png = None\n        try:\n            for idx, path in enumerate(paths, start=1):\n                bom_start = time.time()\n                self._log(f"Starting {path.name} ({idx}/{len(paths)})")\n                try:\n                    bom = pd.read_excel(path)\n                    result = self._resolve_and_calculate(bom, _safe_stem(path.name))\n                    s = self._summary_dict(result)\n                    files = [pathlib.Path(result[k]) for k in ("xlsx", "verified_png", "complete_png", "raw_mc", "zip") if result.get(k)]\n                    generated.extend(files)\n                    last_png = result.get("complete_png")\n                    verified_gwp, exploratory_gwp, screening_complete = self._primary_gwp(s)\n                    review_rows = int(float(s.get("Input/model failure rows", 0)))\n                    self.processed_log.append({\n                        "Input": path.name,\n                        "Verified GWP": round(verified_gwp, 3),\n                        "Exploratory GWP": round(exploratory_gwp, 3),\n                        "Exploratory status": "complete" if screening_complete else "subtotal — input/model failures remain",\n                        "Input/model failure rows": review_rows,\n                        "Workbook": pathlib.Path(result["xlsx"]).name,\n                    })\n                    status_text = "complete" if screening_complete else "SUBTOTAL — input/model failures remain"\n                    messages.append(\n                        f"✅ {path.name}: verified {verified_gwp:,.3f}; complete exploratory {exploratory_gwp:,.3f} "\n                        f"{self.snapshot.get(\'impact_category_ref_unit\') or \'kg CO₂e\'} · {status_text} · input/model failures {review_rows}"\n                    )\n                    self._log(f"Finished {path.name} in {time.time()-bom_start:.1f}s")\n                except Exception as exc:\n                    messages.append(f"❌ {path.name}: {exc}")\n                    self._log(f"ERROR in {path.name}: {exc}")\n                    with self.log:\n                        traceback.print_exc(limit=8)\n                self.file_progress.value = idx\n                self.timer.value = f"<b>Elapsed:</b> {time.time()-started:.1f} s"\n\n            if generated:\n                self.latest_files = generated\n                self.latest_batch_zip = self._make_batch_zip(generated)\n                self.download_batch_btn.disabled = False\n            self.result_summary.value = "<b>Latest batch</b><br>" + "<br>".join(messages)\n            self._update_history()\n            self._show_chart(last_png)\n            self._set_stage("Finished. Select another BOM and process again — no model reload required.")\n            self._on_clear_uploads()\n        finally:\n            self.timer.value = f"<b>Elapsed:</b> {time.time()-started:.1f} s"\n            self._set_busy(False)\n            self._refresh_system_status()\n\n    def _optional_number(self, widget):\n        try:\n            v = float(widget.value)\n            return None if v == 0 else v\n        except Exception:\n            return None\n\n    def _on_process_single(self, _=None):\n        material = self.material.value.strip()\n        unit = self.unit.value.strip()\n        if not material or not unit or float(self.quantity.value) == 0:\n            self._set_stage("Single material requires material, non-zero quantity, and unit")\n            return\n        df = pd.DataFrame([{\n            "ID": self.item_id.value.strip() or "SINGLE-001",\n            "Material": material,\n            "Quantity": float(self.quantity.value),\n            "Unit": unit,\n            "Density_kg_m3": self._optional_number(self.density),\n            "Thickness_mm": self._optional_number(self.thickness),\n            "Mass_per_item_kg": self._optional_number(self.item_mass),\n            "Conversion_factor_to_ref_unit": self._optional_number(self.conv_factor),\n            "Notes": self.notes.value,\n        }])\n        self._set_busy(True)\n        started = time.time()\n        try:\n            result = self._resolve_and_calculate(df, "Single_" + _safe_stem(material[:50]))\n            s = self._summary_dict(result)\n            verified_gwp, exploratory_gwp, screening_complete = self._primary_gwp(s)\n            review_rows = int(float(s.get("Input/model failure rows", 0)))\n            files = [pathlib.Path(result[k]) for k in ("xlsx", "verified_png", "complete_png", "raw_mc", "zip") if result.get(k)]\n            self.latest_files = files\n            self.latest_batch_zip = self._make_batch_zip(files)\n            self.download_batch_btn.disabled = False\n            self.processed_log.append({\n                "Input": f"Single: {material}",\n                "Verified GWP": round(verified_gwp, 3),\n                "Exploratory GWP": round(exploratory_gwp, 3),\n                "Exploratory status": "complete" if screening_complete else "subtotal — input/model failures remain",\n                "Input/model failure rows": review_rows,\n                "Workbook": pathlib.Path(result["xlsx"]).name,\n            })\n            status_text = "complete" if screening_complete else "SUBTOTAL — input/model failures remain"\n            self.result_summary.value = (\n                f"<b>Latest result:</b> {material} · verified {verified_gwp:,.3f}; complete exploratory {exploratory_gwp:,.3f} "\n                f"{self.snapshot.get(\'impact_category_ref_unit\') or \'kg CO₂e\'} · {status_text} · Input/model failures: {review_rows}"\n            )\n            self._update_history()\n            self._show_chart(result.get("complete_png"))\n            self._log(f"Finished single material: {material}")\n            self._set_stage("Finished. Enter another material or switch to BOM upload.")\n        except Exception as exc:\n            self._log(f"ERROR: {exc}")\n            with self.log:\n                traceback.print_exc(limit=8)\n            self._set_stage(f"Error: {exc}")\n        finally:\n            self.timer.value = f"<b>Elapsed:</b> {time.time()-started:.1f} s"\n            self._set_busy(False)\n            self._refresh_system_status()\n\n    def _on_download_batch(self, _=None):\n        if not self.latest_batch_zip or not self.latest_batch_zip.exists():\n            self._log("No result ZIP is available yet.")\n            return\n        try:\n            from google.colab import files\n            self._log(f"Starting download: {self.latest_batch_zip.name}")\n            files.download(str(self.latest_batch_zip))\n        except Exception as exc:\n            self._log(f"Download failed: {exc}")\n\n\ndef launch_native_widgets(work_dir: str | pathlib.Path = "/content/qwen_lca"):\n    """Load Qwen once and render the persistent notebook-native UI."""\n    app = NativeColabLCAApp(work_dir)\n    return app.show()\n'
LAUNCHER_SOURCE = '"""Google Colab launcher for the native-widget LLM-LCA interface."""\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport pathlib\nimport shutil\nimport subprocess\nimport sys\nimport zipfile\nfrom typing import Mapping\n\nWORKFLOW_ID = "llm-assisted-a1-a3-embodied-carbon-screening"\n\n\ndef sha256_file(path: pathlib.Path) -> str:\n    h = hashlib.sha256()\n    with path.open("rb") as f:\n        for chunk in iter(lambda: f.read(1024 * 1024), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef _install_dependencies():\n    packages = [\n        # Exact core package versions recorded by the frozen Qwen benchmark run.\n        "transformers==4.57.6", "accelerate==1.14.0", "bitsandbytes==0.50.1",\n        "safetensors>=0.4", "huggingface_hub>=0.24", "sentencepiece>=0.2",\n        "pandas==2.2.3", "openpyxl==3.1.5", "xlsxwriter>=3.2,<4",\n        "scikit-learn==1.6.1", "numpy>=1.26,<3", "matplotlib>=3.8,<4",\n        "ipywidgets>=8,<9", "ddgs>=9.14,<10", "requests>=2.31,<3",\n        "pypdf>=5,<7", "pdfplumber>=0.11,<1", "pillow>=10,<12",\n    ]\n    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", *packages])\n\n\n\ndef _check_benchmark_runtime():\n    """Fail closed when the Colab inference runtime drifts from the benchmark.\n\n    These are the values recorded in the selected Qwen benchmark workbook. The\n    exact CUDA/PyTorch/GPU check is intentionally strict because this production\n    package is intended to reproduce that frozen model-selection protocol.\n    """\n    import importlib.metadata as im\n    import torch\n\n    expected_packages = {\n        "transformers": "4.57.6",\n        "accelerate": "1.14.0",\n        "bitsandbytes": "0.50.1",\n        "pandas": "2.2.3",\n        "scikit-learn": "1.6.1",\n        "openpyxl": "3.1.5",\n    }\n    problems = []\n    for name, expected in expected_packages.items():\n        try:\n            actual = im.version(name)\n        except Exception:\n            actual = "missing"\n        if actual != expected:\n            problems.append(f"{name}={actual} (benchmark {expected})")\n\n    torch_version = str(torch.__version__)\n    cuda_version = str(torch.version.cuda or "")\n    gpu_name = torch.cuda.get_device_name(0) if torch.cuda.is_available() else "No CUDA GPU"\n    if torch_version != "2.11.0+cu128":\n        problems.append(f"torch={torch_version} (benchmark 2.11.0+cu128)")\n    if cuda_version != "12.8":\n        problems.append(f"CUDA={cuda_version} (benchmark 12.8)")\n    if gpu_name != "Tesla T4":\n        problems.append(f"GPU={gpu_name} (benchmark Tesla T4)")\n\n    if problems and os.getenv("LCA_ALLOW_RUNTIME_DRIFT", "0") != "1":\n        raise RuntimeError(\n            "Benchmark-runtime drift detected. For the strongest 35-row reproducibility, "\n            "use the same Colab T4 runtime used by the benchmark. Differences:\\n - "\n            + "\\n - ".join(problems)\n            + "\\nSet LCA_ALLOW_RUNTIME_DRIFT=1 only if you deliberately accept runtime drift."\n        )\n    if problems:\n        print("Benchmark runtime: DRIFT ALLOWED — " + "; ".join(problems))\n    else:\n        print("Benchmark runtime: PASS (T4/CUDA/PyTorch/core packages match frozen Qwen run).")\n\n\ndef prepare_payload(\n    payload_path: str | pathlib.Path,\n    runtime_source: str | pathlib.Path | None = None,\n    embedded_sources: Mapping[str, str] | None = None,\n):\n    """Extract a frozen-data payload and optionally inject current code modules.\n\n    Embedded source overrides are code only. The frozen ELCD/openLCA catalog,\n    reference-unit map and GWP snapshot are still taken from the uploaded payload\n    and remain hash-verified against its manifest. This allows a standalone Colab\n    runner to update calculation logic without embedding any material-specific\n    environmental factors or densities in the runner itself.\n    """\n    payload_path = pathlib.Path(payload_path)\n    work = pathlib.Path("/content/qwen_lca")\n    if work.exists():\n        shutil.rmtree(work)\n    work.mkdir(parents=True)\n    with zipfile.ZipFile(payload_path) as z:\n        z.extractall(work)\n\n    required_core = {\n        "ELCD_Process_Catalog.xlsx", "ELCD_Catalog_Lock.json",\n        "openlca_catalog.json", "openlca_catalog_metadata.json",\n        "process_reference_units.json", "process_gwp_snapshot.json",\n        "process_gwp_snapshot_metadata.json", "qwen_matcher.py", "catalog_lock.py",\n        "external_ef_resolver.py", "property_resolver.py", "unit_conversion.py",\n        "material_taxonomy.py", "technical_equivalence.py", "uncertainty.py",\n        "guardrails.py", "evidence_consensus.py", "semantic_analog.py",\n        "evidence_cache.py", "colab_calculate.py", "colab_gui_runtime.py",\n        "payload_manifest.json",\n    }\n    missing = sorted(x for x in required_core if not (work / x).exists())\n    if missing:\n        raise RuntimeError("Incomplete payload. Missing: " + ", ".join(missing))\n\n    manifest = json.loads((work / "payload_manifest.json").read_text(encoding="utf-8"))\n    if manifest.get("workflow_id") != WORKFLOW_ID:\n        raise RuntimeError("The uploaded payload was not generated by this workflow.")\n\n    injected_names = set(embedded_sources or {})\n    if runtime_source:\n        injected_names.add("colab_gui_runtime.py")\n\n    # Hash-check all frozen data and every payload code file that is NOT being\n    # intentionally replaced by this standalone runner. The data hashes are never\n    # skipped, so embedded code cannot silently alter the ELCD snapshot.\n    problems = []\n    for group in ("files_sha256", "payload_data_sha256"):\n        for fname, expected in (manifest.get(group) or {}).items():\n            if group == "files_sha256" and fname in injected_names:\n                continue\n            p = work / fname\n            if not p.exists():\n                problems.append(f"missing {fname}")\n            elif sha256_file(p) != expected:\n                problems.append(f"SHA256 mismatch: {fname}")\n    if problems:\n        raise RuntimeError("Payload verification failed:\\n - " + "\\n - ".join(problems))\n\n    if embedded_sources:\n        for fname, source in embedded_sources.items():\n            safe = pathlib.Path(fname)\n            if safe.name != fname or safe.suffix != ".py" or fname not in required_core:\n                raise RuntimeError(f"Unsafe or unsupported embedded module name: {fname}")\n            (work / fname).write_text(str(source), encoding="utf-8")\n\n    if runtime_source:\n        shutil.copy2(runtime_source, work / "colab_gui_runtime.py")\n    return work, manifest\n\n\ndef main(\n    runtime_source: str | pathlib.Path | None = None,\n    embedded_sources: Mapping[str, str] | None = None,\n):\n    try:\n        from google.colab import files, output\n    except Exception as exc:\n        raise RuntimeError("This launcher is intended for Google Colab.") from exc\n\n    output.enable_custom_widget_manager()\n    print(\n        "Upload your Qwen_Colab_Payload.zip. Frozen ELCD/openLCA data come from "\n        "that payload; this runner can inject the current production Python code."\n    )\n    uploaded = files.upload()\n    if len(uploaded) != 1:\n        raise RuntimeError("Upload exactly one Qwen_Colab_Payload.zip file.")\n    name = next(iter(uploaded))\n    if not name.lower().endswith(".zip"):\n        raise RuntimeError("Expected a .zip payload.")\n\n    print("Installing/confirming benchmark-locked Colab dependencies (no Gradio)...")\n    _install_dependencies()\n    _check_benchmark_runtime()\n\n    if runtime_source is None:\n        here = pathlib.Path(__file__).resolve().parent if "__file__" in globals() else pathlib.Path("/content")\n        candidate = here / "colab_gui_runtime.py"\n        if not candidate.exists():\n            candidate = pathlib.Path("/content/colab_gui_runtime.py")\n        runtime_source = candidate if candidate.exists() else None\n\n    work, manifest = prepare_payload(\n        pathlib.Path("/content") / name,\n        runtime_source,\n        embedded_sources=embedded_sources,\n    )\n    os.chdir(work)\n    if str(work) not in sys.path:\n        sys.path.insert(0, str(work))\n\n    print(\n        "Payload data verification: PASS; "\n        f"model={manifest.get(\'model_id\', \'Qwen\')}, "\n        f"revision={manifest.get(\'model_revision\', \'unknown\')}."\n    )\n    if embedded_sources:\n        print("Embedded production-code override: PASS (no embedded material-specific GWP/density data).")\n    from colab_gui_runtime import launch_native_widgets\n    return launch_native_widgets(work)\n\n\nif __name__ == "__main__":\n    main()\n'
EMBEDDED_SOURCES = {'colab_calculate.py': '"""Frozen-snapshot A1-A3 GWP calculation and publication-ready reporting.\n\nFour publication-facing evidence classes are used:\n1. ELCD Direct\n2. ELCD Proxy\n3. External Verified\n4. Unverified Fallback Estimate\n\nExternal Verified contains two sequential retrieval phases: a strict Nepal/direct-\nproduct phase followed, when needed, by a fresh-clock relaxed-geography/source-\nsupported phase. Both phases remain auditable but are reported under Class 3.\nThe verified subtotal contains Classes 1-3; the complete exploratory estimate\ncontains Classes 1-4. Rows that cannot produce a structurally usable value remain\ninput/model failures and are never silently treated as zero.\n"""\nfrom __future__ import annotations\n\nimport gzip\nimport hashlib\nimport json\nimport re\nimport zipfile\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\n\nfrom unit_conversion import convert_quantity\nfrom material_taxonomy import classify_material, BIOGENIC_STORAGE_EXCLUDED_FAMILIES, choose_resolution_material\nfrom uncertainty import (\n    UNCERTAINTY_METHOD_VERSION,\n    MONTE_CARLO_SEED,\n    MONTE_CARLO_SCHEDULE,\n    MONTE_CARLO_MIN_FINAL_RUNS,\n    MONTE_CARLO_CONVERGENCE_TOLERANCE,\n    enrich_row_uncertainty,\n    monte_carlo_with_convergence,\n)\n\nCOLAB_CALCULATOR_VERSION = "7.0-four-class-external-verified-merged"\nCHART_OTHER_THRESHOLD_PCT = 0.1\n\n\ndef _norm(v: Any) -> str:\n    return "" if v is None else str(v).strip().lower()\n\n\ndef _number(v: Any):\n    if v is None:\n        return None\n    try:\n        if pd.isna(v):\n            return None\n    except Exception:\n        pass\n    if isinstance(v, str) and not v.strip():\n        return None\n    try:\n        return float(v)\n    except Exception:\n        return None\n\n\ndef _as_bool(v: Any) -> bool:\n    if isinstance(v, (bool, np.bool_)):\n        return bool(v)\n    if v is None:\n        return False\n    try:\n        if pd.isna(v):\n            return False\n    except Exception:\n        pass\n    return _norm(v) in {"1", "true", "yes", "y"}\n\n\ndef _safe_name(v: str, default: str = "BOM") -> str:\n    s = re.sub(r"[^A-Za-z0-9._-]+", "_", str(v or "").strip()).strip("._")\n    return s or default\n\n\ndef _sha256_file(path: Path) -> str:\n    h = hashlib.sha256()\n    with Path(path).open("rb") as f:\n        for chunk in iter(lambda: f.read(1024 * 1024), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef load_factor_snapshot(path: str | Path) -> dict[str, Any]:\n    p = Path(path)\n    obj = json.loads(p.read_text(encoding="utf-8"))\n    if not isinstance(obj.get("factors"), dict):\n        raise ValueError("Invalid process_gwp_snapshot.json: missing factor mapping.")\n    obj["_file_sha256"] = _sha256_file(p)\n    return obj\n\n\ndef _conversion_inputs(rec: dict[str, Any]):\n    density = _number(rec.get("density_kg_m3"))\n    if density is None:\n        density = _number(rec.get("resolved_density_kg_m3"))\n    thickness = _number(rec.get("thickness_mm"))\n    if thickness is None:\n        thickness = _number(rec.get("resolved_thickness_mm"))\n    mass_per_item = _number(rec.get("mass_per_item_kg"))\n    if mass_per_item is None:\n        mass_per_item = _number(rec.get("resolved_mass_per_item_kg"))\n    return density, thickness, mass_per_item\n\n\ndef _property_traceable(rec: dict[str, Any]) -> bool:\n    status = _norm(rec.get("property_verification"))\n    return status not in {\n        "unverified_fallback_estimate", "llm_unverified_estimate",\n        "conservative_analog_estimate", "unresolved", "input_or_model_failure",\n    }\n\n\ndef _external_relaxed_factor_safe(material: Any, ef: float, ref_unit: Any) -> tuple[bool, str]:\n    """Structural guard for relaxed externally sourced factors.\n\n    This contains no material-specific expected GWP ranges. It checks only sign\n    and strong reference-unit family constraints.\n    """\n    name = _norm(material)\n    ref = _norm(ref_unit).replace("³", "3").replace("²", "2")\n    if ef <= 0:\n        return False, "Non-positive relaxed-phase external A1-A3 factor rejected; credits require verified evidence."\n    is_metal = any(x in name for x in (\n        "steel", "iron", "nail", "binding wire", "rebar", "galvanized", "galvanised", "cgi", "corrugated"\n    ))\n    if is_metal and ref not in {"kg", "t", "ton", "tonne"}:\n        return False, "Metal-product relaxed external factor must use a mass reference unit."\n    return True, "ok"\n\n\ndef _final_evidence_class(row: dict[str, Any], *, ef_traceable: bool, property_traceable: bool) -> str:\n    ef_ver = _norm(row.get("emission_factor_verification"))\n    prop_ver = _norm(row.get("property_verification"))\n    source = _norm(row.get("emission_factor_source_class"))\n    external_source = _norm(row.get("external_ef_source_class"))\n\n    fallback = {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}\n    if ef_ver in fallback or prop_ver in fallback:\n        return "UNVERIFIED_FALLBACK_ESTIMATE"\n\n    # The former provisional/source-supported pathway is now the relaxed phase of\n    # Class 3. A relaxed externally sourced conversion property also makes Class 3\n    # the weakest publication-facing evidence level for the row.\n    if (\n        source == "external_verified"\n        or ef_ver in {"external_verified", "provisional_source_supported"}\n        or prop_ver in {"traceable_web_relaxed", "provisional_source_supported"}\n        or external_source == "external_verified_relaxed"\n    ):\n        return "EXTERNAL_VERIFIED"\n\n    if not ef_traceable or not property_traceable:\n        return "INPUT_OR_MODEL_FAILURE"\n    if source == "database_direct":\n        return "ELCD_DIRECT"\n    if source == "database_proxy":\n        return "ELCD_PROXY"\n    return "INPUT_OR_MODEL_FAILURE"\n\n\ndef calculate_rows(selection_df: pd.DataFrame, snapshot: dict[str, Any]) -> pd.DataFrame:\n    # Qwen retrieval uses the final hash-frozen ELCD descriptor snapshot, while\n    # numerical factors are exported separately from the same active openLCA\n    # database. Their semantic hashes use different representations; exact process\n    # UUID availability is therefore the cross-check.\n    impact_unit = snapshot.get("impact_category_ref_unit") or "kg CO2 eq"\n    out: list[dict[str, Any]] = []\n    factors = snapshot["factors"]\n    selected_uuids = {\n        str(v).strip()\n        for v in selection_df.get(\n            "production_selected_process_uuid", pd.Series(dtype=str)\n        ).dropna().astype(str)\n        if str(v).strip()\n    }\n    missing_factors = sorted(selected_uuids - set(factors))\n    if missing_factors:\n        raise RuntimeError(\n            "Selected frozen-catalog UUID(s) are missing from the frozen factor "\n            f"snapshot: {missing_factors[:10]}"\n        )\n\n    for rec in selection_df.to_dict(orient="records"):\n        row = dict(rec)\n        material_for_family = choose_resolution_material(\n            rec.get("original_material") or rec.get("Material"), rec.get("normalized_material")\n        )[0]\n        row.update({\n            "calculation_status": None,\n            "calculation_engine": None,\n            "calculation_message": None,\n            "process_reference_unit_final": None,\n            "quantity_in_reference_unit": None,\n            "conversion_method": None,\n            "emission_factor_per_reference_unit": None,\n            "emission_factor_source_class": None,\n            "emission_factor_verification": None,\n            "emission_factor_source_url_final": None,\n            "emission_factor_source_geography_final": None,\n            "emission_factor_source_year_final": None,\n            "emission_factor_boundary_final": None,\n            "impact_basis": None,\n            "impact_unit": impact_unit,\n            "gwp_total": None,\n            "calculation_traceability": None,\n            "emission_factor_fallback_method": None,\n            "property_fallback_method_final": None,\n            "unverified_fallback_method": None,\n            "fully_traceable_row": False,\n            "result_evidence_class": "INPUT_OR_MODEL_FAILURE",\n            "included_in_verified_calculation": False,\n            "included_in_evidence_supported_screening": False,\n            "included_in_complete_exploratory_screening": False,\n            "included_in_complete_screening": False,\n            "material_family_final": classify_material(material_for_family),\n            "biogenic_storage_excluded": False,\n            "biogenic_reporting_indicator": None,\n        })\n\n        structured_valid = _as_bool(rec.get("structured_output_valid"))\n        approved = _as_bool(rec.get("production_approved"))\n        match_type = _norm(rec.get("production_match_type"))\n        uid = str(rec.get("production_selected_process_uuid") or "").strip()\n        ext_status = _norm(rec.get("external_ef_resolution_status"))\n        ext_ready = ext_status in {"resolved_external_verified", "resolved_provisional_source_supported", "resolved_unverified_fallback_estimate", "resolved_llm_unverified_estimate", "resolved_conservative_analog_estimate"}\n\n        if not structured_valid and not ext_ready:\n            row["calculation_status"] = "REVIEW_REQUIRED_MODEL_OUTPUT"\n            out.append(row)\n            continue\n\n        density, thickness, mass_per_item = _conversion_inputs(rec)\n        family = row["material_family_final"]\n        is_biogenic_policy = family in BIOGENIC_STORAGE_EXCLUDED_FAMILIES\n\n        ef_traceable = False\n        if approved and match_type in {"direct", "proxy"} and uid and not is_biogenic_policy:\n            snap = factors.get(uid)\n            if not snap or snap.get("status") != "OK":\n                row["calculation_status"] = "REVIEW_REQUIRED_SNAPSHOT_FACTOR"\n                row["calculation_message"] = (snap or {}).get("error") or "No usable frozen openLCA factor for selected process."\n                out.append(row)\n                continue\n            ef = _number(snap.get("emission_factor"))\n            ref_unit = snap.get("reference_unit")\n            if ef is None or not ref_unit:\n                row["calculation_status"] = "REVIEW_REQUIRED_SNAPSHOT_FACTOR"\n                row["calculation_message"] = "Frozen factor or reference unit is missing."\n                out.append(row)\n                continue\n            row["calculation_engine"] = "FROZEN_OPENLCA_SNAPSHOT"\n            row["process_reference_unit_final"] = ref_unit\n            row["emission_factor_source_class"] = "DATABASE_DIRECT" if match_type == "direct" else "DATABASE_PROXY"\n            row["emission_factor_verification"] = "DATABASE_TRACEABLE"\n            row["emission_factor_source_geography_final"] = rec.get("production_selected_process_location")\n            row["emission_factor_boundary_final"] = "SELECTED_LCIA_OF_ELCD_PROCESS"\n            row["impact_basis"] = snap.get("impact_basis")\n            ef_traceable = True\n        elif ext_ready:\n            ef = _number(rec.get("external_ef_value"))\n            ref_unit = rec.get("external_ef_reference_unit")\n            if ef is None or not ref_unit:\n                row["calculation_status"] = "REVIEW_REQUIRED_EXTERNAL_FACTOR_INVALID"\n                out.append(row)\n                continue\n            verification = _norm(rec.get("external_ef_verification"))\n            if is_biogenic_policy:\n                indicator = str(rec.get("external_ef_indicator") or "").upper().replace("_", "-")\n                if ef <= 0:\n                    row["calculation_status"] = "REVIEW_REQUIRED_BIOGENIC_FACTOR_NONPOSITIVE"\n                    row["calculation_message"] = "Biogenic storage is excluded; bio-based EF must be strictly positive."\n                    row["biogenic_storage_excluded"] = True\n                    out.append(row)\n                    continue\n                if verification in {"external_verified", "provisional_source_supported", "unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}:\n                    if "GWP-GHG" not in indicator and "GWP-FOSSIL" not in indicator:\n                        row["calculation_status"] = "REVIEW_REQUIRED_BIOGENIC_INDICATOR"\n                        row["calculation_message"] = "Bio-based factors must explicitly report GWP-GHG or GWP-fossil when storage credit is excluded."\n                        row["biogenic_storage_excluded"] = True\n                        out.append(row)\n                        continue\n                    row["biogenic_reporting_indicator"] = rec.get("external_ef_indicator")\n                else:\n                    row["calculation_status"] = "REVIEW_REQUIRED_EXTERNAL_FACTOR_INVALID"\n                    row["calculation_message"] = "Unsupported external-factor verification class."\n                    out.append(row)\n                    continue\n                row["biogenic_storage_excluded"] = True\n\n            if verification == "external_verified":\n                row["emission_factor_source_class"] = "EXTERNAL_VERIFIED"\n                ef_traceable = True\n            elif verification == "provisional_source_supported":  # legacy payload compatibility\n                safe, msg = _external_relaxed_factor_safe(\n                    rec.get("original_material") or rec.get("normalized_material"), ef, ref_unit\n                )\n                if not safe:\n                    row["calculation_status"] = "INPUT_OR_MODEL_FAILURE_INVALID_RELAXED_EXTERNAL_EF"\n                    row["calculation_message"] = msg\n                    out.append(row)\n                    continue\n                row["emission_factor_source_class"] = "EXTERNAL_VERIFIED"\n                row["emission_factor_verification"] = "EXTERNAL_VERIFIED"\n                ef_traceable = True\n            elif verification in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}:\n                if ef <= 0:\n                    row["calculation_status"] = "INPUT_OR_MODEL_FAILURE_INVALID_LLM_ESTIMATE"\n                    row["calculation_message"] = "LLM-only emission factor must be strictly positive."\n                    out.append(row)\n                    continue\n                row["emission_factor_source_class"] = "UNVERIFIED_FALLBACK_ESTIMATE"\n                ef_traceable = False\n            else:\n                row["calculation_status"] = "REVIEW_REQUIRED_EXTERNAL_FACTOR_INVALID"\n                row["calculation_message"] = "Unsupported external-factor verification class."\n                out.append(row)\n                continue\n\n            row["calculation_engine"] = "EXTERNAL_FACTOR"\n            row["process_reference_unit_final"] = ref_unit\n            row["emission_factor_verification"] = ("EXTERNAL_VERIFIED" if verification in {"external_verified", "provisional_source_supported"} else rec.get("external_ef_verification"))\n            row["emission_factor_fallback_method"] = rec.get("external_ef_fallback_method")\n            row["emission_factor_source_url_final"] = rec.get("external_ef_source_url")\n            row["emission_factor_source_geography_final"] = rec.get("external_ef_source_geography")\n            row["emission_factor_source_year_final"] = rec.get("external_ef_source_year")\n            row["emission_factor_boundary_final"] = rec.get("external_ef_boundary")\n            row["impact_basis"] = (\n                "EXTERNAL_A1_A3_GWP_GHG_NO_BIOGENIC_STORAGE" if is_biogenic_policy else "EXTERNAL_A1_A3_GWP_FACTOR"\n            )\n        else:\n            row["calculation_status"] = "REVIEW_REQUIRED_NO_FACTOR"\n            row["calculation_message"] = rec.get("safety_reason") or rec.get("external_ef_reason")\n            out.append(row)\n            continue\n\n        conv = convert_quantity(\n            _number(rec.get("quantity")), rec.get("unit"), ref_unit,\n            density_kg_m3=density,\n            thickness_mm=thickness,\n            mass_per_item_kg=mass_per_item,\n            conversion_factor_to_ref_unit=_number(rec.get("conversion_factor_to_ref_unit")),\n        )\n        row["conversion_method"] = conv.method\n        if not conv.ok:\n            row["calculation_status"] = "REVIEW_REQUIRED_UNIT_CONVERSION"\n            row["calculation_message"] = conv.message\n            out.append(row)\n            continue\n\n        row["quantity_in_reference_unit"] = float(conv.quantity_in_ref_unit)\n        row["emission_factor_per_reference_unit"] = float(ef)\n        row["gwp_total"] = float(conv.quantity_in_ref_unit) * float(ef)\n        prop_ver = _norm(rec.get("property_verification"))\n        prop_traceable = _property_traceable(rec)\n        if prop_ver in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"} or _norm(row.get("emission_factor_verification")) in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}:\n            row["calculation_traceability"] = "USES_UNVERIFIED_FALLBACK_ESTIMATE"\n        elif prop_ver in {"traceable_web_relaxed", "provisional_source_supported"}:\n            row["calculation_traceability"] = "USES_EXTERNAL_VERIFIED_RELAXED_PROPERTY"\n        elif _norm(rec.get("external_ef_source_class")) == "external_verified_relaxed":\n            row["calculation_traceability"] = "USES_EXTERNAL_VERIFIED_RELAXED_EF"\n        elif not ef_traceable:\n            row["calculation_traceability"] = "EXTERNAL_EVIDENCE_NOT_TRACEABLE"\n        elif prop_ver in {"traceable_web", "project_or_bom", "project_input", "bom_extracted"}:\n            row["calculation_traceability"] = "TRACEABLE_OR_PROJECT_PROPERTY"\n        else:\n            row["calculation_traceability"] = "NO_EXTERNAL_PROPERTY_NEEDED"\n\n        row["property_fallback_method_final"] = rec.get("property_fallback_method")\n        fallback_methods = [str(x) for x in (row.get("emission_factor_fallback_method"), row.get("property_fallback_method_final")) if x not in (None, "", "nan")]\n        row["unverified_fallback_method"] = ";".join(dict.fromkeys(fallback_methods)) or None\n        row["fully_traceable_row"] = bool(ef_traceable and prop_traceable)\n        row["result_evidence_class"] = _final_evidence_class(row, ef_traceable=ef_traceable, property_traceable=prop_traceable)\n        row["included_in_verified_calculation"] = row["result_evidence_class"] in {"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED"}\n        row["included_in_evidence_supported_screening"] = row["included_in_verified_calculation"]  # legacy alias\n        row["included_in_complete_exploratory_screening"] = row["result_evidence_class"] in {"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED", "UNVERIFIED_FALLBACK_ESTIMATE"}\n        row["included_in_complete_screening"] = row["included_in_complete_exploratory_screening"]\n        row["calculation_status"] = "CALCULATED"\n        out.append(row)\n\n    return pd.DataFrame(out)\n\n\ndef _material_label(rec: pd.Series) -> str:\n    # Paper figures prefer the concise BOM wording; normalized terminology\n    # remains available in the workbook audit sheets.\n    original = str(rec.get("original_material") or rec.get("Material") or "").strip()\n    normalized = str(rec.get("normalized_material") or "").strip()\n    return original or normalized or "Material"\n\n\ndef _format_pct(value: float) -> str:\n    v = float(value)\n    if abs(v) >= 10:\n        return f"{v:.1f}%"\n    if abs(v) >= 1:\n        return f"{v:.2f}%"\n    if abs(v) >= 0.1:\n        return f"{v:.3f}%"\n    return f"{v:.4f}%"\n\n\ndef build_contribution_table(results: pd.DataFrame, *, scope: str) -> tuple[pd.DataFrame, str]:\n    calc = results[results["calculation_status"] == "CALCULATED"].copy()\n    if scope == "verified":\n        allowed = {"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED"}\n        calc = calc[calc["result_evidence_class"].isin(allowed)].copy()\n        scope_note = "Includes evidence classes 1-3: ELCD Direct, ELCD Proxy, and External Verified."\n    elif scope == "complete_exploratory":\n        allowed = {"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED", "UNVERIFIED_FALLBACK_ESTIMATE"}\n        calc = calc[calc["result_evidence_class"].isin(allowed)].copy()\n        scope_note = "Includes evidence classes 1-4. Class 4 is the Unverified Fallback Estimate."\n    else:\n        raise ValueError(f"Unknown contribution scope: {scope}")\n\n    cols = ["material", "evidence_class", "gwp_total", "contribution_pct", "cumulative_pct"]\n    if calc.empty:\n        return pd.DataFrame(columns=cols), scope_note\n\n    calc["material"] = calc.apply(_material_label, axis=1)\n    # Aggregate repeated rows of the same displayed material before calculating\n    # chart percentages. If those rows span more than one evidence class, the\n    # chart table records MIXED; the publication figure itself does not encode\n    # evidence class.\n    agg = (\n        calc.groupby("material", as_index=False)\n        .agg(\n            gwp_total=("gwp_total", "sum"),\n            result_evidence_class=("result_evidence_class", lambda x: next(iter(set(x))) if len(set(x)) == 1 else "MIXED"),\n        )\n    )\n    agg = agg.sort_values("gwp_total", ascending=False).reset_index(drop=True)\n    denom = float(agg["gwp_total"].sum())\n    agg["contribution_pct"] = np.where(denom, agg["gwp_total"] / denom * 100.0, 0.0)\n\n    # Publication grouping rule: every material contributing <0.1% individually\n    # is aggregated into a single neutral "Other" bar. The aggregation is based\n    # only on contribution magnitude, never on evidence class.\n    small = agg["contribution_pct"] < CHART_OTHER_THRESHOLD_PCT\n    main = agg.loc[~small].copy()\n    other = agg.loc[small].copy()\n    if not other.empty:\n        main = pd.concat([main, pd.DataFrame([{\n            "material": "Other",\n            "result_evidence_class": "MIXED",\n            "gwp_total": float(other["gwp_total"].sum()),\n            "contribution_pct": float(other["contribution_pct"].sum()),\n        }])], ignore_index=True)\n    main = main.sort_values("gwp_total", ascending=False).reset_index(drop=True)\n    main["cumulative_pct"] = main["contribution_pct"].cumsum()\n    main = main.rename(columns={"result_evidence_class": "evidence_class"})\n    grouping_note = (\n        f"Materials contributing less than {CHART_OTHER_THRESHOLD_PCT:g}% individually are combined as Other; "\n        f"{int(small.sum())} material group(s) were aggregated."\n    )\n    return main[cols], scope_note + " " + grouping_note\n\n\ndef make_contribution_png(contrib: pd.DataFrame, path: str | Path, impact_unit: str, *, title: str | None = None, unresolved_count: int = 0):\n    """Create a compact paper-ready material-contribution chart.\n\n    Publication figures intentionally contain no title, hatch/symbol coding, or\n    evidence-class legend. Evidence classes remain available in the workbook.\n    """\n    import matplotlib.pyplot as plt\n    from PIL import Image\n    import textwrap\n\n    p = Path(path)\n    p.parent.mkdir(parents=True, exist_ok=True)\n    if contrib.empty:\n        fig, ax = plt.subplots(figsize=(6.0, 2.5))\n        ax.text(0.5, 0.5, "No numerical material contributions", ha="center", va="center", fontsize=7.5)\n        ax.axis("off")\n    else:\n        plot_df = contrib.iloc[::-1].copy()\n        labels = [textwrap.fill(str(x), width=29) for x in plot_df["material"]]\n        fig_h = min(max(2.8, 0.34 * len(plot_df) + 1.15), 6.7)\n        fig, ax = plt.subplots(figsize=(6.2, fig_h))\n        bars = ax.barh(labels, plot_df["gwp_total"])\n\n        ax.set_xlabel(f"GWP ({impact_unit})", fontsize=7.1, labelpad=3)\n        ax.set_ylabel("")\n        ax.tick_params(axis="x", labelsize=6.3)\n        ax.tick_params(axis="y", labelsize=6.4, pad=2)\n        ax.grid(axis="x", alpha=0.16, linewidth=0.5)\n        ax.set_axisbelow(True)\n\n        max_abs = max(float(plot_df["gwp_total"].abs().max()), 1.0)\n        for bar, pct in zip(bars, plot_df["contribution_pct"]):\n            x = float(bar.get_width())\n            ax.text(\n                x + max_abs * 0.012, bar.get_y() + bar.get_height()/2,\n                _format_pct(float(pct)), va="center", ha="left", fontsize=5.9,\n            )\n        ax.set_xlim(left=0, right=max_abs * 1.19)\n        # No evidence-class legend/symbols. If failures exist they remain in the\n        # workbook audit/summary rather than being represented as a chart symbol.\n        fig.subplots_adjust(left=0.34, right=0.97, top=0.97, bottom=0.16)\n\n    fig.savefig(p, dpi=320, bbox_inches="tight", pad_inches=0.035)\n    plt.close(fig)\n    try:\n        with Image.open(p) as im:\n            im.save(p, format="PNG", optimize=True, compress_level=9, dpi=(320, 320))\n    except Exception:\n        pass\n    return p\n\n\ndef build_summary(results: pd.DataFrame, uncertainty: pd.DataFrame, impact_unit: str) -> pd.DataFrame:\n    calc = results[results["calculation_status"] == "CALCULATED"].copy()\n    verified_classes = {"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED"}\n    verified = calc[calc["result_evidence_class"].isin(verified_classes)].copy()\n    fallback = calc[calc["result_evidence_class"] == "UNVERIFIED_FALLBACK_ESTIMATE"].copy()\n    failures = results[~results["calculation_status"].eq("CALCULATED")].copy()\n\n    verified_total = float(verified["gwp_total"].sum()) if not verified.empty else 0.0\n    fallback_total = float(fallback["gwp_total"].sum()) if not fallback.empty else 0.0\n    exploratory_total = float(calc["gwp_total"].sum()) if not calc.empty else 0.0\n    exploratory_complete = len(failures) == 0\n    verified_share = (verified_total / exploratory_total * 100.0) if exploratory_total > 0 else 0.0\n    numeric_coverage = (len(calc) / len(results) * 100.0) if len(results) else 0.0\n\n    rows = [\n        ["Verified A1-A3 GWP subtotal (classes 1-3)", verified_total, impact_unit],\n        ["Unverified fallback GWP contribution (class 4)", fallback_total, impact_unit],\n        ["Complete exploratory GWP estimate (classes 1-4)" if exploratory_complete else "Calculated exploratory subtotal (input/model failures remain)", exploratory_total, impact_unit],\n        ["Verified share of complete exploratory GWP", verified_share, "%"],\n        ["Numerical row coverage", numeric_coverage, "% of BOM rows"],\n        ["ELCD Direct rows", int((results["result_evidence_class"] == "ELCD_DIRECT").sum()), "rows"],\n        ["ELCD Proxy rows", int((results["result_evidence_class"] == "ELCD_PROXY").sum()), "rows"],\n        ["External Verified rows", int((results["result_evidence_class"] == "EXTERNAL_VERIFIED").sum()), "rows"],\n        ["Unverified Fallback Estimate rows", int((results["result_evidence_class"] == "UNVERIFIED_FALLBACK_ESTIMATE").sum()), "rows"],\n        ["Input/model failure rows", int(len(failures)), "rows"],\n        ["Exploratory screening complete", bool(exploratory_complete), "boolean"],\n    ]\n    for _, r in uncertainty.iterrows():\n        prefix = str(r["scope"])\n        rows.extend([\n            [f"{prefix} Monte Carlo median", float(r["median"]), impact_unit],\n            [f"{prefix} Monte Carlo 2.5th percentile", float(r["p2_5"]), impact_unit],\n            [f"{prefix} Monte Carlo 97.5th percentile", float(r["p97_5"]), impact_unit],\n        ])\n    return pd.DataFrame(rows, columns=["metric", "value", "unit"])\n\n\ndef _evidence_audit(results: pd.DataFrame) -> pd.DataFrame:\n    preferred = [\n        "item_id", "original_material", "normalized_material", "quantity", "unit",\n        "production_match_type", "production_selected_process_uuid", "production_selected_process_name",\n        "safety_status", "safety_reason", "external_ef_resolution_status",\n        "emission_factor_source_class", "emission_factor_verification", "emission_factor_per_reference_unit",\n        "process_reference_unit_final", "emission_factor_source_url_final", "emission_factor_source_geography_final",\n        "emission_factor_source_year_final", "emission_factor_boundary_final", "external_ef_indicator",\n        "external_ef_evidence_quote", "external_ef_reason", "external_ef_match_type", "external_ef_proxy_basis",\n        "external_ef_fallback_method", "emission_factor_fallback_method",\n        "property_lookup_needed", "property_lookup_reason", "property_required", "property_fallback_method", "property_fallback_method_final", "unverified_fallback_method",\n        "property_verification", "property_source_url", "property_source_geography", "property_source_year",\n        "conversion_method", "quantity_in_reference_unit", "result_evidence_class",\n        "included_in_verified_calculation", "included_in_evidence_supported_screening",\n        "included_in_complete_exploratory_screening", "included_in_complete_screening", "gwp_total",\n        "factor_uncertainty_gsd", "factor_uncertainty_method", "property_uncertainty_gsd",\n        "property_uncertainty_method", "row_uncertainty_gsd", "calculation_status", "calculation_message",\n    ]\n    cols = [c for c in preferred if c in results.columns]\n    extras = [c for c in results.columns if c not in cols]\n    return results[cols + extras].copy()\n\n\ndef _write_raw_mc_gz(raw_mc: pd.DataFrame, path: Path) -> Path:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with gzip.open(path, "wt", encoding="utf-8", newline="") as f:\n        raw_mc.to_csv(f, index=False)\n    return path\n\n\ndef write_final_workbook(\n    results: pd.DataFrame,\n    selections: pd.DataFrame,\n    property_evidence: pd.DataFrame,\n    external_evidence: pd.DataFrame,\n    uncertainty: pd.DataFrame,\n    convergence: pd.DataFrame,\n    verified_contribution: pd.DataFrame,\n    complete_exploratory_contribution: pd.DataFrame,\n    verified_note: str,\n    complete_exploratory_note: str,\n    snapshot: dict[str, Any],\n    output_xlsx: str | Path,\n    verified_png: str | Path,\n    complete_exploratory_png: str | Path,\n):\n    output_xlsx = Path(output_xlsx)\n    output_xlsx.parent.mkdir(parents=True, exist_ok=True)\n    impact_unit = snapshot.get("impact_category_ref_unit") or "kg CO2 eq"\n    summary = build_summary(results, uncertainty, impact_unit)\n    calc = results[results["calculation_status"] == "CALCULATED"].copy()\n    verified = calc[calc["result_evidence_class"].isin({"ELCD_DIRECT", "ELCD_PROXY", "EXTERNAL_VERIFIED"})].copy()\n    complete_exploratory = results.copy()\n    failures = results[~results["calculation_status"].eq("CALCULATED")].copy()\n    audit = _evidence_audit(results)\n    uncertainty_by_row_cols = [c for c in results.columns if c.startswith("gwp_") or "uncertainty" in c or c.startswith("pedigree_")]\n    id_cols = [c for c in ("item_id", "original_material", "normalized_material", "result_evidence_class", "gwp_total") if c in results.columns]\n    uncertainty_by_row = results[id_cols + [c for c in uncertainty_by_row_cols if c not in id_cols]].copy()\n\n    metadata = pd.DataFrame([\n        ["calculated_at_utc", datetime.now(timezone.utc).isoformat()],\n        ["colab_calculator_version", COLAB_CALCULATOR_VERSION],\n        ["catalog_content_sha256", snapshot.get("catalog_content_sha256")],\n        ["factor_snapshot_sha256", snapshot.get("_file_sha256")],\n        ["impact_method_name", snapshot.get("impact_method_name")],\n        ["impact_method_id", snapshot.get("impact_method_id")],\n        ["impact_category_name", snapshot.get("impact_category_name")],\n        ["impact_category_id", snapshot.get("impact_category_id")],\n        ["impact_category_ref_unit", impact_unit],\n        ["result_design", "Verified subtotal (classes 1-3) and complete exploratory estimate (classes 1-4) are reported separately."],\n        ["external_verified_retrieval", "Class 3 uses two sequential source-search phases: strict target-geography/direct-product first, then a fresh-clock relaxed geography/technical-equivalence phase. Both are reported as EXTERNAL_VERIFIED; phase/tier remains auditable."],\n        ["external_verified_timing", "Strict phase up to 60 s; if unresolved, relaxed phase starts a fresh clock up to 120 s with its broader bounded query/source budget."],\n        ["uncertainty_method_version", UNCERTAINTY_METHOD_VERSION],\n        ["uncertainty_hierarchy", "source-reported quantitative uncertainty -> accepted-source dispersion -> adapted pedigree matrix; relaxed Class-3 evidence retains conservative representativeness uncertainty"],\n        ["uncertainty_distribution", "Independent row-level lognormal multiplicative uncertainty; factor and required property log-variances combined."],\n        ["monte_carlo_seed", MONTE_CARLO_SEED],\n        ["monte_carlo_schedule", json.dumps(MONTE_CARLO_SCHEDULE)],\n        ["monte_carlo_min_final_runs", MONTE_CARLO_MIN_FINAL_RUNS],\n        ["monte_carlo_convergence_tolerance", MONTE_CARLO_CONVERGENCE_TOLERANCE],\n        ["chart_other_threshold_pct", CHART_OTHER_THRESHOLD_PCT],\n        ["verified_chart_note", verified_note],\n        ["complete_exploratory_chart_note", complete_exploratory_note],\n        ["final_evidence_hierarchy", "1 ELCD_DIRECT; 2 ELCD_PROXY; 3 EXTERNAL_VERIFIED; 4 UNVERIFIED_FALLBACK_ESTIMATE"],\n        ["unverified_fallback_pathway", "Class 4 is attempted only after ELCD and both External Verified retrieval phases fail. It first performs a dynamic same-family search of the frozen ELCD/openLCA catalog, then a dynamically inferred semantic-analog catalog search. Qwen may generate terminology and rank supplied process identities, but Python reads numerical factors from the hash-verified frozen snapshot. Only if both database-anchored routes fail may one terminal model-only value be retained after deterministic validation. Class 4 is excluded from the verified subtotal."],\n        ["biogenic_carbon_reporting_policy", "Timber/plywood/bamboo exclude biogenic storage credits; verified external GWP-GHG preferred, explicit GWP-fossil allowed."],\n    ], columns=["field", "value"])\n\n    sheets: list[tuple[str, pd.DataFrame]] = [\n        ("Summary", summary),\n        ("Verified_Calculation", verified),\n        ("Complete_Exploratory_Screening", complete_exploratory),\n        ("Evidence_Audit", audit),\n        ("Uncertainty_Summary", uncertainty),\n        ("Uncertainty_By_Row", uncertainty_by_row),\n        ("MC_Convergence", convergence),\n        ("Verified_GWP_Contribution", verified_contribution),\n        ("Complete_Exploratory_GWP", complete_exploratory_contribution),\n        ("Input_Model_Failures", failures),\n        ("Selections_Audit", selections),\n        ("Run_Metadata", metadata),\n    ]\n    if property_evidence is not None and not property_evidence.empty:\n        sheets.append(("Property_Evidence", property_evidence))\n    if external_evidence is not None and not external_evidence.empty:\n        sheets.append(("External_EF_Evidence", external_evidence))\n\n    with pd.ExcelWriter(output_xlsx, engine="xlsxwriter") as writer:\n        for name, df in sheets:\n            df.to_excel(writer, sheet_name=name, index=False)\n\n        wb = writer.book\n        header_fmt = wb.add_format({"bold": True, "font_color": "white", "bg_color": "#1F4E78", "border": 1, "align": "center", "valign": "vcenter"})\n        num_fmt = wb.add_format({"num_format": "0.000"})\n        wrap_fmt = wb.add_format({"text_wrap": True, "valign": "top"})\n\n        for name, df in sheets:\n            ws = writer.sheets[name]\n            ws.freeze_panes(1, 0)\n            if len(df.columns):\n                ws.autofilter(0, 0, max(len(df), 1), len(df.columns)-1)\n            for c, col in enumerate(df.columns):\n                ws.write(0, c, col, header_fmt)\n                sample = [str(col)] + [str(x) for x in df[col].head(80).fillna("").tolist()]\n                width = min(max(max(len(x) for x in sample) + 2, 10), 38)\n                ws.set_column(c, c, width, wrap_fmt if width >= 30 else None)\n\n        sws = writer.sheets["Summary"]\n        sws.set_column("A:A", 55)\n        sws.set_column("B:B", 18, num_fmt)\n        sws.set_column("C:C", 18)\n\n        # Insert figures without an added worksheet heading; the figures themselves\n        # intentionally have no chart title or evidence-class symbols/legend.\n        for sheet, png in [\n            ("Verified_GWP_Contribution", verified_png),\n            ("Complete_Exploratory_GWP", complete_exploratory_png),\n        ]:\n            writer.sheets[sheet].insert_image("F1", str(png), {"x_scale": 0.70, "y_scale": 0.70})\n\n    return output_xlsx, summary\n\n\ndef process_selection_dataframe(\n    selections: pd.DataFrame,\n    snapshot: dict[str, Any],\n    output_dir: str | Path,\n    base_name: str,\n    *,\n    property_evidence: pd.DataFrame | None = None,\n    external_evidence: pd.DataFrame | None = None,\n):\n    outdir = Path(output_dir)\n    outdir.mkdir(parents=True, exist_ok=True)\n    base = _safe_name(base_name)\n\n    results = calculate_rows(selections, snapshot)\n    results = enrich_row_uncertainty(results)\n    uncertainty, convergence, raw_mc = monte_carlo_with_convergence(results)\n\n    verified_contribution, verified_note = build_contribution_table(results, scope="verified")\n    complete_exploratory_contribution, complete_exploratory_note = build_contribution_table(results, scope="complete_exploratory")\n    impact_unit = snapshot.get("impact_category_ref_unit") or "kg CO2 eq"\n    failure_count = int((results["calculation_status"] != "CALCULATED").sum())\n\n    verified_png = make_contribution_png(\n        verified_contribution,\n        outdir / f"{base}_Verified_GWP_Contribution.png",\n        impact_unit,\n        unresolved_count=0,\n    )\n    complete_exploratory_png = make_contribution_png(\n        complete_exploratory_contribution,\n        outdir / f"{base}_Complete_Exploratory_GWP_Contribution.png",\n        impact_unit,\n        unresolved_count=failure_count,\n    )\n\n    xlsx, summary = write_final_workbook(\n        results,\n        selections,\n        property_evidence if property_evidence is not None else pd.DataFrame(),\n        external_evidence if external_evidence is not None else pd.DataFrame(),\n        uncertainty,\n        convergence,\n        verified_contribution,\n        complete_exploratory_contribution,\n        verified_note,\n        complete_exploratory_note,\n        snapshot,\n        outdir / f"{base}_Final_A1-A3_GWP.xlsx",\n        verified_png,\n        complete_exploratory_png,\n    )\n\n    raw_mc_path = _write_raw_mc_gz(raw_mc, outdir / f"{base}_Monte_Carlo_Raw.csv.gz")\n    package = outdir / f"{base}_Results_Package.zip"\n    with zipfile.ZipFile(package, "w", compression=zipfile.ZIP_DEFLATED) as z:\n        for path in (xlsx, verified_png, complete_exploratory_png, raw_mc_path):\n            z.write(path, Path(path).name)\n\n    return {\n        "results": results,\n        "summary": summary,\n        "uncertainty": uncertainty,\n        "convergence": convergence,\n        "verified_contribution": verified_contribution,\n        "complete_exploratory_contribution": complete_exploratory_contribution,\n        "xlsx": xlsx,\n        "verified_png": verified_png,\n        "complete_exploratory_png": complete_exploratory_png,\n        "complete_png": complete_exploratory_png,\n        "png": complete_exploratory_png,\n        "raw_mc": raw_mc_path,\n        "zip": package,\n    }\n', 'external_ef_resolver.py': '"""External A1-A3 GWP-factor resolver for ELCD-unmatched BOM materials.\n\nThis module is deliberately separate from Qwen material/process matching and runs\nonly for rows that were not approved for an ELCD/openLCA process.\n\nPublication-facing hierarchy handled here:\n- Class 3 — EXTERNAL_VERIFIED. Phase A searches strict Nepal/target-geography,\n  direct-product evidence first. If unresolved, Phase B starts a fresh independent\n  clock and broadens geography, source type, and technically relevant product\n  terminology. Every accepted numerical value must still be explicitly supported\n  by retrieved evidence and pass unit, indicator, boundary, and product/family\n  checks. Phase A/B remain auditable but are both reported as Class 3.\n- Class 4 — UNVERIFIED_FALLBACK_ESTIMATE. Used only after both Class-3 phases fail.\n  Database-anchored same-family and semantic-analog routes are attempted before one\n  terminal model-only estimate.\n\nNo material-specific emission factor, density, source URL, preselected EPD, or\nplausible GWP range is stored in this module. Class 4 is excluded from the verified\nsubtotal; Classes 1-3 form the verified result and Classes 1-4 form the complete\nexploratory estimate.\n"""\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nimport io\nimport json\nimport math\nimport re\nimport time\nfrom typing import Any\nfrom urllib.parse import urlparse, urljoin\n\nimport pandas as pd\n\nfrom unit_conversion import (\n    norm_unit, convert_factor_reference_basis,\n)\nfrom evidence_consensus import (\n    robust_positive_consensus, canonical_factor_basis, CONSENSUS_METHOD_VERSION,\n)\nfrom semantic_analog import infer_analog_plan\nfrom technical_equivalence import infer_technical_equivalents, TECHNICAL_EQUIVALENCE_VERSION\nfrom evidence_cache import RuntimeEvidenceCache, CACHE_VERSION\nfrom material_taxonomy import (\n    MATERIAL_TAXONOMY_VERSION, classify_material, external_title_compatibility,\n    BIOGENIC_STORAGE_EXCLUDED_FAMILIES, choose_resolution_material, process_compatibility,\n)\nfrom guardrails import (\n    GUARDRAIL_VERSION, emission_factor_plausible, emission_guardrail_context,\n)\n\nEXTERNAL_EF_RESOLVER_VERSION = "17.0-four-class-external-verified-two-phase"\nTARGET_GEOGRAPHY = "Nepal"\n\nTRACEABLE_EF_SYSTEM_PROMPT = """You are a technical LCA evidence extractor.\n\nYou are given web evidence for ONE construction material. Your job is only to\nextract a defensible product-stage climate-change factor using the requested\nindicator policy.\n\nYou are NOT allowed to invent a value, source, URL, year, boundary, declared unit,\nor evidence quote.\n\nAcceptance rules:\n1. Use ONLY the supplied evidence candidates.\n2. The source must represent the requested material/product or a clearly stated\n   product-level equivalent. Do not substitute a different product family.\n3. Follow required_indicator exactly:\n   - GWP-total: extract total climate change / GWP-total only.\n   - GWP-GHG_NO_BIOGENIC_STORAGE: prefer GWP-GHG, which excludes biogenic CO2\n     uptake/emissions and biogenic carbon stored in the product. If GWP-GHG is\n     unavailable, an explicitly reported GWP-fossil may be used as a conservative\n     fallback. Do NOT use negative GWP-total or convert a negative value to positive.\n4. Accept explicit A1-A3, cradle-to-gate, product-stage, production-stage, manufacturing-stage, or factory-gate values when the source clearly describes the product manufacturing boundary. Reject A1 only, A1-A5, B/C/D modules, whole-life/cradle-to-grave totals, and unspecified-boundary values.\n5. The evidence must state the declared/reference quantity and unit associated\n   with the impact value. Do not guess them.\n6. source_result_id must exactly match one supplied result ID.\n7. evidence_quote must be copied verbatim from the supplied snippet/extracted text.\n8. If the source reports separate A1, A2 and A3 values but no explicit A1-A3 total\n   in the supplied evidence, return found=false rather than doing an undocumented sum.\n9. For GWP-GHG_NO_BIOGENIC_STORAGE, impact_value must be strictly positive.\n10. If the SAME supplied source explicitly reports quantitative uncertainty for the factor,\n    extract it without reinterpretation. Otherwise return null for every uncertainty field.\n    Supported forms are: geometric standard deviation (GSD), coefficient of variation (CV),\n    or a numeric lower/upper interval with its stated confidence level. Do not invent an\n    uncertainty range. uncertainty_evidence_quote must be copied verbatim from the supplied\n    evidence whenever any uncertainty field is non-null.\n11. Return JSON only with exactly these keys:\nfound, impact_value, impact_unit, declared_quantity, declared_unit, boundary,\nindicator, source_result_id, source_year, evidence_quote, uncertainty_type,\nuncertainty_lower_value, uncertainty_upper_value, uncertainty_gsd, uncertainty_cv,\nuncertainty_confidence_level, uncertainty_evidence_quote, reason\n"""\n\nRELAXED_EXTERNAL_EF_SYSTEM_PROMPT = """You are a numerical LCA evidence extractor for ONE retrieved source.\n\nStrict verification has already failed. Extract only SOURCE-SUPPORTED GWP / global-warming / climate-change impact data explicitly present in the supplied evidence. Never estimate from memory. GWP is the only accepted environmental impact indicator. A generic carbon-footprint number is NOT sufficient unless the same retrieved evidence explicitly identifies it as GWP, Global Warming Potential, or the climate-change impact category. The relaxed External Verified phase may use an explicit A1-A3/cradle-to-gate result OR a GWP/climate-change result whose surrounding retrieved source clearly concerns production/manufacturing/embodied carbon and does not show a broader life-cycle boundary.\n\nRules:\n1. Use ONLY the single supplied evidence candidate. Never invent a value, source, URL, boundary, unit, year, or evidence quote.\n2. The product must represent the requested material or stated search proxy; do not knowingly substitute a different product family.\n3. GWP is the only accepted environmental indicator. For ordinary materials use GWP-total / Global Warming Potential / the total climate-change category. For required_indicator=GWP-GHG_NO_BIOGENIC_STORAGE, use only GWP-GHG, GWP-fossil, or climate-change-fossil and never use a negative GWP-total. Never substitute AP, EP, ODP, POCP, ADP, energy, water, waste, or another impact category.\n4. Prefer an explicit A1-A3/product-stage/cradle-to-gate total. If the literal boundary is absent, a TOTAL may still be returned when the SAME retrieved evidence clearly places the GWP/carbon value in material production/manufacturing/embodied-carbon context and does not indicate cradle-to-grave, whole-life, A1-A5, use-stage, or end-of-life coverage. Report boundary exactly as stated when available; otherwise use a short evidence-based phrase such as production/manufacturing context, not an invented A1-A3 label.\n5. If no explicit A1-A3 total is present but the SAME source explicitly reports separate A1, A2 and A3 values for the same GWP indicator, impact unit and declared unit, you may return value_mode=SUM_A1_A2_A3. Python, not you, will add the three modules. Evidence may contain lines beginning `[PDF TABLE PAGE ...]`; pipe characters preserve table columns. Use only the GWP/global-warming/climate-change row and its A1/A2/A3 columns; ignore neighboring AP, EP, ODP, POCP, ADP, energy, water and waste rows.\n6. For value_mode=TOTAL, set impact_value and set a1_value/a2_value/a3_value to null.\n7. For value_mode=SUM_A1_A2_A3, set impact_value=null and return all three explicit module values.\n8. The declared/reference quantity and unit must be explicit or directly represented by an intensity denominator (for example kg CO2e/kg).\n9. evidence_quote must be copied verbatim from supplied text and support the value(s), unit/basis and product-stage interpretation as far as possible.\n10. Do not average sources, convert units, or choose a final factor. Python handles normalization and consensus.\n11. Return JSON only with one top-level key records. records must contain exactly one object with exactly these keys:\nsource_result_id, found, value_mode, impact_value, a1_value, a2_value, a3_value, impact_unit, declared_quantity, declared_unit, boundary, indicator, source_year, evidence_quote, reason\n"""\n\nTERMINAL_LLM_ONLY_EF_SINGLE_SYSTEM_PROMPT = """You are producing ONE terminal exploratory A1-A3 GWP estimate for a construction material after Class-3 source-supported and dynamically database-anchored proxy routes have failed.\n\nThis value is intentionally UNVERIFIED and will be isolated from verified subtotal. No material-specific GWP value, density, plausible range, correction factor, or expected magnitude is supplied. Do not claim a source, citation, EPD, URL, publication year, or verification.\n\nReturn exactly one JSON object with these keys:\nfound, central_value, lower_value, upper_value, reference_unit, boundary, indicator, geography_assumption, product_interpretation, estimation_basis, rationale\n\nRules:\n- Use requested_reference_unit exactly and reason explicitly in that denominator basis.\n- Estimate A1-A3/cradle-to-gate only.\n- lower_value < central_value < upper_value and all values must be finite and positive.\n- Follow required_indicator exactly; for bio-based materials exclude storage/sequestration credits and use positive GWP-GHG or GWP-fossil.\n- This is a terminal model-only estimate, not source-supported evidence.\n- There is no repeated-value consensus step. Produce only this single estimate and do not imitate any prior model number.\n- Preserve the requested product identity explicitly in product_interpretation and rationale. The caller supplies deterministic_material_family derived only from the BOM text/taxonomy; treat it as a binding identity constraint, not as environmental evidence.\n- Do not merely echo or reinterpret an acronym. product_interpretation must spell out enough chemistry/form/function words to be independently compatible with deterministic_material_family. If an acronym could mean something else, use the supplied family rather than inventing another expansion.\n- A deterministic family gate will reject contradictions before any terminal number is retained.\n- JSON only.\n"""\n\nDYNAMIC_DATABASE_PROXY_SELECTOR_SYSTEM_PROMPT = """You are selecting a numerical proxy PROCESS for a construction-material A1-A3 screening fallback.\n\nThe caller supplies only process identity metadata from a frozen ELCD/openLCA catalog. No emission-factor values are shown to you. Your task is semantic/process selection only.\n\nRules:\n1. Preserve the requested product\'s dominant chemistry, manufacturing route, physical form, and construction function.\n2. Prefer the same product family. A broader analog is allowed only when the candidate explicitly states which dynamically inferred analog it represents.\n3. Do not invent a process, UUID, emission factor, density, conversion factor, source, or citation.\n4. Rank only supplied process UUIDs. If no supplied candidate is technically defensible, return an empty ranking.\n5. Geography is secondary to technical compatibility.\n6. Return JSON only with exactly these keys: ranked_process_uuids, selection_reason.\n7. ranked_process_uuids must be a flat list of at most three supplied UUID strings.\n"""\n\nTERMINAL_MINIMAL_EF_SYSTEM_PROMPT = """You are the last numerical fallback for an exploratory A1-A3 construction-material GWP screen.\n\nNo source support or material-specific expected value/range is supplied. The result will be explicitly labeled UNVERIFIED and excluded from verified subtotal. Return a usable positive number only if you can make a model-only engineering estimate. Do not claim a source.\n\nReturn JSON only with exactly these keys:\nfound, central_value, reference_unit, boundary, indicator, product_interpretation, rationale\n\nRules:\n- Use requested_reference_unit exactly.\n- Estimate A1-A3/cradle-to-gate only.\n- central_value must be finite and positive.\n- Follow required_indicator; bio-based materials must exclude storage/sequestration credit and use positive GWP-GHG or GWP-fossil.\n- deterministic_material_family is a binding identity constraint derived from the BOM taxonomy. product_interpretation must explicitly describe that family rather than merely echoing or re-expanding an acronym.\n"""\n\n\n\ndef _clean(v: Any) -> str:\n    if v is None:\n        return ""\n    try:\n        if pd.isna(v):\n            return ""\n    except Exception:\n        pass\n    return str(v).strip()\n\n\ndef _call_matcher(matcher, system_prompt: str, payload: dict[str, Any], *, max_new_tokens: int | None = None) -> str:\n    """Call Qwen with a task-specific output budget without changing benchmark settings.\n\n    Lightweight mocked matchers used by the deterministic tests may not accept\n    the override keyword, so fall back to the legacy two-argument signature.\n    """\n    try:\n        return matcher.generate_with_system(\n            system_prompt, payload, max_new_tokens_override=max_new_tokens\n        )\n    except TypeError:\n        return matcher.generate_with_system(system_prompt, payload)\n\n\ndef _as_bool(v: Any) -> bool:\n    if isinstance(v, bool):\n        return v\n    if v is None:\n        return False\n    try:\n        if pd.isna(v):\n            return False\n    except Exception:\n        pass\n    return _clean(v).lower() in {"1", "true", "yes", "y"}\n\n\ndef _num(v: Any) -> float | None:\n    if v is None:\n        return None\n    try:\n        if pd.isna(v):\n            return None\n    except Exception:\n        pass\n    if isinstance(v, str) and not v.strip():\n        return None\n    try:\n        x = float(v)\n    except Exception:\n        return None\n    return x if math.isfinite(x) else None\n\n\ndef _url_host(url: str) -> str:\n    try:\n        return (urlparse(url).hostname or "").lower()\n    except Exception:\n        return ""\n\n\n_LOW_QUALITY_HOSTS = (\n    "scribd.com", "pinterest.", "quora.", "reddit.", "wisdomanswer.com",\n    "blog.welcu.com", "leukstekadotip.nl", "grokipedia.com",\n)\n\n_EPD_PROGRAM_HOSTS = (\n    "eco-platform.org", "environdec.com", "epd-global.no", "ibu-epd.com",\n    "epdhub.com", "epditaly.it", "epddanmark.dk", "aenor.com", "bregroup.com",\n    "igbc.ie", "bau-epd.at", "daphabitat.pt", "globalgreentag.com",\n    "epd-australasia.com", "ul.com",\n)\n\n_PEER_REVIEWED_HOSTS = (\n    "sciencedirect.com", "springer.com", "springeropen.com", "wiley.com",\n    "tandfonline.com", "mdpi.com", "sagepub.com", "nature.com",\n)\n\n_TECHNICAL_DATABASE_HOSTS = (\n    "buildingtransparency.org", "carbonleadershipforum.org", "nrmca.org",\n    "athenasmi.org", "cerib.com", "ice.org.uk",\n)\n\n\ndef _normalize_text(text: str) -> str:\n    return re.sub(r"\\s+", " ", _clean(text)).strip().lower()\n\n\ndef _source_quality(candidate: dict[str, Any]) -> tuple[bool, str]:\n    host = _url_host(candidate.get("url", ""))\n    evidence = _normalize_text(\n        f"{candidate.get(\'title\',\'\')} {candidate.get(\'snippet\',\'\')} {candidate.get(\'excerpt\',\'\')}"\n    )\n    if not host:\n        return False, "UNKNOWN_SOURCE"\n    if any(bad in host for bad in _LOW_QUALITY_HOSTS):\n        return False, "LOW_QUALITY_WEB"\n    if any(host == h or host.endswith(\'.\' + h) for h in _EPD_PROGRAM_HOSTS):\n        return True, "VERIFIED_EPD_PROGRAM"\n    if host.endswith(".gov.np") or host == "gov.np":\n        return True, "NEPAL_GOVERNMENT"\n    if ".gov." in host or host.endswith(".gov"):\n        return True, "GOVERNMENT"\n    if ".edu." in host or host.endswith(".edu") or ".ac." in host:\n        return True, "ACADEMIC"\n    if any(host == h or host.endswith(\'.\' + h) for h in _PEER_REVIEWED_HOSTS):\n        return True, "PEER_REVIEWED_PUBLICATION"\n    if any(host == h or host.endswith(\'.\' + h) for h in _TECHNICAL_DATABASE_HOSTS):\n        return True, "TECHNICAL_LCA_DATABASE"\n    # A manufacturer-hosted EPD can be useful, but require strong EPD/EN15804 markers.\n    if (\n        "environmental product declaration" in evidence\n        and ("en 15804" in evidence or "iso 14025" in evidence)\n        and ("verified" in evidence or "verification" in evidence or "epd" in evidence)\n    ):\n        return True, "MANUFACTURER_EPD"\n    return False, "UNVERIFIED_WEB_SOURCE"\n\n\ndef _infer_geography(candidate: dict[str, Any]) -> str:\n    host = _url_host(candidate.get("url", ""))\n    evidence = _normalize_text(\n        f"{candidate.get(\'title\',\'\')} {candidate.get(\'snippet\',\'\')} {candidate.get(\'excerpt\',\'\')}"\n    )\n    checks = [\n        ("Nepal", ("nepal",), (".np",)),\n        ("India", ("india",), (".in",)),\n        ("Bangladesh", ("bangladesh",), (".bd",)),\n        ("Sri Lanka", ("sri lanka",), (".lk",)),\n        ("Pakistan", ("pakistan",), (".pk",)),\n        ("Bhutan", ("bhutan",), (".bt",)),\n        ("China", ("china",), (".cn",)),\n        ("Japan", ("japan",), (".jp",)),\n        ("Australia", ("australia",), (".au",)),\n        ("United Kingdom", ("united kingdom", " uk "), (".uk",)),\n        ("United States", ("united states", " usa ", " u.s. "), (".us",)),\n        ("Canada", ("canada", " canadian "), (".ca",)),\n        ("Germany", ("germany",), (".de",)),\n        ("Norway", ("norway",), (".no",)),\n    ]\n    padded = f" {evidence} "\n    for geo, words, suffixes in checks:\n        if any(w in padded for w in words) or any(host.endswith(s) for s in suffixes):\n            return geo\n    if "north america" in evidence:\n        return "North America"\n    if "global" in evidence or "worldwide" in evidence:\n        return "Global"\n    return "Unspecified"\n\n\ndef _tier_geography_ok(tier: str, geography: str) -> bool:\n    if tier == "NEPAL":\n        return geography == "Nepal"\n    if tier == "SOUTH_ASIA":\n        return geography in {"Nepal", "India", "Bangladesh", "Sri Lanka", "Pakistan", "Bhutan"}\n    if tier == "ASIA":\n        return geography in {\n            "Nepal", "India", "Bangladesh", "Sri Lanka", "Pakistan", "Bhutan",\n            "China", "Japan",\n        }\n    return True\n\n\ndef _target_geography_supported(candidate: dict[str, Any], target_geography: str) -> bool:\n    """Return True only when the retrieved source itself supports the target geography.\n\n    This is the Class-3 geography gate. Search-query wording is deliberately\n    ignored so a query containing the target country cannot make a foreign or\n    global source appear local. The relaxed External Verified phase does NOT use this gate.\n    """\n    target = _normalize_text(target_geography)\n    if not target:\n        return False\n    inferred = _normalize_text(_infer_geography(candidate))\n    if inferred and inferred != "unspecified" and inferred == target:\n        return True\n\n    evidence = _normalize_text(\n        f"{candidate.get(\'title\',\'\')} {candidate.get(\'snippet\',\'\')} {candidate.get(\'excerpt\',\'\')}"\n    )\n    host = _url_host(candidate.get(\'url\', \'\'))\n    padded = f" {evidence} "\n\n    aliases = {\n        "nepal": ("nepal",),\n        "india": ("india",),\n        "bangladesh": ("bangladesh",),\n        "sri lanka": ("sri lanka",),\n        "pakistan": ("pakistan",),\n        "bhutan": ("bhutan",),\n        "china": ("china",),\n        "japan": ("japan",),\n        "australia": ("australia",),\n        "united kingdom": ("united kingdom", " uk "),\n        "united states": ("united states", " usa ", " u.s. "),\n        "germany": ("germany",),\n        "norway": ("norway",),\n    }\n    if any(a in padded for a in aliases.get(target, (target,))):\n        return True\n\n    suffixes = {\n        "nepal": ".np", "india": ".in", "bangladesh": ".bd",\n        "sri lanka": ".lk", "pakistan": ".pk", "bhutan": ".bt",\n        "china": ".cn", "japan": ".jp", "australia": ".au",\n        "united kingdom": ".uk", "united states": ".us",\n        "germany": ".de", "norway": ".no",\n    }\n    suffix = suffixes.get(target)\n    return bool(suffix and host.endswith(suffix))\n\n\ndef _quote_supported(quote: str, candidate: dict[str, Any]) -> bool:\n    q = _normalize_text(quote)\n    if not q:\n        return False\n    evidence = _normalize_text(f"{candidate.get(\'snippet\',\'\')} {candidate.get(\'excerpt\',\'\')}")\n    return q in evidence\n\n\ndef _requires_no_biogenic_storage(material: str) -> bool:\n    return classify_material(material) in BIOGENIC_STORAGE_EXCLUDED_FAMILIES\n\n\ndef _required_indicator_policy(material: str) -> str:\n    return "GWP-GHG_NO_BIOGENIC_STORAGE" if _requires_no_biogenic_storage(material) else "GWP-total"\n\n\ndef _biogenic_generic_gwp_is_separate_from_storage(indicator: str, source_text: str) -> bool:\n    """Allow a positive generic GWP row only when the source distinguishes biogenic GWP.\n\n    This is an indicator-structure rule, not a material value. It is useful for\n    EPDs that publish a conventional GWP row plus a separate GWPBIO / biogenic-CO2\n    row rather than the newer GWP-GHG or GWP-fossil labels.\n    """\n    ind = _normalize_text(indicator).replace("–", "-").replace("—", "-")\n    compact_ind = re.sub(r"[\\s_-]+", "", ind)\n    if not ("gwp" in ind or "global warming" in ind or "climate change" in ind):\n        return False\n    if any(x in compact_ind for x in ("gwptotal", "gwpbiogenic", "gwpbio", "gwpluluc")):\n        return False\n    if "fossil" in ind:\n        return False\n    src = _normalize_text(source_text).replace("–", "-").replace("—", "-")\n    compact_src = re.sub(r"[\\s_-]+", "", src)\n    separate_biogenic = (\n        "gwpbiogenic" in compact_src\n        or "gwpbio" in compact_src\n        or "withbiogenicco2" in compact_src\n        or "w/biogenicco2" in compact_src\n    )\n    return separate_biogenic\n\n\ndef _indicator_component_flags(text: str) -> set[str]:\n    """Classify explicit GWP component labels without using any numeric priors.\n\n    The earlier parser could miss labels such as ``Climate change (GWP) -\n    biogenic`` because punctuation sat between ``GWP`` and ``biogenic``.  This\n    helper deliberately inspects normalized words instead of one fragile compact\n    substring, so component rows cannot masquerade as GWP-total.\n    """\n    t = _normalize_text(text).replace("_", "-").replace("–", "-").replace("—", "-")\n    compact = re.sub(r"[^a-z0-9]+", "", t)\n    flags: set[str] = set()\n    if "biogenic" in t or "gwpbio" in compact:\n        flags.add("BIOGENIC")\n    if "luluc" in t or "land use and land use change" in t or "land-use and land-use change" in t:\n        flags.add("LULUC")\n    if "fossil" in t:\n        flags.add("FOSSIL")\n    if "gwp-ghg" in t or "gwp ghg" in t or "gwpghg" in compact:\n        flags.add("GHG")\n    if "gwp-total" in t or "gwp total" in t or "gwptotal" in compact or "climate change - total" in t or "climate change total" in t:\n        flags.add("TOTAL")\n    return flags\n\n\ndef _gwp_indicator_ok(indicator: str, material: str = "", source_text: str = "") -> bool:\n    t = _normalize_text(indicator).replace("_", "-").replace("–", "-").replace("—", "-")\n    if not t or not ("gwp" in t or "global warming" in t or "climate change" in t):\n        return False\n    flags = _indicator_component_flags(t)\n    if _requires_no_biogenic_storage(material):\n        # GWP-GHG is preferred; explicit fossil climate change is the allowed\n        # conservative fallback. A biogenic or LULUC component is never accepted.\n        if "BIOGENIC" in flags or "LULUC" in flags:\n            return False\n        if "GHG" in flags or "FOSSIL" in flags:\n            return True\n        return _biogenic_generic_gwp_is_separate_from_storage(indicator, source_text)\n\n    # Ordinary materials require the total/generic climate-change result. Reject\n    # explicit component rows regardless of punctuation or row naming style.\n    if flags & {"BIOGENIC", "LULUC", "FOSSIL"}:\n        return False\n    return True\n\n\ndef _boundary_ok(boundary: str) -> bool:\n    """Accept explicit A1-A3 or an unambiguously product-stage/cradle-to-gate basis.\n\n    This is intentionally a little more permissive than the previous version so\n    credible external datasets/literature are not discarded merely because they\n    write "cradle-to-gate" instead of the EN 15804 module label. Broader life-cycle\n    boundaries remain excluded.\n    """\n    t = _normalize_text(boundary).replace("–", "-").replace("—", "-")\n    compact = re.sub(r"\\s+", "", t)\n    if any(x in t for x in ("cradle-to-grave", "cradle to grave", "whole life", "a1-a5", "a1 to a5", "a1-c", "a1 to c")):\n        return False\n    if "a1-a3" in compact or "a1to a3" in t or "a1 to a3" in t:\n        return True\n    return any(x in t for x in (\n        "cradle-to-gate", "cradle to gate", "product stage", "product-stage",\n        "production stage", "manufacturing stage", "factory gate",\n    ))\n\n\ndef _impact_to_kg_co2e(value: float, unit: str) -> float | None:\n    u = _normalize_text(unit).replace("₂", "2")\n    u = u.replace("co₂", "co2")\n    if "kg" in u and ("co2" in u or "co₂" in unit.lower()):\n        return value\n    if ("tonne" in u or re.search(r"\\bt\\b", u)) and ("co2" in u or "co₂" in unit.lower()):\n        return value * 1000.0\n    if "g" in u and "kg" not in u and ("co2" in u or "co₂" in unit.lower()):\n        return value / 1000.0\n    return None\n\n\ndef _normalize_declared_unit(unit: str) -> str:\n    u = norm_unit(unit)\n    aliases = {\n        "unit": "item", "each": "item", "piece": "item", "pcs": "item",\n        "ton": "t", "tonne": "t", "metrictonne": "t",\n    }\n    return aliases.get(u, u)\n\n\ndef normalize_factor(impact_value: float, impact_unit: str, declared_quantity: float, declared_unit: str):\n    impact_kg = _impact_to_kg_co2e(impact_value, impact_unit)\n    if impact_kg is None:\n        return None\n    q = _num(declared_quantity)\n    if q is None or q <= 0:\n        return None\n    ref = _normalize_declared_unit(declared_unit)\n    if ref not in {"kg", "g", "t", "m3", "m2", "item"}:\n        return None\n    return impact_kg / q, ref\n\n\ndef _material_family(material: str) -> str:\n    m = _normalize_text(material)\n    if any(x in m for x in ("steel", "iron", "nail", "binding wire", "rebar", "galvanized", "galvanised", "cgi", "metal sheet", "corrugated")):\n        return "METAL"\n    if any(x in m for x in ("plywood", "timber", "wood", "bamboo")):\n        return "BIO_BASED"\n    if any(x in m for x in ("soil", "earth", "mud", "stone", "gravel", "sand", "aggregate", "rock")):\n        return "MINERAL_EARTH"\n    return "OTHER"\n\n\ndef _llm_fallback_plausible(material: str, ef: float, ref: str, lower: float | None, upper: float | None) -> tuple[bool, str]:\n    """Deterministic structural QA for an UNVERIFIED estimate.\n\n    No material-specific expected emission factor or numeric range is encoded\n    here. The guard checks only sign, interval consistency, and reference-unit\n    compatibility. Unverified estimates remain clearly separated from the\n    traceable subtotal.\n    """\n    if ef <= 0:\n        return False, "nonpositive_unverified_a1a3_factor_not_allowed"\n    if lower is not None and lower < 0:\n        return False, "negative_unverified_lower_bound_not_allowed"\n    if upper is not None and upper < 0:\n        return False, "negative_unverified_upper_bound_not_allowed"\n    if lower is not None and upper is not None and lower > upper:\n        return False, "lower_bound_greater_than_upper_bound"\n    if lower is not None and ef < lower:\n        return False, "base_value_below_lower_bound"\n    if upper is not None and ef > upper:\n        return False, "base_value_above_upper_bound"\n    unit_ok, unit_reason = _reference_unit_compatible(material, ref)\n    if not unit_ok:\n        return False, unit_reason\n    return True, "ok"\n\ndef _focus_lca_text(text: str, max_chars: int = 12000) -> str:\n    """Keep multiple high-value windows around EPD/LCA result tables.\n\n    This is material-agnostic: it searches only for environmental-result and\n    declared-unit vocabulary, never for a prescribed factor value.\n    """\n    cleaned = re.sub(r"\\s+", " ", text or "").strip()\n    if not cleaned:\n        return ""\n    low = cleaned.lower().replace("–", "-").replace("—", "-")\n    needles = [\n        "declared unit", "functional unit", "reference flow", "declared unit mass",\n        "a1-a3", "a1 a3", "a1", "a2", "a3", "gwp-total", "gwp fossil",\n        "gwp-fossil", "gwp-ghg", "global warming", "climate change",\n        "environmental data summary", "environmental impact", "kg co2", "kgco2",\n        "cradle-to-gate", "cradle to gate",\n    ]\n    centers = []\n    for needle in needles:\n        start = 0\n        while len(centers) < 24:\n            i = low.find(needle, start)\n            if i < 0:\n                break\n            centers.append(i)\n            start = i + len(needle)\n    if not centers:\n        return cleaned[:max_chars]\n    pieces = []\n    for i in sorted(set(centers))[:18]:\n        a = max(0, i - 650)\n        b = min(len(cleaned), i + 1400)\n        pieces.append(cleaned[a:b])\n    return " ... ".join(pieces)[:max_chars]\n\n\n\n\n_GWP_TEXT_SIGNALS = (\n    "gwp", "global warming potential", "global warming", "climate change",\n)\n_GWP_FOSSIL_SIGNALS = (\n    "gwp-ghg", "gwp ghg", "gwp-fossil", "gwp fossil",\n    "climate change - fossil", "climate change fossil",\n)\n\n\ndef _has_gwp_signal(text: str) -> bool:\n    low = _normalize_text(text).replace("–", "-").replace("—", "-")\n    return any(term in low for term in _GWP_TEXT_SIGNALS)\n\n\ndef _gwp_page_score(text: str) -> int:\n    """Rank PDF pages using only GWP/schema vocabulary, never factor values."""\n    low = _normalize_text(text).replace("–", "-").replace("—", "-")\n    if not low:\n        return 0\n    score = 0\n    if "gwp" in low:\n        score += 8\n    if "global warming" in low:\n        score += 7\n    if "climate change" in low:\n        score += 6\n    if all(x in low for x in ("a1", "a2", "a3")):\n        score += 6\n    elif any(x in low for x in ("a1-a3", "a1 a3", "cradle-to-gate", "cradle to gate")):\n        score += 5\n    if any(x in low for x in ("declared unit", "functional unit", "reference unit", "reference flow")):\n        score += 3\n    if "kg co2" in low or "kgco2" in low:\n        score += 2\n    if any(x in low for x in ("environmental impact", "lcia", "impact assessment", "environmental data summary")):\n        score += 2\n    return score\n\n\ndef _focus_gwp_lines(text: str, max_chars: int = 10000) -> str:\n    """Preserve line/table order around GWP and A1-A3 evidence."""\n    raw = (text or "").replace("\\x00", " ").replace("\\r\\n", "\\n").replace("\\r", "\\n")\n    lines = [re.sub(r"[ \\t]+", " ", line).strip() for line in raw.split("\\n")]\n    lines = [line for line in lines if line]\n    if not lines:\n        return ""\n    centers = []\n    for i, line in enumerate(lines):\n        low = _normalize_text(line).replace("–", "-").replace("—", "-")\n        if (_has_gwp_signal(low)\n                or any(x in low for x in ("a1-a3", "a1 a3", "declared unit", "functional unit", "reference unit"))\n                or ("a1" in low and "a2" in low and "a3" in low)):\n            centers.append(i)\n    if not centers:\n        return _focus_lca_text("\\n".join(lines), max_chars=max_chars)\n    keep = set()\n    for i in centers[:24]:\n        for j in range(max(0, i - 5), min(len(lines), i + 7)):\n            keep.add(j)\n    out = []\n    last = None\n    for j in sorted(keep):\n        if last is not None and j > last + 1:\n            out.append("...")\n        out.append(lines[j])\n        last = j\n    return "\\n".join(out)[:max_chars]\n\n\ndef _normalize_table_cell(value: Any) -> str:\n    if value is None:\n        return ""\n    return re.sub(r"\\s+", " ", str(value)).strip()\n\n\ndef _table_to_gwp_text(table: Any, page_number: int) -> str:\n    """Render only GWP-relevant table structure as auditable plain text."""\n    if not isinstance(table, list) or not table:\n        return ""\n    rows = []\n    for row in table:\n        if not isinstance(row, (list, tuple)):\n            continue\n        cells = [_normalize_table_cell(x) for x in row]\n        if any(cells):\n            rows.append(cells)\n    if not rows:\n        return ""\n    row_text = [" | ".join(r) for r in rows]\n    whole = "\\n".join(row_text)\n    if not _has_gwp_signal(whole):\n        return ""\n    selected = set()\n    for i, line in enumerate(row_text):\n        low = _normalize_text(line).replace("–", "-").replace("—", "-")\n        is_header = (\n            ("a1" in low and "a2" in low and "a3" in low)\n            or ("indicator" in low and "unit" in low)\n            or any(x in low for x in ("declared unit", "functional unit", "reference unit", "reference flow"))\n        )\n        if _has_gwp_signal(low) or is_header:\n            selected.add(i)\n    if not selected:\n        return ""\n    lines = [f"[PDF TABLE PAGE {page_number}]" ]\n    lines.extend(row_text[i] for i in sorted(selected))\n    return "\\n".join(lines)\n\n\ndef _extract_pdf_gwp_evidence(content: bytes, page_limit: int, max_chars: int = 24000) -> str:\n    """Extract GWP-only evidence from a PDF while preserving table/module structure.\n\n    No OCR and no material-specific values are used. pypdf provides page text and\n    pdfplumber is used only on GWP-relevant pages to preserve tabular A1/A2/A3 data.\n    """\n    if not content or not content.lstrip().startswith(b"%PDF"):\n        return ""\n    try:\n        import logging\n        logging.getLogger("pypdf").setLevel(logging.ERROR)\n        from pypdf import PdfReader\n        reader = PdfReader(io.BytesIO(content), strict=False)\n    except Exception:\n        return ""\n\n    count = min(len(reader.pages), max(1, int(page_limit)))\n    page_texts: list[str] = []\n    scored: list[tuple[int, int]] = []\n    for i in range(count):\n        try:\n            txt = reader.pages[i].extract_text() or ""\n        except Exception:\n            txt = ""\n        page_texts.append(txt)\n        scored.append((_gwp_page_score(txt), i))\n\n    target_indices = [i for score, i in sorted(scored, reverse=True) if score > 0][:12]\n\n    # If pypdf did not expose the relevant labels, use pdfplumber text as a\n    # secondary non-OCR page detector before giving up.\n    plumber = None\n    try:\n        import pdfplumber\n        plumber = pdfplumber.open(io.BytesIO(content))\n        if not target_indices:\n            alt_scores = []\n            for i in range(min(len(plumber.pages), count)):\n                try:\n                    txt = plumber.pages[i].extract_text(x_tolerance=2, y_tolerance=3) or ""\n                except Exception:\n                    txt = ""\n                if txt and not page_texts[i]:\n                    page_texts[i] = txt\n                alt_scores.append((_gwp_page_score(txt), i))\n            target_indices = [i for score, i in sorted(alt_scores, reverse=True) if score > 0][:12]\n    except Exception:\n        plumber = None\n\n    if not target_indices:\n        target_indices = list(range(min(count, 6)))\n\n    table_blocks = []\n    page_blocks = []\n    for i in sorted(set(target_indices)):\n        txt = page_texts[i] if i < len(page_texts) else ""\n        focused = _focus_gwp_lines(txt, max_chars=7000)\n        if focused:\n            page_blocks.append(f"[PDF PAGE {i+1}]\\n{focused}")\n        if plumber is not None and i < len(plumber.pages):\n            try:\n                tables = plumber.pages[i].extract_tables() or []\n            except Exception:\n                tables = []\n            for table in tables[:8]:\n                block = _table_to_gwp_text(table, i + 1)\n                if block:\n                    table_blocks.append(block)\n\n    if plumber is not None:\n        try:\n            plumber.close()\n        except Exception:\n            pass\n\n    # Tables go first so the bounded excerpt passed to Qwen keeps A1/A2/A3\n    # columns even when the PDF contains a lot of narrative text.\n    combined = "\\n\\n".join(table_blocks + page_blocks)\n    if not combined:\n        combined = _focus_gwp_lines("\\n".join(page_texts), max_chars=max_chars)\n    return combined[:max_chars]\n\n\n\n\ndef _pdf_table_blocks(text: str) -> list[str]:\n    """Return table blocks emitted by the GWP-focused PDF reader."""\n    raw = text or ""\n    starts = [m.start() for m in re.finditer(r"(?m)^\\[PDF TABLE PAGE \\d+\\]\\s*$", raw)]\n    blocks: list[str] = []\n    for i, start in enumerate(starts):\n        end = starts[i + 1] if i + 1 < len(starts) else len(raw)\n        # Stop before the first non-table page block when present.\n        chunk = raw[start:end]\n        page_marker = re.search(r"(?m)^\\[PDF PAGE \\d+\\]\\s*$", chunk)\n        if page_marker:\n            chunk = chunk[:page_marker.start()]\n        chunk = chunk.strip()\n        if chunk:\n            blocks.append(chunk)\n    return blocks\n\n\ndef _table_rows_from_block(block: str) -> list[list[str]]:\n    rows: list[list[str]] = []\n    for line in (block or "").splitlines():\n        line = line.strip()\n        if not line or line.startswith("[PDF TABLE PAGE"):\n            continue\n        if "|" not in line:\n            continue\n        cells = [_normalize_table_cell(x) for x in line.split("|")]\n        if any(cells):\n            rows.append(cells)\n    return rows\n\n\ndef _module_label(cell: str) -> str | None:\n    t = _normalize_text(cell).replace("–", "-").replace("—", "-")\n    compact = re.sub(r"\\s+", "", t)\n    if re.fullmatch(r"a1(?:-|to)a3", compact):\n        return "A1-A3"\n    if compact == "a1":\n        return "A1"\n    if compact == "a2":\n        return "A2"\n    if compact == "a3":\n        return "A3"\n    return None\n\n\ndef _indicator_row_score(cells: list[str], material: str, source_text: str = "") -> int:\n    text = " | ".join(cells)\n    low = _normalize_text(text).replace("–", "-").replace("—", "-")\n    if not _has_gwp_signal(low) or not _gwp_indicator_ok(text, material, source_text):\n        return -1\n    flags = _indicator_component_flags(low)\n    if _requires_no_biogenic_storage(material):\n        if "GHG" in flags:\n            return 100\n        if "FOSSIL" in flags:\n            return 90\n        if _biogenic_generic_gwp_is_separate_from_storage(text, source_text):\n            return 70\n        return -1\n    if "TOTAL" in flags:\n        return 100\n    if "global warming potential" in low:\n        return 95\n    if "climate change" in low:\n        return 90\n    if "gwp" in low:\n        return 85\n    return -1\n\n\ndef _parse_first_numeric(cell: str) -> float | None:\n    for token in re.findall(_SCI_NUM, cell or ""):\n        v = _parse_decimal_token(token)\n        if v is not None and math.isfinite(v):\n            return float(v)\n    return None\n\n\ndef _impact_unit_from_text(text: str) -> tuple[str | None, str | None]:\n    """Return normalized impact unit plus optional declared-unit denominator.\n\n    This parses unit syntax only; it does not contain any material-specific factor.\n    """\n    t = (text or "").replace("CO₂", "CO2").replace("co₂", "co2").replace("m³", "m3").replace("m²", "m2")\n    low = _normalize_text(t)\n    if "co2" not in low:\n        return None, None\n    if re.search(r"\\bkg\\s*co2", low):\n        impact = "kg CO2e"\n    elif re.search(r"(?:^|\\W)g\\s*co2", low):\n        impact = "g CO2e"\n    elif re.search(r"\\b(?:t|tonne|ton)\\s*co2", low):\n        impact = "t CO2e"\n    else:\n        return None, None\n\n    denom = None\n    patterns = [\n        r"(?:/|per\\s+)(kg|g|t|tonne|ton|m3|m2|item|piece|each|unit)\\b",\n        r"co2(?:e|\\s*eq(?:uivalent)?)?\\s*(?:/|per\\s+)(kg|g|t|tonne|ton|m3|m2|item|piece|each|unit)\\b",\n    ]\n    for pat in patterns:\n        m = re.search(pat, low)\n        if m:\n            denom = _normalize_declared_unit(m.group(1))\n            break\n    return impact, denom\n\n\ndef _declared_basis_from_evidence(text: str) -> tuple[float | None, str | None]:\n    """Extract only an explicitly stated declared/reference quantity and unit."""\n    normalized = (text or "").replace("m³", "m3").replace("m²", "m2")\n    # Prefer explicit declared/functional/reference basis statements.\n    patterns = [\n        rf"(?:declared|functional|reference)\\s+(?:unit|flow)\\s*(?:is|:|=|-)?\\s*({_SCI_NUM})?\\s*(kg|g|t|tonne|ton|m3|m2|item|piece|each|unit)\\b",\n        rf"(?:declared|functional|reference)\\s+(?:unit|flow).*?({_SCI_NUM})\\s*(kg|g|t|tonne|ton|m3|m2|item|piece|each|unit)\\b",\n    ]\n    for pat in patterns:\n        m = re.search(pat, normalized, flags=re.I | re.S)\n        if not m:\n            continue\n        q = _parse_decimal_token(m.group(1)) if m.group(1) else 1.0\n        u = _normalize_declared_unit(m.group(2))\n        if q is not None and q > 0 and u in {"kg", "g", "t", "m3", "m2", "item"}:\n            return float(q), u\n    return None, None\n\n\ndef _indicator_name_from_row(cells: list[str]) -> str:\n    for cell in cells:\n        if _has_gwp_signal(cell):\n            return cell.strip()\n    return "GWP"\n\n\ndef _deterministic_gwp_table_record(material: str, candidate: dict[str, Any]) -> tuple[dict[str, Any] | None, str]:\n    """Parse a structured retrieved EPD table before asking the LLM.\n\n    The parser is deliberately schema-driven and GWP-only. It never contains or\n    supplies a material-specific GWP value. It accepts an explicit A1-A3 total,\n    or explicit A1, A2 and A3 module cells and lets Python sum those source values.\n    """\n    full = _clean(candidate.get("full_text")) or _candidate_evidence_text(candidate)\n    blocks = _pdf_table_blocks(full)\n    if not blocks:\n        return None, "no_structured_pdf_table"\n\n    declared_q, declared_u = _declared_basis_from_evidence(full)\n    best: tuple[int, dict[str, Any]] | None = None\n\n    for block in blocks:\n        raw_rows = _table_rows_from_block(block)\n        if len(raw_rows) < 2:\n            continue\n\n        # pdfplumber sometimes emits visual spacer columns as empty cells. Try\n        # both the raw matrix and a compacted matrix with empty spacer cells\n        # removed; no numeric values are invented or reordered within a row.\n        row_variants = [raw_rows]\n        compact_rows = [[c for c in row if c] for row in raw_rows]\n        if compact_rows != raw_rows:\n            row_variants.append(compact_rows)\n\n        for rows in row_variants:\n            # Find a header row carrying product-stage module labels. A table may\n            # have multiple header rows, so use the row with the most module labels.\n            header_idx = None\n            header_map: dict[str, int] = {}\n            for r_i, row in enumerate(rows):\n                local: dict[str, int] = {}\n                for c_i, cell in enumerate(row):\n                    label = _module_label(cell)\n                    if label:\n                        local[label] = c_i\n                if len(local) > len(header_map):\n                    header_map = local\n                    header_idx = r_i\n            if not header_map:\n                continue\n\n            for r_i, row in enumerate(rows):\n                if r_i == header_idx:\n                    continue\n                score = _indicator_row_score(row, material, full)\n                if score < 0:\n                    continue\n\n                impact_unit = None\n                denominator = None\n                for cell in row:\n                    iu, den = _impact_unit_from_text(cell)\n                    if iu:\n                        impact_unit = iu\n                        denominator = den\n                        break\n                if impact_unit is None:\n                    # Occasionally the unit is placed in a separate header row.\n                    for hrow in rows[: max(1, (header_idx or 0) + 1)]:\n                        for cell in hrow:\n                            iu, den = _impact_unit_from_text(cell)\n                            if iu:\n                                impact_unit = iu\n                                denominator = den\n                                break\n                        if impact_unit:\n                            break\n                if impact_unit is None:\n                    continue\n\n                dq, du = declared_q, declared_u\n                if denominator:\n                    dq, du = 1.0, denominator\n                if dq is None or du is None:\n                    continue\n\n                indicator = _indicator_name_from_row(row)\n                rec: dict[str, Any] | None = None\n                if "A1-A3" in header_map:\n                    idx = header_map["A1-A3"]\n                    if idx < len(row):\n                        total = _parse_first_numeric(row[idx])\n                        if total is not None:\n                            rec = {\n                                "source_result_id": candidate.get("result_id"),\n                                "found": True,\n                                "value_mode": "TOTAL",\n                                "impact_value": total,\n                                "a1_value": None, "a2_value": None, "a3_value": None,\n                                "impact_unit": impact_unit,\n                                "declared_quantity": dq,\n                                "declared_unit": du,\n                                "boundary": "A1-A3",\n                                "indicator": indicator,\n                                "source_year": "",\n                                "evidence_quote": block,\n                                "reason": "Deterministic GWP table parser extracted an explicit A1-A3 source value.",\n                                "extraction_method": "DETERMINISTIC_GWP_TABLE_A1_A3_TOTAL",\n                            }\n                elif all(k in header_map for k in ("A1", "A2", "A3")):\n                    vals = []\n                    ok = True\n                    for k in ("A1", "A2", "A3"):\n                        idx = header_map[k]\n                        if idx >= len(row):\n                            ok = False\n                            break\n                        v = _parse_first_numeric(row[idx])\n                        if v is None:\n                            ok = False\n                            break\n                        vals.append(v)\n                    if ok:\n                        rec = {\n                            "source_result_id": candidate.get("result_id"),\n                            "found": True,\n                            "value_mode": "SUM_A1_A2_A3",\n                            "impact_value": None,\n                            "a1_value": vals[0], "a2_value": vals[1], "a3_value": vals[2],\n                            "impact_unit": impact_unit,\n                            "declared_quantity": dq,\n                            "declared_unit": du,\n                            "boundary": "A1+A2+A3",\n                            "indicator": indicator,\n                            "source_year": "",\n                            "evidence_quote": block,\n                            "reason": "Deterministic GWP table parser extracted explicit A1, A2 and A3 source values; Python will sum them.",\n                            "extraction_method": "DETERMINISTIC_GWP_TABLE_A1_A2_A3",\n                        }\n                if rec is not None and (best is None or score > best[0]):\n                    best = (score, rec)\n\n    if best is None:\n        return None, "no_usable_gwp_a1_a3_table_record"\n    return best[1], "ok"\n\ndef _family_search_term(material: str) -> str | None:\n    """Return a generic taxonomy-family phrase for query expansion.\n\n    This is a search vocabulary only. It contains no emission factor, source URL,\n    manufacturer, EPD identifier, or predetermined answer.\n    """\n    family = classify_material(material)\n    if family == "UNKNOWN":\n        return None\n    return family.lower().replace("_", " ")\n\n\ndef _query_sets(material: str, target_geography: str):\n    """Build broad live-search plans without preselecting any source or factor."""\n    m = material.strip()\n    family_term = _family_search_term(material)\n\n    def direct_queries(geo_label: str, geo_term: str) -> list[str]:\n        q = [\n            f\'"{m}" "A1-A3" GWP {geo_term} EPD\',\n            f\'"{m}" "GWP-total" "declared unit" {geo_term}\',\n            f\'"{m}" "environmental product declaration" {geo_term} filetype:pdf\',\n            f\'"{m}" "cradle-to-gate" "kg CO2" {geo_term}\',\n        ]\n        if geo_label == "GLOBAL":\n            q.extend([\n                f\'site:environdec.com/library "{m}"\',\n                f\'site:manage.epdhub.com "{m}" EPD\',\n                f\'"{m}" EPD "environmental data summary"\',\n            ])\n        return q\n\n    geo_terms = {\n        "NEPAL": target_geography,\n        "SOUTH_ASIA": "India OR South Asia",\n        "ASIA": "Asia",\n        "GLOBAL": "",\n    }\n    for tier in ("NEPAL", "SOUTH_ASIA", "ASIA", "GLOBAL"):\n        yield tier, "DIRECT_PRODUCT", None, direct_queries(tier, geo_terms[tier])\n        if family_term and _normalize_text(family_term) != _normalize_text(m):\n            fq = [\n                f\'"{family_term}" "A1-A3" GWP {geo_terms[tier]} EPD\',\n                f\'"{family_term}" "GWP-total" "declared unit" {geo_terms[tier]}\',\n                f\'"{family_term}" "environmental product declaration" {geo_terms[tier]} filetype:pdf\',\n            ]\n            yield tier, "PRODUCT_PROXY", f"Taxonomy-family query expansion: {family_term}", fq\n\ndef _strip_html(raw: str) -> str:\n    import html as _html\n    s = re.sub(r"(?is)<script.*?>.*?</script>", " ", raw or "")\n    s = re.sub(r"(?is)<style.*?>.*?</style>", " ", s)\n    s = re.sub(r"(?s)<[^>]+>", " ", s)\n    s = _html.unescape(s)\n    return re.sub(r"\\s+", " ", s).strip()\n\n\ndef _parse_decimal_token(token: str) -> float | None:\n    s = _clean(token).replace("−", "-").replace("–", "-")\n    if not s:\n        return None\n    if "," in s and "." not in s:\n        s = s.replace(",", ".")\n    else:\n        s = s.replace(",", "")\n    try:\n        x = float(s)\n    except Exception:\n        return None\n    return x if math.isfinite(x) else None\n\n\n_SCI_NUM = r"[-+]?(?:\\d+(?:[.,]\\d*)?|\\.\\d+)(?:[Ee][-+]?\\d+)?"\n\n\ndef _candidate_evidence_text(candidate: dict[str, Any]) -> str:\n    return " ".join([\n        _clean(candidate.get("snippet")),\n        _clean(candidate.get("excerpt")),\n    ]).strip()\n\n\ndef _source_boundary_supported(candidate: dict[str, Any]) -> bool:\n    text = _candidate_evidence_text(candidate).lower()\n    text = text.replace("–", "-").replace("—", "-")\n    compact = re.sub(r"\\s+", "", text)\n    # A valid EPD may report A1-A3 together with later modules elsewhere in the\n    # same document. Explicit product-stage evidence therefore takes precedence\n    # over the mere presence of A4/C/D terminology in another table/section.\n    if "a1-a3" in compact or bool(re.search(r"\\ba1\\s*(?:-|to)\\s*a3\\b", text)):\n        return True\n    if all(label in text for label in ("a1", "a2", "a3")):\n        return True\n    if any(term in text for term in (\n        "cradle-to-gate", "cradle to gate", "product stage", "product-stage",\n        "production stage", "manufacturing stage", "factory gate",\n    )):\n        return True\n    return False\n\n\ndef _source_indicator_supported(material: str, candidate: dict[str, Any]) -> bool:\n    text = _candidate_evidence_text(candidate).lower()\n    text = text.replace("–", "-").replace("—", "-")\n    if _requires_no_biogenic_storage(material):\n        return any(term in text for term in (\n            "gwp-ghg", "gwp ghg", "gwp-fossil", "gwp fossil",\n            "climate change - fossil", "climate change fossil",\n        ))\n    return any(term in text for term in (\n        "gwp-total", "gwp total", "global warming potential", "gwp",\n        "climate change - total", "climate change total", "climate change",\n    ))\n\n\ndef _provisional_source_allowed(candidate: dict[str, Any]) -> tuple[bool, str]:\n    """Minimum source guard for relaxed-phase Class-3 evidence.\n\n    This deliberately does not require a verified EPD/program host. It does\n    require a real retrievable host and rejects known low-quality/community\n    sources. The numerical value still has to be copied from the source and pass\n    product/unit/boundary checks before it can contribute to a relaxed-phase evidence median.\n    """\n    host = _url_host(candidate.get("url", ""))\n    if not host:\n        return False, "UNKNOWN_SOURCE"\n    if any(bad in host for bad in _LOW_QUALITY_HOSTS):\n        return False, "LOW_QUALITY_WEB"\n    strict_ok, strict_class = _source_quality(candidate)\n    if strict_ok:\n        return True, strict_class\n    return True, "SOURCE_SUPPORTED_WEB"\n\n\n\ndef _promising_class4_candidate(material: str, candidate: dict[str, Any]) -> tuple[bool, str]:\n    """Detect GWP evidence worth deeper relaxed-phase Class-3 extraction.\n\n    Geography may differ. A declaration is not rejected merely because it also\n    reports A4/C/D modules; explicit A1-A3/product-stage GWP evidence can still be\n    isolated. Broader-life-cycle wording blocks only the looser production-context\n    pathway where no explicit product-stage result is present.\n    """\n    source_ok, source_class = _provisional_source_allowed(candidate)\n    if not source_ok:\n        return False, f"source_not_allowed:{source_class}"\n    identity_ok, identity_reason = _product_identity_ok(material, candidate)\n    if not identity_ok:\n        return False, f"identity_not_supported:{identity_reason}"\n    text = _candidate_evidence_text(candidate).lower().replace("–", "-").replace("—", "-")\n    climate = any(x in text for x in ("gwp", "global warming", "climate change"))\n    product_stage = any(x in text for x in (\n        "a1-a3", "a1 a3", "cradle-to-gate", "cradle to gate", "product stage",\n        "product-stage", "production stage", "manufacturing stage", "factory gate"\n    )) or all(x in text for x in ("a1", "a2", "a3"))\n    production_context = any(x in text for x in (\n        "manufacturing", "manufacture of", "manufactured", "production of",\n        "material production", "production process", "factory production",\n        "embodied carbon", "product carbon footprint", "environmental impact of production"\n    ))\n    broader = any(x in text for x in (\n        "cradle-to-grave", "cradle to grave", "whole life", "whole-life",\n        "a1-a5", "a1 to a5", "a1-c", "a1 to c", "end of life", "end-of-life"\n    ))\n    declared_basis = any(x in text for x in (\n        "declared unit", "functional unit", "reference unit", "reference flow", "/kg", "/m2", "/m3",\n        "per kg", "per m2", "per m3"\n    ))\n    if climate and product_stage:\n        return True, "PROMISING_GWP_AND_EXPLICIT_PRODUCT_STAGE" + ("_WITH_DECLARED_BASIS" if declared_basis else "")\n    if climate and production_context and not broader:\n        return True, "PROMISING_GWP_AND_PRODUCTION_CONTEXT" + ("_WITH_DECLARED_BASIS" if declared_basis else "")\n    if broader and not product_stage:\n        return False, "broader_lifecycle_boundary_without_isolatable_product_stage"\n    return False, "insufficient_relaxed_class3_gwp_production_signals"\n\n\ndef _provisional_boundary_supported(candidate: dict[str, Any]) -> tuple[bool, str]:\n    """Relaxed-phase Class-3 boundary gate for an extracted GWP result.\n\n    Explicit A1-A3/product-stage evidence wins even if the declaration also\n    reports downstream modules elsewhere. Broader-life-cycle wording is a hard\n    rejection only when the relaxed External Verified phase relies on an inferred production context\n    rather than an isolatable product-stage result.\n    """\n    text = _candidate_evidence_text(candidate).lower()\n    text = text.replace("–", "-").replace("—", "-")\n    compact = re.sub(r"\\s+", "", text)\n    if "a1-a3" in compact or re.search(r"\\ba1\\s*(?:-|to)\\s*a3\\b", text):\n        return True, "EXPLICIT_A1_A3"\n    if all(label in text for label in ("a1", "a2", "a3")):\n        return True, "EXPLICIT_A1_A2_A3_MODULES"\n    if any(term in text for term in (\n        "cradle-to-gate", "cradle to gate", "product stage", "product-stage",\n        "production stage", "manufacturing stage", "factory gate"\n    )):\n        return True, "PRODUCT_STAGE_CRADLE_TO_GATE"\n    broader = any(term in text for term in (\n        "cradle-to-grave", "cradle to grave", "whole life", "whole-life",\n        "a1-a5", "a1 to a5", "a1-c", "a1 to c", "end of life", "end-of-life"\n    ))\n    climate = any(term in text for term in ("gwp", "global warming", "climate change"))\n    production_context = any(term in text for term in (\n        "manufacturing", "manufacture of", "manufactured", "production of",\n        "material production", "production process", "factory production",\n        "embodied carbon", "product carbon footprint", "environmental impact of production"\n    ))\n    if climate and production_context and not broader:\n        return True, "PRODUCTION_CONTEXT_INFERRED_RELAXED"\n    if broader:\n        return False, "BROADER_LIFECYCLE_WITHOUT_ISOLATABLE_PRODUCT_STAGE"\n    return False, "PRODUCT_STAGE_OR_PRODUCTION_CONTEXT_NOT_SUPPORTED"\n\n\ndef _provisional_indicator_supported(material: str, candidate: dict[str, Any]) -> bool:\n    text = _candidate_evidence_text(candidate).lower().replace("–", "-").replace("—", "-")\n    if _requires_no_biogenic_storage(material):\n        if any(term in text for term in (\n            "gwp-ghg", "gwp ghg", "gwp-fossil", "gwp fossil",\n            "climate change - fossil", "climate change fossil",\n        )):\n            return True\n        # Older declarations may publish generic GWP plus a distinct biogenic row.\n        return any(term in text for term in ("gwp", "global warming", "climate change")) and (\n            "gwpbio" in re.sub(r"[\\s_-]+", "", text)\n            or "gwpbiogenic" in re.sub(r"[\\s_-]+", "", text)\n            or "with biogenic co2" in text\n            or "w/ biogenic co2" in text\n        )\n    return any(term in text for term in (\n        "gwp", "global warming", "climate change",\n    ))\n\n\ndef _canonicalize_provisional_factor(value: float, reference_unit: str):\n    return canonical_factor_basis(value, reference_unit)\n\n\ndef _number_close_in_text(value: float, text: str) -> bool:\n    for token in re.findall(_SCI_NUM, text or ""):\n        parsed = _parse_decimal_token(token)\n        if parsed is None:\n            continue\n        tol = max(1e-9, abs(value) * 1e-6)\n        if abs(parsed - value) <= tol:\n            return True\n    return False\n\n\ndef _gwp_quote_supports_values(\n    quote: str, values: list[float], material: str, source_text: str = "", indicator: str = ""\n) -> bool:\n    """Require the copied evidence to link each number to the allowed GWP row.\n\n    For table excerpts containing several climate-change component rows, the\n    numeric value is checked on its own line whenever possible. This prevents an\n    extractor from labelling a biogenic/fossil/LULUC component as GWP-total just\n    because a different total-GWP row exists elsewhere in the same table block.\n    """\n    q = _clean(quote)\n    if not q or not _has_gwp_signal(q):\n        return False\n    if indicator and not _gwp_indicator_ok(indicator, material, source_text):\n        return False\n    for value in values:\n        if not _number_close_in_text(float(value), q):\n            return False\n        supporting = [\n            line for line in q.splitlines()\n            if _has_gwp_signal(line) and _number_close_in_text(float(value), line)\n        ]\n        if supporting and not any(_gwp_indicator_ok(line, material, source_text) for line in supporting):\n            return False\n    if _requires_no_biogenic_storage(material) and not indicator:\n        low = _normalize_text(q).replace("–", "-").replace("—", "-")\n        if not any(term in low for term in _GWP_FOSSIL_SIGNALS):\n            if not _biogenic_generic_gwp_is_separate_from_storage(q, source_text):\n                return False\n    return True\n\n\ndef _declared_value_supported(quantity: float, unit: str, candidate: dict[str, Any]) -> bool:\n    text = _candidate_evidence_text(candidate)\n    normalized = text.replace("m³", "m3").replace("m²", "m2")\n    ref = _normalize_declared_unit(unit)\n    aliases = {\n        "kg": ("kg",), "g": ("g",), "t": ("t", "tonne", "ton"),\n        "m3": ("m3", "m^3"), "m2": ("m2", "m^2"),\n        "item": ("item", "piece", "each", "unit"),\n    }.get(ref, (ref,))\n    for m in re.finditer(rf"({_SCI_NUM})\\s*([A-Za-z0-9/^³²]+)", normalized, flags=re.I):\n        q = _parse_decimal_token(m.group(1))\n        if q is None:\n            continue\n        u = _normalize_declared_unit(m.group(2))\n        if u == ref or m.group(2).lower() in aliases:\n            tol = max(1e-9, abs(quantity) * 1e-6)\n            if abs(q - quantity) <= tol:\n                return True\n    # A published intensity is often written directly as kg CO2e/kg, kg CO2e/m2,\n    # kg CO2e per m3, etc., with no explicit "1 kg" declared quantity. For the\n    # common declared_quantity=1 case, accept that denominator notation.\n    low = normalized.lower().replace("co₂", "co2")\n    if abs(float(quantity) - 1.0) <= 1e-9:\n        denominator_patterns = {\n            "kg": (r"/\\s*kg\\b", r"per\\s+kg\\b", r"kg\\s*co2e?\\s*/\\s*kg\\b"),\n            "g": (r"/\\s*g\\b", r"per\\s+g\\b"),\n            "t": (r"/\\s*(?:t|tonne|ton)\\b", r"per\\s+(?:t|tonne|ton)\\b"),\n            "m3": (r"/\\s*m3\\b", r"per\\s+m3\\b"),\n            "m2": (r"/\\s*m2\\b", r"per\\s+m2\\b"),\n            "item": (r"/\\s*(?:item|piece|unit)\\b", r"per\\s+(?:item|piece|unit)\\b"),\n        }.get(ref, ())\n        if any(re.search(p, low) for p in denominator_patterns):\n            return True\n    # Tables may put the unit before the numeric value. Require both the exact\n    # quantity and a recognized unit somewhere in the retrieved evidence.\n    return _number_close_in_text(quantity, normalized) and any(a.lower() in low for a in aliases)\n\n\ndef _impact_value_supported(value: float, unit: str, candidate: dict[str, Any]) -> bool:\n    text = _candidate_evidence_text(candidate)\n    normalized = (text.replace("CO₂", "CO2").replace("co₂", "co2")\n                      .replace("–", "-").replace("—", "-"))\n    if not _number_close_in_text(value, normalized):\n        return False\n    u = _normalize_text(unit).replace("co₂", "co2")\n    low = normalized.lower()\n    if "co2" not in u:\n        return False\n    if "kg" in u:\n        return bool(re.search(r"\\bkg\\s*co2", low))\n    if "g" in u and "kg" not in u:\n        return bool(re.search(r"(?:^|\\W)g\\s*co2", low))\n    if "tonne" in u or re.search(r"\\bt\\b", u):\n        return "tonne co2" in low or bool(re.search(r"\\bt\\s*co2", low))\n    return False\n\n\ndef _source_year_supported(year: str, candidate: dict[str, Any]) -> str:\n    y = _clean(year)\n    if not y:\n        return ""\n    if not re.fullmatch(r"20\\d{2}", y):\n        return ""\n    return y if y in _candidate_evidence_text(candidate) else ""\n\n\ndef _declared_pair_context(quantity: float, unit: str, candidate: dict[str, Any]) -> str:\n    text = re.sub(r"\\s+", " ", _candidate_evidence_text(candidate)).strip()\n    if not text:\n        return ""\n    # Find the first occurrence of the quantity token; the complete excerpt is\n    # already retained separately, so this is only a compact audit aid.\n    for m in re.finditer(_SCI_NUM, text):\n        parsed = _parse_decimal_token(m.group(0))\n        if parsed is None:\n            continue\n        tol = max(1e-9, abs(quantity) * 1e-6)\n        if abs(parsed - quantity) <= tol:\n            a=max(0,m.start()-120); b=min(len(text),m.end()+180)\n            return text[a:b]\n    return ""\n\n\ndef _query_subject(candidate: dict[str, Any]) -> str:\n    q = _clean(candidate.get("query"))\n    quoted = re.findall(r\'"([^"]+)"\', q)\n    for phrase in quoted:\n        p = _normalize_text(phrase)\n        if p in {"a1-a3", "gwp-total", "kg co2", "kg co2e"}:\n            continue\n        return phrase\n    return ""\n\n\ndef _product_identity_ok(material: str, candidate: dict[str, Any]) -> tuple[bool, str]:\n    """Conservative external-source product identity check.\n\n    The source title is checked first.  For cement, an additional evidence guard\n    rejects sources that are actually declarations for ready-mix/precast\n    concrete even when the manufacturer/company name contains the word\n    ``cement``.  This directly prevents a concrete EPD from being used as a\n    cement factor.\n    """\n    match_type = _clean(candidate.get("match_type")) or "DIRECT_PRODUCT"\n    title = _clean(candidate.get("title"))\n    ok, reason = external_title_compatibility(\n        material,\n        title,\n        match_type=match_type,\n        proxy_subject=_query_subject(candidate),\n    )\n    if not ok:\n        # EPD portals often expose a generic browser title even though the PDF\n        # itself begins with the actual declared product name. Only when the\n        # title is genuinely generic do we allow the retrieved source text to\n        # provide the identity label; a clearly different titled product is not\n        # overridden by this fallback.\n        generic_title = (\n            not title\n            or _normalize_text(title) in {"environmental product declaration", "epd", "product declaration"}\n            or _normalize_text(title).startswith("environmental product declaration -")\n        )\n        if generic_title:\n            evidence = re.sub(r"\\s+", " ", _clean(candidate.get("excerpt")))\n            # Use context around a literal material-name token when possible, so\n            # an unrelated generic EPD is not accepted merely because its tables\n            # contain generic construction vocabulary.\n            tokens = sorted(\n                {t for t in re.findall(r"[A-Za-z]{3,}", _clean(material).lower()) if t not in {"local", "commercial"}},\n                key=len, reverse=True,\n            )\n            context = ""\n            low_evidence = evidence.lower()\n            for token in tokens:\n                pos = low_evidence.find(token)\n                if pos >= 0:\n                    context = evidence[max(0, pos - 300): min(len(evidence), pos + 700)]\n                    break\n            evidence_label = context or evidence[:1000]\n            ok2, reason2 = external_title_compatibility(\n                material,\n                evidence_label,\n                match_type=match_type,\n                proxy_subject=_query_subject(candidate),\n            )\n            if ok2:\n                ok, reason = True, "generic_epd_title_source_text_" + reason2\n        if not ok:\n            return ok, reason\n\n    family = classify_material(material)\n    if family == "CEMENT" and match_type == "DIRECT_PRODUCT":\n        # Use only strong product-identity phrases here; generic discussion of\n        # concrete in a valid cement EPD is not enough to trigger rejection.\n        evidence = _normalize_text(\n            " ".join([\n                _clean(candidate.get("title")),\n                _clean(candidate.get("snippet")),\n                _clean(candidate.get("excerpt"))[:1800],\n            ])\n        )\n        downstream = (\n            "ready mix concrete", "ready mixed concrete", "ready mix concrete rmc",\n            "precast concrete", "pre cast concrete", "concrete block",\n            "masonry block", "environmental product declaration of ready mixed concrete",\n            "declared unit for the epd is 1m3 of ready mix concrete",\n            "1 m3 of ready mix concrete",\n        )\n        if any(term in evidence for term in downstream):\n            return False, "cement_source_declares_downstream_concrete_product"\n    return True, reason\n\n\ndef _reference_unit_compatible(material: str, reference_unit: str) -> tuple[bool, str]:\n    """High-specificity unit-family guard for external factors.\n\n    This is intentionally conservative and only enforces families whose\n    declared-unit expectations are strong enough to detect a wrong product\n    without guessing a conversion.\n    """\n    family = classify_material(material)\n    ref = _normalize_declared_unit(reference_unit)\n    if family == "CEMENT" and ref not in {"kg", "t"}:\n        return False, "cement_external_factor_requires_mass_reference_unit"\n    if family in {"REBAR", "STEEL_WIRE", "STEEL_FASTENER", "GALVANIZED_FLAT_STEEL"} and ref not in {"kg", "t"}:\n        return False, "metal_product_external_factor_requires_mass_reference_unit"\n    return True, "compatible"\n\n\nclass ExternalEFResolver:\n    def __init__(\n        self,\n        matcher,\n        *,\n        factor_snapshot: dict[str, Any] | None = None,\n        target_geography: str = TARGET_GEOGRAPHY,\n        allow_source_supported_provisional: bool = True,\n        allow_llm_unverified_estimate: bool = True,\n        allow_conservative_analog_estimate: bool = True,\n        search_results_per_query: int = 5,\n        extract_top_n: int = 5,\n        max_evidence_candidates: int = 5,\n        excerpt_chars: int = 6000,\n        timeout: int = 8,\n        class3_source_budget: int = 3,\n        class4_total_source_budget: int = 10,\n        max_search_queries_per_material: int = 6,\n        max_external_seconds_per_material: float = 60.0,\n        adaptive_max_search_queries_per_material: int = 12,\n        adaptive_total_source_budget: int = 10,\n        adaptive_external_seconds_per_material: float = 120.0,\n        pdf_max_pages: int = 24,\n        adaptive_pdf_max_pages: int = 60,\n        max_download_bytes: int = 15 * 1024 * 1024,\n        linked_documents_per_page: int = 1,\n        adaptive_linked_documents_per_page: int = 2,\n        progress_callback=None,\n        evidence_cache_path: str | None = None,\n    ):\n        self.matcher = matcher\n        self.factor_snapshot = factor_snapshot if isinstance(factor_snapshot, dict) else {}\n        self.target_geography = target_geography\n        self.allow_source_supported_provisional = bool(allow_source_supported_provisional)\n        self.allow_llm_unverified_estimate = bool(allow_llm_unverified_estimate)\n        self.allow_conservative_analog_estimate = bool(allow_conservative_analog_estimate)\n        self.search_results_per_query = search_results_per_query\n        self.extract_top_n = extract_top_n\n        self.max_evidence_candidates = max_evidence_candidates\n        self.excerpt_chars = excerpt_chars\n        self.timeout = int(timeout)\n        self.class3_source_budget = max(1, int(class3_source_budget))\n        self.class4_total_source_budget = max(self.class3_source_budget, int(class4_total_source_budget))\n        self.max_search_queries_per_material = max(1, int(max_search_queries_per_material))\n        self.max_external_seconds_per_material = max(5.0, float(max_external_seconds_per_material))\n        self.adaptive_max_search_queries_per_material = max(self.max_search_queries_per_material, int(adaptive_max_search_queries_per_material))\n        self.adaptive_total_source_budget = max(self.class4_total_source_budget, int(adaptive_total_source_budget))\n        self.adaptive_external_seconds_per_material = max(self.max_external_seconds_per_material, float(adaptive_external_seconds_per_material))\n        self.pdf_max_pages = max(1, int(pdf_max_pages))\n        self.adaptive_pdf_max_pages = max(self.pdf_max_pages, int(adaptive_pdf_max_pages))\n        self.max_download_bytes = max(1024 * 1024, int(max_download_bytes))\n        self.linked_documents_per_page = max(0, int(linked_documents_per_page))\n        self.adaptive_linked_documents_per_page = max(self.linked_documents_per_page, int(adaptive_linked_documents_per_page))\n        self.progress_callback = progress_callback\n        self.evidence_cache = RuntimeEvidenceCache(evidence_cache_path)\n        self._search_cache: dict[str, list[dict[str, Any]]] = {}\n        self._resolution_cache: dict[str, dict[str, Any]] = {}\n        self._last_fallback_attempts: list[dict[str, Any]] = []\n\n    def _progress(self, message: str) -> None:\n        if callable(self.progress_callback):\n            try:\n                self.progress_callback(message)\n            except Exception:\n                pass\n\n    def _ddgs(self):\n        from ddgs import DDGS\n        return DDGS(timeout=self.timeout)\n\n    def _search(self, query: str):\n        if query in self._search_cache:\n            return [dict(x) for x in self._search_cache[query]]\n        rows = []\n        for region in ("np-en", "us-en"):\n            try:\n                result = self._ddgs().text(\n                    query, region=region, safesearch="moderate",\n                    max_results=self.search_results_per_query, backend="auto",\n                )\n                rows = list(result or [])\n                if rows:\n                    break\n            except Exception:\n                rows = []\n                continue\n        out = []\n        for r in rows:\n            if not isinstance(r, dict):\n                continue\n            url = _clean(r.get("href") or r.get("url"))\n            if not url:\n                continue\n            out.append({\n                "title": _clean(r.get("title")),\n                "url": url,\n                "snippet": _clean(r.get("body") or r.get("snippet")),\n            })\n        self._search_cache[query] = out\n        return [dict(x) for x in out]\n\n    def _extract(self, url: str):\n        """Retrieve one bounded evidence document safely with GWP-focused PDF parsing.\n\n        PDF parsing is attempted only when the bytes start with the PDF magic\n        header. For PDFs, GWP-relevant pages are detected first and table structure\n        is preserved with pdfplumber. No OCR and no material-specific values are used.\n        """\n        import requests\n\n        request_timeout = (min(5, self.timeout), self.timeout)\n\n        def pdf_text(content: bytes) -> str:\n            if (not content or len(content) > self.max_download_bytes\n                    or not content.lstrip().startswith(b"%PDF")):\n                return ""\n            return _extract_pdf_gwp_evidence(\n                content,\n                page_limit=self.pdf_max_pages,\n                max_chars=24000 if self.pdf_max_pages <= 24 else 32000,\n            )\n\n        try:\n            resp = requests.get(\n                url, timeout=request_timeout, allow_redirects=True, stream=False,\n                headers={"User-Agent": "Mozilla/5.0 LCA-research-resolver/5.0"},\n            )\n            resp.raise_for_status()\n            if len(resp.content) > self.max_download_bytes:\n                return ""\n            ctype = (resp.headers.get("content-type") or "").lower()\n\n            if resp.content.lstrip().startswith(b"%PDF"):\n                return pdf_text(resp.content)\n\n            is_html = (\n                "html" in ctype\n                or resp.content.lstrip()[:100].lower().startswith((b"<!doctype", b"<html"))\n                or b"<html" in resp.content[:3000].lower()\n            )\n            if is_html:\n                try:\n                    raw_html = resp.text\n                except Exception:\n                    raw_html = resp.content.decode("utf-8", errors="ignore")\n                plain = _strip_html(raw_html)\n                parts = [_focus_gwp_lines(plain, max_chars=10000)] if plain else []\n\n                if self.linked_documents_per_page > 0:\n                    links = re.findall(r"href\\s*=\\s*[\'\\"]([^\'\\"]+)[\'\\"]", raw_html, flags=re.I)\n                    document_urls = []\n                    for href in links:\n                        absolute = urljoin(resp.url, href)\n                        low = absolute.lower()\n                        if ".pdf" in low or "download" in low or "declaration" in low or "epd" in low:\n                            if absolute not in document_urls:\n                                document_urls.append(absolute)\n                        if len(document_urls) >= self.linked_documents_per_page:\n                            break\n                    for doc_url in document_urls:\n                        try:\n                            r2 = requests.get(\n                                doc_url, timeout=request_timeout, allow_redirects=True,\n                                headers={"User-Agent": "Mozilla/5.0 LCA-research-resolver/5.0"},\n                            )\n                            r2.raise_for_status()\n                            if len(r2.content) <= self.max_download_bytes and r2.content.lstrip().startswith(b"%PDF"):\n                                t = pdf_text(r2.content)\n                                if t:\n                                    parts.append(t)\n                        except Exception:\n                            continue\n                combined = "\\n\\n... LINKED_DOCUMENT ...\\n\\n".join(x for x in parts if x)\n                if combined:\n                    return combined[:32000]\n        except Exception:\n            pass\n\n        # One compact extraction fallback only; no recursive crawling.\n        try:\n            extracted = self._ddgs().extract(url, fmt="text_rich")\n            if isinstance(extracted, dict):\n                raw = extracted.get("content") or extracted.get("text") or json.dumps(extracted, ensure_ascii=False)\n            else:\n                raw = str(extracted)\n            return _focus_gwp_lines(raw, max_chars=16000)\n        except Exception:\n            return ""\n\n    def _collect_evidence(\n        self, queries, tier, item_id, material, match_type="DIRECT_PRODUCT", proxy_basis=None,\n        *, max_candidates: int | None = None, max_queries: int | None = None,\n        seen_urls: set[str] | None = None,\n    ):\n        """Collect a bounded set of unique candidate sources.\n\n        The budget applies to the material as a whole when the caller shares\n        ``seen_urls``. Search results are ranked generically by source quality\n        before document extraction; no material-specific source is preselected.\n        """\n        seen = seen_urls if seen_urls is not None else set()\n        limit = max(1, int(max_candidates or self.max_evidence_candidates))\n        qlimit = max(1, int(max_queries or len(list(queries))))\n        pool = []\n        queries_used = 0\n        for query in list(queries)[:qlimit]:\n            queries_used += 1\n            for r in self._search(query):\n                if r["url"] in seen or any(x["url"] == r["url"] for x in pool):\n                    continue\n                pool.append({\n                    **r, "query": query, "tier": tier, "match_type": match_type,\n                    "proxy_basis": proxy_basis,\n                })\n            if len(pool) >= limit * 2:\n                break\n\n        def rank(c):\n            ok, cls = _source_quality(c)\n            class_rank = {\n                "VERIFIED_EPD_PROGRAM": 0, "NEPAL_GOVERNMENT": 1,\n                "GOVERNMENT": 2, "TECHNICAL_LCA_DATABASE": 3,\n                "PEER_REVIEWED_PUBLICATION": 4, "ACADEMIC": 5,\n                "MANUFACTURER_EPD": 6,\n            }.get(cls, 20)\n            return (0 if ok else 1, class_rank)\n\n        pool.sort(key=rank)\n        candidates = pool[:limit]\n        rows = []\n        for i, c in enumerate(candidates):\n            seen.add(c["url"])\n            c["result_id"] = f"S{i+1}"\n            self._progress(f"External Verified · inspecting source {i+1}/{len(candidates)} · {material}")\n            c["full_text"] = self._extract(c["url"])\n            c["excerpt"] = c["full_text"][: max(self.excerpt_chars, 2500)]\n            identity_ok, identity_reason = _product_identity_ok(material, c)\n            rows.append({\n                "item_id": item_id, "material": material, "search_tier": tier,\n                "match_type": match_type, "proxy_basis": proxy_basis,\n                "query": c["query"], "query_subject": _query_subject(c),\n                "result_id": c["result_id"], "title": c["title"], "url": c["url"],\n                "snippet": c["snippet"], "excerpt": c["excerpt"],\n                "product_identity_ok": identity_ok, "product_identity_reason": identity_reason,\n                "gwp_table_detected": "[PDF TABLE PAGE" in c["full_text"],\n                "gwp_page_detected": "[PDF PAGE" in c["full_text"],\n                "relaxed_extraction_status": None, "relaxed_extraction_method": None, "relaxed_rejection_reason": None,\n                "selected": False, "uncertainty_peer": False,\n                "relaxed_candidate": False, "relaxed_retained": False,\n                "relaxed_outlier": False, "relaxed_reason": None,\n                "relaxed_normalized_ef": None, "relaxed_reference_unit": None,\n            })\n        return candidates, rows, queries_used\n\n    def _traceable_from_deterministic(self, material, tier, selected, rec):\n        """Validate a deterministic GWP-table extraction for strict Class 3."""\n        source_ok, source_class = _source_quality(selected)\n        if not source_ok:\n            return None, f"source_quality_rejected:{source_class}"\n        identity_ok, identity_reason = _product_identity_ok(material, selected)\n        if not identity_ok:\n            return None, f"product_identity_rejected:{identity_reason}"\n\n        quote = _clean(rec.get("evidence_quote"))\n        if not _quote_supported(quote, selected):\n            return None, "deterministic_evidence_quote_not_in_retrieved_source"\n        indicator = _clean(rec.get("indicator"))\n        if not _gwp_indicator_ok(indicator, material, _candidate_evidence_text(selected)):\n            return None, "deterministic_indicator_not_allowed_by_reporting_policy"\n        if not _source_indicator_supported(material, selected):\n            return None, "indicator_not_supported_by_retrieved_source"\n        if not _source_boundary_supported(selected):\n            return None, "a1_a3_boundary_not_supported_by_retrieved_source"\n\n        dq = _num(rec.get("declared_quantity"))\n        declared_unit = _clean(rec.get("declared_unit"))\n        if dq is None or dq <= 0 or not _declared_value_supported(dq, declared_unit, selected):\n            return None, "declared_quantity_or_unit_not_supported_by_retrieved_source"\n\n        impact_unit = _clean(rec.get("impact_unit"))\n        mode = _clean(rec.get("value_mode")).upper()\n        calculation_basis = None\n        if mode == "TOTAL":\n            iv = _num(rec.get("impact_value"))\n            if iv is None or not _impact_value_supported(iv, impact_unit, selected):\n                return None, "deterministic_impact_value_or_unit_not_supported_by_source"\n            if not _gwp_quote_supports_values(quote, [iv], material, _candidate_evidence_text(selected), indicator):\n                return None, "deterministic_quote_does_not_link_total_to_gwp"\n            calculation_basis = "DETERMINISTIC_EXPLICIT_SOURCE_A1_A3_TOTAL"\n        elif mode == "SUM_A1_A2_A3":\n            vals = [_num(rec.get(k)) for k in ("a1_value", "a2_value", "a3_value")]\n            if any(v is None for v in vals):\n                return None, "deterministic_a1_a2_a3_incomplete"\n            text = _candidate_evidence_text(selected).lower().replace("–", "-").replace("—", "-")\n            if not all(label in text for label in ("a1", "a2", "a3")):\n                return None, "deterministic_a1_a2_a3_labels_not_supported"\n            if not all(_impact_value_supported(float(v), impact_unit, selected) for v in vals):\n                return None, "deterministic_module_value_or_unit_not_supported"\n            if not _gwp_quote_supports_values(quote, [float(v) for v in vals], material, _candidate_evidence_text(selected), indicator):\n                return None, "deterministic_quote_does_not_link_modules_to_gwp"\n            iv = float(sum(float(v) for v in vals))\n            calculation_basis = "PYTHON_SUM_OF_EXPLICIT_SOURCE_A1_A2_A3"\n        else:\n            return None, "deterministic_unsupported_value_mode"\n\n        norm = normalize_factor(iv, impact_unit, dq, declared_unit)\n        if norm is None:\n            return None, "impact_or_reference_unit_invalid"\n        ef_value, ref_unit = norm\n        unit_ok, unit_reason = _reference_unit_compatible(material, ref_unit)\n        if not unit_ok:\n            return None, unit_reason\n        if _requires_no_biogenic_storage(material) and ef_value <= 0:\n            return None, "biogenic_storage_excluded_requires_positive_factor"\n        plausible, plausibility_reason = emission_factor_plausible(material, ef_value, ref_unit)\n        if not plausible:\n            return None, f"factor_plausibility_rejected:{plausibility_reason}"\n\n        geography = _infer_geography(selected)\n        if not _target_geography_supported(selected, self.target_geography):\n            return None, f"target_geography_not_verified:{geography or \'Unspecified\'}"\n        if _clean(selected.get("match_type")) not in {"", "DIRECT_PRODUCT"}:\n            return None, "class3_requires_direct_product_evidence"\n\n        selected["class3_extraction_method"] = _clean(rec.get("extraction_method")) or "DETERMINISTIC_GWP_TABLE"\n        return {\n            "ef_value": ef_value,\n            "reference_unit": ref_unit,\n            "lower_value": None,\n            "upper_value": None,\n            "verification": "EXTERNAL_VERIFIED",\n            "verification_tier": "STRICT",\n            "source_class": source_class,\n            "source_title": selected["title"],\n            "source_url": selected["url"],\n            "source_geography": geography,\n            "source_year": _source_year_supported(_clean(rec.get("source_year")), selected),\n            "search_tier": tier,\n            "search_query": selected["query"],\n            "evidence_quote": quote,\n            "declared_unit_evidence": _declared_pair_context(dq, declared_unit, selected),\n            "boundary": _clean(rec.get("boundary")) or "A1-A3",\n            "indicator": indicator,\n            "declared_impact_value": iv,\n            "declared_impact_unit": impact_unit,\n            "declared_quantity": dq,\n            "declared_unit": declared_unit,\n            "uncertainty_type": None,\n            "uncertainty_lower_value": None,\n            "uncertainty_upper_value": None,\n            "uncertainty_gsd": None,\n            "uncertainty_cv": None,\n            "uncertainty_confidence_level": None,\n            "uncertainty_evidence_quote": None,\n            "reason": (_clean(rec.get("reason")) + f" [{calculation_basis}]").strip(),\n            "calculation_basis": calculation_basis,\n            "extraction_method": selected["class3_extraction_method"],\n            "raw_model_output": None,\n            "selected_result_id": selected.get("result_id"),\n            "external_match_type": selected.get("match_type", "DIRECT_PRODUCT"),\n            "external_proxy_basis": selected.get("proxy_basis"),\n            "product_identity_status": "PASS",\n            "product_identity_reason": identity_reason,\n            "product_identity_title": selected.get("title"),\n            "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n            "proxy_representativeness": "DIRECT_TARGET_GEOGRAPHY",\n        }, "ok"\n\n    def _choose_traceable(self, material, tier, candidates):\n        if not candidates:\n            return None, "no_candidates"\n\n        # Deterministic structured-table extraction is attempted before Qwen.\n        # A foreign/proxy source that fails strict Class 3 remains available to\n        # the independent Class-4 pathway later.\n        deterministic_reasons = []\n        for selected in candidates:\n            rec, det_reason = _deterministic_gwp_table_record(material, selected)\n            if rec is None:\n                deterministic_reasons.append(f"{selected.get(\'result_id\')}:{det_reason}")\n                continue\n            out, reason = self._traceable_from_deterministic(material, tier, selected, rec)\n            selected["class3_deterministic_status"] = "ACCEPTED" if out is not None else "REJECTED"\n            selected["class3_deterministic_reason"] = reason\n            if out is not None:\n                return out, "ok"\n            deterministic_reasons.append(f"{selected.get(\'result_id\')}:{reason}")\n\n        payload = {\n            "material": material,\n            "target_geography": self.target_geography,\n            "search_tier": tier,\n            "required_indicator": _required_indicator_policy(material),\n            "required_boundary": "A1-A3",\n            "evidence_candidates": [\n                {\n                    "result_id": c["result_id"],\n                    "title": c["title"],\n                    "url": c["url"],\n                    "search_snippet": c["snippet"][:700],\n                    "extracted_text": c["excerpt"][: self.excerpt_chars],\n                }\n                for c in candidates\n            ],\n        }\n        raw = _call_matcher(self.matcher, TRACEABLE_EF_SYSTEM_PROMPT, payload, max_new_tokens=768)\n        try:\n            obj = json.loads(raw.strip())\n        except Exception:\n            m = re.search(r"\\{.*\\}", raw, flags=re.S)\n            if not m:\n                return None, "parse_error"\n            try:\n                obj = json.loads(m.group(0))\n            except Exception:\n                return None, "parse_error"\n\n        required = {\n            "found", "impact_value", "impact_unit", "declared_quantity", "declared_unit",\n            "boundary", "indicator", "source_result_id", "source_year", "evidence_quote",\n            "uncertainty_type", "uncertainty_lower_value", "uncertainty_upper_value",\n            "uncertainty_gsd", "uncertainty_cv", "uncertainty_confidence_level",\n            "uncertainty_evidence_quote", "reason",\n        }\n        if set(obj.keys()) != required:\n            return None, "schema_invalid"\n        if not bool(obj.get("found")):\n            return None, _clean(obj.get("reason")) or "not_found"\n\n        sid = _clean(obj.get("source_result_id"))\n        by_id = {c["result_id"]: c for c in candidates}\n        if sid not in by_id:\n            return None, "source_id_invalid"\n        selected = by_id[sid]\n\n        source_ok, source_class = _source_quality(selected)\n        if not source_ok:\n            return None, f"source_quality_rejected:{source_class}"\n\n        identity_ok, identity_reason = _product_identity_ok(material, selected)\n        if not identity_ok:\n            return None, f"product_identity_rejected:{identity_reason}"\n\n        quote = _clean(obj.get("evidence_quote"))\n        if not _quote_supported(quote, selected):\n            return None, "evidence_quote_not_in_retrieved_source"\n        if not _gwp_indicator_ok(_clean(obj.get("indicator")), material, _candidate_evidence_text(selected)):\n            return None, "indicator_not_allowed_by_reporting_policy"\n        if not _source_indicator_supported(material, selected):\n            return None, "indicator_not_supported_by_retrieved_source"\n        if not _boundary_ok(_clean(obj.get("boundary"))):\n            return None, "boundary_not_a1_a3"\n        if not _source_boundary_supported(selected):\n            return None, "a1_a3_boundary_not_supported_by_retrieved_source"\n\n        iv = _num(obj.get("impact_value"))\n        dq = _num(obj.get("declared_quantity"))\n        if iv is None or dq is None or dq <= 0:\n            return None, "value_or_declared_quantity_invalid"\n        if not _impact_value_supported(iv, _clean(obj.get("impact_unit")), selected):\n            return None, "impact_value_or_unit_not_supported_by_retrieved_source"\n        if not _declared_value_supported(dq, _clean(obj.get("declared_unit")), selected):\n            return None, "declared_quantity_or_unit_not_supported_by_retrieved_source"\n        norm = normalize_factor(iv, _clean(obj.get("impact_unit")), dq, _clean(obj.get("declared_unit")))\n        if norm is None:\n            return None, "impact_or_reference_unit_invalid"\n        ef_value, ref_unit = norm\n        unit_ok, unit_reason = _reference_unit_compatible(material, ref_unit)\n        if not unit_ok:\n            return None, unit_reason\n        if _requires_no_biogenic_storage(material) and ef_value <= 0:\n            return None, "biogenic_storage_excluded_requires_positive_factor"\n        plausible, plausibility_reason = emission_factor_plausible(material, ef_value, ref_unit)\n        if not plausible:\n            return None, f"factor_plausibility_rejected:{plausibility_reason}"\n\n        geography = _infer_geography(selected)\n\n        # CLASS 3 IS STRICT: the source itself must explicitly support the target\n        # study geography. Global, regional, foreign, and geography-unspecified\n        # sources are not promoted to EXTERNAL_VERIFIED; they remain eligible for\n        # the relaxed External Verified screening phase below.\n        if not _target_geography_supported(selected, self.target_geography):\n            return None, f"target_geography_not_verified:{geography or \'Unspecified\'}"\n\n        # Class 3 is also reserved for direct-product evidence. A broader\n        # taxonomy-family/source proxy is still usable, but only in the relaxed External Verified phase.\n        if _clean(selected.get("match_type")) not in {"", "DIRECT_PRODUCT"}:\n            return None, "class3_requires_direct_product_evidence"\n\n        # Optional source-reported quantitative uncertainty. It is accepted only\n        # when the model copied an uncertainty quote from the retrieved evidence\n        # and every non-null numeric field is literally present in that evidence.\n        uncertainty_type = _clean(obj.get("uncertainty_type"))\n        uncertainty_lower = _num(obj.get("uncertainty_lower_value"))\n        uncertainty_upper = _num(obj.get("uncertainty_upper_value"))\n        uncertainty_gsd = _num(obj.get("uncertainty_gsd"))\n        uncertainty_cv = _num(obj.get("uncertainty_cv"))\n        uncertainty_conf = _num(obj.get("uncertainty_confidence_level"))\n        uncertainty_quote = _clean(obj.get("uncertainty_evidence_quote"))\n        uncertainty_values = [x for x in (uncertainty_lower, uncertainty_upper, uncertainty_gsd, uncertainty_cv, uncertainty_conf) if x is not None]\n        if uncertainty_values:\n            if not uncertainty_quote or not _quote_supported(uncertainty_quote, selected):\n                return None, "uncertainty_quote_not_in_retrieved_source"\n            evidence_text = _candidate_evidence_text(selected)\n            for val in uncertainty_values:\n                if not _number_close_in_text(val, evidence_text):\n                    return None, "uncertainty_value_not_supported_by_retrieved_source"\n            if uncertainty_gsd is not None and uncertainty_gsd < 1:\n                return None, "source_reported_gsd_less_than_one"\n            if uncertainty_lower is not None and uncertainty_upper is not None and uncertainty_lower >= uncertainty_upper:\n                return None, "source_reported_uncertainty_interval_invalid"\n        else:\n            uncertainty_type = ""\n            uncertainty_quote = ""\n\n        return {\n            "ef_value": ef_value,\n            "reference_unit": ref_unit,\n            "lower_value": None,\n            "upper_value": None,\n            "verification": "EXTERNAL_VERIFIED",\n            "verification_tier": "STRICT",\n            "source_class": source_class,\n            "source_title": selected["title"],\n            "source_url": selected["url"],\n            "source_geography": geography,\n            "source_year": _source_year_supported(_clean(obj.get("source_year")), selected),\n            "search_tier": tier,\n            "search_query": selected["query"],\n            "evidence_quote": quote,\n            "declared_unit_evidence": _declared_pair_context(dq, _clean(obj.get("declared_unit")), selected),\n            "boundary": _clean(obj.get("boundary")),\n            "indicator": _clean(obj.get("indicator")),\n            "declared_impact_value": iv,\n            "declared_impact_unit": _clean(obj.get("impact_unit")),\n            "declared_quantity": dq,\n            "declared_unit": _clean(obj.get("declared_unit")),\n            "uncertainty_type": uncertainty_type or None,\n            "uncertainty_lower_value": uncertainty_lower,\n            "uncertainty_upper_value": uncertainty_upper,\n            "uncertainty_gsd": uncertainty_gsd,\n            "uncertainty_cv": uncertainty_cv,\n            "uncertainty_confidence_level": uncertainty_conf,\n            "uncertainty_evidence_quote": uncertainty_quote or None,\n            "reason": _clean(obj.get("reason")),\n            "raw_model_output": raw,\n            "selected_result_id": sid,\n            "external_match_type": selected.get("match_type", "DIRECT_PRODUCT"),\n            "external_proxy_basis": selected.get("proxy_basis"),\n            "product_identity_status": "PASS",\n            "product_identity_reason": identity_reason,\n            "product_identity_title": selected.get("title"),\n            "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n            "proxy_representativeness": "DIRECT_TARGET_GEOGRAPHY",\n        }, "ok"\n\n    def _collect_peer_factors(self, material, tier, candidates, primary, max_total: int = 3):\n        """Collect a small same-tier set of independently accepted factors for uncertainty.\n\n        These peers are never used to replace the primary selected factor. They\n        are retained only to estimate empirical dispersion when two or more\n        defensible factors with the same reference unit are available.\n        """\n        peers = [primary]\n        remaining = [c for c in candidates if c.get("result_id") != primary.get("selected_result_id")]\n        while remaining and len(peers) < max_total:\n            alt, _ = self._choose_traceable(material, tier, remaining)\n            if alt is None:\n                break\n            sid = alt.get("selected_result_id")\n            remaining = [c for c in remaining if c.get("result_id") != sid]\n            if alt.get("reference_unit") != primary.get("reference_unit"):\n                continue\n            val = _num(alt.get("ef_value"))\n            if val is None or val <= 0:\n                continue\n            # Different URLs are required so duplicate search hits do not create\n            # artificial evidence of variability.\n            if any(_clean(x.get("source_url")) == _clean(alt.get("source_url")) for x in peers):\n                continue\n            peers.append(alt)\n        return peers\n\n    def _extract_relaxed_candidates(self, material, tier, candidates):\n        """Extract relaxed-phase Class-3 GWP values with deterministic-table-first logic.\n\n        Structured GWP/A1/A2/A3 tables are parsed by Python first. Qwen is used\n        only when deterministic extraction is absent or fails validation.\n        """\n        if not candidates:\n            return []\n\n        accepted = []\n        required = {\n            "source_result_id", "found", "value_mode", "impact_value",\n            "a1_value", "a2_value", "a3_value", "impact_unit",\n            "declared_quantity", "declared_unit", "boundary", "indicator",\n            "source_year", "evidence_quote", "reason",\n        }\n\n        for selected in candidates:\n            selected["relaxed_extraction_status"] = "STARTED"\n            selected["relaxed_rejection_reason"] = None\n            selected["relaxed_extraction_method"] = None\n            attempts: list[dict[str, Any]] = []\n\n            def validate_record(rec: dict[str, Any], extraction_method: str):\n                sid = _clean(rec.get("source_result_id"))\n                if sid != selected.get("result_id"):\n                    return None, "source_result_id_mismatch"\n                if not bool(rec.get("found")):\n                    return None, "gwp_not_extracted:" + (_clean(rec.get("reason")) or "not_found")\n\n                source_ok, source_class = _provisional_source_allowed(selected)\n                if not source_ok:\n                    return None, f"source_not_allowed:{source_class}"\n                identity_ok, identity_reason = _product_identity_ok(material, selected)\n                if not identity_ok:\n                    return None, f"product_identity_rejected:{identity_reason}"\n                quote = _clean(rec.get("evidence_quote"))\n                if not _quote_supported(quote, selected):\n                    return None, "evidence_quote_not_in_retrieved_source"\n\n                dq = _num(rec.get("declared_quantity"))\n                if dq is None or dq <= 0:\n                    return None, "declared_quantity_missing_or_invalid"\n                declared_unit = _clean(rec.get("declared_unit"))\n                if not _declared_value_supported(dq, declared_unit, selected):\n                    return None, "declared_unit_or_quantity_not_supported_by_source"\n\n                impact_unit = _clean(rec.get("impact_unit"))\n                indicator = _clean(rec.get("indicator"))\n                if not _gwp_indicator_ok(indicator, material, _candidate_evidence_text(selected)):\n                    return None, "extracted_indicator_is_not_allowed_gwp_category"\n                mode = _clean(rec.get("value_mode")).upper()\n                calculation_basis = None\n                if mode == "TOTAL":\n                    iv = _num(rec.get("impact_value"))\n                    if iv is None or not _impact_value_supported(iv, impact_unit, selected):\n                        return None, "gwp_total_value_or_impact_unit_not_supported_by_source"\n                    if not _gwp_quote_supports_values(quote, [iv], material, _candidate_evidence_text(selected), indicator):\n                        return None, "evidence_quote_does_not_link_numeric_value_to_gwp"\n                    calculation_basis = (\n                        "DETERMINISTIC_EXPLICIT_SOURCE_A1_A3_TOTAL"\n                        if extraction_method.startswith("DETERMINISTIC_")\n                        else "EXPLICIT_SOURCE_GWP_TOTAL"\n                    )\n                elif mode == "SUM_A1_A2_A3":\n                    vals = [_num(rec.get(k)) for k in ("a1_value", "a2_value", "a3_value")]\n                    if any(v is None for v in vals):\n                        return None, "a1_a2_a3_numeric_values_incomplete"\n                    text = _candidate_evidence_text(selected).lower().replace("–", "-").replace("—", "-")\n                    if not all(label in text for label in ("a1", "a2", "a3")):\n                        return None, "a1_a2_a3_labels_not_supported_by_source"\n                    if not all(_impact_value_supported(float(v), impact_unit, selected) for v in vals):\n                        return None, "one_or_more_a1_a2_a3_values_not_supported_by_source"\n                    if not _gwp_quote_supports_values(quote, [float(v) for v in vals], material, _candidate_evidence_text(selected), indicator):\n                        return None, "evidence_quote_does_not_link_a1_a2_a3_values_to_gwp"\n                    iv = float(sum(float(v) for v in vals))\n                    calculation_basis = "PYTHON_SUM_OF_EXPLICIT_SOURCE_A1_A2_A3"\n                else:\n                    return None, "unsupported_value_mode"\n\n                norm = normalize_factor(iv, impact_unit, dq, declared_unit)\n                if norm is None:\n                    return None, "factor_normalization_failed"\n                ef_value, ref_unit = norm\n                canonical = _canonicalize_provisional_factor(ef_value, ref_unit)\n                if canonical is None:\n                    return None, "canonical_factor_basis_failed"\n                ef_value, ref_unit = canonical\n                unit_ok, unit_reason = _reference_unit_compatible(material, ref_unit)\n                if not unit_ok or ef_value <= 0:\n                    return None, "reference_unit_incompatible:" + unit_reason\n\n                boundary_ok, boundary_quality = _provisional_boundary_supported(selected)\n                if not boundary_ok:\n                    return None, "relaxed_boundary_rejected:" + boundary_quality\n                if mode == "TOTAL" and not extraction_method.startswith("DETERMINISTIC_"):\n                    if boundary_quality == "EXPLICIT_A1_A3":\n                        calculation_basis = "EXPLICIT_SOURCE_A1_A3_TOTAL"\n                    elif boundary_quality == "EXPLICIT_A1_A2_A3_MODULES":\n                        calculation_basis = "EXPLICIT_SOURCE_PRODUCT_STAGE_GWP_TOTAL_WITH_MODULE_LABELS"\n                    elif boundary_quality == "PRODUCT_STAGE_CRADLE_TO_GATE":\n                        calculation_basis = "EXPLICIT_SOURCE_PRODUCT_STAGE_GWP_TOTAL"\n                    elif boundary_quality == "PRODUCTION_CONTEXT_INFERRED_RELAXED":\n                        calculation_basis = "EXPLICIT_SOURCE_GWP_WITH_PRODUCTION_CONTEXT_RELAXED"\n                if not _provisional_indicator_supported(material, selected):\n                    return None, "gwp_indicator_not_supported_by_retrieved_source"\n                if _requires_no_biogenic_storage(material) and ef_value <= 0:\n                    return None, "biogenic_policy_requires_positive_gwp_ghg_or_fossil"\n                plausible, plausible_reason = emission_factor_plausible(material, ef_value, ref_unit)\n                if not plausible:\n                    return None, "guardrail_rejected:" + plausible_reason\n\n                geography = _infer_geography(selected)\n                out = {\n                    "ef_value": float(ef_value),\n                    "reference_unit": ref_unit,\n                    "verification": "EXTERNAL_VERIFIED",\n                    "verification_tier": "RELAXED",\n                    "source_class": "EXTERNAL_VERIFIED_RELAXED",\n                    "source_title": selected.get("title"),\n                    "source_url": selected.get("url"),\n                    "source_geography": geography,\n                    "geography_representativeness": (\n                        "TARGET_GEOGRAPHY" if _target_geography_supported(selected, self.target_geography)\n                        else "NON_TARGET_OR_UNSPECIFIED_ACCEPTED_IN_RELAXED_PHASE"\n                    ),\n                    "source_year": _source_year_supported(_clean(rec.get("source_year")), selected),\n                    "search_tier": tier,\n                    "search_query": selected.get("query"),\n                    "evidence_quote": quote,\n                    "boundary": _clean(rec.get("boundary")) or boundary_quality,\n                    "boundary_quality": boundary_quality,\n                    "indicator": indicator,\n                    "declared_impact_value": iv,\n                    "declared_impact_unit": impact_unit,\n                    "declared_quantity": dq,\n                    "declared_unit": declared_unit,\n                    "reason": (_clean(rec.get("reason")) + f" [{calculation_basis}]").strip(),\n                    "calculation_basis": calculation_basis,\n                    "extraction_method": extraction_method,\n                    "raw_model_output": json.dumps(attempts, ensure_ascii=False),\n                    "selected_result_id": sid,\n                    "external_match_type": selected.get("match_type", "DIRECT_PRODUCT"),\n                    "external_proxy_basis": selected.get("proxy_basis"),\n                    "product_identity_status": "PASS_SOURCE_SUPPORTED",\n                    "product_identity_reason": identity_reason,\n                    "product_identity_title": selected.get("title"),\n                    "gwp_table_detected": "[PDF TABLE PAGE" in _clean(selected.get("full_text")),\n                    "gwp_page_detected": "[PDF PAGE" in _clean(selected.get("full_text")),\n                    "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n                }\n                return out, "ok"\n\n            # Attempt 1: deterministic structured EPD/GWP table parser.\n            det, det_reason = _deterministic_gwp_table_record(material, selected)\n            if det is not None:\n                method = _clean(det.pop("extraction_method", "")) or "DETERMINISTIC_GWP_TABLE"\n                attempts.append({"method": method, "record": det})\n                out, reason = validate_record(det, method)\n                if out is not None:\n                    selected["relaxed_extraction_status"] = "ACCEPTED"\n                    selected["relaxed_extraction_method"] = method\n                    selected["relaxed_rejection_reason"] = None\n                    out["raw_model_output"] = json.dumps(attempts, ensure_ascii=False)\n                    accepted.append(out)\n                    continue\n                attempts.append({"method": method, "validation_rejection": reason})\n            else:\n                attempts.append({"method": "DETERMINISTIC_GWP_TABLE", "status": det_reason})\n\n            # Attempt 2: Qwen source extractor only when deterministic extraction\n            # did not produce a validated factor.\n            payload = {\n                "material": material,\n                "target_geography": self.target_geography,\n                "search_tier": tier,\n                "required_indicator": _required_indicator_policy(material),\n                "indicator_scope": "GWP_ONLY",\n                "evidence_candidates": [{\n                    "result_id": selected["result_id"],\n                    "title": selected["title"],\n                    "url": selected["url"],\n                    "search_snippet": selected["snippet"][:900],\n                    "extracted_text": selected["excerpt"][: self.excerpt_chars],\n                }],\n            }\n            raw = _call_matcher(self.matcher, RELAXED_EXTERNAL_EF_SYSTEM_PROMPT, payload, max_new_tokens=640)\n            attempts.append({"method": "QWEN_EVIDENCE_EXTRACTOR", "raw": raw})\n            try:\n                obj = json.loads(raw.strip())\n            except Exception:\n                m = re.search(r"\\{.*\\}", raw or "", flags=re.S)\n                if not m:\n                    selected["relaxed_extraction_status"] = "REJECTED"\n                    selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n                    selected["relaxed_rejection_reason"] = "model_json_parse_error_after_deterministic_fallback"\n                    continue\n                try:\n                    obj = json.loads(m.group(0))\n                except Exception:\n                    selected["relaxed_extraction_status"] = "REJECTED"\n                    selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n                    selected["relaxed_rejection_reason"] = "model_json_parse_error_after_deterministic_fallback"\n                    continue\n            if set(obj.keys()) != {"records"} or not isinstance(obj.get("records"), list) or len(obj["records"]) != 1:\n                selected["relaxed_extraction_status"] = "REJECTED"\n                selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n                selected["relaxed_rejection_reason"] = "model_schema_invalid"\n                continue\n            rec = obj["records"][0]\n            if not isinstance(rec, dict) or set(rec.keys()) != required:\n                selected["relaxed_extraction_status"] = "REJECTED"\n                selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n                selected["relaxed_rejection_reason"] = "model_record_schema_invalid"\n                continue\n            out, reason = validate_record(rec, "QWEN_EVIDENCE_EXTRACTOR")\n            if out is None:\n                selected["relaxed_extraction_status"] = "REJECTED"\n                selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n                selected["relaxed_rejection_reason"] = reason\n                continue\n            selected["relaxed_extraction_status"] = "ACCEPTED"\n            selected["relaxed_extraction_method"] = "QWEN_EVIDENCE_EXTRACTOR"\n            selected["relaxed_rejection_reason"] = None\n            out["raw_model_output"] = json.dumps(attempts, ensure_ascii=False)\n            accepted.append(out)\n\n        return accepted\n\n    def _build_provisional_consensus(self, material, factors):\n        if not factors:\n            return None\n\n        # De-duplicate URLs so repeated search hits do not masquerade as\n        # independent evidence. Prefer direct-product evidence whenever any\n        # exists; taxonomy-family proxies are used only if no direct evidence is\n        # source-supported.\n        unique = []\n        seen_urls = set()\n        for f in factors:\n            url = _clean(f.get("source_url"))\n            if not url or url in seen_urls:\n                continue\n            seen_urls.add(url)\n            unique.append(dict(f))\n        if not unique:\n            return None\n        direct = [x for x in unique if _clean(x.get("external_match_type")) == "DIRECT_PRODUCT"]\n        pool = direct if direct else unique\n\n        # Values with different declared bases cannot be combined without a\n        # physical conversion assumption. Select the best-supported common basis\n        # by source count, then geography tier.\n        tier_rank = {"NEPAL": 0, "SOUTH_ASIA": 1, "ASIA": 2, "GLOBAL": 3}\n        groups: dict[str, list[dict[str, Any]]] = {}\n        for f in pool:\n            groups.setdefault(_clean(f.get("reference_unit")), []).append(f)\n        ranked = sorted(\n            groups.items(),\n            key=lambda kv: (\n                -len(kv[1]),\n                min(tier_rank.get(_clean(x.get("search_tier")).upper(), 9) for x in kv[1]),\n                kv[0],\n            ),\n        )\n        ref_unit, group = ranked[0]\n        values = [float(x["ef_value"]) for x in group]\n        consensus = robust_positive_consensus(values)\n        if consensus is None:\n            return None\n        retained = [group[i] for i in consensus.retained_indices]\n        outliers = [group[i] for i in consensus.outlier_indices]\n        if not retained:\n            return None\n\n        retained_values = [float(x["ef_value"]) for x in retained]\n        retained_urls = [x.get("source_url") for x in retained]\n        geos = sorted({_clean(x.get("source_geography")) for x in retained if _clean(x.get("source_geography"))})\n        years = [int(x["source_year"]) for x in retained if str(x.get("source_year") or "").isdigit()]\n        source_details = []\n        retained_url_set = set(retained_urls)\n        outlier_url_set = {_clean(x.get("source_url")) for x in outliers}\n        for f in group:\n            source_details.append({\n                "ef_value": float(f["ef_value"]),\n                "reference_unit": f.get("reference_unit"),\n                "source_title": f.get("source_title"),\n                "source_url": f.get("source_url"),\n                "source_class": f.get("source_class"),\n                "source_geography": f.get("source_geography"),\n                "geography_representativeness": f.get("geography_representativeness"),\n                "source_year": f.get("source_year"),\n                "search_tier": f.get("search_tier"),\n                "match_type": f.get("external_match_type"),\n                "boundary_quality": f.get("boundary_quality"),\n                "indicator": f.get("indicator"),\n                "evidence_quote": f.get("evidence_quote"),\n                "retained_for_consensus": _clean(f.get("source_url")) in retained_url_set,\n                "outlier": _clean(f.get("source_url")) in outlier_url_set,\n            })\n\n        one = retained[0]\n        multi = len(retained) > 1\n        proxy_used = all(_clean(x.get("external_match_type")) != "DIRECT_PRODUCT" for x in retained)\n        return {\n            "ef_value": float(consensus.central_value),\n            "reference_unit": ref_unit,\n            "lower_value": min(retained_values) if multi else None,\n            "upper_value": max(retained_values) if multi else None,\n            "verification": "EXTERNAL_VERIFIED",\n            "verification_tier": "RELAXED",\n            "source_class": "EXTERNAL_VERIFIED_RELAXED",\n            "source_title": (\n                f"Median of {len(retained)} source-supported factors" if multi\n                else one.get("source_title")\n            ),\n            "source_url": None if multi else one.get("source_url"),\n            "source_geography": ", ".join(geos) if geos else "Unspecified",\n            "source_year": str(max(years)) if years else None,\n            "search_tier": min(\n                (x.get("search_tier") for x in retained),\n                key=lambda t: tier_rank.get(_clean(t).upper(), 9),\n            ),\n            "search_query": None if multi else one.get("search_query"),\n            "evidence_quote": None if multi else one.get("evidence_quote"),\n            "declared_unit_evidence": None,\n            "boundary": "Source-supported product-stage/production-context screening basis",\n            "indicator": (\n                "GWP-GHG/GWP-fossil external verified (relaxed phase)"\n                if _requires_no_biogenic_storage(material)\n                else "GWP external verified (relaxed phase)"\n            ),\n            "declared_impact_value": None,\n            "declared_impact_unit": None,\n            "declared_quantity": 1.0,\n            "declared_unit": ref_unit,\n            "uncertainty_type": "MULTI_SOURCE_DISPERSION" if multi else None,\n            "uncertainty_lower_value": None,\n            "uncertainty_upper_value": None,\n            "uncertainty_gsd": None,\n            "uncertainty_cv": None,\n            "uncertainty_confidence_level": None,\n            "uncertainty_evidence_quote": None,\n            "peer_values_json": json.dumps(retained_values, ensure_ascii=False),\n            "peer_sources_json": json.dumps(source_details, ensure_ascii=False),\n            "relaxed_sources_json": json.dumps(source_details, ensure_ascii=False),\n            "relaxed_source_count": len(group),\n            "relaxed_retained_count": len(retained),\n            "relaxed_outlier_count": len(outliers),\n            "relaxed_consensus_method": consensus.method,\n            "relaxed_consensus_version": CONSENSUS_METHOD_VERSION,\n            "reason": (\n                f"External Verified relaxed-phase factor from {len(retained)} retained independent source(s) "\n                f"on a common {ref_unit} basis using {consensus.method}; {len(outliers)} source-set outlier(s) excluded."\n            ),\n            "raw_model_output": None,\n            "selected_result_id": one.get("selected_result_id") if not multi else None,\n            "external_match_type": "EXTERNAL_VERIFIED_RELAXED_PROXY" if proxy_used else "EXTERNAL_VERIFIED_RELAXED_DIRECT",\n            "external_proxy_basis": one.get("external_proxy_basis") if proxy_used else None,\n            "product_identity_status": "PASS_SOURCE_SUPPORTED",\n            "product_identity_reason": "Every retained source passed deterministic material/product identity checks.",\n            "product_identity_title": None if multi else one.get("product_identity_title"),\n            "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n            "proxy_representativeness": "EXTERNAL_VERIFIED_RELAXED",\n        }\n\n    def _resolve_one(self, item_id, material):\n        key = material.strip().lower()\n        if key in self._resolution_cache:\n            return dict(self._resolution_cache[key]), []\n\n        cached = self.evidence_cache.get(\n            category="emission_factor", material=material,\n            target_geography=self.target_geography,\n        )\n        if cached and cached.get("verification") in {"EXTERNAL_VERIFIED", "PROVISIONAL_SOURCE_SUPPORTED"}:\n            cached = dict(cached)\n            cached["reason"] = (_clean(cached.get("reason")) + " Runtime evidence-cache reuse.").strip()\n            cached["source_class"] = _clean(cached.get("source_class")) or "RUNTIME_EVIDENCE_CACHE"\n            cached["evidence_cache_version"] = CACHE_VERSION\n            self._progress(f"EF cache hit · {material} · {cached.get(\'verification\')}")\n            self._resolution_cache[key] = dict(cached)\n            cache_evidence = [{\n                "item_id": item_id, "material": material, "search_tier": "RUNTIME_CACHE",\n                "match_type": cached.get("external_match_type"), "proxy_basis": cached.get("external_proxy_basis"),\n                "query": None, "query_subject": material, "result_id": "CACHE1",\n                "title": cached.get("source_title"), "url": cached.get("source_url"),\n                "snippet": cached.get("evidence_quote"), "excerpt": cached.get("evidence_quote"),\n                "product_identity_ok": True, "product_identity_reason": "Previously accepted retrieved evidence",\n                "selected": True, "uncertainty_peer": False, "relaxed_candidate": cached.get("verification") == "PROVISIONAL_SOURCE_SUPPORTED",\n                "relaxed_retained": cached.get("verification") == "PROVISIONAL_SOURCE_SUPPORTED",\n                "relaxed_outlier": False, "relaxed_reason": "Runtime evidence-cache reuse",\n                "relaxed_normalized_ef": cached.get("ef_value"), "relaxed_reference_unit": cached.get("reference_unit"),\n            }]\n            return cached, cache_evidence\n\n        all_evidence = []\n        provisional_factors = []\n        seen_urls: set[str] = set()\n        promising_reasons: list[str] = []\n        promising_candidates: list[dict[str, Any]] = []\n        plans = list(_query_sets(material, self.target_geography))\n\n        # ------------------------------------------------------------------\n        # CLASS 3 / EXTERNAL VERIFIED — Phase A: strict target-geography/direct-product search.\n        # This clock is independent from the relaxed Phase B. Phase B never inherits an\n        # exhausted strict-phase timer or source/query budget.\n        # ------------------------------------------------------------------\n        class3_started = time.monotonic()\n        class3_inspected = 0\n        class3_queries_used = 0\n        class3_plan = next((p for p in plans if p[0] == "NEPAL" and p[1] == "DIRECT_PRODUCT"), None)\n        if class3_plan is not None:\n            tier, match_type, proxy_basis, queries = class3_plan\n            self._progress(\n                f"External Verified · Phase A strict {self.target_geography} search · {material} · "\n                f"independent budget {self.max_external_seconds_per_material:.0f} s · "\n                f"max {self.class3_source_budget} sources"\n            )\n            candidates, rows, used = self._collect_evidence(\n                queries, tier, item_id, material, match_type=match_type, proxy_basis=proxy_basis,\n                max_candidates=self.class3_source_budget,\n                max_queries=min(3, self.max_search_queries_per_material),\n                seen_urls=seen_urls,\n            )\n            class3_queries_used += used\n            class3_inspected += len(candidates)\n            all_evidence.extend(rows)\n            for c in candidates:\n                ok_promising, why_promising = _promising_class4_candidate(material, c)\n                if ok_promising:\n                    promising_reasons.append(why_promising)\n                    if c.get("url") and not any(x.get("url") == c.get("url") for x in promising_candidates):\n                        promising_candidates.append(dict(c))\n\n            selected, _ = self._choose_traceable(material, tier, candidates)\n            if selected is not None:\n                sid = selected.get("selected_result_id")\n                for row in all_evidence:\n                    if row["search_tier"] == tier and row["result_id"] == sid and row["url"] == selected["source_url"]:\n                        row["selected"] = True\n                peers = self._collect_peer_factors(material, tier, candidates, selected, max_total=3)\n                selected = dict(selected)\n                selected["peer_values_json"] = json.dumps([float(x["ef_value"]) for x in peers], ensure_ascii=False)\n                selected["peer_sources_json"] = json.dumps([{\n                    "ef_value": float(x["ef_value"]), "reference_unit": x.get("reference_unit"),\n                    "source_title": x.get("source_title"), "source_url": x.get("source_url"),\n                    "source_geography": x.get("source_geography"), "source_year": x.get("source_year"),\n                } for x in peers], ensure_ascii=False)\n                selected["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                selected["evidence_cache_version"] = CACHE_VERSION\n                self.evidence_cache.put(\n                    category="emission_factor", material=material, target_geography=self.target_geography,\n                    resolved=selected,\n                )\n                self._resolution_cache[key] = dict(selected)\n                self._progress(f"EF Class 3 accepted · {material}")\n                return selected, all_evidence\n\n            # A target-geography source that fails strict Class-3 verification can\n            # still be considered later under the relaxed External Verified Phase B.\n            if self.allow_source_supported_provisional and candidates:\n                provisional_factors.extend(self._extract_relaxed_candidates(material, tier, candidates))\n\n        self._progress(\n            f"EF Class 3 finished · {material} · {class3_inspected} source(s), "\n            f"{class3_queries_used} query/queries · starting External Verified Phase B with a fresh clock"\n        )\n\n        # ------------------------------------------------------------------\n        # CLASS 4 — independent source-supported search.\n        # Geography is deliberately relaxed. Technical equivalents are allowed.\n        # Explicit A1-A3 is preferred but not mandatory: a retrieved GWP/carbon\n        # value can qualify when the source clearly places it in production or\n        # manufacturing context and does not show a broader life-cycle boundary.\n        # ------------------------------------------------------------------\n        if not self.allow_source_supported_provisional:\n            self._progress(f"External Verified Phase B disabled · {material}; moving to Class 4 fallback")\n            return None, all_evidence\n\n        class4_started = time.monotonic()\n        class4_inspected = 0\n        external_verified_relaxed_queries_used = 0\n        class4_source_budget = self.adaptive_total_source_budget\n        class4_query_budget = self.adaptive_max_search_queries_per_material\n        class4_time_budget = self.adaptive_external_seconds_per_material\n\n        self._progress(\n            f"External Verified · Phase B relaxed geography/source-supported search · {material} · "\n            f"budget {class4_time_budget:.0f} s · up to {class4_query_budget} queries / "\n            f"{class4_source_budget} unique sources · geography may differ"\n        )\n\n        class4_plans = [p for p in plans if not (p[0] == "NEPAL" and p[1] == "DIRECT_PRODUCT")]\n        class4_priority = {\n            ("SOUTH_ASIA", "DIRECT_PRODUCT"): 0,\n            ("GLOBAL", "DIRECT_PRODUCT"): 1,\n            ("ASIA", "DIRECT_PRODUCT"): 2,\n            ("SOUTH_ASIA", "PRODUCT_PROXY"): 4,\n            ("GLOBAL", "PRODUCT_PROXY"): 5,\n            ("ASIA", "PRODUCT_PROXY"): 6,\n            ("NEPAL", "PRODUCT_PROXY"): 7,\n        }\n        class4_plans.sort(key=lambda p: class4_priority.get((p[0], p[1]), 9))\n\n        # Generate terminology only; the model is forbidden to supply any factor.\n        equivalent_plan = infer_technical_equivalents(\n            self.matcher, material=material, target_context=self.target_geography\n        )\n        equivalent_plans = []\n        if equivalent_plan:\n            for rec in equivalent_plan.get("search_terms", []):\n                subject = _clean(rec.get("term"))\n                basis = _clean(rec.get("equivalence_basis"))\n                if not subject:\n                    continue\n                equivalent_plans.extend([\n                    ("GLOBAL", "PRODUCT_PROXY", f"Dynamic technical equivalence: {basis}", [\n                        f\'"{subject}" GWP EPD\',\n                        f\'"{subject}" "cradle-to-gate" GWP\',\n                        f\'"{subject}" manufacturing "carbon footprint"\',\n                        f\'"{subject}" GWP USA Canada EPD\',\n                    ]),\n                    ("SOUTH_ASIA", "PRODUCT_PROXY", f"Dynamic technical equivalence: {basis}", [\n                        f\'"{subject}" GWP India EPD\',\n                        f\'"{subject}" production carbon footprint South Asia\',\n                    ]),\n                ])\n\n        # Direct product searches first; then dynamic technical-equivalence terms;\n        # then the remaining generic proxy plans. Search/url caches remove repeats.\n        direct_plans = [p for p in class4_plans if p[1] == "DIRECT_PRODUCT"]\n        proxy_plans = [p for p in class4_plans if p[1] != "DIRECT_PRODUCT"]\n        search_plans = direct_plans + equivalent_plans + proxy_plans\n\n        for tier, match_type, proxy_basis, queries in search_plans:\n            if time.monotonic() - class4_started >= class4_time_budget:\n                self._progress(f"External Verified Phase B time budget reached · {material}; moving toward Class 4 fallback")\n                break\n            if class4_inspected >= class4_source_budget or external_verified_relaxed_queries_used >= class4_query_budget:\n                break\n            remaining_sources = class4_source_budget - class4_inspected\n            remaining_queries = class4_query_budget - external_verified_relaxed_queries_used\n            candidates, rows, used = self._collect_evidence(\n                queries, tier, item_id, material, match_type=match_type, proxy_basis=proxy_basis,\n                max_candidates=min(2, remaining_sources),\n                max_queries=min(2, remaining_queries),\n                seen_urls=seen_urls,\n            )\n            external_verified_relaxed_queries_used += used\n            class4_inspected += len(candidates)\n            all_evidence.extend(rows)\n\n            for c in candidates:\n                ok_promising, why_promising = _promising_class4_candidate(material, c)\n                if ok_promising:\n                    promising_reasons.append(why_promising)\n                    if c.get("url") and not any(x.get("url") == c.get("url") for x in promising_candidates):\n                        promising_candidates.append(dict(c))\n\n            if candidates:\n                extracted = self._extract_relaxed_candidates(material, tier, candidates)\n                provisional_factors.extend(extracted)\n                by_url = {_clean(x.get("source_url")): x for x in extracted}\n                candidate_by_url = {_clean(x.get("url")): x for x in candidates}\n                for row in all_evidence:\n                    url = _clean(row.get("url"))\n                    cdiag = candidate_by_url.get(url)\n                    if cdiag is not None:\n                        row["relaxed_extraction_status"] = cdiag.get("relaxed_extraction_status")\n                        row["relaxed_extraction_method"] = cdiag.get("relaxed_extraction_method")\n                        row["relaxed_rejection_reason"] = cdiag.get("relaxed_rejection_reason")\n                        row["gwp_table_detected"] = "[PDF TABLE PAGE" in _clean(cdiag.get("full_text"))\n                        row["gwp_page_detected"] = "[PDF PAGE" in _clean(cdiag.get("full_text"))\n                    f = by_url.get(url)\n                    if f is not None:\n                        row["relaxed_candidate"] = True\n                        row["relaxed_reason"] = f.get("reason")\n                        row["relaxed_normalized_ef"] = f.get("ef_value")\n                        row["relaxed_reference_unit"] = f.get("reference_unit")\n\n                provisional = self._build_provisional_consensus(material, provisional_factors)\n                if provisional is not None:\n                    try:\n                        source_details = json.loads(provisional.get("relaxed_sources_json") or "[]")\n                    except Exception:\n                        source_details = []\n                    retained_urls = {_clean(x.get("source_url")) for x in source_details if x.get("retained_for_consensus")}\n                    outlier_urls = {_clean(x.get("source_url")) for x in source_details if x.get("outlier")}\n                    for row in all_evidence:\n                        url = _clean(row.get("url"))\n                        if url in retained_urls:\n                            row["relaxed_retained"] = True\n                            row["selected"] = True\n                        if url in outlier_urls:\n                            row["relaxed_outlier"] = True\n                    provisional = dict(provisional)\n                    provisional["technical_equivalence_version"] = TECHNICAL_EQUIVALENCE_VERSION if equivalent_plan else None\n                    provisional["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                    provisional["external_verified_relaxed_elapsed_seconds"] = round(time.monotonic() - class4_started, 3)\n                    provisional["external_verified_relaxed_queries_used"] = external_verified_relaxed_queries_used\n                    provisional["external_verified_relaxed_sources_inspected"] = class4_inspected\n                    provisional["evidence_cache_version"] = CACHE_VERSION\n                    self.evidence_cache.put(\n                        category="emission_factor", material=material, target_geography=self.target_geography,\n                        resolved=provisional,\n                    )\n                    self._resolution_cache[key] = dict(provisional)\n                    self._progress(\n                        f"External Verified Phase B accepted · {material} · "\n                        f"{provisional.get(\'relaxed_retained_count\', 1)} retained source(s)"\n                    )\n                    return provisional, all_evidence\n\n        # If a source looked promising but the first extraction was incomplete,\n        # use remaining relaxed-phase time to re-open at most two such documents more\n        # deeply. This is still source extraction only; no GWP value is in code.\n        if promising_candidates and time.monotonic() - class4_started < class4_time_budget:\n            old_pages = self.pdf_max_pages\n            old_links = self.linked_documents_per_page\n            try:\n                self.pdf_max_pages = self.adaptive_pdf_max_pages\n                self.linked_documents_per_page = self.adaptive_linked_documents_per_page\n                deep_candidates = []\n                for c0 in promising_candidates[:2]:\n                    if time.monotonic() - class4_started >= class4_time_budget:\n                        break\n                    c = dict(c0)\n                    self._progress(f"External Verified · Phase B deeper extraction of promising source · {material}")\n                    c["full_text"] = self._extract(c.get("url"))\n                    c["excerpt"] = c["full_text"][: max(self.excerpt_chars, 2500)]\n                    deep_candidates.append(c)\n                for c in deep_candidates:\n                    provisional_factors.extend(\n                        self._extract_relaxed_candidates(material, c.get("tier") or "GLOBAL", [c])\n                    )\n                provisional = self._build_provisional_consensus(material, provisional_factors) if provisional_factors else None\n                if provisional is not None:\n                    provisional = dict(provisional)\n                    provisional["adaptive_search_used"] = True\n                    provisional["adaptive_search_trigger"] = "; ".join(sorted(set(promising_reasons)))\n                    provisional["adaptive_deep_extraction_used"] = True\n                    provisional["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                    provisional["external_verified_relaxed_elapsed_seconds"] = round(time.monotonic() - class4_started, 3)\n                    provisional["external_verified_relaxed_queries_used"] = external_verified_relaxed_queries_used\n                    provisional["external_verified_relaxed_sources_inspected"] = class4_inspected\n                    provisional["evidence_cache_version"] = CACHE_VERSION\n                    self.evidence_cache.put(\n                        category="emission_factor", material=material,\n                        target_geography=self.target_geography, resolved=provisional,\n                    )\n                    self._resolution_cache[key] = dict(provisional)\n                    self._progress(f"External Verified Phase B accepted after deeper extraction · {material}")\n                    return provisional, all_evidence\n            finally:\n                self.pdf_max_pages = old_pages\n                self.linked_documents_per_page = old_links\n\n        self._progress(\n            f"External Verified Phase B finished without accepted factor · {material} · "\n            f"{class4_inspected} source(s), {external_verified_relaxed_queries_used} query/queries · moving to Class 4 fallback"\n        )\n        return None, all_evidence\n\n    @staticmethod\n    def _parse_model_json(raw: str) -> dict[str, Any] | None:\n        try:\n            obj = json.loads(raw.strip())\n            return obj if isinstance(obj, dict) else None\n        except Exception:\n            m = re.search(r"\\{.*\\}", raw or "", flags=re.S)\n            if not m:\n                return None\n            try:\n                obj = json.loads(m.group(0))\n                return obj if isinstance(obj, dict) else None\n            except Exception:\n                return None\n\n\n    def _validated_model_factor(\n        self, obj: dict[str, Any], material: str, expected_reference_unit: str,\n        preferred_reference_unit: str, *, analog: bool,\n    ):\n        """Validate one Class-4 model estimate and normalize its denominator.\n\n        No environmental magnitude prior is used. The model must answer in the\n        unit requested for that independent call. Python then converts that\n        denominator, when dimensionally possible without a material property, to\n        the final reference unit used by the BOM calculation. This makes kg/g/t\n        or kWh/MJ scale mistakes visible as disagreement between independent\n        calls instead of silently accepting one denominator interpretation.\n        """\n        required = {\n            "found", "central_value", "lower_value", "upper_value", "reference_unit",\n            "boundary", "indicator", "geography_assumption", "estimation_basis",\n            ("analog_material" if analog else "product_interpretation"), "rationale",\n        }\n        if not isinstance(obj, dict) or set(obj.keys()) != required or not bool(obj.get("found")):\n            return None, "schema_or_found_invalid"\n\n        raw_central = _num(obj.get("central_value"))\n        raw_lower = _num(obj.get("lower_value"))\n        raw_upper = _num(obj.get("upper_value"))\n        if raw_central is None or raw_lower is None or raw_upper is None or not (0 < raw_lower < raw_central < raw_upper):\n            return None, "range_invalid"\n\n        expected_ref = norm_unit(expected_reference_unit)\n        preferred_ref = norm_unit(preferred_reference_unit)\n        generated_ref = norm_unit(obj.get("reference_unit"))\n        if generated_ref != expected_ref:\n            return None, f"reference_unit_mismatch:{generated_ref or \'blank\'}_vs_requested_{expected_ref}"\n\n        if not _boundary_ok(_clean(obj.get("boundary"))):\n            return None, "boundary_not_product_stage_a1_a3"\n\n        indicator = _clean(obj.get("indicator")).upper().replace("_", "-")\n        if _requires_no_biogenic_storage(material):\n            if "GWP-GHG" not in indicator and "GWP-FOSSIL" not in indicator:\n                return None, "biogenic_indicator_invalid"\n            final_indicator = "GWP-GHG" if "GWP-GHG" in indicator else "GWP-fossil"\n        else:\n            if "GWP" not in indicator and "CLIMATE" not in indicator:\n                return None, "indicator_invalid"\n            final_indicator = "GWP-total"\n\n        # First validate the raw model output structurally in the unit requested\n        # for this call. This uses no material-specific magnitude limit.\n        plausible, reason = emission_factor_plausible(\n            material, raw_central, generated_ref, raw_lower, raw_upper\n        )\n        if not plausible:\n            return None, reason\n\n        central = convert_factor_reference_basis(raw_central, generated_ref, preferred_ref)\n        lower = convert_factor_reference_basis(raw_lower, generated_ref, preferred_ref)\n        upper = convert_factor_reference_basis(raw_upper, generated_ref, preferred_ref)\n        if central is None or lower is None or upper is None:\n            return None, f"reference_unit_not_dimensionally_convertible:{generated_ref}_to_{preferred_ref}"\n        if not (0 < lower < central < upper):\n            return None, "normalized_range_invalid"\n\n        plausible, reason = emission_factor_plausible(\n            material, central, preferred_ref, lower, upper\n        )\n        if not plausible:\n            return None, f"normalized_{reason}"\n\n        if not analog:\n            identity_ok, identity_reason = self._model_product_identity_compatible(\n                material,\n                _clean(obj.get("product_interpretation")),\n                _clean(obj.get("rationale")),\n                _clean(obj.get("estimation_basis")),\n            )\n            if not identity_ok:\n                return None, f"semantic_identity_veto:{identity_reason}"\n\n        return {\n            "central": float(central), "lower": float(lower), "upper": float(upper),\n            "ref_unit": preferred_ref, "indicator": final_indicator,\n            "basis": _clean(obj.get("estimation_basis")),\n            "interpretation": _clean(obj.get("analog_material" if analog else "product_interpretation")),\n            "rationale": _clean(obj.get("rationale")),\n            "geography": _clean(obj.get("geography_assumption")),\n            "generated_reference_unit": generated_ref,\n            "requested_reference_unit": expected_ref,\n            "generated_central_value": float(raw_central),\n            "generated_lower_value": float(raw_lower),\n            "generated_upper_value": float(raw_upper),\n        }, "ok"\n\n    @staticmethod\n    def _invalid_factor_candidate(*, analog: bool, analog_material: str = "") -> dict[str, Any]:\n        d = {\n            "found": False, "central_value": None, "lower_value": None,\n            "upper_value": None, "reference_unit": None, "boundary": None,\n            "indicator": None, "geography_assumption": None,\n            "estimation_basis": None, "rationale": None,\n        }\n        if analog:\n            d["analog_material"] = analog_material\n        else:\n            d["product_interpretation"] = None\n        return d\n\n    def _generate_one_factor_candidate(\n        self, *, system_prompt: str, payload: dict[str, Any], material: str,\n        requested_reference_unit: str, preferred_reference_unit: str, analog: bool,\n        analog_material: str = "",\n    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:\n        attempts = []\n        working = dict(payload)\n        for attempt_no in range(1, 3):\n            raw = _call_matcher(self.matcher, system_prompt, working, max_new_tokens=480)\n            obj = self._parse_model_json(raw)\n            reason = "parse_error"\n            parsed = None\n            if isinstance(obj, dict):\n                parsed, reason = self._validated_model_factor(\n                    obj, material, requested_reference_unit, preferred_reference_unit, analog=analog\n                )\n                if analog and parsed is not None and _clean(obj.get("analog_material")) != _clean(analog_material):\n                    parsed = None\n                    reason = "analog_name_not_preserved"\n            attempts.append({\n                "attempt": attempt_no, "accepted": parsed is not None,\n                "requested_reference_unit": norm_unit(requested_reference_unit),\n                "normalized_reference_unit": norm_unit(preferred_reference_unit),\n                "reason": reason, "raw_model_output": raw,\n            })\n            if parsed is not None:\n                return obj, attempts\n            working = {\n                **payload,\n                "repair_instruction": (\n                    "Return one complete JSON object only. Correct the schema/unit/boundary/interval issue stated below. "\n                    "Use requested_reference_unit exactly. Do not use any prescribed material-specific numeric range."\n                ),\n                "previous_validation_error": reason,\n                "previous_output": (raw or "")[-1400:],\n            }\n        return self._invalid_factor_candidate(analog=analog, analog_material=analog_material), attempts\n\n\n    def _snapshot_process_factor(self, process: dict[str, Any], preferred: str):\n        """Return one frozen-snapshot factor normalized to the BOM reference unit.\n\n        This helper never invents or clamps a magnitude. It accepts only a finite\n        positive factor already present in the hash-verified openLCA snapshot and\n        uses universal denominator conversion when the process basis is directly\n        convertible to the BOM basis.\n        """\n        uid = _clean(process.get("process_uuid"))\n        factors = self.factor_snapshot.get("factors") if isinstance(self.factor_snapshot, dict) else None\n        if not uid or not isinstance(factors, dict):\n            return None, "factor_snapshot_unavailable"\n        snap = factors.get(uid)\n        if not isinstance(snap, dict) or _clean(snap.get("status")).upper() != "OK":\n            return None, "snapshot_factor_not_ok"\n        raw_factor = _num(snap.get("emission_factor"))\n        raw_ref = norm_unit(snap.get("reference_unit") or process.get("ref_unit"))\n        if raw_factor is None or raw_factor <= 0 or not raw_ref:\n            return None, "snapshot_factor_missing_or_nonpositive"\n        normalized = convert_factor_reference_basis(float(raw_factor), raw_ref, preferred)\n        if normalized is None or not math.isfinite(float(normalized)) or float(normalized) <= 0:\n            return None, f"snapshot_reference_unit_not_convertible:{raw_ref}_to_{preferred}"\n        ok, reason = emission_factor_plausible("", float(normalized), preferred)\n        if not ok:\n            return None, f"snapshot_normalized_{reason}"\n        return {\n            "process_uuid": uid,\n            "process_name": _clean(process.get("process_name")),\n            "location": _clean(process.get("location")),\n            "category": _clean(process.get("category")),\n            "process_type": _clean(process.get("process_type")),\n            "process_reference_unit": raw_ref,\n            "snapshot_factor_raw": float(raw_factor),\n            "reference_unit": preferred,\n            "normalized_factor": float(normalized),\n            "impact_basis": snap.get("impact_basis"),\n        }, "ok"\n\n    def _rank_dynamic_database_candidates(\n        self,\n        material: str,\n        candidates: list[dict[str, Any]],\n        *,\n        proxy_level: str,\n    ) -> tuple[list[str], dict[str, Any]]:\n        """Rank only supplied catalog processes; factor magnitudes are hidden from Qwen."""\n        if not candidates:\n            return [], {"accepted": False, "reason": "no_candidates"}\n        allowed = {_clean(x.get("process_uuid")) for x in candidates if _clean(x.get("process_uuid"))}\n        presented = []\n        for c in candidates[:18]:\n            presented.append({\n                "process_uuid": c.get("process_uuid"),\n                "process_name": c.get("process_name"),\n                "category": c.get("category"),\n                "location": c.get("location"),\n                "process_type": c.get("process_type"),\n                "reference_unit": c.get("process_reference_unit"),\n                "query_origin": c.get("query_origin"),\n                "analog_material": c.get("analog_material"),\n                "similarity_basis": c.get("similarity_basis"),\n            })\n        payload = {\n            "material": material,\n            "target_context": self.target_geography,\n            "proxy_level": proxy_level,\n            "candidates": presented,\n            "important": "No emission-factor values are supplied. Rank only technical/process suitability.",\n        }\n        raw = _call_matcher(\n            self.matcher, DYNAMIC_DATABASE_PROXY_SELECTOR_SYSTEM_PROMPT, payload,\n            max_new_tokens=320,\n        )\n        obj = self._parse_model_json(raw)\n        ranked: list[str] = []\n        reason = ""\n        if isinstance(obj, dict) and set(obj.keys()) == {"ranked_process_uuids", "selection_reason"}:\n            xs = obj.get("ranked_process_uuids")\n            if isinstance(xs, list) and len(xs) <= 3 and all(isinstance(x, str) for x in xs):\n                ranked = [x for x in xs if x in allowed]\n                if len(ranked) != len(xs):\n                    ranked = []\n                reason = _clean(obj.get("selection_reason"))\n        return ranked, {\n            "accepted": bool(ranked),\n            "reason": reason or ("valid_ranked_processes" if ranked else "model_ranking_invalid_or_empty"),\n            "raw_model_output": raw,\n            "candidate_count": len(candidates),\n            "factor_values_hidden_from_model": True,\n        }\n\n    @staticmethod\n    def _sort_catalog_proxy_candidates(candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:\n        """Deterministic fallback order after all candidates already pass compatibility."""\n        return sorted(\n            candidates,\n            key=lambda x: (\n                int(x.get("analog_rank") or 0),\n                -float(x.get("retrieval_score") or 0.0),\n                _clean(x.get("process_name")).lower(),\n                _clean(x.get("process_uuid")),\n            ),\n        )\n\n    def _resolved_dynamic_snapshot_proxy(\n        self,\n        material: str,\n        selected: dict[str, Any],\n        candidates: list[dict[str, Any]],\n        *,\n        method: str,\n        proxy_level: str,\n        selection_reason: str,\n        selector_diag: dict[str, Any],\n        planning_diag: dict[str, Any] | None = None,\n    ) -> dict[str, Any]:\n        peers = [\n            {\n                "process_uuid": c.get("process_uuid"),\n                "process_name": c.get("process_name"),\n                "location": c.get("location"),\n                "reference_unit": c.get("reference_unit"),\n                "normalized_factor": c.get("normalized_factor"),\n                "query_origin": c.get("query_origin"),\n                "analog_material": c.get("analog_material"),\n                "similarity_basis": c.get("similarity_basis"),\n            }\n            for c in candidates[:12]\n        ]\n        selected_factor = float(selected["normalized_factor"])\n        attempt = {\n            "stage": method,\n            "accepted": True,\n            "proxy_level": proxy_level,\n            "selected_process_uuid": selected.get("process_uuid"),\n            "selected_process_name": selected.get("process_name"),\n            "selection_reason": selection_reason,\n            "selector": selector_diag,\n            "planning": planning_diag,\n            "candidate_count": len(candidates),\n            "factor_origin": "HASH_VERIFIED_FROZEN_OPENLCA_SNAPSHOT",\n            "llm_generated_emission_factor": False,\n        }\n        self._last_fallback_attempts.append(attempt)\n        analog_text = _clean(selected.get("analog_material"))\n        sim_text = _clean(selected.get("similarity_basis"))\n        basis_bits = [\n            f"Frozen ELCD/openLCA process: {selected.get(\'process_name\')}",\n            f"dynamic proxy level: {proxy_level}",\n        ]\n        if analog_text:\n            basis_bits.append(f"analog: {analog_text}")\n        if sim_text:\n            basis_bits.append(f"analog basis: {sim_text}")\n        return {\n            "ef_value": selected_factor,\n            "reference_unit": selected.get("reference_unit"),\n            "lower_value": None,\n            "upper_value": None,\n            "verification": "UNVERIFIED_FALLBACK_ESTIMATE",\n            "source_class": "UNVERIFIED_FALLBACK_ESTIMATE",\n            "fallback_method": method,\n            "source_title": f"Frozen ELCD/openLCA dynamic proxy: {selected.get(\'process_name\')}",\n            "source_url": None,\n            "source_geography": selected.get("location") or "ELCD process location not stated",\n            "source_year": None,\n            "search_tier": proxy_level,\n            "search_query": selected.get("query_origin"),\n            "evidence_quote": None,\n            "declared_unit_evidence": f"Frozen snapshot reference unit: {selected.get(\'process_reference_unit\')}",\n            "boundary": "Selected LCIA of frozen ELCD/openLCA proxy process; proxy selection is unverified",\n            "indicator": "GWP-total",\n            "declared_impact_value": selected_factor,\n            "declared_impact_unit": "kg CO2e",\n            "declared_quantity": 1.0,\n            "declared_unit": selected.get("reference_unit"),\n            "uncertainty_type": "DYNAMIC_DATABASE_PROXY_PEDIGREE_REQUIRED",\n            "uncertainty_lower_value": None,\n            "uncertainty_upper_value": None,\n            "uncertainty_gsd": None,\n            "uncertainty_cv": None,\n            "uncertainty_confidence_level": None,\n            "uncertainty_evidence_quote": None,\n            "reason": (\n                "No acceptable external/source-supported factor was found. The numerical factor was NOT generated by Qwen. "\n                "Qwen was used only to expand terminology/analogs and rank supplied frozen catalog processes; Python then read the selected process factor from the hash-verified openLCA snapshot. "\n                + "; ".join(basis_bits)\n            ),\n            "raw_model_output": selector_diag.get("raw_model_output"),\n            "fallback_attempts_json": json.dumps(self._last_fallback_attempts, ensure_ascii=False),\n            "guardrail_version": GUARDRAIL_VERSION,\n            "guardrail_status": "PASS_DYNAMIC_FROZEN_DATABASE_PROXY",\n            "guardrail_reason": selection_reason,\n            "selected_result_id": selected.get("process_uuid"),\n            "external_match_type": "UNVERIFIED_FALLBACK_ESTIMATE",\n            "external_proxy_basis": "; ".join(basis_bits),\n            "product_identity_status": "DYNAMIC_DATABASE_PROXY_NOT_SOURCE_VERIFIED",\n            "product_identity_reason": selection_reason,\n            "product_identity_title": material,\n            "biogenic_carbon_policy": None,\n            "proxy_representativeness": proxy_level,\n            "peer_values_json": json.dumps([c.get("normalized_factor") for c in candidates[:12]], ensure_ascii=False),\n            "peer_sources_json": json.dumps(peers, ensure_ascii=False),\n            "unit_basis_records_json": json.dumps(peers, ensure_ascii=False),\n            "terminal_quality_flag": "DATABASE_ANCHORED_CLASS5",\n        }\n\n    def _estimate_dynamic_frozen_database_proxy(self, material: str, source_unit: Any):\n        """Class-4A: same-family dynamic proxy using only frozen database numbers."""\n        preferred = norm_unit(source_unit)\n        if preferred not in {"kg", "g", "t", "m3", "l", "cm3", "m2", "cm2", "mm2", "item", "kwh", "mj"}:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5A_DYNAMIC_FROZEN_DATABASE_PROXY", "accepted": False,\n                "reason": f"unsupported_reference_unit:{preferred or \'blank\'}",\n            })\n            return None\n        if _requires_no_biogenic_storage(material):\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5A_DYNAMIC_FROZEN_DATABASE_PROXY", "accepted": False,\n                "reason": "skipped_biogenic_policy_requires_gwp_ghg_or_fossil",\n            })\n            return None\n        if not isinstance(self.factor_snapshot.get("factors"), dict):\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5A_DYNAMIC_FROZEN_DATABASE_PROXY", "accepted": False,\n                "reason": "factor_snapshot_unavailable",\n            })\n            return None\n\n        queries = [material]\n        plan = infer_technical_equivalents(\n            self.matcher, material=material, target_context=self.target_geography\n        )\n        if plan:\n            normalized_product = _clean(plan.get("normalized_product"))\n            if normalized_product:\n                compatible, _ = process_compatibility(material, normalized_product)\n                if compatible:\n                    queries.append(normalized_product)\n            queries.extend(_clean(x.get("term")) for x in plan.get("search_terms", []) if _clean(x.get("term")))\n        queries = list(dict.fromkeys(q for q in queries if q))\n\n        by_uuid: dict[str, dict[str, Any]] = {}\n        retrieval_diag = []\n        for query_rank, query in enumerate(queries, start=1):\n            try:\n                retrieved = list(self.matcher.retriever.retrieve(query) or [])\n            except Exception as exc:\n                retrieval_diag.append({"query": query, "error": str(exc)})\n                continue\n            retrieval_diag.append({"query": query, "retrieved": len(retrieved)})\n            for r in retrieved:\n                pname = _clean(r.get("process_name"))\n                compatible, why = process_compatibility(material, pname)\n                if not compatible:\n                    continue\n                factor_rec, freason = self._snapshot_process_factor(r, preferred)\n                if factor_rec is None:\n                    continue\n                factor_rec.update({\n                    "query_origin": query,\n                    "query_rank": query_rank,\n                    "analog_rank": 0,\n                    "retrieval_score": float(r.get("retrieval_score") or 0.0),\n                    "compatibility_reason": why,\n                })\n                uid = factor_rec["process_uuid"]\n                prev = by_uuid.get(uid)\n                if prev is None or float(factor_rec.get("retrieval_score") or 0.0) > float(prev.get("retrieval_score") or 0.0):\n                    by_uuid[uid] = factor_rec\n\n        candidates = self._sort_catalog_proxy_candidates(list(by_uuid.values()))\n        if not candidates:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5A_DYNAMIC_FROZEN_DATABASE_PROXY", "accepted": False,\n                "reason": "no_compatible_unit_convertible_frozen_process",\n                "queries": queries, "retrieval": retrieval_diag,\n                "technical_equivalence_plan": plan,\n            })\n            return None\n\n        ranked, selector_diag = self._rank_dynamic_database_candidates(\n            material, candidates, proxy_level="SAME_FAMILY_DYNAMIC_FROZEN_DATABASE_PROXY"\n        )\n        selected = next((c for uid in ranked for c in candidates if c.get("process_uuid") == uid), None)\n        selection_reason = selector_diag.get("reason") or ""\n        if selected is None:\n            # This deterministic fallback is safe because every candidate has\n            # already passed the requested material\'s family compatibility gate\n            # and has a usable factor in the hash-verified snapshot.\n            selected = candidates[0]\n            selection_reason = "MODEL_RANKING_EMPTY; deterministic best retrieval among pre-vetted same-family processes"\n        return self._resolved_dynamic_snapshot_proxy(\n            material, selected, candidates,\n            method="DYNAMIC_FROZEN_ELCD_SAME_FAMILY_PROXY",\n            proxy_level="SAME_FAMILY_DYNAMIC_FROZEN_DATABASE_PROXY",\n            selection_reason=selection_reason,\n            selector_diag=selector_diag,\n            planning_diag={"technical_equivalence_plan": plan, "queries": queries, "retrieval": retrieval_diag},\n        )\n\n    def _estimate_dynamic_frozen_analog_proxy(self, material: str, source_unit: Any):\n        """Class-4B: dynamically inferred nearby analog, but factor remains database-derived."""\n        preferred = norm_unit(source_unit)\n        if preferred not in {"kg", "g", "t", "m3", "l", "cm3", "m2", "cm2", "mm2", "item", "kwh", "mj"}:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5B_DYNAMIC_FROZEN_ANALOG_PROXY", "accepted": False,\n                "reason": f"unsupported_reference_unit:{preferred or \'blank\'}",\n            })\n            return None\n        if _requires_no_biogenic_storage(material):\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5B_DYNAMIC_FROZEN_ANALOG_PROXY", "accepted": False,\n                "reason": "skipped_biogenic_policy_requires_gwp_ghg_or_fossil",\n            })\n            return None\n        if not isinstance(self.factor_snapshot.get("factors"), dict):\n            return None\n\n        plan = infer_analog_plan(\n            self.matcher, material=material,\n            estimation_target=f"select a frozen ELCD/openLCA A1-A3 GWP proxy convertible to {preferred}; do not estimate GWP",\n            target_context=self.target_geography,\n            feedback="Keep analogs as close as possible to the requested product family; no numerical values.",\n        )\n        if not plan:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5B_DYNAMIC_FROZEN_ANALOG_PROXY", "accepted": False,\n                "reason": "semantic_analog_plan_invalid",\n            })\n            return None\n\n        requested_family = classify_material(material)\n        by_uuid: dict[str, dict[str, Any]] = {}\n        analog_diag = []\n        for analog_rank, analog in enumerate(plan.get("analogs", []), start=1):\n            analog_name = _clean(analog.get("analog_material"))\n            similarity_basis = _clean(analog.get("similarity_basis"))\n            if not analog_name:\n                continue\n            # For known requested families, the inferred analog must itself pass\n            # the same deterministic family-compatibility gate. This prevents a\n            # galvanized-steel product from drifting to aluminium, paperboard,\n            # cement/plastic, etc. Unknown families retain the LLM-planned analog.\n            if requested_family != "UNKNOWN":\n                analog_ok, analog_reason = process_compatibility(material, analog_name)\n                if not analog_ok:\n                    analog_diag.append({\n                        "analog": analog_name, "accepted": False,\n                        "reason": f"requested_family_veto:{analog_reason}",\n                    })\n                    continue\n            try:\n                retrieved = list(self.matcher.retriever.retrieve(analog_name) or [])\n            except Exception as exc:\n                analog_diag.append({"analog": analog_name, "accepted": False, "reason": str(exc)})\n                continue\n            analog_diag.append({"analog": analog_name, "accepted": True, "retrieved": len(retrieved)})\n            for r in retrieved:\n                pname = _clean(r.get("process_name"))\n                process_ok, process_reason = process_compatibility(analog_name, pname)\n                if not process_ok:\n                    continue\n                factor_rec, freason = self._snapshot_process_factor(r, preferred)\n                if factor_rec is None:\n                    continue\n                factor_rec.update({\n                    "query_origin": analog_name,\n                    "analog_material": analog_name,\n                    "similarity_basis": similarity_basis,\n                    "semantic_family": plan.get("family_description"),\n                    "analog_rank": analog_rank,\n                    "retrieval_score": float(r.get("retrieval_score") or 0.0),\n                    "compatibility_reason": process_reason,\n                })\n                uid = factor_rec["process_uuid"]\n                prev = by_uuid.get(uid)\n                if prev is None or analog_rank < int(prev.get("analog_rank") or 999):\n                    by_uuid[uid] = factor_rec\n\n        candidates = self._sort_catalog_proxy_candidates(list(by_uuid.values()))\n        if not candidates:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5B_DYNAMIC_FROZEN_ANALOG_PROXY", "accepted": False,\n                "reason": "no_compatible_unit_convertible_dynamic_analog_process",\n                "semantic_analog_plan": plan, "analog_diagnostics": analog_diag,\n            })\n            return None\n\n        ranked, selector_diag = self._rank_dynamic_database_candidates(\n            material, candidates, proxy_level="SEMANTIC_ANALOG_DYNAMIC_FROZEN_DATABASE_PROXY"\n        )\n        selected = next((c for uid in ranked for c in candidates if c.get("process_uuid") == uid), None)\n        selection_reason = selector_diag.get("reason") or ""\n        if selected is None:\n            selected = candidates[0]\n            selection_reason = "MODEL_RANKING_EMPTY; deterministic closest analog order among pre-vetted analog processes"\n        return self._resolved_dynamic_snapshot_proxy(\n            material, selected, candidates,\n            method="DYNAMIC_FROZEN_ELCD_SEMANTIC_ANALOG_PROXY",\n            proxy_level="SEMANTIC_ANALOG_DYNAMIC_FROZEN_DATABASE_PROXY",\n            selection_reason=selection_reason,\n            selector_diag=selector_diag,\n            planning_diag={"semantic_analog_plan": plan, "analog_diagnostics": analog_diag},\n        )\n\n    @staticmethod\n    def _model_product_identity_compatible(material: str, interpretation: str, rationale: str = "", basis: str = "") -> tuple[bool, str]:\n        """Deterministic semantic veto for free-form terminal model estimates.\n\n        The product_interpretation itself must pass the same taxonomy/process\n        compatibility logic used elsewhere. Rationale/basis may veto a result but\n        can never rescue a contradictory interpretation. This prevents circular\n        acceptance where a model merely repeats an acronym (for example ``CGI``)\n        while expanding it into a different product family. No GWP magnitude or\n        material-specific environmental value is used here.\n        """\n        expected = classify_material(material)\n        if expected == "UNKNOWN":\n            return True, "unknown_material_family_no_deterministic_identity_veto"\n\n        interp = _clean(interpretation)\n        if not interp:\n            return False, "model_product_interpretation_blank"\n\n        # Identity must be explicit in product_interpretation itself. Do not let\n        # rationale, estimation basis, or an echoed shorthand token rescue it.\n        interp_ok, interp_reason = process_compatibility(material, interp)\n        if not interp_ok:\n            return False, f"model_product_interpretation_not_family_compatible:{expected}:{interp_reason}"\n\n        ferrous = {"REBAR", "STEEL_WIRE", "STEEL_FASTENER", "GALVANIZED_FLAT_STEEL"}\n        cementitious_or_stone = {"CEMENT", "PLAIN_CONCRETE", "STONECRETE_BLOCK", "PLASTER", "NATURAL_STONE", "GRAVEL_AGGREGATE", "SAND"}\n        bio = {"TIMBER", "PLYWOOD", "BAMBOO"}\n        earth = {"SOIL_EARTH", "SOIL_BLOCK"}\n\n        rationale_text = " ".join(x for x in (_clean(rationale), _clean(basis)) if x)\n        rationale_family = classify_material(rationale_text) if rationale_text else "UNKNOWN"\n        if expected in ferrous and rationale_family not in ferrous | {"UNKNOWN"}:\n            return False, f"model_rationale_chemistry_contradiction:{expected}_vs_{rationale_family}"\n        if expected in bio and rationale_family in ferrous | cementitious_or_stone | earth:\n            return False, f"model_rationale_chemistry_contradiction:{expected}_vs_{rationale_family}"\n        if expected in earth and rationale_family in ferrous | bio | cementitious_or_stone:\n            return False, f"model_rationale_chemistry_contradiction:{expected}_vs_{rationale_family}"\n        if expected in cementitious_or_stone and rationale_family in ferrous | bio | earth:\n            return False, f"model_rationale_chemistry_contradiction:{expected}_vs_{rationale_family}"\n\n        combined = " ".join(x for x in (interp, _clean(rationale), _clean(basis)) if x)\n        combined_ok, combined_reason = process_compatibility(material, combined)\n        if not combined_ok:\n            return False, f"model_combined_identity_not_family_compatible:{expected}:{combined_reason}"\n        return True, "model_identity_passes_interpretation_first_family_gate"\n\n    def _parse_terminal_minimal_factor(self, raw: str, material: str, preferred: str):\n        obj = self._parse_model_json(raw)\n        required = {\n            "found", "central_value", "reference_unit", "boundary", "indicator",\n            "product_interpretation", "rationale",\n        }\n        if not isinstance(obj, dict) or set(obj.keys()) != required or not bool(obj.get("found")):\n            return None, "terminal_minimal_schema_invalid"\n        central = _num(obj.get("central_value"))\n        if central is None or central <= 0:\n            return None, "terminal_minimal_value_invalid"\n        generated_ref = norm_unit(obj.get("reference_unit"))\n        if generated_ref != preferred:\n            return None, f"terminal_minimal_reference_unit_mismatch:{generated_ref or \'blank\'}_vs_{preferred}"\n        if not _boundary_ok(_clean(obj.get("boundary"))):\n            return None, "terminal_minimal_boundary_invalid"\n        indicator = _clean(obj.get("indicator")).upper().replace("_", "-")\n        if _requires_no_biogenic_storage(material):\n            if "GWP-GHG" not in indicator and "GWP-FOSSIL" not in indicator:\n                return None, "terminal_minimal_biogenic_indicator_invalid"\n            final_indicator = "GWP-GHG" if "GWP-GHG" in indicator else "GWP-fossil"\n        else:\n            if "GWP" not in indicator and "CLIMATE" not in indicator:\n                return None, "terminal_minimal_indicator_invalid"\n            final_indicator = "GWP-total"\n        ok, reason = emission_factor_plausible(material, central, preferred)\n        if not ok:\n            return None, f"terminal_minimal_{reason}"\n        identity_ok, identity_reason = self._model_product_identity_compatible(\n            material, _clean(obj.get("product_interpretation")), _clean(obj.get("rationale")), ""\n        )\n        if not identity_ok:\n            return None, f"terminal_minimal_semantic_identity_veto:{identity_reason}"\n        return {\n            "central": float(central), "lower": None, "upper": None,\n            "ref_unit": preferred, "indicator": final_indicator,\n            "interpretation": _clean(obj.get("product_interpretation")),\n            "rationale": _clean(obj.get("rationale")),\n        }, "ok"\n\n    def _estimate_terminal_llm_only_value(self, material: str, source_unit: Any):\n        """Last-resort single model-only value after database anchors are unavailable.\n\n        Unlike the earlier implementation, repeated model outputs are never used\n        as a validation signal and no pooled/median candidate rule can turn shared\n        hallucination into an accepted value. One fresh product-level estimate is\n        requested in the final reference unit. It must pass structural validation\n        AND the deterministic material-family semantic veto. A minimal-schema\n        retry exists only for JSON/parser recovery and must pass the same identity\n        veto. The result remains Class 4 and is excluded from verified and\n        verified subtotal.\n        """\n        preferred = norm_unit(source_unit)\n        supported = {"kg", "g", "t", "m3", "l", "cm3", "m2", "cm2", "mm2", "item", "kwh", "mj"}\n        if preferred not in supported:\n            self._last_fallback_attempts.append({\n                "stage": "CLASS5C_TERMINAL_MODEL_ONLY", "accepted": False,\n                "reason": f"unsupported_reference_unit:{preferred or \'blank\'}",\n            })\n            return None\n\n        self._progress(f"EF Class 4 · Method C · one terminal model-only estimate · {material} · basis {preferred}")\n        payload = {\n            "material": material,\n            "target_context": self.target_geography,\n            "requested_reference_unit": preferred,\n            "final_calculation_reference_unit": preferred,\n            "required_indicator": _required_indicator_policy(material),\n            "deterministic_material_family": classify_material(material),\n            "identity_validation_requirement": "product_interpretation must explicitly describe this family; do not merely echo or re-expand an acronym",\n            "estimation_lens": "fresh product-level composition and manufacturing reconstruction",\n            **emission_guardrail_context(material, preferred),\n            "status": (\n                "External evidence and dynamic frozen-database proxy routes failed. "\n                "Return one terminal unverified numerical estimate only if the product identity can be preserved."\n            ),\n            "important": (\n                "Do not treat agreement with any earlier model output as evidence. "\n                "Describe the requested product itself; a deterministic family gate will veto contradictory interpretations."\n            ),\n        }\n        obj, attempts = self._generate_one_factor_candidate(\n            system_prompt=TERMINAL_LLM_ONLY_EF_SINGLE_SYSTEM_PROMPT,\n            payload=payload,\n            material=material,\n            requested_reference_unit=preferred,\n            preferred_reference_unit=preferred,\n            analog=False,\n        )\n        parsed, reason = (\n            self._validated_model_factor(obj, material, preferred, preferred, analog=False)\n            if isinstance(obj, dict) and bool(obj.get("found")) else (None, "invalid_terminal_candidate")\n        )\n        self._last_fallback_attempts.append({\n            "stage": "CLASS5C_TERMINAL_MODEL_ONLY",\n            "accepted": parsed is not None,\n            "reason": reason,\n            "generation_attempts": attempts,\n            "repeated_value_consensus_used": False,\n        })\n        if parsed is not None:\n            central = float(parsed["central"])\n            lower = float(parsed["lower"])\n            upper = float(parsed["upper"])\n            return {\n                "ef_value": central,\n                "reference_unit": preferred,\n                "lower_value": lower,\n                "upper_value": upper,\n                "verification": "UNVERIFIED_FALLBACK_ESTIMATE",\n                "source_class": "UNVERIFIED_FALLBACK_ESTIMATE",\n                "fallback_method": "TERMINAL_SINGLE_LLM_VALUE_SEMANTIC_VETO",\n                "source_title": "Qwen terminal single model-only exploratory estimate",\n                "source_url": None,\n                "source_geography": "Unverified model assumption; target context " + self.target_geography,\n                "source_year": None,\n                "search_tier": "FINAL_TERMINAL_SINGLE_LLM_VALUE",\n                "search_query": None,\n                "evidence_quote": None,\n                "declared_unit_evidence": None,\n                "boundary": "A1-A3 / cradle-to-gate model assumption",\n                "indicator": parsed.get("indicator") or ("GWP-GHG" if _requires_no_biogenic_storage(material) else "GWP-total"),\n                "declared_impact_value": central,\n                "declared_impact_unit": "kg CO2e",\n                "declared_quantity": 1.0,\n                "declared_unit": preferred,\n                "uncertainty_type": "TERMINAL_SINGLE_MODEL_RANGE",\n                "uncertainty_lower_value": lower,\n                "uncertainty_upper_value": upper,\n                "uncertainty_gsd": None,\n                "uncertainty_cv": None,\n                "uncertainty_confidence_level": 95.0,\n                "uncertainty_evidence_quote": None,\n                "reason": (\n                    "No source-supported or database-anchored proxy could be used. One fresh model-only A1-A3 estimate was retained solely for terminal exploratory coverage. "\n                    "It passed unit/boundary/indicator checks and the deterministic material-family semantic veto. Repeated-value consensus was not used as validation."\n                ),\n                "raw_model_output": json.dumps(obj, ensure_ascii=False),\n                "fallback_attempts_json": json.dumps(self._last_fallback_attempts, ensure_ascii=False),\n                "guardrail_version": GUARDRAIL_VERSION,\n                "guardrail_status": "TERMINAL_SINGLE_VALUE_INTERPRETATION_FIRST_IDENTITY_PASS",\n                "guardrail_reason": "No repeated-value consensus used; product_interpretation independently passed deterministic family compatibility",\n                "selected_result_id": None,\n                "external_match_type": "UNVERIFIED_FALLBACK_ESTIMATE",\n                "external_proxy_basis": None,\n                "product_identity_status": "TERMINAL_UNVERIFIED_MODEL_ONLY_SEMANTIC_VETO_PASS",\n                "product_identity_reason": parsed.get("interpretation"),\n                "product_identity_title": material,\n                "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n                "proxy_representativeness": "TERMINAL_MODEL_ONLY_NO_DATABASE_ANCHOR",\n                "peer_values_json": json.dumps([central], ensure_ascii=False),\n                "terminal_quality_flag": "LOWEST_CONFIDENCE_MODEL_ONLY",\n            }\n\n        # Parser rescue only: this does not broaden semantic acceptance. The same\n        # deterministic product-family veto is applied by _parse_terminal_minimal_factor.\n        working = {\n            "material": material,\n            "target_context": self.target_geography,\n            "requested_reference_unit": preferred,\n            "required_indicator": _required_indicator_policy(material),\n            "deterministic_material_family": classify_material(material),\n            "identity_validation_requirement": "product_interpretation must explicitly describe this family; do not merely echo or re-expand an acronym",\n            "status": "Parser-recovery only for one terminal unverified A1-A3 value.",\n            "repair_instruction": "Preserve the exact product identity; JSON only.",\n        }\n        minimal_attempts = []\n        for attempt_no in range(1, 3):\n            raw = _call_matcher(self.matcher, TERMINAL_MINIMAL_EF_SYSTEM_PROMPT, working, max_new_tokens=260)\n            parsed_min, min_reason = self._parse_terminal_minimal_factor(raw, material, preferred)\n            minimal_attempts.append({\n                "attempt": attempt_no,\n                "accepted": parsed_min is not None,\n                "reason": min_reason,\n                "raw_model_output": raw,\n            })\n            if parsed_min is not None:\n                central = float(parsed_min["central"])\n                self._last_fallback_attempts.append({\n                    "stage": "CLASS5D_TERMINAL_MINIMAL_PARSER_RESCUE",\n                    "accepted": True,\n                    "attempts": minimal_attempts,\n                    "repeated_value_consensus_used": False,\n                })\n                return {\n                    "ef_value": central,\n                    "reference_unit": preferred,\n                    "lower_value": None,\n                    "upper_value": None,\n                    "verification": "UNVERIFIED_FALLBACK_ESTIMATE",\n                    "source_class": "UNVERIFIED_FALLBACK_ESTIMATE",\n                    "fallback_method": "TERMINAL_MINIMAL_SINGLE_LLM_VALUE_SEMANTIC_VETO",\n                    "source_title": "Qwen terminal minimal-schema model-only estimate",\n                    "source_url": None,\n                    "source_geography": "Unverified model assumption; target context " + self.target_geography,\n                    "source_year": None,\n                    "search_tier": "FINAL_TERMINAL_MINIMAL_SINGLE_VALUE",\n                    "search_query": None,\n                    "evidence_quote": None,\n                    "declared_unit_evidence": None,\n                    "boundary": "A1-A3 / cradle-to-gate model assumption",\n                    "indicator": parsed_min["indicator"],\n                    "declared_impact_value": central,\n                    "declared_impact_unit": "kg CO2e",\n                    "declared_quantity": 1.0,\n                    "declared_unit": preferred,\n                    "uncertainty_type": "TERMINAL_MODEL_NO_VALID_RANGE",\n                    "uncertainty_lower_value": None,\n                    "uncertainty_upper_value": None,\n                    "uncertainty_gsd": None,\n                    "uncertainty_cv": None,\n                    "uncertainty_confidence_level": None,\n                    "uncertainty_evidence_quote": None,\n                    "reason": (\n                        "All anchored Class-4 routes failed and the richer terminal schema could not be validated. "\n                        "A minimal single model-only value was retained after the same semantic identity veto. It is the lowest-confidence output and repeated-value consensus was not used."\n                    ),\n                    "raw_model_output": raw,\n                    "fallback_attempts_json": json.dumps(self._last_fallback_attempts, ensure_ascii=False),\n                    "guardrail_version": GUARDRAIL_VERSION,\n                    "guardrail_status": "TERMINAL_MINIMAL_SINGLE_VALUE_INTERPRETATION_FIRST_IDENTITY_PASS",\n                    "guardrail_reason": "LOWEST_CONFIDENCE_MODEL_ONLY_NO_RANGE",\n                    "selected_result_id": None,\n                    "external_match_type": "UNVERIFIED_FALLBACK_ESTIMATE",\n                    "external_proxy_basis": None,\n                    "product_identity_status": "TERMINAL_UNVERIFIED_MODEL_ONLY_SEMANTIC_VETO_PASS",\n                    "product_identity_reason": parsed_min.get("interpretation"),\n                    "product_identity_title": material,\n                    "biogenic_carbon_policy": ("EXCLUDE_STORAGE_USE_GWP_GHG" if _requires_no_biogenic_storage(material) else None),\n                    "proxy_representativeness": "TERMINAL_MINIMAL_MODEL_ONLY_NO_DATABASE_ANCHOR",\n                    "peer_values_json": json.dumps([central]),\n                    "terminal_quality_flag": "LOWEST_CONFIDENCE_MODEL_ONLY_NO_RANGE",\n                }\n            working = {\n                **working,\n                "previous_validation_error": min_reason,\n                "previous_output": (raw or "")[-1000:],\n                "repair_instruction": "Return the exact minimal JSON schema only and preserve the requested product family.",\n            }\n\n        self._last_fallback_attempts.append({\n            "stage": "CLASS5D_TERMINAL_MINIMAL_PARSER_RESCUE",\n            "accepted": False,\n            "attempts": minimal_attempts,\n            "reason": "no_semantically_valid_parseable_positive_terminal_value",\n        })\n        return None\n\n    def resolve_record(self, rec: dict[str, Any]):\n        item_id = _clean(rec.get("item_id") or rec.get("ID")) or "ITEM"\n        original_material = _clean(rec.get("original_material") or rec.get("Material"))\n        normalized_material = _clean(rec.get("normalized_material"))\n        material, material_basis = choose_resolution_material(original_material, normalized_material)\n        approved = _as_bool(rec.get("production_approved"))\n        structured_valid = _as_bool(rec.get("structured_output_valid"))\n        result = {\n            "external_ef_resolution_status": "NOT_APPLICABLE_ELCD_APPROVED" if approved else "UNRESOLVED",\n            "external_ef_value": None,\n            "external_ef_reference_unit": None,\n            "external_ef_lower_value": None,\n            "external_ef_upper_value": None,\n            "external_ef_uncertainty_type": None,\n            "external_ef_uncertainty_lower_value": None,\n            "external_ef_uncertainty_upper_value": None,\n            "external_ef_uncertainty_gsd": None,\n            "external_ef_uncertainty_cv": None,\n            "external_ef_uncertainty_confidence_level": None,\n            "external_ef_uncertainty_evidence_quote": None,\n            "external_ef_peer_values_json": None,\n            "external_ef_peer_sources_json": None,\n            "external_ef_unit_basis_records_json": None,\n            "external_ef_relaxed_sources_json": None,\n            "external_ef_relaxed_source_count": None,\n            "external_ef_relaxed_retained_count": None,\n            "external_ef_relaxed_outlier_count": None,\n            "external_ef_relaxed_consensus_method": None,\n            "external_ef_relaxed_consensus_version": None,\n            "external_ef_verification": "NOT_APPLICABLE" if approved else "UNRESOLVED",\n            "external_ef_source_class": None,\n            "external_ef_source_title": None,\n            "external_ef_source_url": None,\n            "external_ef_source_geography": None,\n            "external_ef_source_year": None,\n            "external_ef_search_tier": None,\n            "external_ef_search_query": None,\n            "external_ef_evidence_quote": None,\n            "external_ef_declared_unit_evidence": None,\n            "external_ef_boundary": None,\n            "external_ef_indicator": None,\n            "external_ef_reason": None,\n            "external_ef_match_type": None,\n            "external_ef_proxy_basis": None,\n            "external_ef_product_identity_status": None,\n            "external_ef_product_identity_reason": None,\n            "external_ef_product_identity_title": None,\n            "external_ef_material_query": material,\n            "external_ef_material_selection_basis": material_basis,\n            "external_ef_trigger": ("BIOGENIC_POLICY_EXTERNAL_REQUIRED" if _requires_no_biogenic_storage(material) else ("ELCD_REVIEW_REQUIRED" if structured_valid else "INVALID_QWEN_OUTPUT")),\n            "external_ef_material_family": classify_material(material),\n            "external_ef_material_taxonomy_version": MATERIAL_TAXONOMY_VERSION,\n            "external_ef_biogenic_carbon_policy": None,\n            "external_ef_proxy_representativeness": None,\n            "external_ef_fallback_method": None,\n            "external_ef_terminal_quality_flag": None,\n            "external_ef_details_json": None,\n            "external_ef_fallback_attempts_json": None,\n            "external_ef_guardrail_status": None,\n            "external_ef_guardrail_reason": None,\n            "external_ef_resolver_version": EXTERNAL_EF_RESOLVER_VERSION,\n            "external_ef_guardrail_version": GUARDRAIL_VERSION,\n            "external_ef_evidence_cache_version": CACHE_VERSION,\n            "external_ef_resolved_at_utc": datetime.now(timezone.utc).isoformat(),\n        }\n        if approved and not _requires_no_biogenic_storage(material):\n            return result, []\n        self._last_fallback_attempts = []\n        # A malformed Qwen response is still a Review Required outcome.  The\n        # external resolver is independent of the model selection stage, so it may\n        # continue from the original BOM description instead of discarding the row.\n        resolved, evidence = self._resolve_one(item_id, material)\n        source_unit = rec.get("unit") or rec.get("Unit")\n\n        # Class 4 fallback is database-anchored first. Qwen may expand terminology or\n        # rank supplied catalog processes, but it does not generate the numerical\n        # factor for these preferred fallback routes. This specifically prevents\n        # repeated model hallucinations from being treated as numerical validation.\n        if resolved is None and (self.allow_llm_unverified_estimate or self.allow_conservative_analog_estimate):\n            self._progress(f"EF Class 4 · Method A · dynamic same-family frozen-database proxy · {material}")\n            resolved = self._estimate_dynamic_frozen_database_proxy(material, source_unit)\n        if resolved is None and (self.allow_llm_unverified_estimate or self.allow_conservative_analog_estimate):\n            self._progress(f"EF Class 4 · Method B · dynamic semantic-analog frozen-database proxy · {material}")\n            resolved = self._estimate_dynamic_frozen_analog_proxy(material, source_unit)\n\n        # Only after source-supported and both database-anchored Class-4 routes\n        # fail is a free-form model number attempted. It is explicitly terminal,\n        # excluded from verified subtotal, and must pass the\n        # deterministic product-family semantic veto in addition to unit/boundary\n        # validation. No repeated-value consensus is treated as verification.\n        if resolved is None and self.allow_llm_unverified_estimate:\n            self._progress(f"EF Class 4 · Method C · terminal model-only fallback with semantic veto · {material}")\n            resolved = self._estimate_terminal_llm_only_value(material, source_unit)\n        if resolved is None:\n            # Ordinary evidence scarcity should not reach this branch. It is reserved\n            # for unsupported/invalid units or complete inability to obtain any\n            # parseable finite positive terminal model value after all retries.\n            result["external_ef_resolution_status"] = "INPUT_OR_MODEL_FAILURE"\n            result["external_ef_verification"] = "INPUT_OR_MODEL_FAILURE"\n            result["external_ef_reason"] = "No usable source-supported factor, dynamic frozen-database proxy, or semantically valid terminal model-only value could be obtained; see fallback_attempts_json."\n            result["external_ef_fallback_attempts_json"] = json.dumps(self._last_fallback_attempts, ensure_ascii=False)\n            return result, evidence\n\n        result.update({\n            "external_ef_value": resolved.get("ef_value"),\n            "external_ef_reference_unit": resolved.get("reference_unit"),\n            "external_ef_lower_value": resolved.get("lower_value"),\n            "external_ef_upper_value": resolved.get("upper_value"),\n            "external_ef_uncertainty_type": resolved.get("uncertainty_type"),\n            "external_ef_uncertainty_lower_value": resolved.get("uncertainty_lower_value"),\n            "external_ef_uncertainty_upper_value": resolved.get("uncertainty_upper_value"),\n            "external_ef_uncertainty_gsd": resolved.get("uncertainty_gsd"),\n            "external_ef_uncertainty_cv": resolved.get("uncertainty_cv"),\n            "external_ef_uncertainty_confidence_level": resolved.get("uncertainty_confidence_level"),\n            "external_ef_uncertainty_evidence_quote": resolved.get("uncertainty_evidence_quote"),\n            "external_ef_peer_values_json": resolved.get("peer_values_json"),\n            "external_ef_peer_sources_json": resolved.get("peer_sources_json"),\n            "external_ef_unit_basis_records_json": resolved.get("unit_basis_records_json"),\n            "external_ef_relaxed_sources_json": resolved.get("relaxed_sources_json"),\n            "external_ef_relaxed_source_count": resolved.get("relaxed_source_count"),\n            "external_ef_relaxed_retained_count": resolved.get("relaxed_retained_count"),\n            "external_ef_relaxed_outlier_count": resolved.get("relaxed_outlier_count"),\n            "external_ef_relaxed_consensus_method": resolved.get("relaxed_consensus_method"),\n            "external_ef_relaxed_consensus_version": resolved.get("relaxed_consensus_version"),\n            "external_ef_verification": ("EXTERNAL_VERIFIED" if resolved.get("verification") in {"EXTERNAL_VERIFIED", "PROVISIONAL_SOURCE_SUPPORTED"} else resolved.get("verification")),\n            "external_ef_verification_tier": resolved.get("verification_tier") or ("RELAXED" if resolved.get("verification") == "PROVISIONAL_SOURCE_SUPPORTED" else None),\n            "external_ef_source_class": ("EXTERNAL_VERIFIED_RELAXED" if resolved.get("verification") == "PROVISIONAL_SOURCE_SUPPORTED" else resolved.get("source_class")),\n            "external_ef_source_title": resolved.get("source_title"),\n            "external_ef_source_url": resolved.get("source_url"),\n            "external_ef_source_geography": resolved.get("source_geography"),\n            "external_ef_source_year": resolved.get("source_year"),\n            "external_ef_search_tier": resolved.get("search_tier"),\n            "external_ef_search_query": resolved.get("search_query"),\n            "external_ef_evidence_quote": resolved.get("evidence_quote"),\n            "external_ef_declared_unit_evidence": resolved.get("declared_unit_evidence"),\n            "external_ef_boundary": resolved.get("boundary"),\n            "external_ef_indicator": resolved.get("indicator"),\n            "external_ef_reason": resolved.get("reason"),\n            "external_ef_match_type": resolved.get("external_match_type"),\n            "external_ef_proxy_basis": resolved.get("external_proxy_basis"),\n            "external_ef_product_identity_status": resolved.get("product_identity_status"),\n            "external_ef_product_identity_reason": resolved.get("product_identity_reason"),\n            "external_ef_product_identity_title": resolved.get("product_identity_title"),\n            "external_ef_material_family": resolved.get("material_family") or classify_material(material),\n            "external_ef_material_taxonomy_version": resolved.get("material_taxonomy_version") or MATERIAL_TAXONOMY_VERSION,\n            "external_ef_biogenic_carbon_policy": resolved.get("biogenic_carbon_policy"),\n            "external_ef_proxy_representativeness": resolved.get("proxy_representativeness"),\n            "external_ef_fallback_method": resolved.get("fallback_method"),\n            "external_ef_terminal_quality_flag": resolved.get("terminal_quality_flag"),\n            "external_ef_details_json": json.dumps(resolved, ensure_ascii=False),\n            "external_ef_fallback_attempts_json": resolved.get("fallback_attempts_json"),\n            "external_ef_guardrail_status": resolved.get("guardrail_status"),\n            "external_ef_guardrail_reason": resolved.get("guardrail_reason"),\n        })\n        if resolved.get("verification") in {"EXTERNAL_VERIFIED", "PROVISIONAL_SOURCE_SUPPORTED"}:\n            result["external_ef_resolution_status"] = "RESOLVED_EXTERNAL_VERIFIED"\n        elif resolved.get("verification") == "UNVERIFIED_FALLBACK_ESTIMATE":\n            result["external_ef_resolution_status"] = "RESOLVED_UNVERIFIED_FALLBACK_ESTIMATE"\n        else:\n            result["external_ef_resolution_status"] = "INPUT_OR_MODEL_FAILURE"\n            result["external_ef_verification"] = "INPUT_OR_MODEL_FAILURE"\n        return result, evidence\n\n    def resolve_batch(self, df: pd.DataFrame):\n        rows = []\n        evidence_rows = []\n        records = df.to_dict(orient="records")\n        total = len(records)\n        for i, rec in enumerate(records, start=1):\n            material = _clean(rec.get("normalized_material") or rec.get("original_material") or rec.get("Material"))\n            self._progress(f"EF resolver · row {i}/{total} · {material}")\n            resolved, evidence = self.resolve_record(rec)\n            merged = dict(rec)\n            merged.update(resolved)\n            rows.append(merged)\n            evidence_rows.extend(evidence)\n            status = resolved.get("external_ef_verification") or resolved.get("external_ef_resolution_status")\n            self._progress(f"EF resolver · row {i}/{total} complete · {material} · {status}")\n        return pd.DataFrame(rows), pd.DataFrame(evidence_rows)\n', 'property_resolver.py': '"""Automatic physical-property resolution for standardized BOM quantities.\n\nThe resolver is used only when a deterministic unit conversion needs a physical\nproperty that the user did not provide (for example density for m3 -> kg).\n\nResolution hierarchy:\n1. User/project value already present in the BOM.\n2. Value explicitly encoded in the BOM description (currently thickness in mm).\n3. Live traceable web retrieval, searched Nepal first, then South Asia, Asia, global.\n4. If strict verification fails, a source-supported relaxed-phase property may be\n   formed only from explicit numerical values in retrieved evidence.\n5. If no retrieved value survives and the conversion still requires a property,\n   a final UNVERIFIED_FALLBACK_ESTIMATE may be used with an explicit broad model-estimated\n   range. It is never treated as traceable evidence.\n\nNo case-study-specific density, thickness, mass-per-item value, source URL, or\npreselected reference is stored in this resolver.\n\nFor verified and source-supported relaxed-phase properties, Qwen is an evidence\nextractor only and every value must be supported by retrieved text. The final\nLLM-only property fallback is isolated and explicitly marked unverified. Search\nevidence and the final fallback assumptions are retained for auditability.\n"""\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nimport io\nimport json\nimport math\nimport re\nimport time\nfrom typing import Any\n\nimport pandas as pd\n\nfrom unit_conversion import convert_quantity, norm_unit\nfrom evidence_consensus import (\n    robust_positive_consensus, CONSENSUS_METHOD_VERSION, robust_model_ensemble_consensus,\n    MODEL_ENSEMBLE_SIZE, MODEL_ENSEMBLE_METHOD_VERSION,\n)\nfrom semantic_analog import infer_analog_plan, SEMANTIC_ANALOG_VERSION\nfrom technical_equivalence import infer_technical_equivalents, TECHNICAL_EQUIVALENCE_VERSION\nfrom evidence_cache import RuntimeEvidenceCache, CACHE_VERSION\nfrom material_taxonomy import MATERIAL_TAXONOMY_VERSION, classify_material, choose_resolution_material, external_title_compatibility\nfrom guardrails import GUARDRAIL_VERSION, property_plausible, property_guardrail_context\n\nPROPERTY_RESOLVER_VERSION = "11.0-four-class-strict-relaxed-external"\nTARGET_GEOGRAPHY = "Nepal"\n\nTRACEABLE_SYSTEM_PROMPT = """You are a technical evidence extractor supporting an LCA unit-conversion workflow.\n\nYou are NOT allowed to invent a physical-property value, source, citation, URL, year, geography, or evidence quote.\nYou receive web-search evidence that has already been retrieved for one material property.\n\nRules:\n1. Use ONLY the supplied evidence candidates.\n2. A value is acceptable only when the evidence explicitly supports the requested material/product AND the requested physical property.\n3. Physical condition is mandatory. If the requested property is BULK DENSITY for aggregate/stone/soil, reject particle density, true density, specific gravity, solid-rock density, or generic material density unless the evidence explicitly states bulk/unit-weight conditions consistent with a bulk BOM volume.\n4. Do not treat a downstream or different product as equivalent.\n5. source_result_id must exactly match one supplied result ID.\n6. evidence_quote MUST be copied verbatim from the supplied snippet or extracted text. Never reconstruct or paraphrase the quote.\n7. Do not infer geography from the search query. Geography must be supported by the source itself.\n8. If no supplied evidence gives a defensible explicit value, return found=false. Do not estimate.\n9. For density return kg/m3. For mass-per-item return kg/item. For thickness return mm.\n10. If a source provides a defensible range, return lower_value and upper_value. Otherwise use null.\n11. Return JSON only with exactly these keys:\nfound, value, lower_value, upper_value, unit, source_result_id, source_geography, source_year, source_class, evidence_quote, reason\n"""\n\nPROVISIONAL_PROPERTY_SYSTEM_PROMPT = """You are a numerical engineering evidence extractor.\n\nStrict source verification has already failed. Extract only physical-property\nvalues that are explicitly present in the supplied retrieved evidence. Never\nestimate from memory.\n\nRules:\n1. Use ONLY supplied evidence candidates.\n2. Evaluate every result_id independently.\n3. The source text must explicitly support the requested material/product and\n   requested property.\n4. For bulk density, reject particle density, true density, specific gravity, or\n   solid-material density unless the evidence explicitly describes bulk/unit-weight\n   conditions consistent with a bulk BOM volume.\n5. Return the value only in the requested standardized unit. Do not invent a unit\n   conversion; if the supplied text does not provide a directly interpretable value\n   in that unit, return found=false for that candidate.\n6. evidence_quote must be copied verbatim and include/support the numerical value.\n7. Do not average or choose a final value. Python will combine independently\n   supported values with a robust median/outlier procedure.\n8. Return JSON only with exactly one top-level key, records. Each record must have\n   exactly: source_result_id, found, value, lower_value, upper_value, unit,\n   source_year, evidence_quote, reason\n"""\n\nLLM_UNVERIFIED_PROPERTY_SYSTEM_PROMPT = """You are the model-only exploratory physical-property fallback in a construction LCA unit-conversion workflow.\n\nTraceable and source-supported property evidence failed. Produce exactly FIVE independent candidate estimates for the requested material itself. Python will perform material-agnostic robust consensus; no material-specific density, thickness, or item-mass range is supplied.\n\nRules:\n1. Do not claim a source, URL, citation, standard, year, or evidence quote.\n2. Estimate ONLY requested_property.\n3. Every candidate must use required_standardized_unit EXACTLY.\n4. Each candidate must have finite positive lower_value < central_value < upper_value.\n5. Use the supplied estimation_lenses to make genuinely distinct engineering estimates; do not clone one number five times merely to force agreement.\n6. For bulk density estimate bulk/unit-weight conditions for the BOM volume, not particle density, true density, or specific gravity.\n7. No expected numerical range is supplied. Python rejects disagreement after generation.\n8. Return JSON only with exactly one top-level key: candidates.\n9. candidates must contain exactly five objects, each with exactly these keys:\nfound, central_value, lower_value, upper_value, unit, material_interpretation, estimation_basis, rationale\n"""\n\nCONSERVATIVE_ANALOG_PROPERTY_SYSTEM_PROMPT = """You are the final analog-estimation stage for a construction LCA physical-property conversion.\n\nThe exact-product five-candidate estimate did not agree. You are given a semantic family and exactly five analog products inferred dynamically from the material description. Estimate ONE candidate for EACH supplied analog. Python will reject outliers and require at least three agreeing candidates.\n\nRules:\n1. Do not claim a source, citation, URL, standard, or publication year.\n2. Use only the supplied analogs; there is no hard-coded material-to-analog mapping.\n3. Estimate only requested_property and use required_standardized_unit EXACTLY.\n4. Each candidate must have finite positive lower_value < central_value < upper_value.\n5. For bulk density use bulk/unit-weight conditions, not particle density or specific gravity.\n6. Preserve each supplied analog_material name exactly.\n7. Do not force agreement; Python performs the consensus test.\n8. Return JSON only with exactly one top-level key: candidates.\n9. candidates must contain exactly five objects, each with exactly these keys:\nfound, central_value, lower_value, upper_value, unit, analog_material, estimation_basis, rationale\n"""\n\nLLM_UNVERIFIED_PROPERTY_SINGLE_SYSTEM_PROMPT = """You are producing ONE independent exploratory physical-property estimate for a construction material.\n\nNo material-specific density, thickness, or mass-per-item value/range is supplied. Do not claim a source, citation, URL, standard, or publication year. Use only the single estimation_lens supplied.\n\nReturn exactly one JSON object with these keys:\nfound, central_value, lower_value, upper_value, unit, material_interpretation, estimation_basis, rationale\n\nRules:\n- Estimate only requested_property.\n- Use required_standardized_unit exactly.\n- lower_value < central_value < upper_value and all values must be finite and positive.\n- For bulk density, use bulk/unit-weight conditions appropriate to BOM volume, not particle density/specific gravity.\n- Do not try to force agreement with other candidates.\n- JSON only.\n"""\n\nCONSERVATIVE_ANALOG_PROPERTY_SINGLE_SYSTEM_PROMPT = """You are producing ONE independent exploratory physical-property estimate for ONE dynamically inferred analog product.\n\nNo material-specific numeric value/range or hard-coded material-to-analog mapping is supplied. Do not claim a source, citation, URL, standard, or year.\n\nReturn exactly one JSON object with these keys:\nfound, central_value, lower_value, upper_value, unit, analog_material, estimation_basis, rationale\n\nRules:\n- Preserve analog_material exactly.\n- Estimate only requested_property in required_standardized_unit exactly.\n- lower_value < central_value < upper_value and all values must be finite and positive.\n- For bulk density, use bulk/unit-weight conditions, not particle density/specific gravity.\n- Do not force agreement with other analogs.\n- JSON only.\n"""\nTERMINAL_MINIMAL_PROPERTY_SYSTEM_PROMPT = """You are the last numerical fallback for one physical property needed only to convert a construction BOM quantity.\n\nNo material-specific property value, density range, item mass, thickness, source, or expected magnitude is supplied. The result will be explicitly labeled UNVERIFIED and used only in the separated exploratory calculation. Do not claim a source.\n\nReturn JSON only with exactly these keys:\nfound, value, unit, material_interpretation, rationale\n\nRules:\n- Estimate only requested_property.\n- Use required_standardized_unit exactly.\n- value must be finite and positive.\n- For bulk density, estimate the bulk/unit-weight condition appropriate to the BOM volume rather than particle density or specific gravity.\n"""\n\n\n\ndef _clean(v: Any) -> str:\n    if v is None:\n        return ""\n    try:\n        if pd.isna(v):\n            return ""\n    except Exception:\n        pass\n    return str(v).strip()\n\n\ndef _call_matcher(matcher, system_prompt: str, payload: dict[str, Any], *, max_new_tokens: int | None = None) -> str:\n    try:\n        return matcher.generate_with_system(system_prompt, payload, max_new_tokens_override=max_new_tokens)\n    except TypeError:\n        return matcher.generate_with_system(system_prompt, payload)\n\n\ndef _as_bool(v: Any) -> bool:\n    if isinstance(v, bool):\n        return v\n    if v is None:\n        return False\n    try:\n        if pd.isna(v):\n            return False\n    except Exception:\n        pass\n    return _clean(v).lower() in {"1", "true", "yes", "y"}\n\n\ndef _num(v: Any) -> float | None:\n    if v is None:\n        return None\n    try:\n        if pd.isna(v):\n            return None\n    except Exception:\n        pass\n    if isinstance(v, str) and not v.strip():\n        return None\n    try:\n        x = float(v)\n    except Exception:\n        return None\n    return x if math.isfinite(x) else None\n\n\ndef extract_thickness_mm(material: str) -> float | None:\n    """Extract an explicit thickness such as \'19mm\' or \'0.45 mm\' from BOM text."""\n    text = _clean(material).lower().replace("millimetres", "mm").replace("millimeters", "mm")\n    m = re.search(r"(?<![\\d.])(\\d+(?:\\.\\d+)?)\\s*mm\\b", text)\n    if not m:\n        return None\n    value = float(m.group(1))\n    return value if value > 0 else None\n\n\n_BULK_VOLUME_TERMS = (\n    "gravel", "aggregate", "crushed stone", "stone", "soil", "earth",\n    "mud", "backfill", "ballast", "sand",\n)\n\n_LOW_QUALITY_HOSTS = (\n    "scribd.com", "pinterest.", "quora.", "reddit.",\n    "wisdomanswer.com", "blog.welcu.com", "leukstekadotip.nl",\n)\n\n_RECOGNIZED_TECHNICAL_HOSTS = (\n    "istructe.org", "inbar.int", "apawood.org", "astm.org",\n    "iso.org", "bsigroup.com", "ccaa.com.au",\n)\n\n_PEER_REVIEWED_HOSTS = (\n    "sciencedirect.com", "springer.com", "springeropen.com",\n    "wiley.com", "tandfonline.com", "mdpi.com", "sagepub.com",\n    "nature.com",\n)\n\n\ndef _property_label(kind: str, material: str | None = None) -> tuple[str, str]:\n    if kind == "density_kg_m3":\n        m = _clean(material).lower()\n        if any(term in m for term in _BULK_VOLUME_TERMS):\n            return (\n                "bulk density / bulk unit weight for the material volume as supplied in the BOM",\n                "kg/m3",\n            )\n        return "material density", "kg/m3"\n    if kind == "mass_per_item_kg":\n        return "mass per item", "kg/item"\n    if kind == "thickness_mm":\n        return "product thickness", "mm"\n    raise ValueError(f"Unsupported property kind: {kind}")\n\n\ndef _url_host(url: str) -> str:\n    from urllib.parse import urlparse\n    try:\n        return (urlparse(url).hostname or "").lower()\n    except Exception:\n        return ""\n\n\ndef _source_quality(url: str, title: str = "") -> tuple[bool, str]:\n    host = _url_host(url)\n    if not host:\n        return False, "UNKNOWN_SOURCE"\n    if any(bad in host for bad in _LOW_QUALITY_HOSTS):\n        return False, "LOW_QUALITY_WEB"\n    if host.endswith(".gov.np") or host == "gov.np":\n        return True, "NEPAL_GOVERNMENT"\n    if ".gov." in host or host.endswith(".gov"):\n        return True, "GOVERNMENT"\n    if ".edu." in host or host.endswith(".edu") or ".ac." in host:\n        return True, "ACADEMIC"\n    if any(host.endswith(h) or host == h for h in _RECOGNIZED_TECHNICAL_HOSTS):\n        return True, "RECOGNIZED_TECHNICAL_ORGANIZATION"\n    if any(host.endswith(h) or host == h for h in _PEER_REVIEWED_HOSTS):\n        return True, "PEER_REVIEWED_PUBLISHER"\n    return False, "UNVERIFIED_WEB_SOURCE"\n\n\n\n\ndef _property_identity_ok(material: str, selected: dict[str, Any]) -> tuple[bool, str]:\n    """Deterministically reject physical-property evidence for the wrong product family."""\n    requested_family = classify_material(material)\n    evidence = _clean(selected.get("title")) + " " + _clean(selected.get("snippet"))\n    evidence_family = classify_material(evidence)\n\n    if requested_family != "UNKNOWN":\n        if evidence_family == requested_family:\n            return True, "material_family_match"\n        if evidence_family != "UNKNOWN":\n            return False, f"wrong_material_family:{evidence_family}"\n\n        # When the taxonomy cannot classify the source text, require at least\n        # one meaningful token from the material description to be present.\n        stop = {"mm", "kg", "m", "grade", "local", "natural", "ordinary", "for", "and", "the"}\n        tokens = [t for t in re.findall(r"[a-z0-9]+", _clean(material).lower()) if len(t) >= 4 and t not in stop]\n        low = evidence.lower()\n        if any(t in low for t in tokens):\n            return True, "material_token_match"\n        return False, "material_identity_not_supported"\n\n    tokens = [t for t in re.findall(r"[a-z0-9]+", _clean(material).lower()) if len(t) >= 4]\n    low = evidence.lower()\n    if tokens and any(t in low for t in tokens):\n        return True, "unknown_family_token_match"\n    return False, "unknown_family_identity_not_supported"\n\ndef _normalize_quote(text: str) -> str:\n    return re.sub(r"\\s+", " ", _clean(text)).strip().lower()\n\n\ndef _quote_supported(quote: str, selected: dict[str, Any]) -> bool:\n    q = _normalize_quote(quote)\n    if not q:\n        return False\n    evidence = _normalize_quote(\n        f"{selected.get(\'snippet\', \'\')} {selected.get(\'excerpt\', \'\')}"\n    )\n    return q in evidence\n\n\ndef _infer_geography(selected: dict[str, Any]) -> str:\n    host = _url_host(selected.get("url", ""))\n    evidence = _normalize_quote(\n        f"{selected.get(\'title\', \'\')} {selected.get(\'snippet\', \'\')} "\n        f"{selected.get(\'excerpt\', \'\')}"\n    )\n    if host.endswith(".np") or "nepal" in evidence:\n        return "Nepal"\n    if host.endswith(".in") or "india" in evidence:\n        return "India"\n    if host.endswith(".bd") or "bangladesh" in evidence:\n        return "Bangladesh"\n    if host.endswith(".lk") or "sri lanka" in evidence:\n        return "Sri Lanka"\n    if host.endswith(".pk") or "pakistan" in evidence:\n        return "Pakistan"\n    if host.endswith(".bt") or "bhutan" in evidence:\n        return "Bhutan"\n    if host.endswith(".au") or "australia" in evidence:\n        return "Australia"\n    if host.endswith(".uk") or "united kingdom" in evidence:\n        return "United Kingdom"\n    return "Unspecified"\n\n\ndef _tier_geography_ok(tier: str, geography: str) -> bool:\n    if tier == "NEPAL":\n        return geography == "Nepal"\n    if tier == "SOUTH_ASIA":\n        return geography in {\n            "Nepal", "India", "Bangladesh", "Sri Lanka", "Pakistan", "Bhutan"\n        }\n    if tier == "ASIA":\n        # Accept only explicitly inferred Asian geography before the global tier.\n        return geography in {\n            "Nepal", "India", "Bangladesh", "Sri Lanka", "Pakistan", "Bhutan"\n        }\n    return True\n\n\ndef _target_geography_supported(selected: dict[str, Any], target_geography: str) -> bool:\n    """Strict Class-3/traceable-property geography test based on source evidence.\n\n    The search query is never used as geography evidence. relaxed External Verified\n    properties intentionally bypass this exact-geography gate.\n    """\n    target = _normalize_quote(target_geography)\n    if not target:\n        return False\n    inferred = _normalize_quote(_infer_geography(selected))\n    if inferred and inferred != "unspecified" and inferred == target:\n        return True\n    evidence = _normalize_quote(\n        f"{selected.get(\'title\',\'\')} {selected.get(\'snippet\',\'\')} {selected.get(\'excerpt\',\'\')}"\n    )\n    host = _url_host(selected.get(\'url\',\'\'))\n    padded = f" {evidence} "\n    aliases = {\n        "nepal": ("nepal",), "india": ("india",),\n        "bangladesh": ("bangladesh",), "sri lanka": ("sri lanka",),\n        "pakistan": ("pakistan",), "bhutan": ("bhutan",),\n        "australia": ("australia",),\n        "united kingdom": ("united kingdom", " uk "),\n        "united states": ("united states", " usa ", " u.s. "),\n        "germany": ("germany",), "norway": ("norway",),\n    }\n    if any(a in padded for a in aliases.get(target, (target,))):\n        return True\n    suffixes = {\n        "nepal": ".np", "india": ".in", "bangladesh": ".bd",\n        "sri lanka": ".lk", "pakistan": ".pk", "bhutan": ".bt",\n        "australia": ".au", "united kingdom": ".uk",\n        "united states": ".us", "germany": ".de", "norway": ".no",\n    }\n    suffix = suffixes.get(target)\n    return bool(suffix and host.endswith(suffix))\n\n\ndef _bulk_density_evidence_ok(material: str, selected: dict[str, Any]) -> bool:\n    m = _clean(material).lower()\n    if not any(term in m for term in _BULK_VOLUME_TERMS):\n        return True\n    evidence = _normalize_quote(\n        f"{selected.get(\'snippet\', \'\')} {selected.get(\'excerpt\', \'\')}"\n    )\n    good_terms = (\n        "bulk density", "bulk unit weight", "loose density",\n        "rodded density", "compacted density", "unit weight",\n    )\n    bad_only_terms = (\n        "particle density", "specific gravity", "true density",\n        "solid density", "rock density",\n    )\n    if any(term in evidence for term in good_terms):\n        return True\n    if any(term in evidence for term in bad_only_terms):\n        return False\n    # For granular/earth materials, generic "density" without bulk condition\n    # is not strong enough for a volume-to-mass BOM conversion.\n    return False\n\n\ndef _expected_unit_ok(kind: str, unit: str) -> bool:\n    u = _clean(unit).lower().replace("³", "3").replace("^3", "3").replace(" ", "")\n    if kind == "density_kg_m3":\n        return u in {"kg/m3", "kgperm3", "kgm-3"}\n    if kind == "mass_per_item_kg":\n        return u in {"kg/item", "kg/piece", "kg/each", "kg"}\n    if kind == "thickness_mm":\n        return u in {"mm", "millimeter", "millimetre"}\n    return False\n\n\ndef _number_close_in_text(value: float, text: str) -> bool:\n    for token in re.findall(r"[-+]?(?:\\d+(?:[.,]\\d*)?|\\.\\d+)(?:[Ee][-+]?\\d+)?", text or ""):\n        s = token.replace("−", "-").replace("–", "-")\n        if "," in s and "." not in s:\n            s = s.replace(",", ".")\n        else:\n            s = s.replace(",", "")\n        try:\n            parsed = float(s)\n        except Exception:\n            continue\n        tol = max(1e-9, abs(float(value)) * 1e-6)\n        if abs(parsed - float(value)) <= tol:\n            return True\n    return False\n\n\ndef _property_unit_supported_in_quote(kind: str, quote: str) -> bool:\n    q = _normalize_quote(quote).replace("³", "3").replace("^3", "3")\n    if kind == "density_kg_m3":\n        return any(x in q for x in ("kg/m3", "kg per m3", "kg m-3", "kgm-3"))\n    if kind == "mass_per_item_kg":\n        return "kg" in q and any(x in q for x in ("item", "piece", "each", "unit", "kg"))\n    if kind == "thickness_mm":\n        return "mm" in q or "millimeter" in q or "millimetre" in q\n    return False\n\n\ndef _provisional_source_allowed(url: str, title: str = "") -> tuple[bool, str]:\n    host = _url_host(url)\n    if not host:\n        return False, "UNKNOWN_SOURCE"\n    if any(bad in host for bad in _LOW_QUALITY_HOSTS):\n        return False, "LOW_QUALITY_WEB"\n    strict_ok, strict_class = _source_quality(url, title)\n    if strict_ok:\n        return True, strict_class\n    return True, "SOURCE_SUPPORTED_WEB"\n\n\n\ndef _promising_property_candidate(material: str, kind: str, candidate: dict[str, Any]) -> tuple[bool, str]:\n    """Value-free trigger for a deeper relaxed-phase Class-3 property search."""\n    allowed, source_class = _provisional_source_allowed(candidate.get("url", ""), candidate.get("title", ""))\n    if not allowed:\n        return False, f"source_not_allowed:{source_class}"\n    identity_ok, identity_reason = external_title_compatibility(\n        material, candidate.get("title"), match_type="DIRECT_PRODUCT"\n    )\n    if not identity_ok:\n        return False, f"identity_not_supported:{identity_reason}"\n    text = _normalize_quote(f"{candidate.get(\'snippet\',\'\')} {candidate.get(\'excerpt\',\'\')}")\n    label, expected_unit = _property_label(kind, material)\n    label_terms = [x for x in re.split(r"[^a-z0-9]+", _normalize_quote(label)) if len(x) > 2]\n    has_label = any(x in text for x in label_terms)\n    has_unit = _property_unit_supported_in_quote(kind, text) or _normalize_quote(expected_unit) in text\n    return (has_label or has_unit), ("PROMISING_PROPERTY_SIGNAL" if (has_label or has_unit) else "no_property_signal")\n\ndef conversion_requirements(source_unit: str | None, ref_unit: str | None) -> list[str]:\n    """Return physical properties required after pure deterministic conversions are tried."""\n    src = norm_unit(source_unit)\n    ref = norm_unit(ref_unit)\n    if not src or not ref:\n        return []\n\n    probe = convert_quantity(1.0, src, ref)\n    if probe.ok:\n        return []\n\n    mass_units = {"kg", "g", "t"}\n    if src == "m3" and ref in mass_units:\n        return ["density_kg_m3"]\n    if src == "m2" and ref in mass_units:\n        return ["thickness_mm", "density_kg_m3"]\n    if src == "m2" and ref == "m3":\n        return ["thickness_mm"]\n    if src == "m3" and ref == "m2":\n        return ["thickness_mm"]\n    if src == "item" and ref in mass_units:\n        return ["mass_per_item_kg"]\n    if src in mass_units and ref == "m3":\n        return ["density_kg_m3"]\n    if src in mass_units and ref == "m2":\n        return ["thickness_mm", "density_kg_m3"]\n    if src in mass_units and ref == "item":\n        return ["mass_per_item_kg"]\n    return []\n\n\ndef _query_sets(material: str, kind: str, target_geography: str) -> list[tuple[str, list[str]]]:\n    label, unit = _property_label(kind, material)\n    m = material.strip()\n    family = classify_material(material)\n    family_term = family.lower().replace("_", " ") if family != "UNKNOWN" else None\n\n    south_asia = [\n        f\'"{m}" {label} {unit} India Nepal construction standard\',\n        f\'"{m}" {label} {unit} South Asia filetype:pdf\',\n    ]\n    global_queries = [\n        f\'"{m}" {label} {unit} construction material technical data\',\n        f\'"{m}" {label} {unit} filetype:pdf\',\n    ]\n    if family_term and family_term.lower() != m.lower():\n        # Same-family terminology broadens retrieval only; it contributes no\n        # physical-property value and every extracted number still has to pass\n        # product/property/unit/source checks.\n        south_asia.insert(0, f\'"{family_term}" {label} {unit} India construction technical data\')\n        global_queries.insert(0, f\'"{family_term}" {label} {unit} construction material technical data\')\n\n    return [\n        (\n            "NEPAL",\n            [\n                f\'"{m}" {label} {unit} {target_geography} construction\',\n                f\'"{m}" {label} {unit} {target_geography} filetype:pdf\',\n                f\'{m} {label} {unit} site:gov.np\',\n                f\'{m} {label} {unit} Nepal engineering\',\n            ],\n        ),\n        ("SOUTH_ASIA", south_asia),\n        ("ASIA", [f\'"{m}" {label} {unit} Asia construction technical data\']),\n        ("GLOBAL", global_queries),\n    ]\n\n\n\nclass WebPropertyResolver:\n    def __init__(\n        self,\n        matcher,\n        *,\n        target_geography: str = TARGET_GEOGRAPHY,\n        allow_source_supported_provisional: bool = True,\n        allow_llm_unverified_estimate: bool = True,\n        allow_conservative_analog_estimate: bool = True,\n        search_results_per_query: int = 5,\n        extract_top_n: int = 5,\n        max_evidence_candidates: int = 5,\n        excerpt_chars: int = 4500,\n        timeout: int = 8,\n        class3_source_budget: int = 3,\n        class4_total_source_budget: int = 10,\n        max_search_queries_per_property: int = 5,\n        max_external_seconds_per_property: float = 60.0,\n        adaptive_max_search_queries_per_property: int = 10,\n        adaptive_total_source_budget: int = 9,\n        adaptive_external_seconds_per_property: float = 120.0,\n        pdf_max_pages: int = 20,\n        adaptive_pdf_max_pages: int = 50,\n        max_download_bytes: int = 12 * 1024 * 1024,\n        progress_callback=None,\n        evidence_cache_path: str | None = None,\n    ):\n        self.matcher = matcher\n        self.target_geography = target_geography\n        self.allow_source_supported_provisional = bool(allow_source_supported_provisional)\n        self.allow_llm_unverified_estimate = bool(allow_llm_unverified_estimate)\n        self.allow_conservative_analog_estimate = bool(allow_conservative_analog_estimate)\n        self.search_results_per_query = search_results_per_query\n        self.extract_top_n = extract_top_n\n        self.max_evidence_candidates = max_evidence_candidates\n        self.excerpt_chars = excerpt_chars\n        self.timeout = int(timeout)\n        self.class3_source_budget = max(1, int(class3_source_budget))\n        self.class4_total_source_budget = max(self.class3_source_budget, int(class4_total_source_budget))\n        self.max_search_queries_per_property = max(1, int(max_search_queries_per_property))\n        self.max_external_seconds_per_property = max(5.0, float(max_external_seconds_per_property))\n        self.adaptive_max_search_queries_per_property = max(self.max_search_queries_per_property, int(adaptive_max_search_queries_per_property))\n        self.adaptive_total_source_budget = max(self.class4_total_source_budget, int(adaptive_total_source_budget))\n        self.adaptive_external_seconds_per_property = max(self.max_external_seconds_per_property, float(adaptive_external_seconds_per_property))\n        self.pdf_max_pages = max(1, int(pdf_max_pages))\n        self.adaptive_pdf_max_pages = max(self.pdf_max_pages, int(adaptive_pdf_max_pages))\n        self.max_download_bytes = max(1024 * 1024, int(max_download_bytes))\n        self.progress_callback = progress_callback\n        self.evidence_cache = RuntimeEvidenceCache(evidence_cache_path)\n        self._search_cache: dict[str, list[dict[str, Any]]] = {}\n        self._resolution_cache: dict[tuple[str, str], dict[str, Any]] = {}\n        self._last_fallback_attempts: list[dict[str, Any]] = []\n        self._relaxed_property_pool: list[dict[str, Any]] = []\n        self._anchored_exact_property_pool: list[dict[str, Any]] = []\n\n    def _progress(self, message: str) -> None:\n        if callable(self.progress_callback):\n            try:\n                self.progress_callback(message)\n            except Exception:\n                pass\n\n    def _ddgs(self):\n        from ddgs import DDGS\n        return DDGS(timeout=self.timeout)\n\n    def _search(self, query: str) -> list[dict[str, Any]]:\n        """Search defensively.\n\n        Search-engine backends can legitimately return no results, time out,\n        rate-limit, or fail transiently. None of those conditions should abort\n        a building-LCA run. We try a small sequence of region settings and, if\n        all attempts fail, cache an empty result so the resolver can continue\n        to the next query/geography tier and ultimately an unresolved result or the explicit LLM\n        fallback when the user has enabled it.\n        """\n        if query in self._search_cache:\n            return [dict(x) for x in self._search_cache[query]]\n\n        rows = []\n        for region in ("np-en", "us-en"):\n            try:\n                result = self._ddgs().text(\n                    query,\n                    region=region,\n                    safesearch="moderate",\n                    max_results=self.search_results_per_query,\n                    backend="auto",\n                )\n                rows = list(result or [])\n                if rows:\n                    break\n            except Exception:\n                # "No results found", timeout, backend errors, rate limits,\n                # unsupported region values, etc. are treated as no evidence\n                # for this attempt rather than fatal pipeline errors.\n                rows = []\n                continue\n\n        out = []\n        for r in rows:\n            if not isinstance(r, dict):\n                continue\n            url = _clean(r.get("href") or r.get("url"))\n            if not url:\n                continue\n            out.append({\n                "title": _clean(r.get("title")),\n                "url": url,\n                "snippet": _clean(r.get("body") or r.get("snippet")),\n            })\n\n        self._search_cache[query] = out\n        return [dict(x) for x in out]\n\n    def _extract(self, url: str) -> str:\n        """Extract one bounded source document safely.\n\n        pypdf is used only when the downloaded bytes begin with the PDF magic\n        header, preventing HTML/PNG/access-denied bodies from generating PDF\n        parser storms. No recursive crawling is performed for property sources.\n        """\n        request_timeout = (min(5, self.timeout), self.timeout)\n        try:\n            import requests\n            resp = requests.get(\n                url, timeout=request_timeout, allow_redirects=True,\n                headers={"User-Agent": "Mozilla/5.0 LCA-research-resolver/4.0"},\n            )\n            resp.raise_for_status()\n            if len(resp.content) > self.max_download_bytes:\n                return ""\n            ctype = (resp.headers.get("content-type") or "").lower()\n            if resp.content.lstrip().startswith(b"%PDF"):\n                try:\n                    import logging\n                    logging.getLogger("pypdf").setLevel(logging.ERROR)\n                    from pypdf import PdfReader\n                    reader = PdfReader(io.BytesIO(resp.content), strict=False)\n                    parts = []\n                    for page in reader.pages[: self.pdf_max_pages]:\n                        try:\n                            txt = page.extract_text() or ""\n                        except Exception:\n                            txt = ""\n                        if txt:\n                            parts.append(txt)\n                    text = re.sub(r"\\s+", " ", " ".join(parts)).strip()\n                    if text:\n                        return text[: max(self.excerpt_chars, 5000)]\n                except Exception:\n                    return ""\n\n            is_html = (\n                "html" in ctype\n                or resp.content.lstrip()[:100].lower().startswith((b"<!doctype", b"<html"))\n                or b"<html" in resp.content[:2500].lower()\n            )\n            if is_html:\n                try:\n                    raw = resp.text\n                except Exception:\n                    raw = resp.content.decode("utf-8", errors="ignore")\n                raw = re.sub(r"(?is)<script.*?>.*?</script>", " ", raw)\n                raw = re.sub(r"(?is)<style.*?>.*?</style>", " ", raw)\n                raw = re.sub(r"(?s)<[^>]+>", " ", raw)\n                text = re.sub(r"\\s+", " ", raw).strip()\n                if text:\n                    return text[: max(self.excerpt_chars, 5000)]\n        except Exception:\n            pass\n\n        # One compact search-engine extraction fallback, then stop.\n        try:\n            extracted = self._ddgs().extract(url, fmt="text_rich")\n            if isinstance(extracted, dict):\n                text = extracted.get("content") or extracted.get("text") or json.dumps(extracted, ensure_ascii=False)\n            else:\n                text = str(extracted)\n            text = re.sub(r"\\s+", " ", text).strip()\n            return text[: max(self.excerpt_chars, 5000)]\n        except Exception:\n            return ""\n\n    def _collect_evidence(\n        self, queries: list[str], tier: str, item_id: str, material: str, kind: str,\n        *, max_candidates: int | None = None, max_queries: int | None = None,\n        seen_urls: set[str] | None = None,\n    ):\n        seen = seen_urls if seen_urls is not None else set()\n        limit = max(1, int(max_candidates or self.max_evidence_candidates))\n        qlimit = max(1, int(max_queries or len(queries)))\n        pool: list[dict[str, Any]] = []\n        queries_used = 0\n        for query in queries[:qlimit]:\n            queries_used += 1\n            for r in self._search(query):\n                if r["url"] in seen or any(x["url"] == r["url"] for x in pool):\n                    continue\n                pool.append({**r, "query": query, "tier": tier})\n            if len(pool) >= limit * 2:\n                break\n\n        def rank(c):\n            ok, cls = _source_quality(c.get("url", ""), c.get("title", ""))\n            class_rank = {\n                "NEPAL_GOVERNMENT": 0, "GOVERNMENT": 1, "ACADEMIC": 2,\n                "RECOGNIZED_TECHNICAL_ORGANIZATION": 3, "PEER_REVIEWED_PUBLISHER": 4,\n            }.get(cls, 20)\n            return (0 if ok else 1, class_rank)\n\n        pool.sort(key=rank)\n        candidates = pool[:limit]\n        evidence_rows: list[dict[str, Any]] = []\n        for i, c in enumerate(candidates):\n            seen.add(c["url"])\n            c["result_id"] = f"P{i+1}"\n            self._progress(f"External property evidence · inspecting source {i+1}/{len(candidates)} · {material} · {kind}")\n            c["full_text"] = self._extract(c["url"])\n            c["excerpt"] = c["full_text"][: max(self.excerpt_chars, 2500)]\n            identity_ok, identity_reason = _property_identity_ok(material, c)\n            evidence_rows.append({\n                "item_id": item_id, "material": material, "property_kind": kind,\n                "search_tier": tier, "query": c["query"], "result_id": c["result_id"],\n                "title": c["title"], "url": c["url"], "snippet": c["snippet"],\n                "excerpt": c["excerpt"], "product_identity_ok": identity_ok,\n                "product_identity_reason": identity_reason, "selected": False,\n                "relaxed_candidate": False, "relaxed_retained": False,\n                "relaxed_outlier": False, "relaxed_value": None,\n                "relaxed_reason": None,\n            })\n        return candidates, evidence_rows, queries_used\n\n    def _choose_traceable(self, material: str, kind: str, tier: str, candidates: list[dict[str, Any]]):\n        if not candidates:\n            return None, "no_candidates"\n        label, expected_unit = _property_label(kind, material)\n        payload = {\n            "material": material,\n            "target_geography": self.target_geography,\n            "search_tier": tier,\n            "requested_property": label,\n            "required_standardized_unit": expected_unit,\n            "evidence_candidates": [\n                {\n                    "result_id": c["result_id"],\n                    "title": c["title"],\n                    "url": c["url"],\n                    "search_snippet": c["snippet"][:700],\n                    "extracted_text": c["excerpt"][: self.excerpt_chars],\n                }\n                for c in candidates\n            ],\n        }\n        raw = _call_matcher(self.matcher, TRACEABLE_SYSTEM_PROMPT, payload, max_new_tokens=640)\n        try:\n            obj = json.loads(raw.strip())\n        except Exception:\n            m = re.search(r"\\{.*\\}", raw, flags=re.S)\n            if not m:\n                return None, f"parse_error:{raw[:120]}"\n            try:\n                obj = json.loads(m.group(0))\n            except Exception:\n                return None, "parse_error"\n\n        required_keys = {\n            "found", "value", "lower_value", "upper_value", "unit",\n            "source_result_id", "source_geography", "source_year",\n            "source_class", "evidence_quote", "reason",\n        }\n        if set(obj.keys()) != required_keys:\n            return None, "schema_invalid"\n        if not bool(obj.get("found")):\n            return None, _clean(obj.get("reason")) or "not_found"\n\n        sid = _clean(obj.get("source_result_id"))\n        by_id = {c["result_id"]: c for c in candidates}\n        if sid not in by_id:\n            return None, "source_id_invalid"\n        value = _num(obj.get("value"))\n        if value is None or value <= 0 or not _expected_unit_ok(kind, _clean(obj.get("unit"))):\n            return None, "value_or_unit_invalid"\n\n        selected = by_id[sid]\n\n        # Deterministic QA: the LLM can extract, but it cannot promote weak\n        # web pages, invent evidence, or assign geography from the query.\n        source_ok, source_class = _source_quality(\n            selected.get("url", ""),\n            selected.get("title", ""),\n        )\n        if not source_ok:\n            return None, f"source_quality_rejected:{source_class}"\n\n        identity_ok, identity_reason = _property_identity_ok(material, selected)\n        if not identity_ok:\n            return None, f"product_identity_rejected:{identity_reason}"\n\n        quote = _clean(obj.get("evidence_quote"))\n        if not _quote_supported(quote, selected):\n            return None, "evidence_quote_not_in_retrieved_source"\n\n        geography = _infer_geography(selected)\n        # A property can support a Class-3 row only when the property source\n        # itself is explicitly representative of the target study geography.\n        # Foreign/global/unspecified sources remain eligible in the relaxed External Verified phase.\n        if not _target_geography_supported(selected, self.target_geography):\n            return None, f"target_geography_not_verified:{geography or \'Unspecified\'}"\n\n        if kind == "density_kg_m3" and not _bulk_density_evidence_ok(\n            material, selected\n        ):\n            return None, "density_condition_not_bulk_compatible"\n\n        return {\n            "kind": kind,\n            "value": value,\n            "lower_value": _num(obj.get("lower_value")),\n            "upper_value": _num(obj.get("upper_value")),\n            "unit": _clean(obj.get("unit")),\n            "source_class": source_class,\n            "verification": "TRACEABLE_WEB",\n            "source_title": selected["title"],\n            "source_url": selected["url"],\n            "source_geography": geography,\n            "source_year": _clean(obj.get("source_year")),\n            "search_tier": tier,\n            "search_query": selected["query"],\n            "evidence_quote": quote,\n            "reason": _clean(obj.get("reason")),\n            "raw_model_output": raw,\n            "selected_result_id": sid,\n            "product_identity_status": "PASS",\n            "product_identity_reason": identity_reason,\n        }, "ok"\n\n    def _extract_relaxed_candidates(self, material: str, kind: str, tier: str, candidates: list[dict[str, Any]]):\n        """Extract relaxed-phase Class-3 physical properties one source at a time.\n\n        This reduces JSON truncation and keeps every accepted value tied to one\n        explicit retrieved quote. No material-specific property value is stored.\n        """\n        if not candidates:\n            return []\n        label, expected_unit = _property_label(kind, material)\n        required = {\n            "source_result_id", "found", "value", "lower_value", "upper_value",\n            "unit", "source_year", "evidence_quote", "reason",\n        }\n        accepted = []\n        for selected in candidates:\n            payload = {\n                "material": material, "target_geography": self.target_geography,\n                "search_tier": tier, "requested_property": label,\n                "required_standardized_unit": expected_unit,\n                "evidence_candidates": [{\n                    "result_id": selected["result_id"], "title": selected["title"],\n                    "url": selected["url"], "search_snippet": selected["snippet"][:900],\n                    "extracted_text": selected["excerpt"][: self.excerpt_chars],\n                }],\n            }\n            raw = _call_matcher(\n                self.matcher, PROVISIONAL_PROPERTY_SYSTEM_PROMPT, payload,\n                max_new_tokens=480,\n            )\n            try:\n                obj = json.loads(raw.strip())\n            except Exception:\n                m = re.search(r"\\{.*\\}", raw or "", flags=re.S)\n                if not m:\n                    continue\n                try:\n                    obj = json.loads(m.group(0))\n                except Exception:\n                    continue\n            if set(obj.keys()) != {"records"} or not isinstance(obj.get("records"), list) or len(obj["records"]) != 1:\n                continue\n            rec = obj["records"][0]\n            if not isinstance(rec, dict) or set(rec.keys()) != required:\n                continue\n            sid = _clean(rec.get("source_result_id"))\n            if sid != selected.get("result_id") or not bool(rec.get("found")):\n                continue\n            value = _num(rec.get("value"))\n            if value is None or value <= 0 or not _expected_unit_ok(kind, _clean(rec.get("unit"))):\n                continue\n            source_ok, source_class = _provisional_source_allowed(selected.get("url", ""), selected.get("title", ""))\n            if not source_ok:\n                continue\n            identity_ok, identity_reason = _property_identity_ok(material, selected)\n            if not identity_ok:\n                continue\n            quote = _clean(rec.get("evidence_quote"))\n            if not _quote_supported(quote, selected) or not _number_close_in_text(value, quote):\n                continue\n            if not _property_unit_supported_in_quote(kind, quote):\n                continue\n            if kind == "density_kg_m3" and not _bulk_density_evidence_ok(material, selected):\n                continue\n            geography = _infer_geography(selected)\n            accepted.append({\n                "kind": kind, "value": float(value),\n                "lower_value": _num(rec.get("lower_value")),\n                "upper_value": _num(rec.get("upper_value")),\n                "unit": _clean(rec.get("unit")), "source_class": source_class,\n                "verification": "TRACEABLE_WEB_RELAXED",\n                "source_title": selected.get("title"), "source_url": selected.get("url"),\n                "source_geography": geography,\n                "geography_representativeness": (\n                    "TARGET_GEOGRAPHY" if _target_geography_supported(selected, self.target_geography)\n                    else "NON_TARGET_OR_UNSPECIFIED_ACCEPTED_AS_CLASS4"\n                ),\n                "source_year": _clean(rec.get("source_year")), "search_tier": tier,\n                "search_query": selected.get("query"), "evidence_quote": quote,\n                "reason": _clean(rec.get("reason")), "raw_model_output": raw,\n                "selected_result_id": sid, "product_identity_status": "PASS_SOURCE_SUPPORTED",\n                "product_identity_reason": identity_reason,\n            })\n        return accepted\n\n    def _build_provisional_consensus(self, kind: str, factors: list[dict[str, Any]]):\n        unique = []\n        seen_urls = set()\n        for f in factors:\n            url = _clean(f.get("source_url"))\n            if not url or url in seen_urls:\n                continue\n            seen_urls.add(url)\n            unique.append(dict(f))\n        if not unique:\n            return None\n        consensus = robust_positive_consensus([float(x["value"]) for x in unique])\n        if consensus is None:\n            return None\n        retained = [unique[i] for i in consensus.retained_indices]\n        outliers = [unique[i] for i in consensus.outlier_indices]\n        if not retained:\n            return None\n        values = [float(x["value"]) for x in retained]\n        geos = sorted({_clean(x.get("source_geography")) for x in retained if _clean(x.get("source_geography"))})\n        years = [int(x["source_year"]) for x in retained if str(x.get("source_year") or "").isdigit()]\n        source_details = []\n        retained_urls = {_clean(x.get("source_url")) for x in retained}\n        outlier_urls = {_clean(x.get("source_url")) for x in outliers}\n        for f in unique:\n            source_details.append({\n                "value": float(f["value"]),\n                "unit": f.get("unit"),\n                "source_title": f.get("source_title"),\n                "source_url": f.get("source_url"),\n                "source_class": f.get("source_class"),\n                "source_geography": f.get("source_geography"),\n                "geography_representativeness": f.get("geography_representativeness"),\n                "source_year": f.get("source_year"),\n                "search_tier": f.get("search_tier"),\n                "evidence_quote": f.get("evidence_quote"),\n                "retained_for_consensus": _clean(f.get("source_url")) in retained_urls,\n                "outlier": _clean(f.get("source_url")) in outlier_urls,\n            })\n        one = retained[0]\n        multi = len(retained) > 1\n        return {\n            "kind": kind,\n            "value": float(consensus.central_value),\n            "lower_value": min(values) if multi else None,\n            "upper_value": max(values) if multi else None,\n            "unit": one.get("unit"),\n            "source_class": "EXTERNAL_VERIFIED_RELAXED",\n            "verification": "TRACEABLE_WEB_RELAXED",\n            "source_title": f"Median of {len(retained)} source-supported property values" if multi else one.get("source_title"),\n            "source_url": None if multi else one.get("source_url"),\n            "source_geography": ", ".join(geos) if geos else "Unspecified",\n            "source_year": str(max(years)) if years else None,\n            "search_tier": one.get("search_tier"),\n            "search_query": None if multi else one.get("search_query"),\n            "evidence_quote": None if multi else one.get("evidence_quote"),\n            "reason": (\n                f"Relaxed-phase External Verified property from {len(retained)} retained independent source(s) "\n                f"using {consensus.method}; {len(outliers)} source-set outlier(s) excluded."\n            ),\n            "raw_model_output": None,\n            "selected_result_id": one.get("selected_result_id") if not multi else None,\n            "product_identity_status": "PASS_SOURCE_SUPPORTED",\n            "product_identity_reason": "Every retained source passed deterministic material/property identity checks.",\n            "peer_values_json": json.dumps(values, ensure_ascii=False),\n            "peer_sources_json": json.dumps(source_details, ensure_ascii=False),\n            "relaxed_source_count": len(unique),\n            "relaxed_retained_count": len(retained),\n            "relaxed_outlier_count": len(outliers),\n            "relaxed_consensus_method": consensus.method,\n            "relaxed_consensus_version": CONSENSUS_METHOD_VERSION,\n        }\n\n    def _parse_model_json(self, raw: str):\n        try:\n            return json.loads(raw.strip())\n        except Exception:\n            m = re.search(r"\\{.*\\}", raw, flags=re.S)\n            if not m:\n                return None\n            try:\n                return json.loads(m.group(0))\n            except Exception:\n                return None\n\n\n    def _validated_model_property(self, obj, material: str, kind: str, expected_unit: str, required_keys: set[str]):\n        if not isinstance(obj, dict) or set(obj.keys()) != required_keys or not bool(obj.get("found")):\n            return None, "schema_or_found_invalid"\n        central = _num(obj.get("central_value")); lower = _num(obj.get("lower_value")); upper = _num(obj.get("upper_value"))\n        if central is None or lower is None or upper is None or not (0 < lower < central < upper):\n            return None, "invalid_central_or_range"\n        if _clean(obj.get("unit")).lower().replace("³", "3") != expected_unit.lower().replace("³", "3"):\n            return None, "unit_mismatch"\n        ok, reason = property_plausible(material, kind, central, lower, upper)\n        if not ok:\n            return None, reason\n        return {\n            "central": central, "lower": lower, "upper": upper,\n            "interpretation": _clean(obj.get("analog_material") or obj.get("material_interpretation")),\n            "basis": _clean(obj.get("estimation_basis")), "rationale": _clean(obj.get("rationale")),\n        }, "ok"\n\n    def _property_ensemble_from_output(self, raw: str, material: str, kind: str, expected_unit: str, *, analog: bool):\n        obj = self._parse_model_json(raw)\n        if not isinstance(obj, dict) or set(obj.keys()) != {"candidates"} or not isinstance(obj.get("candidates"), list):\n            return None, {"accepted": False, "reason": "ensemble_schema_invalid", "raw_model_output": raw}\n        if len(obj["candidates"]) != MODEL_ENSEMBLE_SIZE:\n            return None, {"accepted": False, "reason": f"expected_{MODEL_ENSEMBLE_SIZE}_candidates", "raw_model_output": raw}\n        required = {"found","central_value","lower_value","upper_value","unit","estimation_basis","rationale",("analog_material" if analog else "material_interpretation")}\n        valid=[]; rejected=[]\n        for i,candidate in enumerate(obj["candidates"]):\n            parsed, reason = self._validated_model_property(candidate, material, kind, expected_unit, required)\n            if parsed is None:\n                rejected.append({"index":i,"reason":reason,"candidate":candidate})\n            else:\n                valid.append((i,candidate,parsed))\n        values=[x[2]["central"] for x in valid]\n        consensus=robust_model_ensemble_consensus(values)\n        diag={"accepted":bool(consensus.accepted),"reason":consensus.reason,"method":consensus.method,\n              "retained_ratio":consensus.retained_ratio,"valid_candidate_count":len(valid),\n              "rejected_candidates":rejected,"all_valid_central_values":values,\n              "valid_candidate_details":[x[2] for x in valid],\n              "ensemble_method_version":MODEL_ENSEMBLE_METHOD_VERSION,"raw_model_output":raw}\n        if not consensus.accepted:\n            return None, diag\n        retained_valid=[valid[i] for i in consensus.retained_indices]\n        retained=[x[2] for x in retained_valid]\n        central=float(consensus.central_value); lower=min(x["lower"] for x in retained); upper=max(x["upper"] for x in retained)\n        if not (0 < lower < central < upper):\n            return None, {**diag,"accepted":False,"reason":"consensus_interval_invalid"}\n        diag["retained_candidate_indices"]=[x[0] for x in retained_valid]\n        diag["retained_values"]=[x[2]["central"] for x in retained_valid]\n        return {"central":central,"lower":lower,"upper":upper,\n                "interpretations":[x["interpretation"] for x in retained],\n                "bases":[x["basis"] for x in retained],"rationales":[x["rationale"] for x in retained],\n                "all_values":values,"diagnostics":diag}, diag\n\n    @staticmethod\n    def _invalid_property_candidate(*, analog: bool, analog_material: str = "") -> dict[str, Any]:\n        d={"found":False,"central_value":None,"lower_value":None,"upper_value":None,\n           "unit":None,"estimation_basis":None,"rationale":None}\n        if analog: d["analog_material"]=analog_material\n        else: d["material_interpretation"]=None\n        return d\n\n    def _generate_one_property_candidate(self, *, system_prompt: str, payload: dict[str, Any],\n                                         material: str, kind: str, expected_unit: str,\n                                         analog: bool, analog_material: str = ""):\n        required={"found","central_value","lower_value","upper_value","unit","estimation_basis","rationale",\n                  ("analog_material" if analog else "material_interpretation")}\n        attempts=[]; working=dict(payload)\n        for attempt_no in range(1,3):\n            raw=_call_matcher(self.matcher,system_prompt,working,max_new_tokens=360)\n            obj=self._parse_model_json(raw)\n            parsed=None; reason="parse_error"\n            if isinstance(obj,dict):\n                parsed,reason=self._validated_model_property(obj,material,kind,expected_unit,required)\n                if analog and parsed is not None and _clean(obj.get("analog_material")) != _clean(analog_material):\n                    parsed=None; reason="analog_name_not_preserved"\n            attempts.append({"attempt":attempt_no,"accepted":parsed is not None,"reason":reason,"raw_model_output":raw})\n            if parsed is not None:\n                return obj,attempts\n            working={**payload,"repair_instruction":"Return one complete JSON object only and correct the schema/unit/interval problem without using a prescribed numerical range.",\n                     "previous_validation_error":reason,"previous_output":(raw or "")[-1200:]}\n        return self._invalid_property_candidate(analog=analog,analog_material=analog_material),attempts\n\n\n    @staticmethod\n    def _property_anchor_warning(diag: dict[str, Any]) -> tuple[bool, str]:\n        vals = []\n        for v in (diag.get("all_valid_central_values") or []):\n            try:\n                vals.append(float(v))\n            except Exception:\n                pass\n        if len(vals) < 4:\n            return False, "insufficient_candidates_for_anchor_check"\n        counts: dict[str, int] = {}\n        for v in vals:\n            key = format(v, ".12g")\n            counts[key] = counts.get(key, 0) + 1\n        most = max(counts.values(), default=0)\n        distinct = len(counts)\n        suspicious = most >= 3 and distinct > 1 and diag.get("method") in {"REPEATED_LOG_MEDIAN", "TIGHTEST_LOG_CLUSTER"}\n        return suspicious, ("repeated_exact_model_value_with_disagreement" if suspicious else "no_anchor_warning")\n\n    def _estimate_llm_unverified_property(self, material: str, kind: str):\n        label, expected_unit = _property_label(kind, material)\n        lenses=["composition and physical structure","manufacturing/product form","functional-product comparison",\n                "unit-basis reconstruction","conservative engineering interpretation without a preset range"]\n        candidates=[]; calls=[]\n        self._progress(f"Property Class 4 · Method A · exact-material consensus · {material} · {kind}")\n        for i,lens in enumerate(lenses,start=1):\n            self._progress(f"Property Class 4 · Method A · candidate {i}/{len(lenses)} · {material} · {kind}")\n            payload={"material":material,"target_context":self.target_geography,"requested_property":label,\n                     "required_standardized_unit":expected_unit,"candidate_index":i,"estimation_lens":lens,\n                     **property_guardrail_context(material,kind),\n                     "status":"Evidence-backed property pathways failed; exploratory estimate only."}\n            obj,attempts=self._generate_one_property_candidate(\n                system_prompt=LLM_UNVERIFIED_PROPERTY_SINGLE_SYSTEM_PROMPT,payload=payload,material=material,\n                kind=kind,expected_unit=expected_unit,analog=False)\n            candidates.append(obj); calls.append({"candidate_index":i,"lens":lens,"attempts":attempts})\n        raw=json.dumps({"candidates":candidates},ensure_ascii=False)\n        ensemble,diag=self._property_ensemble_from_output(raw,material,kind,expected_unit,analog=False)\n        diag["generation_calls"]=calls\n        self._relaxed_property_pool.extend([{**x,"kind":kind,"unit":expected_unit} for x in diag.get("valid_candidate_details", [])])\n        anchor_warning,anchor_reason=self._property_anchor_warning(diag)\n        diag["anchor_warning"]=anchor_warning; diag["anchor_reason"]=anchor_reason\n        self._last_fallback_attempts.append({"stage":"CLASS5A_EXACT_PROPERTY","diagnostics":diag})\n        if ensemble is None: return None\n        if anchor_warning:\n            self._anchored_exact_property_pool = [{**x,"kind":kind,"unit":expected_unit} for x in diag.get("valid_candidate_details", [])]\n            self._progress(f"Property Class 4 · repeated-value anchor detected; trying Method B before terminal fallback · {material} · {kind}")\n            return None\n        central,lower,upper=ensemble["central"],ensemble["lower"],ensemble["upper"]\n        interp="; ".join(dict.fromkeys(x for x in ensemble["interpretations"] if x))\n        return {\n            "kind":kind,"value":central,"lower_value":lower,"upper_value":upper,"unit":expected_unit,\n            "source_class":"UNVERIFIED_FALLBACK_ESTIMATE","verification":"UNVERIFIED_FALLBACK_ESTIMATE",\n            "fallback_method":"EXACT_MATERIAL_LLM_CONSENSUS",\n            "source_title":"Qwen five-independent-call property consensus estimate","source_url":None,\n            "source_geography":"Unverified model assumption; target context "+self.target_geography,"source_year":None,\n            "search_tier":"FINAL_LLM_PRODUCT_ENSEMBLE","search_query":None,"evidence_quote":None,\n            "reason":f"Five independent material-agnostic property calls using {diag.get(\'method\')}; retained {len(diag.get(\'retained_values\',[]))} candidate(s).",\n            "raw_model_output":raw,"selected_result_id":None,"product_identity_status":"UNVERIFIED_MODEL_ENSEMBLE",\n            "product_identity_reason":interp,"peer_values_json":json.dumps(ensemble["all_values"],ensure_ascii=False),\n            "peer_sources_json":None,"relaxed_source_count":None,"relaxed_retained_count":None,\n            "relaxed_outlier_count":None,"relaxed_consensus_method":None,"relaxed_consensus_version":None,\n            "guardrail_status":"PASS_ENSEMBLE_CONSENSUS","guardrail_reason":diag.get("method"),"guardrail_version":GUARDRAIL_VERSION,\n            "fallback_attempts_json":json.dumps(self._last_fallback_attempts,ensure_ascii=False),\n        }\n\n    def _estimate_conservative_analog_property(self, material: str, kind: str):\n        label, expected_unit = _property_label(kind, material)\n        feedback=None; rounds=[]\n        self._progress(f"Property Class 4 · Method B · dynamic analog fallback · {material} · {kind}")\n        for round_no in range(1,3):\n            self._progress(f"Property Class 4 · Method B · analog-plan round {round_no}/2 · {material} · {kind}")\n            plan=infer_analog_plan(self.matcher,material=material,estimation_target=f"{label} in {expected_unit}",target_context=self.target_geography,feedback=feedback)\n            if plan is None:\n                rounds.append({"round":round_no,"accepted":False,"reason":"semantic_analog_plan_invalid"})\n                feedback="Infer one broader but technically defensible family and five distinct analog products."\n                continue\n            candidates=[]; calls=[]\n            for i,a in enumerate(plan["analogs"],start=1):\n                analog_name=_clean(a.get("analog_material"))\n                self._progress(f"Property Class 4 · Method B · analog {i}/{len(plan[\'analogs\'])} · {material} → {analog_name} · {kind}")\n                payload={"material":material,"semantic_family":plan["family_description"],"analog_material":analog_name,\n                         "similarity_basis":a.get("similarity_basis"),"target_context":self.target_geography,\n                         "requested_property":label,"required_standardized_unit":expected_unit,"candidate_index":i,\n                         **property_guardrail_context(material,kind)}\n                obj,attempts=self._generate_one_property_candidate(\n                    system_prompt=CONSERVATIVE_ANALOG_PROPERTY_SINGLE_SYSTEM_PROMPT,payload=payload,material=material,\n                    kind=kind,expected_unit=expected_unit,analog=True,analog_material=analog_name)\n                candidates.append(obj); calls.append({"analog":analog_name,"attempts":attempts})\n            raw=json.dumps({"candidates":candidates},ensure_ascii=False)\n            ensemble,diag=self._property_ensemble_from_output(raw,material,kind,expected_unit,analog=True)\n            diag["generation_calls"]=calls\n            rounds.append({"round":round_no,"family":plan["family_description"],"analogs":plan["analogs"],"diagnostics":diag})\n            self._relaxed_property_pool.extend([{**x,"kind":kind,"unit":expected_unit} for x in diag.get("valid_candidate_details", [])])\n            if ensemble is None:\n                feedback=f"Previous analog property estimates had no robust 3-of-5 consensus ({diag.get(\'reason\')}). Move one semantic level broader while preserving composition, form and function."\n                continue\n            central,lower,upper=ensemble["central"],ensemble["lower"],ensemble["upper"]\n            analogs="; ".join(dict.fromkeys(x for x in ensemble["interpretations"] if x))\n            self._last_fallback_attempts.append({"stage":"CLASS5B_ANALOG_PROPERTY","rounds":rounds})\n            return {\n                "kind":kind,"value":central,"lower_value":lower,"upper_value":upper,"unit":expected_unit,\n                "source_class":"UNVERIFIED_FALLBACK_ESTIMATE","verification":"UNVERIFIED_FALLBACK_ESTIMATE",\n                "fallback_method":"DYNAMIC_ANALOG_CONSENSUS",\n                "source_title":"Qwen dynamic semantic-family five-independent-analog property consensus","source_url":None,\n                "source_geography":"Unverified analog assumption; target context "+self.target_geography,"source_year":None,\n                "search_tier":"FINAL_DYNAMIC_ANALOG_ENSEMBLE","search_query":None,"evidence_quote":None,\n                "reason":f"Dynamic semantic family: {plan[\'family_description\']}; retained analogs: {analogs}.",\n                "raw_model_output":raw,"selected_result_id":None,"product_identity_status":"DYNAMIC_SEMANTIC_ANALOG_CONSENSUS",\n                "product_identity_reason":f"Family inferred at run time: {plan[\'family_description\']}; analogs: {analogs}",\n                "peer_values_json":json.dumps(ensemble["all_values"],ensure_ascii=False),"peer_sources_json":None,\n                "relaxed_source_count":None,"relaxed_retained_count":None,"relaxed_outlier_count":None,\n                "relaxed_consensus_method":None,"relaxed_consensus_version":None,\n                "guardrail_status":"PASS_ENSEMBLE_CONSENSUS","guardrail_reason":diag.get("method"),"guardrail_version":GUARDRAIL_VERSION,\n                "fallback_attempts_json":json.dumps(self._last_fallback_attempts,ensure_ascii=False),"semantic_analog_version":SEMANTIC_ANALOG_VERSION,\n            }\n        self._last_fallback_attempts.append({"stage":"CLASS5B_ANALOG_PROPERTY","rounds":rounds,"accepted":False})\n        return None\n\n    def _estimate_relaxed_valid_property_median(self, material: str, kind: str):\n        """Final Class-4 property safety net from individually valid candidates."""\n        label, expected_unit = _property_label(kind, material)\n        anchored = [x for x in self._anchored_exact_property_pool if isinstance(x, dict) and x.get("kind") == kind and x.get("unit") == expected_unit]\n        valid = anchored if anchored else [x for x in self._relaxed_property_pool if isinstance(x, dict) and x.get("kind") == kind and x.get("unit") == expected_unit]\n        if not valid:\n            self._last_fallback_attempts.append({"stage":"CLASS5C_RELAXED_PROPERTY","accepted":False,"reason":"no_individually_valid_candidates","kind":kind})\n            return None\n        values = sorted(float(x["central"]) for x in valid)\n        n=len(values); central=values[n//2] if n%2 else (values[n//2-1]+values[n//2])/2.0\n        lower=min(float(x["lower"]) for x in valid); upper=max(float(x["upper"]) for x in valid)\n        if not (0 < lower < central < upper):\n            self._last_fallback_attempts.append({"stage":"CLASS5C_RELAXED_PROPERTY","accepted":False,"reason":"combined_interval_invalid","kind":kind,"values":values})\n            return None\n        interpretations="; ".join(dict.fromkeys(_clean(x.get("interpretation")) for x in valid if _clean(x.get("interpretation"))))\n        terminal_method="TERMINAL_ROUNDED_EXACT_MATERIAL_MEDIAN" if anchored else "TERMINAL_VALID_CANDIDATE_MEDIAN"\n        self._last_fallback_attempts.append({"stage":"CLASS5C_RELAXED_PROPERTY","accepted":True,"kind":kind,"valid_candidate_count":len(valid),"values":values,"terminal_method":terminal_method})\n        return {\n            "kind":kind,"value":central,"lower_value":lower,"upper_value":upper,"unit":expected_unit,\n            "source_class":"UNVERIFIED_FALLBACK_ESTIMATE","verification":"UNVERIFIED_FALLBACK_ESTIMATE",\n            "fallback_method":terminal_method,\n            "source_title":("Qwen terminal median of anchored exact-material property candidates" if anchored else "Qwen terminal median of individually valid property candidates"),"source_url":None,\n            "source_geography":"Unverified model/analog assumption; target context "+self.target_geography,"source_year":None,\n            "search_tier":"FINAL_TERMINAL_VALID_CANDIDATE_MEDIAN","search_query":None,"evidence_quote":None,\n            "reason":(f"Strict/independence-aware exact-material acceptance and analog property consensus failed. Used the median of {len(valid)} anchored exact-material candidates as the terminal numerical fallback; repeated/rounded values are permitted only at this final stage and the full exact-candidate envelope is retained as uncertainty." if anchored else f"Strict/independence-aware exact-material acceptance and analog property consensus failed. Used the median of {len(valid)} individually valid candidates as the terminal numerical fallback; the full envelope is retained as uncertainty."),\n            "raw_model_output":None,"selected_result_id":None,"product_identity_status":"UNVERIFIED_RELAXED_MODEL_ANALOG_POOL",\n            "product_identity_reason":interpretations or "Individually valid fallback property candidates",\n            "peer_values_json":json.dumps(values,ensure_ascii=False),"peer_sources_json":None,\n            "relaxed_source_count":None,"relaxed_retained_count":None,"relaxed_outlier_count":None,\n            "relaxed_consensus_method":None,"relaxed_consensus_version":None,\n            "guardrail_status":"PASS_INDIVIDUAL_VALIDATION_RELAXED_CONSENSUS","guardrail_reason":terminal_method,\n            "guardrail_version":GUARDRAIL_VERSION,"fallback_attempts_json":json.dumps(self._last_fallback_attempts,ensure_ascii=False),\n        }\n\n\n    @staticmethod\n    def _median_property_value(values: list[float]) -> float:\n        vals = sorted(float(v) for v in values)\n        n = len(vals)\n        if not n:\n            raise ValueError("median requires at least one value")\n        return vals[n // 2] if n % 2 else (vals[n // 2 - 1] + vals[n // 2]) / 2.0\n\n    def _estimate_terminal_llm_only_property(self, material: str, kind: str):\n        """Last Class-4 property fallback used to preserve exploratory coverage.\n\n        This stage contains no material-specific property value/range. It runs\n        only after evidence, exact-material consensus, analog consensus, and the\n        existing valid-candidate median have failed. Fresh Qwen estimates are\n        generated in the standardized property unit. Their median is retained\n        even without strong consensus because the resulting row remains Class 4\n        and is excluded from verified subtotal.\n        """\n        label, expected_unit = _property_label(kind, material)\n        lenses = [\n            "fresh physical-structure reconstruction",\n            "independent product-form/manufacturing reconstruction",\n            "independent functional engineering estimate",\n        ]\n        valid=[]; calls=[]\n        self._progress(f"Property Class 4 · Method D · terminal LLM-only numerical fallback · {material} · {kind}")\n        for i,lens in enumerate(lenses,start=1):\n            payload={\n                "material":material,"target_context":self.target_geography,\n                "requested_property":label,"required_standardized_unit":expected_unit,\n                "candidate_index":i,"estimation_lens":lens,\n                **property_guardrail_context(material,kind),\n                "status":"All stronger property checks failed. A terminal unverified numerical value is required only for the separated exploratory calculation.",\n            }\n            obj,attempts=self._generate_one_property_candidate(\n                system_prompt=LLM_UNVERIFIED_PROPERTY_SINGLE_SYSTEM_PROMPT,\n                payload=payload,material=material,kind=kind,expected_unit=expected_unit,analog=False)\n            required={"found","central_value","lower_value","upper_value","unit","estimation_basis","rationale","material_interpretation"}\n            parsed,reason=self._validated_model_property(obj,material,kind,expected_unit,required) if isinstance(obj,dict) else (None,"parse_error")\n            calls.append({"candidate_index":i,"lens":lens,"attempts":attempts,"accepted":parsed is not None,"reason":reason})\n            if parsed is not None:\n                valid.append(parsed)\n        if valid:\n            values=[float(x["central"]) for x in valid]\n            central=self._median_property_value(values)\n            lower=min(float(x["lower"]) for x in valid)\n            upper=max(float(x["upper"]) for x in valid)\n            if not (0 < lower < central < upper):\n                lower=None; upper=None\n            method="TERMINAL_LLM_ONLY_PROPERTY_MEDIAN_NO_CONSENSUS" if len(valid)>1 else "TERMINAL_LLM_ONLY_PROPERTY_SINGLE_VALID_ESTIMATE"\n            self._last_fallback_attempts.append({\n                "stage":"CLASS5D_TERMINAL_PROPERTY","accepted":True,"method":method,\n                "valid_candidate_count":len(valid),"values":values,"generation_calls":calls,\n                "quality":"VERY_LOW_CONFIDENCE_MODEL_ONLY",\n            })\n            interp="; ".join(dict.fromkeys(_clean(x.get("interpretation")) for x in valid if _clean(x.get("interpretation"))))\n            return {\n                "kind":kind,"value":central,"lower_value":lower,"upper_value":upper,"unit":expected_unit,\n                "source_class":"UNVERIFIED_FALLBACK_ESTIMATE","verification":"UNVERIFIED_FALLBACK_ESTIMATE",\n                "fallback_method":method,"source_title":"Qwen terminal model-only exploratory property estimate","source_url":None,\n                "source_geography":"Unverified model assumption; target context "+self.target_geography,"source_year":None,\n                "search_tier":"FINAL_TERMINAL_LLM_ONLY_PROPERTY","search_query":None,"evidence_quote":None,\n                "reason":f"Stronger property checks failed. Used the median of {len(valid)} fresh model-only estimate(s) in {expected_unit} solely to preserve exploratory numerical coverage. No source support or material-specific coded range is claimed.",\n                "raw_model_output":None,"selected_result_id":None,"product_identity_status":"TERMINAL_UNVERIFIED_MODEL_ONLY_PROPERTY",\n                "product_identity_reason":interp or "Fresh terminal property estimate",\n                "peer_values_json":json.dumps(values,ensure_ascii=False),"peer_sources_json":None,\n                "relaxed_source_count":None,"relaxed_retained_count":None,"relaxed_outlier_count":None,\n                "relaxed_consensus_method":None,"relaxed_consensus_version":None,\n                "guardrail_status":"TERMINAL_VALUE_PRESERVED_AFTER_FAILED_STRONG_CONSENSUS",\n                "guardrail_reason":"VERY_LOW_CONFIDENCE_MODEL_ONLY","guardrail_version":GUARDRAIL_VERSION,\n                "fallback_attempts_json":json.dumps(self._last_fallback_attempts,ensure_ascii=False),\n                "terminal_quality_flag":"VERY_LOW_CONFIDENCE_MODEL_ONLY",\n            }\n\n        working={\n            "material":material,"target_context":self.target_geography,\n            "requested_property":label,"required_standardized_unit":expected_unit,\n            "status":"Last numerical property fallback; return one unverified positive value.",\n        }\n        attempts=[]\n        for attempt_no in range(1,3):\n            raw=_call_matcher(self.matcher,TERMINAL_MINIMAL_PROPERTY_SYSTEM_PROMPT,working,max_new_tokens=220)\n            obj=self._parse_model_json(raw)\n            reason="minimal_schema_invalid"; value=None\n            if isinstance(obj,dict) and set(obj.keys())=={"found","value","unit","material_interpretation","rationale"} and bool(obj.get("found")):\n                value=_num(obj.get("value"))\n                if value is None or value<=0:\n                    reason="minimal_value_invalid"; value=None\n                elif _clean(obj.get("unit")).lower().replace("³","3") != expected_unit.lower().replace("³","3"):\n                    reason="minimal_unit_mismatch"; value=None\n                else:\n                    ok,why=property_plausible(material,kind,value)\n                    if not ok:\n                        reason=why; value=None\n                    else:\n                        reason="ok"\n            attempts.append({"attempt":attempt_no,"accepted":value is not None,"reason":reason,"raw_model_output":raw})\n            if value is not None:\n                self._last_fallback_attempts.append({\n                    "stage":"CLASS5E_TERMINAL_MINIMAL_PROPERTY","accepted":True,"attempts":attempts,\n                    "quality":"LOWEST_CONFIDENCE_MODEL_ONLY_NO_RANGE",\n                })\n                return {\n                    "kind":kind,"value":float(value),"lower_value":None,"upper_value":None,"unit":expected_unit,\n                    "source_class":"UNVERIFIED_FALLBACK_ESTIMATE","verification":"UNVERIFIED_FALLBACK_ESTIMATE",\n                    "fallback_method":"TERMINAL_MINIMAL_SINGLE_LLM_PROPERTY_VALUE",\n                    "source_title":"Qwen terminal minimal-schema model-only property estimate","source_url":None,\n                    "source_geography":"Unverified model assumption; target context "+self.target_geography,"source_year":None,\n                    "search_tier":"FINAL_TERMINAL_MINIMAL_PROPERTY_VALUE","search_query":None,"evidence_quote":None,\n                    "reason":"All stronger property paths failed. Retained one final positive model-only value in the required standardized unit to preserve exploratory coverage; no source-supported range is claimed.",\n                    "raw_model_output":raw,"selected_result_id":None,"product_identity_status":"TERMINAL_UNVERIFIED_MODEL_ONLY_PROPERTY",\n                    "product_identity_reason":_clean(obj.get("material_interpretation")),\n                    "peer_values_json":json.dumps([float(value)]),"peer_sources_json":None,\n                    "relaxed_source_count":None,"relaxed_retained_count":None,"relaxed_outlier_count":None,\n                    "relaxed_consensus_method":None,"relaxed_consensus_version":None,\n                    "guardrail_status":"TERMINAL_MINIMAL_VALUE_ONLY","guardrail_reason":"LOWEST_CONFIDENCE_MODEL_ONLY_NO_RANGE",\n                    "guardrail_version":GUARDRAIL_VERSION,"fallback_attempts_json":json.dumps(self._last_fallback_attempts,ensure_ascii=False),\n                    "terminal_quality_flag":"LOWEST_CONFIDENCE_MODEL_ONLY_NO_RANGE",\n                }\n            working={**working,"repair_instruction":"Return exactly the requested minimal JSON schema with one finite positive value in required_standardized_unit.","previous_validation_error":reason,"previous_output":(raw or "")[-800:]}\n        self._last_fallback_attempts.append({"stage":"CLASS5E_TERMINAL_MINIMAL_PROPERTY","accepted":False,"attempts":attempts})\n        return None\n\n    def _resolve_one_property(self, item_id: str, material: str, kind: str):\n        cache_key = (material.strip().lower(), kind)\n        if cache_key in self._resolution_cache:\n            return dict(self._resolution_cache[cache_key]), []\n\n        cached = self.evidence_cache.get(\n            category="physical_property", material=material,\n            target_geography=self.target_geography, property_kind=kind,\n        )\n        if cached and cached.get("verification") in {"TRACEABLE_WEB", "TRACEABLE_WEB_RELAXED"}:\n            cached = dict(cached)\n            cached["reason"] = (_clean(cached.get("reason")) + " Runtime evidence-cache reuse.").strip()\n            cached["evidence_cache_version"] = CACHE_VERSION\n            self._progress(f"Property cache hit · {material} · {kind} · {cached.get(\'verification\')}")\n            self._resolution_cache[cache_key] = dict(cached)\n            cache_evidence = [{\n                "item_id": item_id, "material": material, "property_kind": kind,\n                "search_tier": "RUNTIME_CACHE", "query": None, "result_id": "CACHEP1",\n                "title": cached.get("source_title"), "url": cached.get("source_url"),\n                "snippet": cached.get("evidence_quote"), "excerpt": cached.get("evidence_quote"),\n                "product_identity_ok": True, "product_identity_reason": "Previously accepted retrieved evidence",\n                "selected": True, "relaxed_candidate": cached.get("verification") == "TRACEABLE_WEB_RELAXED",\n                "relaxed_retained": cached.get("verification") == "TRACEABLE_WEB_RELAXED",\n                "relaxed_outlier": False, "relaxed_value": cached.get("value"),\n                "relaxed_reason": "Runtime evidence-cache reuse",\n            }]\n            return cached, cache_evidence\n\n        all_evidence: list[dict[str, Any]] = []\n        provisional_factors: list[dict[str, Any]] = []\n        seen_urls: set[str] = set()\n        promising_reasons: list[str] = []\n        promising_candidates: list[dict[str, Any]] = []\n        plans = list(_query_sets(material, kind, self.target_geography))\n\n        # CLASS 3 PROPERTY — independent target-geography clock.\n        class3_started = time.monotonic()\n        class3_inspected = 0\n        class3_queries_used = 0\n        nepal_plan = next((p for p in plans if p[0] == "NEPAL"), None)\n        if nepal_plan is not None:\n            tier, queries = nepal_plan\n            self._progress(\n                f"External property evidence · Phase A strict {self.target_geography} · {material} · {kind} · "\n                f"independent budget {self.max_external_seconds_per_property:.0f} s · "\n                f"max {self.class3_source_budget} sources"\n            )\n            candidates, evidence_rows, used = self._collect_evidence(\n                queries, tier, item_id, material, kind,\n                max_candidates=self.class3_source_budget,\n                max_queries=min(3, self.max_search_queries_per_property),\n                seen_urls=seen_urls,\n            )\n            class3_queries_used += used\n            class3_inspected += len(candidates)\n            all_evidence.extend(evidence_rows)\n            for c in candidates:\n                ok_promising, why_promising = _promising_property_candidate(material, kind, c)\n                if ok_promising:\n                    promising_reasons.append(why_promising)\n                    if c.get("url") and not any(x.get("url") == c.get("url") for x in promising_candidates):\n                        promising_candidates.append(dict(c))\n            selected, _ = self._choose_traceable(material, kind, tier, candidates)\n            if selected is not None:\n                sid = selected.get("selected_result_id")\n                for row in all_evidence:\n                    if row["search_tier"] == tier and row["result_id"] == sid and row["url"] == selected["source_url"]:\n                        row["selected"] = True\n                selected = dict(selected)\n                selected["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                selected["evidence_cache_version"] = CACHE_VERSION\n                self.evidence_cache.put(\n                    category="physical_property", material=material, target_geography=self.target_geography,\n                    property_kind=kind, resolved=selected,\n                )\n                self._resolution_cache[cache_key] = dict(selected)\n                self._progress(f"External property evidence Phase A accepted · {material} · {kind}")\n                return selected, all_evidence\n            if self.allow_source_supported_provisional and candidates:\n                provisional_factors.extend(self._extract_relaxed_candidates(material, kind, tier, candidates))\n\n        self._progress(\n            f"External property evidence Phase A finished · {material} · {kind} · {class3_inspected} source(s), "\n            f"{class3_queries_used} query/queries · starting Phase B relaxed search with a fresh clock"\n        )\n\n        if not self.allow_source_supported_provisional:\n            return None, all_evidence\n\n        # CLASS 4 PROPERTY — independent geography-relaxed clock. This is used\n        # only when deterministic unit conversion actually requires the property.\n        class4_started = time.monotonic()\n        class4_inspected = 0\n        external_verified_relaxed_queries_used = 0\n        class4_source_budget = self.adaptive_total_source_budget\n        class4_query_budget = self.adaptive_max_search_queries_per_property\n        class4_time_budget = self.adaptive_external_seconds_per_property\n        self._progress(\n            f"External property evidence · Phase B relaxed source-supported search · {material} · {kind} · "\n            f"budget {class4_time_budget:.0f} s · up to {class4_query_budget} queries / "\n            f"{class4_source_budget} unique sources · geography may differ"\n        )\n\n        equivalent_plan = infer_technical_equivalents(\n            self.matcher, material=material, target_context=self.target_geography\n        )\n        label, unit = _property_label(kind, material)\n        equivalent_plans = []\n        if equivalent_plan:\n            for rec in equivalent_plan.get("search_terms", []):\n                subject = _clean(rec.get("term"))\n                if not subject:\n                    continue\n                equivalent_plans.extend([\n                    ("GLOBAL", [\n                        f\'"{subject}" {label} {unit} technical data\',\n                        f\'"{subject}" {label} {unit} USA Canada\',\n                        f\'"{subject}" {label} {unit} filetype:pdf\',\n                    ]),\n                    ("SOUTH_ASIA", [\n                        f\'"{subject}" {label} {unit} India technical data\',\n                        f\'"{subject}" {label} {unit} South Asia\',\n                    ]),\n                ])\n\n        standard_non_nepal = [p for p in plans if p[0] != "NEPAL"]\n        search_plans = standard_non_nepal + equivalent_plans\n        for tier, queries in search_plans:\n            if time.monotonic() - class4_started >= class4_time_budget:\n                self._progress(f"External property evidence Phase B time budget reached · {material} · {kind}; moving toward Class 4 fallback")\n                break\n            if class4_inspected >= class4_source_budget or external_verified_relaxed_queries_used >= class4_query_budget:\n                break\n            remaining_sources = class4_source_budget - class4_inspected\n            remaining_queries = class4_query_budget - external_verified_relaxed_queries_used\n            candidates, evidence_rows, used = self._collect_evidence(\n                queries, tier, item_id, material, kind,\n                max_candidates=min(2, remaining_sources),\n                max_queries=min(2, remaining_queries),\n                seen_urls=seen_urls,\n            )\n            external_verified_relaxed_queries_used += used\n            class4_inspected += len(candidates)\n            all_evidence.extend(evidence_rows)\n            for c in candidates:\n                ok_promising, why_promising = _promising_property_candidate(material, kind, c)\n                if ok_promising:\n                    promising_reasons.append(why_promising)\n                    if c.get("url") and not any(x.get("url") == c.get("url") for x in promising_candidates):\n                        promising_candidates.append(dict(c))\n            if candidates:\n                extracted = self._extract_relaxed_candidates(material, kind, tier, candidates)\n                provisional_factors.extend(extracted)\n                by_url = {_clean(x.get("source_url")): x for x in extracted}\n                for row in all_evidence:\n                    f = by_url.get(_clean(row.get("url")))\n                    if f is not None:\n                        row["relaxed_candidate"] = True\n                        row["relaxed_value"] = f.get("value")\n                        row["relaxed_reason"] = f.get("reason")\n                provisional = self._build_provisional_consensus(kind, provisional_factors)\n                if provisional is not None:\n                    try:\n                        details = json.loads(provisional.get("peer_sources_json") or "[]")\n                    except Exception:\n                        details = []\n                    retained_urls = {_clean(x.get("source_url")) for x in details if x.get("retained_for_consensus")}\n                    outlier_urls = {_clean(x.get("source_url")) for x in details if x.get("outlier")}\n                    for row in all_evidence:\n                        url = _clean(row.get("url"))\n                        if url in retained_urls:\n                            row["relaxed_retained"] = True\n                            row["selected"] = True\n                        if url in outlier_urls:\n                            row["relaxed_outlier"] = True\n                    provisional = dict(provisional)\n                    provisional["technical_equivalence_version"] = TECHNICAL_EQUIVALENCE_VERSION if equivalent_plan else None\n                    provisional["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                    provisional["external_verified_relaxed_elapsed_seconds"] = round(time.monotonic() - class4_started, 3)\n                    provisional["external_verified_relaxed_queries_used"] = external_verified_relaxed_queries_used\n                    provisional["external_verified_relaxed_sources_inspected"] = class4_inspected\n                    provisional["evidence_cache_version"] = CACHE_VERSION\n                    self.evidence_cache.put(\n                        category="physical_property", material=material, target_geography=self.target_geography,\n                        property_kind=kind, resolved=provisional,\n                    )\n                    self._resolution_cache[cache_key] = dict(provisional)\n                    self._progress(f"External property evidence Phase B accepted · {material} · {kind}")\n                    return provisional, all_evidence\n\n        # Deep re-extraction of a small number of promising documents is allowed\n        # within the same independent relaxed-phase Class-3 clock.\n        if promising_candidates and time.monotonic() - class4_started < class4_time_budget:\n            old_pages = self.pdf_max_pages\n            try:\n                self.pdf_max_pages = self.adaptive_pdf_max_pages\n                deep_candidates = []\n                for c0 in promising_candidates[:2]:\n                    if time.monotonic() - class4_started >= class4_time_budget:\n                        break\n                    c = dict(c0)\n                    self._progress(f"External property evidence · Phase B deeper extraction of promising source · {material} · {kind}")\n                    c["full_text"] = self._extract(c.get("url"))\n                    c["excerpt"] = c["full_text"][: max(self.excerpt_chars, 2200)]\n                    deep_candidates.append(c)\n                for c in deep_candidates:\n                    provisional_factors.extend(\n                        self._extract_relaxed_candidates(material, kind, c.get("tier") or "GLOBAL", [c])\n                    )\n                provisional = self._build_provisional_consensus(kind, provisional_factors) if provisional_factors else None\n                if provisional is not None:\n                    provisional = dict(provisional)\n                    provisional["adaptive_search_used"] = True\n                    provisional["adaptive_search_trigger"] = "; ".join(sorted(set(promising_reasons)))\n                    provisional["adaptive_deep_extraction_used"] = True\n                    provisional["external_verified_strict_elapsed_seconds"] = round(time.monotonic() - class3_started, 3)\n                    provisional["external_verified_relaxed_elapsed_seconds"] = round(time.monotonic() - class4_started, 3)\n                    provisional["external_verified_relaxed_queries_used"] = external_verified_relaxed_queries_used\n                    provisional["external_verified_relaxed_sources_inspected"] = class4_inspected\n                    provisional["evidence_cache_version"] = CACHE_VERSION\n                    self.evidence_cache.put(\n                        category="physical_property", material=material, target_geography=self.target_geography,\n                        property_kind=kind, resolved=provisional,\n                    )\n                    self._resolution_cache[cache_key] = dict(provisional)\n                    self._progress(f"External property evidence Phase B accepted after deeper extraction · {material} · {kind}")\n                    return provisional, all_evidence\n            finally:\n                self.pdf_max_pages = old_pages\n\n        self._progress(\n            f"External property evidence Phase B finished without accepted value · {material} · {kind} · "\n            f"{class4_inspected} source(s), {external_verified_relaxed_queries_used} query/queries · moving to Class 4 fallback"\n        )\n        return None, all_evidence\n\n    def resolve_record(self, rec: dict[str, Any]):\n        item_id = _clean(rec.get("item_id") or rec.get("ID")) or "ITEM"\n        original_material = _clean(rec.get("original_material") or rec.get("Material"))\n        normalized_material = _clean(rec.get("normalized_material"))\n        material, material_basis = choose_resolution_material(original_material, normalized_material)\n        source_unit = rec.get("unit") or rec.get("Unit")\n        approved = _as_bool(rec.get("production_approved"))\n        external_status = _clean(rec.get("external_ef_resolution_status"))\n        external_ready = external_status in {\n            "RESOLVED_EXTERNAL_VERIFIED",\n            "RESOLVED_TRACEABLE_WEB_RELAXED",\n            "RESOLVED_UNVERIFIED_FALLBACK_ESTIMATE",\n            "RESOLVED_LLM_UNVERIFIED_ESTIMATE",  # legacy payload compatibility\n            "RESOLVED_CONSERVATIVE_ANALOG_ESTIMATE",  # legacy payload compatibility\n        }\n        # Approved ELCD rows use the Qwen-selected production process unit; rows\n        # routed to an external factor use the external factor\'s reference unit.\n        if approved:\n            ref_unit = rec.get("production_selected_process_ref_unit")\n        elif external_ready:\n            ref_unit = rec.get("external_ef_reference_unit")\n        else:\n            ref_unit = None\n\n        result = {\n            "property_resolution_status": "NOT_NEEDED",\n            "property_required": None,\n            "property_lookup_needed": False,\n            "property_lookup_reason": None,\n            "property_fallback_method": None,\n            "property_terminal_quality_flag": None,\n            "resolved_density_kg_m3": None,\n            "resolved_thickness_mm": None,\n            "resolved_mass_per_item_kg": None,\n            "property_verification": "NOT_NEEDED",\n            "property_source_class": None,\n            "property_source_title": None,\n            "property_source_url": None,\n            "property_source_geography": None,\n            "property_source_year": None,\n            "property_search_tier": None,\n            "property_search_query": None,\n            "property_evidence_quote": None,\n            "property_lower_value": None,\n            "property_upper_value": None,\n            "property_peer_values_json": None,\n            "property_peer_sources_json": None,\n            "property_relaxed_source_count": None,\n            "property_relaxed_retained_count": None,\n            "property_relaxed_outlier_count": None,\n            "property_relaxed_consensus_method": None,\n            "property_relaxed_consensus_version": None,\n            "property_details_json": None,\n            "property_material_query": material,\n            "property_material_selection_basis": material_basis,\n            "property_material_family": classify_material(material),\n            "property_material_taxonomy_version": MATERIAL_TAXONOMY_VERSION,\n            "property_resolver_version": PROPERTY_RESOLVER_VERSION,\n            "property_resolved_at_utc": datetime.now(timezone.utc).isoformat(),\n            "property_guardrail_status": None,\n            "property_guardrail_reason": None,\n            "property_guardrail_version": GUARDRAIL_VERSION,\n            "property_evidence_cache_version": CACHE_VERSION,\n            "property_fallback_attempts_json": None,\n        }\n        evidence: list[dict[str, Any]] = []\n\n        if not approved and not external_ready:\n            result["property_resolution_status"] = "SKIPPED_NO_APPROVED_FACTOR"\n            result["property_verification"] = "NOT_APPLICABLE"\n            return result, evidence\n        if not _clean(ref_unit):\n            result["property_resolution_status"] = "DEFERRED_REFERENCE_UNIT_UNKNOWN"\n            result["property_verification"] = "INPUT_OR_MODEL_FAILURE"\n            return result, evidence\n\n        explicit_factor = _num(rec.get("conversion_factor_to_ref_unit") or rec.get("Conversion_factor_to_ref_unit"))\n        if explicit_factor is not None and explicit_factor > 0:\n            result["property_lookup_reason"] = "Explicit Conversion_factor_to_ref_unit supplied; no physical-property lookup needed."\n            return result, evidence\n\n        requirements = conversion_requirements(source_unit, ref_unit)\n        if not requirements:\n            result["property_lookup_reason"] = f"BOM unit {norm_unit(source_unit) or source_unit} converts directly to EF reference unit {norm_unit(ref_unit) or ref_unit}; no physical property needed."\n            return result, evidence\n\n        result["property_required"] = ";".join(requirements)\n        result["property_lookup_needed"] = True\n        result["property_lookup_reason"] = f"Physical conversion required from BOM unit {norm_unit(source_unit) or source_unit} to EF reference unit {norm_unit(ref_unit) or ref_unit}: {\', \'.join(requirements)}."\n        self._last_fallback_attempts = []\n        self._relaxed_property_pool = []\n        self._anchored_exact_property_pool = []\n        details: list[dict[str, Any]] = []\n        any_provisional = False\n        any_web = False\n        any_llm = False\n        any_analog = False\n        unresolved = False\n\n        for kind in requirements:\n            # User/project value has highest priority.\n            source_field = kind\n            user_value = _num(rec.get(source_field))\n            if user_value is not None and user_value > 0:\n                d = {\n                    "kind": kind,\n                    "value": user_value,\n                    "verification": "PROJECT_INPUT",\n                    "source_class": "USER_PROJECT_INPUT",\n                    "source_title": None,\n                    "source_url": None,\n                    "source_geography": self.target_geography,\n                    "source_year": None,\n                    "search_tier": None,\n                    "search_query": None,\n                    "evidence_quote": None,\n                    "lower_value": None,\n                    "upper_value": None,\n                    "reason": "Physical property supplied directly in the BOM.",\n                }\n                details.append(d)\n                continue\n\n            # Thickness explicitly present in material name is an extraction, not an LLM estimate.\n            if kind == "thickness_mm":\n                thickness = extract_thickness_mm(\n                    _clean(rec.get("original_material") or material)\n                )\n                if thickness is not None:\n                    d = {\n                        "kind": kind,\n                        "value": thickness,\n                        "verification": "BOM_EXTRACTED",\n                        "source_class": "BOM_DESCRIPTION",\n                        "source_title": None,\n                        "source_url": None,\n                        "source_geography": self.target_geography,\n                        "source_year": None,\n                        "search_tier": None,\n                        "search_query": None,\n                        "evidence_quote": _clean(rec.get("original_material") or material),\n                        "lower_value": None,\n                        "upper_value": None,\n                        "reason": "Thickness explicitly encoded in BOM material description.",\n                    }\n                    details.append(d)\n                    continue\n\n            d, ev = self._resolve_one_property(item_id, material, kind)\n            evidence.extend(ev)\n            if d is None and self.allow_llm_unverified_estimate:\n                d = self._estimate_llm_unverified_property(material, kind)\n            if d is None and self.allow_conservative_analog_estimate:\n                d = self._estimate_conservative_analog_property(material, kind)\n            if d is None and (self.allow_llm_unverified_estimate or self.allow_conservative_analog_estimate):\n                self._progress(f"Property Class 4 · Method C · terminal valid-candidate median · {material} · {kind}")\n                d = self._estimate_relaxed_valid_property_median(material, kind)\n            if d is None and (self.allow_llm_unverified_estimate or self.allow_conservative_analog_estimate):\n                self._progress(f"Property Class 4 · Method D/E · value-preserving terminal fallback · {material} · {kind}")\n                d = self._estimate_terminal_llm_only_property(material, kind)\n            if d is None:\n                unresolved = True\n                details.append({\n                    "kind": kind,\n                    "value": None,\n                    "verification": "INPUT_OR_MODEL_FAILURE",\n                    "source_class": None,\n                    "reason": "No traceable strict/relaxed external property or Class-4 unverified fallback property estimate passed deterministic checks.",\n                    "fallback_attempts_json": json.dumps(self._last_fallback_attempts, ensure_ascii=False),\n                })\n                continue\n            details.append(d)\n            if d.get("verification") == "TRACEABLE_WEB":\n                any_web = True\n            if d.get("verification") == "TRACEABLE_WEB_RELAXED":\n                any_provisional = True\n            if d.get("verification") == "UNVERIFIED_FALLBACK_ESTIMATE":\n                any_llm = True\n                if d.get("fallback_method") == "DYNAMIC_ANALOG_CONSENSUS":\n                    any_analog = True\n\n        by_kind = {d["kind"]: d for d in details if d.get("value") is not None}\n        if "density_kg_m3" in by_kind:\n            result["resolved_density_kg_m3"] = by_kind["density_kg_m3"]["value"]\n        if "thickness_mm" in by_kind:\n            result["resolved_thickness_mm"] = by_kind["thickness_mm"]["value"]\n        if "mass_per_item_kg" in by_kind:\n            result["resolved_mass_per_item_kg"] = by_kind["mass_per_item_kg"]["value"]\n\n        if unresolved:\n            result["property_resolution_status"] = "INPUT_OR_MODEL_FAILURE"\n            result["property_verification"] = "INPUT_OR_MODEL_FAILURE"\n            result["property_fallback_attempts_json"] = json.dumps(self._last_fallback_attempts, ensure_ascii=False)\n        elif any_llm or any_analog:\n            result["property_resolution_status"] = "RESOLVED_UNVERIFIED_FALLBACK_ESTIMATE"\n            result["property_verification"] = "UNVERIFIED_FALLBACK_ESTIMATE"\n        elif any_provisional:\n            result["property_resolution_status"] = "RESOLVED_TRACEABLE_WEB_RELAXED"\n            result["property_verification"] = "TRACEABLE_WEB_RELAXED"\n        elif any_web:\n            result["property_resolution_status"] = "RESOLVED_TRACEABLE_WEB"\n            result["property_verification"] = "TRACEABLE_WEB"\n        else:\n            result["property_resolution_status"] = "RESOLVED_FROM_BOM_OR_PROJECT_INPUT"\n            result["property_verification"] = "PROJECT_OR_BOM"\n\n        # Surface the first external property in flat audit columns; all details remain in JSON.\n        primary = next(\n            (d for d in details if d.get("verification") in {"TRACEABLE_WEB", "TRACEABLE_WEB_RELAXED", "UNVERIFIED_FALLBACK_ESTIMATE"}),\n            details[0] if details else None,\n        )\n        if primary:\n            result["property_source_class"] = primary.get("source_class")\n            result["property_source_title"] = primary.get("source_title")\n            result["property_source_url"] = primary.get("source_url")\n            result["property_source_geography"] = primary.get("source_geography")\n            result["property_source_year"] = primary.get("source_year")\n            result["property_search_tier"] = primary.get("search_tier")\n            result["property_search_query"] = primary.get("search_query")\n            result["property_evidence_quote"] = primary.get("evidence_quote")\n            result["property_lower_value"] = primary.get("lower_value")\n            result["property_upper_value"] = primary.get("upper_value")\n            result["property_peer_values_json"] = primary.get("peer_values_json")\n            result["property_peer_sources_json"] = primary.get("peer_sources_json")\n            result["property_relaxed_source_count"] = primary.get("relaxed_source_count")\n            result["property_relaxed_retained_count"] = primary.get("relaxed_retained_count")\n            result["property_relaxed_outlier_count"] = primary.get("relaxed_outlier_count")\n            result["property_relaxed_consensus_method"] = primary.get("relaxed_consensus_method")\n            result["property_relaxed_consensus_version"] = primary.get("relaxed_consensus_version")\n            result["property_fallback_method"] = primary.get("fallback_method")\n            result["property_terminal_quality_flag"] = primary.get("terminal_quality_flag")\n            result["property_guardrail_status"] = primary.get("guardrail_status")\n            result["property_guardrail_reason"] = primary.get("guardrail_reason")\n            result["property_fallback_attempts_json"] = primary.get("fallback_attempts_json")\n        result["property_details_json"] = json.dumps(details, ensure_ascii=False)\n        return result, evidence\n\n    def resolve_batch(self, df: pd.DataFrame):\n        rows = []\n        evidence_rows: list[dict[str, Any]] = []\n        records = df.to_dict(orient="records")\n        total = len(records)\n        for i, rec in enumerate(records, start=1):\n            material = _clean(rec.get("normalized_material") or rec.get("original_material") or rec.get("Material"))\n            self._progress(f"Property resolver · row {i}/{total} · {material}")\n            resolved, evidence = self.resolve_record(rec)\n            merged = dict(rec)\n            merged.update(resolved)\n            rows.append(merged)\n            evidence_rows.extend(evidence)\n            status = resolved.get("property_verification") or resolved.get("property_resolution_status")\n            self._progress(f"Property resolver · row {i}/{total} complete · {material} · {status}")\n        return pd.DataFrame(rows), pd.DataFrame(evidence_rows)\n', 'unit_conversion.py': '"""Deterministic quantity conversion for openLCA reference units.\n\nThis module never invents density, thickness, or item mass. Required physical\nproperties can come from the user/project BOM or from the separate audited\nproperty_resolver. Python performs only deterministic arithmetic here.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Optional\n\n\n@dataclass\nclass ConversionResult:\n    ok: bool\n    quantity_in_ref_unit: float | None\n    normalized_ref_unit: str | None\n    method: str\n    message: str | None = None\n\n\ndef norm_unit(unit: str | None) -> str:\n    if unit is None:\n        return ""\n    u = str(unit).strip().lower().replace("³", "3").replace("²", "2")\n    aliases = {\n        "kilogram": "kg", "kilograms": "kg", "kgs": "kg",\n        "gram": "g", "grams": "g",\n        "ton": "t", "tons": "t", "tonne": "t", "tonnes": "t", "metric ton": "t", "metric tonne": "t",\n        "m^3": "m3", "cu.m.": "m3", "cu.m": "m3", "cubic meter": "m3", "cubic metre": "m3",\n        "liter": "l", "liters": "l", "litre": "l", "litres": "l", "dm3": "l", "dm^3": "l",\n        "cm^3": "cm3", "cubic centimeter": "cm3", "cubic centimeters": "cm3",\n        "cubic centimetre": "cm3", "cubic centimetres": "cm3",\n        "m^2": "m2", "sq.m.": "m2", "sq.m": "m2", "square meter": "m2", "square metre": "m2",\n        "cm^2": "cm2", "square centimeter": "cm2", "square centimeters": "cm2",\n        "square centimetre": "cm2", "square centimetres": "cm2",\n        "mm^2": "mm2", "square millimeter": "mm2", "square millimeters": "mm2",\n        "square millimetre": "mm2", "square millimetres": "mm2",\n        "nos.": "item", "nos": "item", "no.": "item", "number": "item", "piece": "item", "pieces": "item", "pcs": "item",\n        "kilowatt hour": "kwh", "kilowatt-hour": "kwh",\n        "megajoule": "mj",\n    }\n    return aliases.get(u, u)\n\n\ndef _mass_to_kg(q: float, unit: str) -> float | None:\n    return {"kg": q, "g": q / 1000.0, "t": q * 1000.0}.get(unit)\n\n\ndef _kg_to_mass(qkg: float, ref: str) -> float | None:\n    return {"kg": qkg, "g": qkg * 1000.0, "t": qkg / 1000.0}.get(ref)\n\n\ndef _volume_to_m3(q: float, unit: str) -> float | None:\n    return {"m3": q, "l": q / 1000.0, "cm3": q / 1_000_000.0}.get(unit)\n\n\ndef _m3_to_volume(qm3: float, ref: str) -> float | None:\n    return {"m3": qm3, "l": qm3 * 1000.0, "cm3": qm3 * 1_000_000.0}.get(ref)\n\n\ndef _area_to_m2(q: float, unit: str) -> float | None:\n    return {"m2": q, "cm2": q / 10_000.0, "mm2": q / 1_000_000.0}.get(unit)\n\n\ndef _m2_to_area(qm2: float, ref: str) -> float | None:\n    return {"m2": qm2, "cm2": qm2 * 10_000.0, "mm2": qm2 * 1_000_000.0}.get(ref)\n\n\ndef convert_quantity(\n    quantity: float,\n    source_unit: str,\n    ref_unit: str,\n    *,\n    density_kg_m3: Optional[float] = None,\n    thickness_mm: Optional[float] = None,\n    mass_per_item_kg: Optional[float] = None,\n    conversion_factor_to_ref_unit: Optional[float] = None,\n) -> ConversionResult:\n    q = float(quantity)\n    src = norm_unit(source_unit)\n    ref = norm_unit(ref_unit)\n\n    if q < 0:\n        return ConversionResult(False, None, ref, "invalid", "Quantity cannot be negative.")\n    if not src or not ref:\n        return ConversionResult(False, None, ref or None, "invalid", "Source or reference unit is blank.")\n    if src == ref:\n        return ConversionResult(True, q, ref, "same_unit")\n\n    if conversion_factor_to_ref_unit is not None:\n        f = float(conversion_factor_to_ref_unit)\n        if f <= 0:\n            return ConversionResult(False, None, ref, "explicit_factor", "Conversion factor must be > 0.")\n        return ConversionResult(True, q * f, ref, "explicit_factor")\n\n    # Pure mass conversions.\n    qkg = _mass_to_kg(q, src)\n    if qkg is not None and ref in {"kg", "g", "t"}:\n        return ConversionResult(True, _kg_to_mass(qkg, ref), ref, "mass_unit_conversion")\n\n    # Pure volume conversions. These are universal SI relationships and require\n    # no material density or other product-specific property.\n    qm3 = _volume_to_m3(q, src)\n    if qm3 is not None and ref in {"m3", "l", "cm3"}:\n        return ConversionResult(True, _m3_to_volume(qm3, ref), ref, "volume_unit_conversion")\n\n    # Pure area conversions. These are universal SI relationships and require\n    # no thickness, density, or product-specific property.\n    qm2 = _area_to_m2(q, src)\n    if qm2 is not None and ref in {"m2", "cm2", "mm2"}:\n        return ConversionResult(True, _m2_to_area(qm2, ref), ref, "area_unit_conversion")\n\n    # Volume to mass using user-supplied density.\n    if src == "m3" and ref in {"kg", "g", "t"}:\n        if density_kg_m3 is None or float(density_kg_m3) <= 0:\n            return ConversionResult(False, None, ref, "volume_to_mass", "density_kg_m3 is required.")\n        qkg = q * float(density_kg_m3)\n        return ConversionResult(True, _kg_to_mass(qkg, ref), ref, "volume_to_mass")\n\n    # Mass to volume using density.\n    if src in {"kg", "g", "t"} and ref == "m3":\n        if density_kg_m3 is None or float(density_kg_m3) <= 0:\n            return ConversionResult(False, None, ref, "mass_to_volume", "density_kg_m3 is required.")\n        qkg = _mass_to_kg(q, src)\n        return ConversionResult(True, qkg / float(density_kg_m3), ref, "mass_to_volume")\n\n    # Mass to area using thickness and density.\n    if src in {"kg", "g", "t"} and ref == "m2":\n        if thickness_mm is None or float(thickness_mm) <= 0:\n            return ConversionResult(False, None, ref, "mass_to_area", "thickness_mm is required.")\n        if density_kg_m3 is None or float(density_kg_m3) <= 0:\n            return ConversionResult(False, None, ref, "mass_to_area", "density_kg_m3 is required.")\n        qkg = _mass_to_kg(q, src)\n        volume_m3 = qkg / float(density_kg_m3)\n        area_m2 = volume_m3 / (float(thickness_mm) / 1000.0)\n        return ConversionResult(True, area_m2, ref, "mass_to_area")\n\n    # Mass to item count using a resolved unit mass.\n    if src in {"kg", "g", "t"} and ref == "item":\n        if mass_per_item_kg is None or float(mass_per_item_kg) <= 0:\n            return ConversionResult(False, None, ref, "mass_to_count", "mass_per_item_kg is required.")\n        qkg = _mass_to_kg(q, src)\n        return ConversionResult(True, qkg / float(mass_per_item_kg), ref, "mass_to_count")\n\n    # Area <-> volume using an explicit/BOM-resolved thickness.\n    if src == "m2" and ref == "m3":\n        if thickness_mm is None or float(thickness_mm) <= 0:\n            return ConversionResult(False, None, ref, "area_to_volume", "thickness_mm is required.")\n        return ConversionResult(True, q * float(thickness_mm) / 1000.0, ref, "area_to_volume")\n\n    if src == "m3" and ref == "m2":\n        if thickness_mm is None or float(thickness_mm) <= 0:\n            return ConversionResult(False, None, ref, "volume_to_area", "thickness_mm is required.")\n        return ConversionResult(True, q / (float(thickness_mm) / 1000.0), ref, "volume_to_area")\n\n    # Area to mass using thickness and density.\n    if src == "m2" and ref in {"kg", "g", "t"}:\n        if thickness_mm is None or float(thickness_mm) <= 0:\n            return ConversionResult(False, None, ref, "area_to_mass", "thickness_mm is required.")\n        if density_kg_m3 is None or float(density_kg_m3) <= 0:\n            return ConversionResult(False, None, ref, "area_to_mass", "density_kg_m3 is required.")\n        volume_m3 = q * float(thickness_mm) / 1000.0\n        qkg = volume_m3 * float(density_kg_m3)\n        return ConversionResult(True, _kg_to_mass(qkg, ref), ref, "area_to_mass")\n\n    # Count to mass using user-supplied unit mass.\n    if src == "item" and ref in {"kg", "g", "t"}:\n        if mass_per_item_kg is None or float(mass_per_item_kg) <= 0:\n            return ConversionResult(False, None, ref, "count_to_mass", "mass_per_item_kg is required.")\n        qkg = q * float(mass_per_item_kg)\n        return ConversionResult(True, _kg_to_mass(qkg, ref), ref, "count_to_mass")\n\n    # Simple energy conversion.\n    if src == "mj" and ref == "kwh":\n        return ConversionResult(True, q / 3.6, ref, "energy_unit_conversion")\n    if src == "kwh" and ref == "mj":\n        return ConversionResult(True, q * 3.6, ref, "energy_unit_conversion")\n\n    return ConversionResult(\n        False, None, ref, "unsupported",\n        f"No deterministic conversion rule from \'{source_unit}\' to \'{ref_unit}\'. Supply Conversion_factor_to_ref_unit if justified."\n    )\n\n\ndef equivalent_reference_units(reference_unit: str) -> tuple[str, ...]:\n    """Return dimensionally equivalent units that require no material property.\n\n    The mapping contains only universal unit relationships. It intentionally\n    contains no material-specific factor, density, thickness, item mass, or\n    plausibility value. The requested unit is always returned first.\n    """\n    ref = norm_unit(reference_unit)\n    groups = (\n        ("kg", "g", "t"),\n        ("m3", "l", "cm3"),\n        ("m2", "cm2", "mm2"),\n        ("kwh", "mj"),\n    )\n    for group in groups:\n        if ref in group:\n            return (ref,) + tuple(u for u in group if u != ref)\n    return (ref,) if ref else tuple()\n\n\ndef convert_factor_reference_basis(\n    value: float,\n    from_reference_unit: str,\n    to_reference_unit: str,\n) -> float | None:\n    """Convert an intensity denominator using deterministic unit arithmetic.\n\n    ``value`` is interpreted as kg CO2e per ``from_reference_unit``. The\n    returned value is kg CO2e per ``to_reference_unit``. Conversion is allowed\n    only when :func:`convert_quantity` can convert one target reference unit to\n    the source reference unit without any material-specific physical property.\n\n    Example logic (not material data): if a factor is expressed per tonne and\n    the calculation needs per kilogram, Python converts the denominator using\n    the same universal mass-unit conversion already used for BOM quantities.\n    """\n    try:\n        v = float(value)\n    except Exception:\n        return None\n    src = norm_unit(from_reference_unit)\n    dst = norm_unit(to_reference_unit)\n    if not src or not dst:\n        return None\n    if src == dst:\n        return v\n    # For an intensity F / src, obtain how many src units are contained in one\n    # dst unit, then scale F by that quantity. No density or product property is\n    # supplied here; conversions needing such information fail deterministically.\n    q = convert_quantity(1.0, dst, src)\n    if not q.ok or q.quantity_in_ref_unit is None:\n        return None\n    return v * float(q.quantity_in_ref_unit)\n\n\ndef reference_unit_schedule(reference_unit: str, count: int) -> tuple[str, ...]:\n    """Build a deterministic multi-unit schedule for independent estimates.\n\n    For dimensions with multiple directly convertible units, calls are rotated\n    across those units so a denominator-scale mistake cannot create artificial\n    agreement merely because every call was requested in the same basis.\n    Non-convertible reference units remain unchanged.\n    """\n    n = max(0, int(count))\n    if n == 0:\n        return tuple()\n    variants = equivalent_reference_units(reference_unit)\n    if not variants:\n        return tuple()\n    return tuple(variants[i % len(variants)] for i in range(n))\n', 'material_taxonomy.py': '"""Deterministic construction-material taxonomy used by the production safety layers.\n\nThe taxonomy is intentionally small and engineering-oriented.  It is not an LCA\nfactor database.  It provides reusable family identity rules so that obvious\nsemantic false positives (for example, earthen soil -> PVC soil pipe) are\nrejected before they can enter the calculation.\n"""\nfrom __future__ import annotations\n\nimport re\nfrom typing import Any\n\nMATERIAL_TAXONOMY_VERSION = "1.6"\n\n\ndef _norm(value: Any) -> str:\n    s = "" if value is None else str(value).lower()\n    s = s.replace("–", "-").replace("—", "-")\n    s = re.sub(r"[^a-z0-9]+", " ", s)\n    return " ".join(s.split())\n\n\ndef _has_any(text: str, terms) -> bool:\n    """Loose substring helper for intentionally broad/stem-based rules."""\n    return any(t in text for t in terms)\n\n\ndef _has_term(text: str, term: str) -> bool:\n    """Match a normalized whole word or multi-word phrase, never a substring.\n\n    This prevents false positives such as ``cement`` matching the tail of\n    ``reinforcement`` and also handles hyphenated source labels because both\n    inputs are normalized before comparison.\n    """\n    normalized_text = f" {_norm(text)} "\n    normalized_term = _norm(term)\n    if not normalized_term:\n        return False\n    return f" {normalized_term} " in normalized_text\n\n\ndef _has_any_term(text: str, terms) -> bool:\n    return any(_has_term(text, term) for term in terms)\n\n\ndef classify_material(material: Any) -> str:\n    """Classify a BOM description into a reusable construction product family."""\n    m = _norm(material)\n\n    # Specific manufactured products before their constituents.\n    if "stonecrete" in m:\n        return "STONECRETE_BLOCK"\n    if _has_any(m, ("compressed earth block", "compressed soil block", "soil block", "earth block", "ceb")):\n        return "SOIL_BLOCK"\n    if "plywood" in m:\n        return "PLYWOOD"\n    if _has_term(m, "bamboo"):\n        return "BAMBOO"\n    if _has_any(m, ("plain cement concrete", "pcc m10", "pcc 1 3 6", "blinding concrete", "blinding layer")):\n        return "PLAIN_CONCRETE"\n    # Generic concrete/RMC descriptions must be classified before the word\n    # ``cement`` is considered.  This keeps company names such as "... Cement"\n    # from masking the fact that the declared product itself is concrete.\n    if _has_any_term(m, ("ready mix concrete", "ready mixed concrete", "precast concrete", "pre cast concrete", "concrete")):\n        return "PLAIN_CONCRETE"\n    if _has_any(m, ("plaster", "render")):\n        return "PLASTER"\n    if _has_any(m, (\n        "cgi", "corrugated galvanized", "corrugated galvanised", "corrugated iron",\n        "galvanized sheet", "galvanised sheet", "galvanized steel sheet", "galvanised steel sheet",\n        "galvanized steel coil", "galvanised steel coil", "galvanized flat steel",\n        "galvanised flat steel", "zinc coated steel", "zinc-coated steel",\n        "hot dip coated steel", "hot-dip coated steel",\n    )):\n        return "GALVANIZED_FLAT_STEEL"\n    if _has_any(m, ("binding wire", "tie wire", "annealed wire", "steel wire")):\n        return "STEEL_WIRE"\n    if _has_any(m, ("nail", "fastener")):\n        return "STEEL_FASTENER"\n    if _has_any(m, (\n        "rebar", "reinforcing steel", "reinforcement steel", "reinforcing bar",\n        "reinforcement bar", "tmt bar", "tmt steel", "tmt fe",\n    )):\n        return "REBAR"\n    if _has_term(m, "cement"):\n        return "CEMENT"\n    if _has_term(m, "sand"):\n        return "SAND"\n    if _has_any_term(m, ("gravel", "aggregate")):\n        return "GRAVEL_AGGREGATE"\n    if _has_any_term(m, ("soil", "earth", "mud", "backfill")):\n        return "SOIL_EARTH"\n    if _has_any_term(m, ("timber", "wood", "lumber", "sawnwood")):\n        return "TIMBER"\n    if _has_any_term(m, ("stone", "rock", "quarry")):\n        return "NATURAL_STONE"\n    return "UNKNOWN"\n\ndef choose_resolution_material(original_material: Any, normalized_material: Any) -> tuple[str, str]:\n    """Choose the safest material text for downstream external/property resolution.\n\n    Qwen normalization is useful when it preserves the BOM product family.  When\n    the original BOM contains a recognizable construction family but the normalized\n    text changes that family (for example, binding wire -> rebar), the original BOM\n    description takes precedence.  This prevents a valid safety-gate rejection from\n    being undone by downstream source searches.\n    """\n    original = "" if original_material is None else str(original_material).strip()\n    normalized = "" if normalized_material is None else str(normalized_material).strip()\n    ofam = classify_material(original) if original else "UNKNOWN"\n    nfam = classify_material(normalized) if normalized else "UNKNOWN"\n\n    if original and ofam != "UNKNOWN":\n        if not normalized or nfam == "UNKNOWN" or nfam != ofam:\n            return original, "ORIGINAL_BOM_FAMILY_OVERRIDE"\n    if normalized:\n        return normalized, "QWEN_NORMALIZED_SAME_FAMILY" if ofam == nfam and nfam != "UNKNOWN" else "QWEN_NORMALIZED"\n    if original:\n        return original, "ORIGINAL_BOM_ONLY"\n    return "", "NO_MATERIAL_TEXT"\n\n\nBIOGENIC_STORAGE_EXCLUDED_FAMILIES = {"TIMBER", "PLYWOOD", "BAMBOO"}\n\n\ndef excludes_biogenic_storage(material: Any) -> bool:\n    """Return True for bio-based product families reported without storage credits."""\n    return classify_material(material) in BIOGENIC_STORAGE_EXCLUDED_FAMILIES\n\n\ndef process_compatibility(material: Any, process_name: Any) -> tuple[bool, str]:\n    """Conservative deterministic compatibility check for an ELCD process title.\n\n    It only vetoes clear family contradictions.  It never selects a replacement.\n    """\n    family = classify_material(material)\n    p = _norm(process_name)\n    if not p:\n        return False, "selected_process_name_blank"\n\n    # Cross-cutting false positives.\n    if family in {"REBAR", "STEEL_WIRE", "STEEL_FASTENER", "GALVANIZED_FLAT_STEEL"} and _has_any(p, ("copper", "aluminium", "aluminum")):\n        return False, "ferrous_product_mapped_to_nonferrous_process"\n\n    rules = {\n        "CEMENT": (\n            lambda: _has_term(p, "cement")\n            and not _has_any_term(\n                p,\n                (\n                    "concrete",\n                    "mortar",\n                    "concrete block",\n                    "precast concrete",\n                    "pre cast concrete",\n                    "ready mixed concrete",\n                    "ready mix concrete",\n                ),\n            ),\n            "cement_requires_cement_process_not_downstream_product",\n        ),\n        "SAND": (lambda: "sand" in p, "sand_requires_sand_process"),\n        "GRAVEL_AGGREGATE": (\n            lambda: _has_any(p, ("gravel", "aggregate", "crushed stone")),\n            "gravel_requires_aggregate_gravel_or_crushed_stone_process",\n        ),\n        "NATURAL_STONE": (\n            lambda: _has_any(p, ("stone", "rock", "quarry", "aggregate")) and not _has_any(p, ("concrete block", "brick")),\n            "stone_requires_stone_rock_or_quarry_process",\n        ),\n        "PLAIN_CONCRETE": (\n            lambda: _has_term(p, "concrete") and not _has_any_term(p, ("concrete block", "aerated concrete", "autoclaved", "aac")),\n            "plain_concrete_requires_concrete_process_not_cement_or_block",\n        ),\n        "STONECRETE_BLOCK": (\n            lambda: _has_any(p, ("concrete block", "masonry block")) and not _has_any(p, ("aerated", "autoclaved", "aac")),\n            "stonecrete_block_rejects_aac_and_non_block_processes",\n        ),\n        "REBAR": (\n            lambda: _has_any(p, (\n                "rebar", "reinforcing steel", "reinforcement steel",\n                "reinforcing bar", "reinforcement bar", "tmt bar", "tmt steel",\n            )),\n            "rebar_requires_reinforcing_steel_process",\n        ),\n        "STEEL_WIRE": (\n            lambda: _has_any(p, ("steel wire", "wire drawing", "wire rod", "annealed wire")),\n            "binding_wire_requires_steel_wire_family_process",\n        ),\n        "STEEL_FASTENER": (\n            lambda: _has_any(p, ("nail", "fastener", "steel screw", "screw")),\n            "nail_requires_steel_fastener_family_process",\n        ),\n        "GALVANIZED_FLAT_STEEL": (\n            lambda: _has_any(p, ("galvanized", "galvanised", "zinc coated", "zinc-coated", "coated steel", "steel sheet", "steel coil")) and not _has_any(p, ("floor panel", "access floor", "sandwich panel")),\n            "cgi_requires_galvanized_flat_steel_family_process",\n        ),\n        "TIMBER": (\n            lambda: _has_any(p, ("wood", "timber", "lumber", "sawn", "roundwood")) and "plywood" not in p,\n            "timber_requires_wood_or_timber_process",\n        ),\n        "PLASTER": (\n            lambda: _has_any_term(p, ("plaster", "render", "mortar")),\n            "plaster_requires_plaster_render_or_mortar_process",\n        ),\n        "SOIL_EARTH": (\n            lambda: _has_any(p, ("soil", "earth", "rammed earth")) and not _has_any(p, ("pipe", "pvc", "waste", "drain", "sewer", "plumbing", "conduit")),\n            "earth_material_rejects_soil_pipe_and_non_earth_products",\n        ),\n        "SOIL_BLOCK": (\n            lambda: _has_any(p, ("soil block", "earth block", "compressed earth", "compressed soil", "ceb")) and not _has_any(p, ("aerated concrete", "autoclaved", "aac")),\n            "soil_block_requires_earthen_block_process",\n        ),\n        "PLYWOOD": (\n            lambda: _has_any(p, ("plywood", "veneer", "wood panel", "wood based panel", "wood-based panel")),\n            "plywood_requires_manufactured_wood_panel_process",\n        ),\n        "BAMBOO": (lambda: _has_term(p, "bamboo"), "bamboo_requires_bamboo_product_process"),\n    }\n    if family == "UNKNOWN":\n        return True, "unknown_family_no_high_specificity_veto"\n    rule = rules.get(family)\n    if rule is None:\n        return True, "family_without_specific_veto"\n    ok = bool(rule[0]())\n    return ok, "compatible" if ok else rule[1]\n\n\ndef external_title_compatibility(material: Any, title: Any, *, match_type: str = "DIRECT_PRODUCT", proxy_subject: str | None = None) -> tuple[bool, str]:\n    """Check whether an external EPD/literature title belongs to the requested family."""\n    family = classify_material(material)\n    t = _norm(title)\n    s = _norm(proxy_subject)\n\n    if not t:\n        return False, "external_title_blank"\n\n    # Negative context always wins for earthen materials.\n    if family in {"SOIL_EARTH", "SOIL_BLOCK"} and _has_any(t, ("pipe", "pvc", "waste pipe", "drain", "sewer", "plumbing", "conduit")):\n        return False, "earthen_material_rejects_plumbing_pipe_context"\n\n    if match_type == "DIRECT_PRODUCT":\n        checks = {\n            "CEMENT": lambda: _has_term(t, "cement")\n            and not _has_any_term(\n                t,\n                (\n                    "ready mix concrete", "ready mixed concrete", "ready-mix concrete",\n                    "ready-mixed concrete", "precast concrete", "pre cast concrete",\n                    "concrete block", "masonry block", "mortar", "clinker",\n                ),\n            ),\n            "SAND": lambda: _has_term(t, "sand"),\n            "GRAVEL_AGGREGATE": lambda: _has_any_term(t, ("gravel", "aggregate", "crushed stone")),\n            "NATURAL_STONE": lambda: _has_any_term(t, ("stone", "rock", "quarry")),\n            "REBAR": lambda: _has_any(t, (\n                "rebar", "reinforcing steel", "reinforcement steel",\n                "reinforcing bar", "reinforcement bar", "tmt bar", "tmt steel",\n            )),\n            "TIMBER": lambda: _has_any_term(t, ("timber", "wood", "lumber", "sawnwood")) and "plywood" not in t,\n            "SOIL_EARTH": lambda: _has_any(t, ("rammed earth", "earth material", "soil material", "earthen")),\n            "SOIL_BLOCK": lambda: _has_any(t, ("compressed earth block", "earth block", "soil block", "ceb")),\n            "PLYWOOD": lambda: "plywood" in t,\n            "BAMBOO": lambda: "bamboo" in t,\n            "STEEL_WIRE": lambda: _has_any(t, ("binding wire", "tie wire", "steel wire", "annealed wire")),\n            "STEEL_FASTENER": lambda: "nail" in t,\n            "GALVANIZED_FLAT_STEEL": lambda: _has_any(t, ("galvan", "zinc coat", "hot dip coat")) and _has_any(t, ("steel", "sheet", "coil")),\n            "PLAIN_CONCRETE": lambda: "concrete" in t,\n            "STONECRETE_BLOCK": lambda: _has_any(t, ("masonry block", "concrete block")),\n            "PLASTER": lambda: _has_any(t, ("plaster", "render")),\n        }\n        fn = checks.get(family)\n        if fn is None:\n            return True, "direct_title_no_specific_rule"\n        return (True, "direct_title_family_match") if fn() else (False, "direct_title_wrong_family")\n\n    # For a documented product-family proxy, require both the proxy query\n    # subject and the retrieved title to resolve to the same deterministic\n    # material family as the BOM. This is a validation rule only: it contains\n    # no source URL, factor, manufacturer, or predetermined product mapping.\n    if match_type == "PRODUCT_PROXY":\n        proxy_family = classify_material(proxy_subject)\n        title_family = classify_material(title)\n        if family == "UNKNOWN":\n            return False, "proxy_unknown_material_family"\n        if proxy_family != family:\n            return False, "proxy_query_wrong_family"\n        if title_family != family:\n            return False, "proxy_title_wrong_family"\n        return True, "proxy_title_family_match"\n\n    return False, "unknown_external_match_type"\n', 'uncertainty.py': '"""Transparent uncertainty assignment and Monte Carlo propagation for LLM-LCA.\n\nThe implementation follows a hierarchy suitable for screening LCA:\n1. source-reported quantitative uncertainty when it is explicitly supported;\n2. empirical dispersion across multiple independently accepted factors for the\n   same product/tier/reference unit;\n3. an adapted ecoinvent pedigree-matrix calculation when quantitative source\n   uncertainty is unavailable;\n4. source-supported provisional multi-source dispersion when available;\n5. otherwise a conservative adapted pedigree-matrix estimate.\n\nThe ecoinvent pedigree matrix expresses additional uncertainty as variances of\nan underlying normal distribution for lognormal data.  These variances are added\nand converted to a geometric standard deviation (GSD) with exp(sqrt(variance)).\nFor characterized construction-product factors, a small basic log-variance of\n0.0006 is used as a transparent screening minimum, adapted from the ecoinvent\nbasic uncertainty value for semi-finished products.  This is an uncertainty\nmodel for this study; it is not claimed to be uncertainty metadata supplied by\nELCD.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom dataclasses import dataclass\nfrom statistics import NormalDist\nfrom typing import Any, Iterable\n\nimport numpy as np\nimport pandas as pd\n\nUNCERTAINTY_METHOD_VERSION = "1.1"\nSTUDY_REFERENCE_YEAR = 2026\nTARGET_GEOGRAPHY = "Nepal"\nBASIC_LOG_VARIANCE = 0.0006\nMONTE_CARLO_SEED = 42\nMONTE_CARLO_SCHEDULE = (1000, 5000, 10000, 25000, 50000)\nMONTE_CARLO_MIN_FINAL_RUNS = 10000\nMONTE_CARLO_CONVERGENCE_TOLERANCE = 0.01\n\n# ecoinvent v3 Data Quality Guidelines, Table 10.5: variances of the\n# underlying normal distributions used for pedigree uncertainty.\nPEDIGREE_VARIANCES = {\n    "reliability": {1: 0.0000, 2: 0.0006, 3: 0.0020, 4: 0.0080, 5: 0.0400},\n    "completeness": {1: 0.0000, 2: 0.0001, 3: 0.0006, 4: 0.0020, 5: 0.0080},\n    "temporal": {1: 0.0000, 2: 0.0002, 3: 0.0020, 4: 0.0080, 5: 0.0400},\n    "geographical": {1: 0.0000, 2: 0.000025, 3: 0.0001, 4: 0.0006, 5: 0.0020},\n    "technological": {1: 0.0000, 2: 0.0006, 3: 0.0080, 4: 0.0400, 5: 0.1200},\n}\n\n\ndef _clean(v: Any) -> str:\n    if v is None:\n        return ""\n    try:\n        if pd.isna(v):\n            return ""\n    except Exception:\n        pass\n    return str(v).strip()\n\n\ndef _norm(v: Any) -> str:\n    return _clean(v).lower()\n\n\ndef _num(v: Any) -> float | None:\n    if v is None:\n        return None\n    try:\n        if pd.isna(v):\n            return None\n    except Exception:\n        pass\n    if isinstance(v, str) and not v.strip():\n        return None\n    try:\n        x = float(v)\n    except Exception:\n        return None\n    return x if math.isfinite(x) else None\n\n\ndef gsd_from_cv(cv: float) -> float | None:\n    """Convert coefficient of variation (fraction, not percent) to lognormal GSD."""\n    cv = float(cv)\n    if cv < 0 or not math.isfinite(cv):\n        return None\n    sigma = math.sqrt(math.log1p(cv * cv))\n    return math.exp(sigma)\n\n\ndef gsd_from_interval(lower: float, upper: float, confidence: float = 0.95) -> float | None:\n    """Derive lognormal GSD from a central multiplicative confidence interval."""\n    lower = float(lower)\n    upper = float(upper)\n    confidence = float(confidence)\n    if lower <= 0 or upper <= 0 or lower >= upper or not (0 < confidence < 1):\n        return None\n    z = NormalDist().inv_cdf((1.0 + confidence) / 2.0)\n    if z <= 0:\n        return None\n    sigma = (math.log(upper) - math.log(lower)) / (2.0 * z)\n    return math.exp(max(sigma, 0.0))\n\n\ndef gsd_from_peer_values(values: Iterable[float]) -> float | None:\n    vals = [float(v) for v in values if v is not None and float(v) > 0 and math.isfinite(float(v))]\n    if len(vals) < 2:\n        return None\n    logs = np.log(np.asarray(vals, dtype=float))\n    sigma = float(np.std(logs, ddof=1))\n    if not math.isfinite(sigma):\n        return None\n    return math.exp(max(sigma, 0.0))\n\n\ndef _parse_json_numbers(value: Any) -> list[float]:\n    if isinstance(value, (list, tuple)):\n        seq = value\n    else:\n        s = _clean(value)\n        if not s:\n            return []\n        try:\n            seq = json.loads(s)\n        except Exception:\n            return []\n    out: list[float] = []\n    for x in seq:\n        if isinstance(x, dict):\n            x = x.get("ef_value")\n        n = _num(x)\n        if n is not None and n > 0:\n            out.append(n)\n    return out\n\n\ndef _temporal_score(year: Any, study_year: int = STUDY_REFERENCE_YEAR) -> int:\n    y = _num(year)\n    if y is None:\n        return 5\n    diff = abs(int(study_year) - int(y))\n    if diff < 3:\n        return 1\n    if diff < 6:\n        return 2\n    if diff < 10:\n        return 3\n    if diff < 15:\n        return 4\n    return 5\n\n\ndef _geography_score(geography: Any, target: str = TARGET_GEOGRAPHY) -> int:\n    g = _norm(geography)\n    t = _norm(target)\n    if not g:\n        return 5\n    if t and t in g:\n        return 1\n    if "south asia" in g:\n        return 2\n    if any(x in g for x in ("india", "bangladesh", "sri lanka", "pakistan", "bhutan")):\n        return 3\n    if "asia" in g or "global" in g or "world" in g:\n        return 4\n    return 5\n\n\ndef pedigree_scores_for_row(rec: dict[str, Any]) -> tuple[dict[str, int], str]:\n    """Assign transparent pedigree scores from evidence metadata.\n\n    The mapping intentionally avoids material-specific numerical expectations.\n    It reflects evidence quality/representativeness only.\n    """\n    source = _norm(rec.get("emission_factor_source_class"))\n    verification = _norm(rec.get("emission_factor_verification"))\n    external_source_class = _norm(rec.get("external_ef_source_class"))\n    match_type = _norm(rec.get("production_match_type"))\n    external_match = _norm(rec.get("external_ef_match_type"))\n\n    relaxed_external = (source == "provisional_source_supported" or verification == "provisional_source_supported" or external_source_class == "external_verified_relaxed")\n    if relaxed_external:\n        year = rec.get("emission_factor_source_year_final") or rec.get("external_ef_source_year")\n        geography = rec.get("emission_factor_source_geography_final") or rec.get("external_ef_source_geography")\n        scores = {\n            "reliability": 4,\n            "completeness": 4,\n            "temporal": _temporal_score(year),\n            "geographical": _geography_score(geography),\n            "technological": 4,\n        }\n        return scores, (\n            "External Verified relaxed-phase factor: conservative reliability/completeness/technology "\n            "scores with temporal/geographic representativeness derived from retrieved evidence metadata."\n        )\n\n    # Reliability: verified program/database evidence is strongest; sources that\n    # are traceable but not independently program-verified are one level lower.\n    if source.startswith("database_"):\n        reliability = 2\n    elif external_source_class in {"verified_epd_program", "government", "nepal_government", "technical_lca_database"}:\n        reliability = 1\n    elif external_source_class in {"manufacturer_epd", "peer_reviewed_publication", "academic"}:\n        reliability = 2\n    else:\n        reliability = 3\n\n    # Completeness cannot usually be inferred quantitatively from web snippets.\n    # Database direct values receive score 2, proxies 3; product-specific external\n    # declarations are conservatively treated as one/few-site evidence (score 4).\n    if source == "database_direct":\n        completeness = 2\n    elif source == "database_proxy":\n        completeness = 3\n    elif source == "external_verified":\n        completeness = 4\n    else:\n        completeness = 4\n\n    year = rec.get("emission_factor_source_year_final") or rec.get("external_ef_source_year")\n    temporal = _temporal_score(year)\n\n    geography = (\n        rec.get("emission_factor_source_geography_final")\n        or rec.get("external_ef_source_geography")\n        or rec.get("production_selected_process_location")\n    )\n    geographical = _geography_score(geography)\n\n    if source == "database_direct":\n        technological = 1\n    elif source == "database_proxy":\n        technological = 3\n    elif source == "external_verified":\n        technological = 4 if external_match == "product_proxy" else 2\n    else:\n        technological = 4 if match_type == "proxy" else 3\n\n    scores = {\n        "reliability": reliability,\n        "completeness": completeness,\n        "temporal": temporal,\n        "geographical": geographical,\n        "technological": technological,\n    }\n    reason = (\n        f"Pedigree scores derived from source class={source or verification or \'unknown\'}, "\n        f"external source class={external_source_class or \'n/a\'}, year={_clean(year) or \'unknown\'}, "\n        f"geography={_clean(geography) or \'unknown\'}, process/external match={external_match or match_type or \'unknown\'}."\n    )\n    return scores, reason\n\n\ndef pedigree_gsd(scores: dict[str, int], basic_variance: float = BASIC_LOG_VARIANCE) -> tuple[float, float]:\n    variance = float(basic_variance)\n    for key in ("reliability", "completeness", "temporal", "geographical", "technological"):\n        score = int(scores[key])\n        variance += PEDIGREE_VARIANCES[key][score]\n    sigma = math.sqrt(max(variance, 0.0))\n    return math.exp(sigma), variance\n\n\ndef _factor_gsd(rec: dict[str, Any]) -> tuple[float, str, str, dict[str, int] | None]:\n    verification = _norm(rec.get("emission_factor_verification"))\n    relaxed_external = (verification == "provisional_source_supported" or _norm(rec.get("emission_factor_source_class")) == "provisional_source_supported" or _norm(rec.get("external_ef_source_class")) == "external_verified_relaxed" or _norm(rec.get("external_ef_verification_tier")) == "relaxed")\n\n    fallback_method = _norm(rec.get("emission_factor_fallback_method") or rec.get("external_ef_fallback_method"))\n    if verification in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"} or _norm(rec.get("emission_factor_source_class")) in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}:\n        lower = _num(rec.get("external_ef_lower_value"))\n        upper = _num(rec.get("external_ef_upper_value"))\n        if lower is not None and upper is not None and 0 < lower < upper:\n            gsd = gsd_from_interval(lower, upper, 0.95)\n            if gsd is not None:\n                label = "UNVERIFIED_FALLBACK_RANGE" if not fallback_method else f"UNVERIFIED_{fallback_method.upper()}_RANGE"\n                return gsd, label, "Derived lognormal GSD from the Class-4 unverified fallback envelope; this is exploratory rather than source-verified uncertainty.", None\n        scores = {"reliability": 5, "completeness": 5, "temporal": 5, "geographical": 5, "technological": 5}\n        gsd, variance = pedigree_gsd(scores)\n        return gsd, "UNVERIFIED_FALLBACK_MAX_PEDIGREE", f"No valid Class-4 fallback range was available; maximum adapted pedigree scores used, log-variance={variance:.8f}.", scores\n\n    # Explicit uncertainty extracted from a fully verified traceable source.\n    if not relaxed_external:\n        gsd = _num(rec.get("external_ef_uncertainty_gsd"))\n        if gsd is not None and gsd >= 1:\n            return gsd, "SOURCE_REPORTED_GSD", "GSD explicitly reported and verified in retrieved source evidence.", None\n\n        cv = _num(rec.get("external_ef_uncertainty_cv"))\n        if cv is not None:\n            cv_fraction = cv / 100.0 if cv > 1 else cv\n            gsd = gsd_from_cv(cv_fraction)\n            if gsd is not None:\n                return gsd, "SOURCE_REPORTED_CV", f"Converted source-reported CV={cv_fraction:.6g} to lognormal GSD.", None\n\n        lower = _num(rec.get("external_ef_uncertainty_lower_value"))\n        upper = _num(rec.get("external_ef_uncertainty_upper_value"))\n        conf = _num(rec.get("external_ef_uncertainty_confidence_level"))\n        if lower is not None and upper is not None:\n            confidence = (conf / 100.0 if conf and conf > 1 else conf) if conf is not None else 0.95\n            gsd = gsd_from_interval(lower, upper, confidence or 0.95)\n            if gsd is not None:\n                return gsd, "SOURCE_REPORTED_INTERVAL", f"Derived lognormal GSD from source-reported central {100*(confidence or 0.95):.1f}% interval.", None\n\n    # Dispersion among independently accepted/supporting source values is usable\n    # for both verified and provisional pathways because every peer value is\n    # anchored to retrieved evidence rather than model memory.\n    peers = _parse_json_numbers(rec.get("external_ef_peer_values_json"))\n    gsd = gsd_from_peer_values(peers)\n    if gsd is not None:\n        label = "RELAXED_EXTERNAL_MULTI_SOURCE_DISPERSION" if relaxed_external else "MULTI_SOURCE_DISPERSION"\n        return gsd, label, f"Calculated GSD from {len(peers)} independently retrieved factors on the same normalized reference basis.", None\n\n    scores, score_reason = pedigree_scores_for_row(rec)\n    gsd, variance = pedigree_gsd(scores)\n    return gsd, "ADAPTED_PEDIGREE_MATRIX", f"{score_reason} Combined log-variance={variance:.8f}.", scores\n\n\ndef _property_gsd(rec: dict[str, Any]) -> tuple[float, str, str]:\n    method = _norm(rec.get("conversion_method"))\n    uses_property = method in {\n        "volume_to_mass", "mass_to_volume", "mass_to_area", "mass_to_count",\n        "area_to_volume", "volume_to_area", "area_to_mass", "count_to_mass",\n    }\n    if not uses_property:\n        return 1.0, "NO_STOCHASTIC_PROPERTY", "No uncertain physical property is required by this conversion."\n\n    verification = _norm(rec.get("property_verification"))\n    if verification in {"project_or_bom", "project_input", "bom_extracted"}:\n        return 1.0, "PROJECT_OR_BOM_PROPERTY", "Project/BOM property is treated as fixed because no project-specific uncertainty was supplied."\n\n    fallback_method = _norm(rec.get("property_fallback_method_final") or rec.get("property_fallback_method"))\n    if verification in {"unverified_fallback_estimate", "llm_unverified_estimate", "conservative_analog_estimate"}:\n        lower = _num(rec.get("property_lower_value"))\n        upper = _num(rec.get("property_upper_value"))\n        if lower is not None and upper is not None and 0 < lower < upper:\n            gsd = gsd_from_interval(lower, upper, 0.95)\n            if gsd is not None:\n                label = "UNVERIFIED_FALLBACK_PROPERTY_RANGE" if not fallback_method else f"UNVERIFIED_{fallback_method.upper()}_PROPERTY_RANGE"\n                return gsd, label, "Derived property GSD from the Class-4 unverified fallback envelope; this is exploratory rather than source-verified uncertainty."\n        scores = {"reliability": 5, "completeness": 5, "temporal": 5, "geographical": 5, "technological": 5}\n        gsd, variance = pedigree_gsd(scores)\n        return gsd, "UNVERIFIED_FALLBACK_PROPERTY_MAX_PEDIGREE", f"No valid Class-4 property range was available; maximum adapted pedigree scores used, log-variance={variance:.8f}."\n\n    if verification in {"provisional_source_supported", "traceable_web_relaxed"}:\n        peers = _parse_json_numbers(rec.get("property_peer_values_json"))\n        gsd = gsd_from_peer_values(peers)\n        if gsd is not None:\n            return gsd, "RELAXED_EXTERNAL_PROPERTY_MULTI_SOURCE_DISPERSION", f"Calculated property GSD from {len(peers)} independent source-supported values."\n        temporal = _temporal_score(rec.get("property_source_year"))\n        geographical = _geography_score(rec.get("property_source_geography"))\n        scores = {\n            "reliability": 4,\n            "completeness": 4,\n            "temporal": temporal,\n            "geographical": geographical,\n            "technological": 4,\n        }\n        gsd, variance = pedigree_gsd(scores)\n        return gsd, "RELAXED_EXTERNAL_PROPERTY_ADAPTED_PEDIGREE", f"External Verified relaxed-phase property; conservative pedigree log-variance={variance:.8f}."\n\n    # Traceable web property: derive representativeness scores from its metadata.\n    temporal = _temporal_score(rec.get("property_source_year"))\n    geographical = _geography_score(rec.get("property_source_geography"))\n    scores = {\n        "reliability": 2,\n        "completeness": 4,\n        "temporal": temporal,\n        "geographical": geographical,\n        "technological": 2,\n    }\n    gsd, variance = pedigree_gsd(scores)\n    return gsd, "PROPERTY_ADAPTED_PEDIGREE", f"Traceable conversion property pedigree log-variance={variance:.8f}."\n\n\ndef enrich_row_uncertainty(results: pd.DataFrame) -> pd.DataFrame:\n    out = results.copy()\n    new_cols = [\n        "factor_uncertainty_gsd", "factor_uncertainty_method", "factor_uncertainty_reason",\n        "property_uncertainty_gsd", "property_uncertainty_method", "property_uncertainty_reason",\n        "row_uncertainty_gsd", "uncertainty_method_version",\n        "pedigree_reliability", "pedigree_completeness", "pedigree_temporal",\n        "pedigree_geographical", "pedigree_technological",\n        "gwp_p2_5", "gwp_p5", "gwp_p50", "gwp_p95", "gwp_p97_5",\n    ]\n    for c in new_cols:\n        if c not in out.columns:\n            out[c] = np.nan if c.startswith(("factor_uncertainty_gsd", "property_uncertainty_gsd", "row_uncertainty_gsd", "pedigree_", "gwp_")) else None\n\n    mask = out["calculation_status"].eq("CALCULATED")\n    for idx in out.index[mask]:\n        rec = out.loc[idx].to_dict()\n        factor_gsd, factor_method, factor_reason, scores = _factor_gsd(rec)\n        prop_gsd, prop_method, prop_reason = _property_gsd(rec)\n        sigma = math.sqrt(math.log(max(factor_gsd, 1.0)) ** 2 + math.log(max(prop_gsd, 1.0)) ** 2)\n        row_gsd = math.exp(sigma)\n        point = float(out.at[idx, "gwp_total"])\n        q = [math.exp(z * sigma) for z in (-1.959963984540054, -1.6448536269514722, 0.0, 1.6448536269514722, 1.959963984540054)]\n        vals = [point * m for m in q]\n\n        out.at[idx, "factor_uncertainty_gsd"] = factor_gsd\n        out.at[idx, "factor_uncertainty_method"] = factor_method\n        out.at[idx, "factor_uncertainty_reason"] = factor_reason\n        out.at[idx, "property_uncertainty_gsd"] = prop_gsd\n        out.at[idx, "property_uncertainty_method"] = prop_method\n        out.at[idx, "property_uncertainty_reason"] = prop_reason\n        out.at[idx, "row_uncertainty_gsd"] = row_gsd\n        out.at[idx, "uncertainty_method_version"] = UNCERTAINTY_METHOD_VERSION\n        if scores:\n            out.at[idx, "pedigree_reliability"] = scores["reliability"]\n            out.at[idx, "pedigree_completeness"] = scores["completeness"]\n            out.at[idx, "pedigree_temporal"] = scores["temporal"]\n            out.at[idx, "pedigree_geographical"] = scores["geographical"]\n            out.at[idx, "pedigree_technological"] = scores["technological"]\n        for c, v in zip(("gwp_p2_5", "gwp_p5", "gwp_p50", "gwp_p95", "gwp_p97_5"), vals):\n            out.at[idx, c] = v\n    return out\n\n\ndef _scope_stats(draws: np.ndarray, point: float, scope: str, n: int) -> dict[str, Any]:\n    q = np.percentile(draws[:n], [2.5, 5, 50, 95, 97.5])\n    return {\n        "scope": scope,\n        "point_estimate": float(point),\n        "mean": float(np.mean(draws[:n])),\n        "p2_5": float(q[0]),\n        "p5": float(q[1]),\n        "median": float(q[2]),\n        "p95": float(q[3]),\n        "p97_5": float(q[4]),\n    }\n\n\ndef _relative_change(a: float, b: float) -> float:\n    denom = max(abs(float(b)), 1e-12)\n    return abs(float(a) - float(b)) / denom\n\n\ndef monte_carlo_with_convergence(results: pd.DataFrame):\n    """Run reproducible row-specific lognormal Monte Carlo with convergence.\n\n    Returns ``(summary_df, convergence_df, raw_draws_df)``. Factor and physical-\n    property uncertainty are sampled independently in log space.  The raw table\n    stores, for every run and calculated BOM row, the sampled emission factor,\n    sampled quantity in the factor reference unit, and resulting line-item GWP.\n    This makes every value entering every Monte Carlo building total auditable.\n\n    One seeded random stream is generated up to the maximum schedule size and\n    smaller convergence trials use deterministic prefixes of that same stream.\n    """\n    calc = results[results["calculation_status"] == "CALCULATED"].copy()\n    if calc.empty:\n        empty_summary = pd.DataFrame(columns=[\n            "scope", "point_estimate", "mean", "p2_5", "p5", "median", "p95", "p97_5",\n            "simulations", "seed", "converged", "convergence_tolerance",\n        ])\n        return empty_summary, pd.DataFrame(), pd.DataFrame()\n\n    points = calc["gwp_total"].astype(float).to_numpy()\n    base_efs = calc["emission_factor_per_reference_unit"].astype(float).to_numpy()\n    base_qty = calc["quantity_in_reference_unit"].astype(float).to_numpy()\n    factor_sigmas = np.log(calc["factor_uncertainty_gsd"].astype(float).clip(lower=1.0).to_numpy())\n    property_sigmas = np.log(calc["property_uncertainty_gsd"].astype(float).clip(lower=1.0).to_numpy())\n\n    max_n = max(MONTE_CARLO_SCHEDULE)\n    rng = np.random.default_rng(MONTE_CARLO_SEED)\n    # Independent factor/property draws.  Their product is equivalent to the\n    # combined row-level lognormal variance used for analytical row quantiles.\n    z_factor = rng.standard_normal(size=(max_n, len(calc)))\n    z_property = rng.standard_normal(size=(max_n, len(calc)))\n    factor_multiplier = np.exp(z_factor * factor_sigmas[None, :])\n    property_multiplier = np.exp(z_property * property_sigmas[None, :])\n    sampled_ef = base_efs[None, :] * factor_multiplier\n    sampled_qty = base_qty[None, :] * property_multiplier\n    sampled_rows = sampled_ef * sampled_qty\n\n    def _bool_mask(name: str, default: bool) -> np.ndarray:\n        series = calc[name] if name in calc.columns else pd.Series(default, index=calc.index)\n        vals = []\n        for v in series.tolist():\n            if isinstance(v, (bool, np.bool_)):\n                vals.append(bool(v))\n            elif v is None or (isinstance(v, float) and math.isnan(v)):\n                vals.append(default)\n            else:\n                vals.append(str(v).strip().lower() in {"1", "true", "yes", "y"})\n        return np.asarray(vals, dtype=bool)\n\n    verified_mask = _bool_mask("included_in_verified_calculation", False)\n    exploratory_mask = _bool_mask("included_in_complete_exploratory_screening", True)\n    verified_total = sampled_rows[:, verified_mask].sum(axis=1) if verified_mask.any() else np.zeros(max_n)\n    exploratory_total = sampled_rows[:, exploratory_mask].sum(axis=1) if exploratory_mask.any() else np.zeros(max_n)\n    verified_point = float(points[verified_mask].sum()) if verified_mask.any() else 0.0\n    exploratory_point = float(points[exploratory_mask].sum()) if exploratory_mask.any() else 0.0\n    exploratory_complete = bool(results.get("calculation_status", pd.Series(index=results.index, dtype=str)).eq("CALCULATED").all())\n    exploratory_scope = "Complete exploratory GWP (classes 1-4)" if exploratory_complete else "Exploratory GWP subtotal (input/model failures remain)"\n\n    convergence_rows: list[dict[str, Any]] = []\n    prev_by_scope: dict[str, dict[str, Any]] = {}\n    selected_n = max_n\n    converged = False\n    for n in MONTE_CARLO_SCHEDULE:\n        scopes = [\n            _scope_stats(verified_total, verified_point, "Verified A1-A3 GWP (classes 1-3)", n),\n            _scope_stats(exploratory_total, exploratory_point, exploratory_scope, n),\n        ]\n        max_change = 0.0\n        have_previous = True\n        for st in scopes:\n            prev = prev_by_scope.get(st["scope"])\n            if prev is None:\n                have_previous = False\n                change = None\n            else:\n                change = max(\n                    _relative_change(st["p2_5"], prev["p2_5"]),\n                    _relative_change(st["median"], prev["median"]),\n                    _relative_change(st["p97_5"], prev["p97_5"]),\n                )\n                max_change = max(max_change, change)\n            convergence_rows.append({\n                "scope": st["scope"],\n                "simulations": n,\n                "p2_5": st["p2_5"],\n                "median": st["median"],\n                "p97_5": st["p97_5"],\n                "max_relative_change_vs_previous": change,\n            })\n            prev_by_scope[st["scope"]] = st\n        if have_previous and n >= MONTE_CARLO_MIN_FINAL_RUNS and max_change <= MONTE_CARLO_CONVERGENCE_TOLERANCE:\n            selected_n = n\n            converged = True\n            break\n\n    summary_rows = []\n    for draws, point, scope in [\n        (verified_total, verified_point, "Verified A1-A3 GWP (classes 1-3)"),\n        (exploratory_total, exploratory_point, exploratory_scope),\n    ]:\n        st = _scope_stats(draws, point, scope, selected_n)\n        st.update({\n            "simulations": selected_n,\n            "seed": MONTE_CARLO_SEED,\n            "converged": converged,\n            "convergence_tolerance": MONTE_CARLO_CONVERGENCE_TOLERANCE,\n        })\n        summary_rows.append(st)\n\n    # Stable short labels based on item ID; duplicate IDs are disambiguated\n    # deterministically.  Three columns per row expose the exact MC inputs and\n    # output contribution: sampled EF, sampled reference quantity, sampled GWP.\n    labels: list[str] = []\n    used: dict[str, int] = {}\n    for i, (_, rec) in enumerate(calc.iterrows(), start=1):\n        raw_label = _clean(rec.get("item_id") or rec.get("ID") or f"row{i}")\n        label = "item_" + "".join(ch if ch.isalnum() or ch in "_-" else "_" for ch in raw_label)[:40]\n        used[label] = used.get(label, 0) + 1\n        if used[label] > 1:\n            label = f"{label}_{used[label]}"\n        labels.append(label)\n\n    raw = pd.DataFrame({"run": np.arange(1, selected_n + 1)})\n    for j, label in enumerate(labels):\n        raw[f"{label}__ef"] = sampled_ef[:selected_n, j]\n        raw[f"{label}__quantity_ref"] = sampled_qty[:selected_n, j]\n        raw[f"{label}__gwp"] = sampled_rows[:selected_n, j]\n    raw["verified_total_gwp"] = verified_total[:selected_n]\n    raw["complete_exploratory_total_gwp"] = exploratory_total[:selected_n]\n\n    return pd.DataFrame(summary_rows), pd.DataFrame(convergence_rows), raw\n', 'guardrails.py': '"""Material-agnostic structural validation for exploratory LCA fallbacks.\n\nThis module deliberately contains NO material names, material-family GWP caps,\ndensity ranges, item-mass ranges, or prescribed environmental/property values.\nIt validates only universal structure: finite positive numbers, supported units,\nand internally ordered uncertainty intervals.\n\nNo material-specific numerical magnitude prior is used for terminal model-only\nestimates. Evidence-supported rows are controlled by retrieved-source validation,\nand database-anchored Class-4 rows use frozen snapshot factors. A terminal model\nnumber, when all anchored routes fail, remains explicitly unverified and is gated\nonly by universal numeric/unit structure plus deterministic product identity.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom typing import Any\n\nfrom unit_conversion import norm_unit\n\nGUARDRAIL_VERSION = "2.1-material-agnostic-no-terminal-consensus"\n\n_SUPPORTED_FACTOR_UNITS = {"kg", "g", "t", "m3", "l", "cm3", "m2", "cm2", "mm2", "item", "kwh", "mj"}\n\n\ndef emission_factor_cap(material: Any, reference_unit: Any) -> None:\n    """Compatibility shim: no material-specific numerical cap exists."""\n    return None\n\n\ndef emission_factor_plausible(\n    material: Any,\n    value: Any,\n    reference_unit: Any,\n    lower: Any = None,\n    upper: Any = None,\n) -> tuple[bool, str]:\n    try:\n        value = float(value)\n    except Exception:\n        return False, "factor_not_numeric"\n    if not math.isfinite(value) or value <= 0:\n        return False, "factor_must_be_finite_and_positive"\n    ref = norm_unit(reference_unit)\n    if ref not in _SUPPORTED_FACTOR_UNITS:\n        return False, f"unsupported_reference_unit:{ref or \'blank\'}"\n\n    lo = None if lower is None else float(lower)\n    hi = None if upper is None else float(upper)\n    if lo is not None and (not math.isfinite(lo) or lo <= 0 or lo >= value):\n        return False, "invalid_lower_bound"\n    if hi is not None and (not math.isfinite(hi) or hi <= value):\n        return False, "invalid_upper_bound"\n    if lo is not None and hi is not None and hi <= lo:\n        return False, "invalid_uncertainty_interval"\n    return True, "ok"\n\n\ndef emission_guardrail_context(material: Any, reference_unit: Any) -> dict[str, Any]:\n    return {\n        "reference_unit": norm_unit(reference_unit),\n        "material_specific_numeric_limits_used": False,\n        "validation_role": "structure/unit validation only; no material-specific numerical magnitude prior",\n    }\n\n\ndef property_range(material: Any, kind: str) -> None:\n    """Compatibility shim: no material-specific physical-property range exists."""\n    return None\n\n\ndef property_plausible(\n    material: Any,\n    kind: str,\n    value: Any,\n    lower: Any = None,\n    upper: Any = None,\n) -> tuple[bool, str]:\n    try:\n        value = float(value)\n    except Exception:\n        return False, "property_not_numeric"\n    if not math.isfinite(value) or value <= 0:\n        return False, "property_must_be_finite_and_positive"\n    lo = None if lower is None else float(lower)\n    hi = None if upper is None else float(upper)\n    if lo is not None and (not math.isfinite(lo) or lo <= 0 or lo >= value):\n        return False, "invalid_property_lower_bound"\n    if hi is not None and (not math.isfinite(hi) or hi <= value):\n        return False, "invalid_property_upper_bound"\n    if lo is not None and hi is not None and hi <= lo:\n        return False, "invalid_property_uncertainty_interval"\n    return True, "ok"\n\n\ndef property_guardrail_context(material: Any, kind: str) -> dict[str, Any]:\n    return {\n        "requested_property": kind,\n        "material_specific_numeric_limits_used": False,\n        "validation_role": "structure/unit validation only; no material-specific numerical magnitude prior",\n    }\n', 'evidence_consensus.py': '"""Robust consensus utilities for source-supported provisional evidence.\n\nThe functions in this module are intentionally material-agnostic. They never\nencode expected embodied-carbon factors, densities, or product-specific values.\nThey only combine positive numerical observations that have already been\nextracted from retrieved evidence and passed the relevant identity/unit checks.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nimport math\nfrom typing import Iterable, Sequence\n\nimport numpy as np\n\nCONSENSUS_METHOD_VERSION = "1.0"\nMODIFIED_Z_THRESHOLD = 3.5\n\n\n@dataclass(frozen=True)\nclass ConsensusResult:\n    central_value: float\n    retained_indices: tuple[int, ...]\n    outlier_indices: tuple[int, ...]\n    method: str\n    input_count: int\n    retained_count: int\n\n\ndef _positive_finite(values: Sequence[float]) -> tuple[list[float], list[int]]:\n    clean: list[float] = []\n    original_indices: list[int] = []\n    for i, raw in enumerate(values):\n        try:\n            value = float(raw)\n        except Exception:\n            continue\n        if math.isfinite(value) and value > 0:\n            clean.append(value)\n            original_indices.append(i)\n    return clean, original_indices\n\n\ndef robust_positive_consensus(values: Sequence[float]) -> ConsensusResult | None:\n    """Return a median-based consensus with log-space robust outlier filtering.\n\n    No material-specific plausibility range is used. Outliers are identified\n    only from disagreement within the retrieved evidence itself.\n\n    Rules:\n    - one observation -> use that source-supported value;\n    - two observations -> use their ordinary median, no outlier claim;\n    - three or more -> use modified z-scores in log space (MAD); when MAD is\n      exactly zero because a majority of observations are identical, retain the\n      repeated consensus values and flag disagreeing observations.\n    - filtering is abandoned if it would leave fewer than two observations in a\n      multi-source set; this avoids manufacturing consensus from one surviving\n      point.\n    """\n    clean, original_indices = _positive_finite(values)\n    n = len(clean)\n    if n == 0:\n        return None\n    if n == 1:\n        return ConsensusResult(\n            central_value=float(clean[0]),\n            retained_indices=(original_indices[0],),\n            outlier_indices=(),\n            method="SINGLE_SOURCE_MEDIAN",\n            input_count=1,\n            retained_count=1,\n        )\n\n    arr = np.asarray(clean, dtype=float)\n    keep = np.ones(n, dtype=bool)\n    method = "MULTI_SOURCE_MEDIAN_NO_OUTLIER_FILTER"\n\n    if n >= 3:\n        logs = np.log(arr)\n        med = float(np.median(logs))\n        abs_dev = np.abs(logs - med)\n        mad = float(np.median(abs_dev))\n        eps = 1e-12\n        if mad > eps:\n            modified_z = 0.6744897501960817 * abs_dev / mad\n            candidate_keep = modified_z <= MODIFIED_Z_THRESHOLD\n            if int(candidate_keep.sum()) >= 2:\n                keep = candidate_keep\n                method = "LOG_MAD_FILTERED_MEDIAN"\n        else:\n            # A zero MAD means at least half the observations sit exactly on the\n            # log-median. When two or more observations form that repeated\n            # consensus and other values disagree, the disagreeing values are\n            # source-set outliers. If all observations are essentially equal,\n            # keep everything.\n            consensus_mask = abs_dev <= eps\n            if int(consensus_mask.sum()) >= 2 and int(consensus_mask.sum()) < n:\n                keep = consensus_mask\n                method = "REPEATED_MEDIAN_FILTERED"\n            else:\n                method = "MULTI_SOURCE_MEDIAN_ZERO_MAD"\n\n    retained_local = np.where(keep)[0].tolist()\n    if n >= 2 and len(retained_local) < 2:\n        retained_local = list(range(n))\n        keep = np.ones(n, dtype=bool)\n        method = "MULTI_SOURCE_MEDIAN_FILTER_ABORTED"\n\n    retained_values = arr[keep]\n    central = float(np.median(retained_values))\n    retained_original = tuple(original_indices[i] for i in retained_local)\n    outlier_original = tuple(\n        original_indices[i] for i in range(n) if not bool(keep[i])\n    )\n    return ConsensusResult(\n        central_value=central,\n        retained_indices=retained_original,\n        outlier_indices=outlier_original,\n        method=method,\n        input_count=n,\n        retained_count=len(retained_original),\n    )\n\n\ndef canonical_factor_basis(value: float, reference_unit: str) -> tuple[float, str] | None:\n    """Canonicalize mass-reference emission factors for evidence comparison.\n\n    The returned value is still kg CO2e per returned reference unit. Non-mass\n    reference units are left unchanged. This conversion is dimensional only and\n    contains no material-specific assumptions.\n    """\n    try:\n        value = float(value)\n    except Exception:\n        return None\n    if not math.isfinite(value) or value <= 0:\n        return None\n    u = str(reference_unit or "").strip().lower().replace("³", "3").replace("²", "2")\n    aliases = {"ton": "t", "tonne": "t", "metrictonne": "t", "unit": "item", "piece": "item", "each": "item"}\n    u = aliases.get(u, u)\n    if u == "t":\n        return value / 1000.0, "kg"\n    if u == "g":\n        return value * 1000.0, "kg"\n    if u in {"kg", "m3", "m2", "item"}:\n        return value, u\n    return None\n\n# Material-agnostic ensemble settings for model-only fallback estimates.\n# These are global statistical criteria, not material-specific environmental or\n# physical-property limits.\nMODEL_ENSEMBLE_SIZE = 5\nMODEL_ENSEMBLE_MIN_AGREEMENT = 3\nMODEL_ENSEMBLE_MAX_RETAINED_RATIO = 4.0\nMODEL_ENSEMBLE_METHOD_VERSION = "1.0"\n\n\n@dataclass(frozen=True)\nclass EnsembleConsensusResult:\n    accepted: bool\n    central_value: float | None\n    retained_indices: tuple[int, ...]\n    outlier_indices: tuple[int, ...]\n    method: str\n    input_count: int\n    retained_count: int\n    retained_ratio: float | None\n    reason: str\n\n\ndef robust_model_ensemble_consensus(\n    values: Sequence[float],\n    *,\n    min_agreement: int = MODEL_ENSEMBLE_MIN_AGREEMENT,\n    max_retained_ratio: float = MODEL_ENSEMBLE_MAX_RETAINED_RATIO,\n) -> EnsembleConsensusResult:\n    """Consensus gate for five model-generated candidates, with no material priors.\n\n    The calculation is performed in log space so multiplicative disagreement is\n    treated symmetrically. First, modified-z/MAD filtering removes clear outliers.\n    If the retained set is still too dispersed, the tightest contiguous cluster\n    containing at least ``min_agreement`` estimates is examined. A consensus is\n    accepted only when at least the requested number agree within the same global\n    multiplicative spread. No GWP, density, thickness, or item-mass value is\n    encoded here.\n    """\n    clean, original_indices = _positive_finite(values)\n    n = len(clean)\n    if n < min_agreement:\n        return EnsembleConsensusResult(False, None, (), tuple(original_indices),\n            "INSUFFICIENT_VALID_CANDIDATES", n, 0, None,\n            f"need_at_least_{min_agreement}_positive_finite_candidates")\n\n    arr = np.asarray(clean, dtype=float)\n    logs = np.log(arr)\n    med = float(np.median(logs))\n    abs_dev = np.abs(logs - med)\n    mad = float(np.median(abs_dev))\n    keep = np.ones(n, dtype=bool)\n    method = "LOG_MAD"\n    eps = 1e-12\n    if mad > eps:\n        modified_z = 0.6744897501960817 * abs_dev / mad\n        keep = modified_z <= MODIFIED_Z_THRESHOLD\n    else:\n        same = abs_dev <= eps\n        if int(same.sum()) >= min_agreement:\n            keep = same\n            method = "REPEATED_LOG_MEDIAN"\n\n    def _ratio(indices: list[int]) -> float:\n        vals = arr[indices]\n        return float(vals.max() / vals.min()) if len(vals) else math.inf\n\n    retained_local = np.where(keep)[0].tolist()\n    ratio = _ratio(retained_local) if retained_local else math.inf\n\n    # If the first robust pass is too small or too dispersed, find the tightest\n    # multiplicative cluster of >= min_agreement candidates. This catches cases\n    # such as [0.3, 0.4, 0.5, 100, 300] without any material-specific ceiling.\n    if len(retained_local) < min_agreement or ratio > max_retained_ratio:\n        order = np.argsort(arr)\n        best: tuple[float, list[int]] | None = None\n        for width in range(min_agreement, n + 1):\n            for start in range(0, n - width + 1):\n                idx = order[start:start + width].tolist()\n                r = _ratio(idx)\n                if best is None or r < best[0] or (math.isclose(r, best[0]) and len(idx) > len(best[1])):\n                    best = (r, idx)\n        if best is not None and best[0] <= max_retained_ratio:\n            ratio, retained_local = best\n            method = "TIGHTEST_LOG_CLUSTER"\n        else:\n            return EnsembleConsensusResult(False, None, (), tuple(original_indices),\n                "NO_COHERENT_CLUSTER", n, 0,\n                None if best is None else float(best[0]),\n                f"no_{min_agreement}_candidate_cluster_within_{max_retained_ratio:g}x_spread")\n\n    retained_set = set(retained_local)\n    retained_original = tuple(original_indices[i] for i in retained_local)\n    outlier_original = tuple(original_indices[i] for i in range(n) if i not in retained_set)\n    central = float(np.median(arr[retained_local]))\n    return EnsembleConsensusResult(True, central, retained_original, outlier_original,\n        method, n, len(retained_original), float(ratio), "ok")\n', 'semantic_analog.py': '"""Dynamic semantic analog planning with no material lookup table.\n\nThe LLM derives the technical family and nearby analog products from the BOM text\nat run time.  This module contains no material names, family mappings, densities,\nor emission factors.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom typing import Any\n\nSEMANTIC_ANALOG_VERSION = "1.0"\nANALOG_COUNT = 5\n\nANALOG_PLAN_SYSTEM_PROMPT = """You are a construction-material semantic analog planner.\n\nDo NOT provide any GWP, density, mass, thickness, or other numerical property.\nGiven the requested material and the estimation target, infer its broad technical\nfamily from composition, manufacturing process, physical form, and construction\nfunction. Then propose exactly five distinct nearby analog products, ordered from\nmost technically similar to broader-but-still-defensible.\n\nImportant rules:\n1. Derive the family from the supplied material description at run time. Do not\n   assume a fixed lookup table.\n2. Prefer the exact product family first. If exact-product knowledge is sparse,\n   move only one semantic level broader at a time.\n3. Analog choices should preserve the dominant material chemistry/manufacturing\n   route and construction function as far as possible.\n4. Do not invent sources or numerical values.\n5. Return JSON only with exactly these keys:\nfamily_description, analogs\n6. analogs must contain exactly five objects, each with exactly:\nanalog_material, similarity_basis\n"""\n\n\ndef _parse_json(raw: str) -> dict[str, Any] | None:\n    try:\n        obj = json.loads((raw or "").strip())\n        return obj if isinstance(obj, dict) else None\n    except Exception:\n        m = re.search(r"\\{.*\\}", raw or "", flags=re.S)\n        if not m:\n            return None\n        try:\n            obj = json.loads(m.group(0))\n            return obj if isinstance(obj, dict) else None\n        except Exception:\n            return None\n\n\ndef infer_analog_plan(matcher, *, material: str, estimation_target: str, target_context: str, feedback: str | None = None) -> dict[str, Any] | None:\n    payload = {\n        "material": material,\n        "estimation_target": estimation_target,\n        "target_context": target_context,\n        "required_analog_count": ANALOG_COUNT,\n        "previous_consensus_feedback": feedback,\n    }\n    try:\n        raw = matcher.generate_with_system(\n            ANALOG_PLAN_SYSTEM_PROMPT, payload, max_new_tokens_override=512\n        )\n    except TypeError:\n        # Compatibility with lightweight test/mocked matchers.\n        raw = matcher.generate_with_system(ANALOG_PLAN_SYSTEM_PROMPT, payload)\n    obj = _parse_json(raw)\n    if not isinstance(obj, dict) or set(obj.keys()) != {"family_description", "analogs"}:\n        return None\n    family = str(obj.get("family_description") or "").strip()\n    analogs = obj.get("analogs")\n    if not family or not isinstance(analogs, list) or len(analogs) != ANALOG_COUNT:\n        return None\n    cleaned = []\n    seen = set()\n    for a in analogs:\n        if not isinstance(a, dict) or set(a.keys()) != {"analog_material", "similarity_basis"}:\n            return None\n        name = str(a.get("analog_material") or "").strip()\n        basis = str(a.get("similarity_basis") or "").strip()\n        key = name.lower()\n        if not name or not basis or key in seen:\n            return None\n        seen.add(key)\n        cleaned.append({"analog_material": name, "similarity_basis": basis})\n    return {"family_description": family, "analogs": cleaned, "raw_model_output": raw}\n', 'technical_equivalence.py': '"""Dynamic technical-equivalence search planning.\n\nThis module helps the relaxed phase of Class 3 broaden live searches when exact wording does not find\nusable evidence.  It never returns GWP factors, densities, thicknesses, item\nmasses, source URLs, EPD IDs, or other numerical environmental/property values.\nAll returned search terms are checked against the deterministic material family\nbefore they are allowed to drive a relaxed Class-3 product-proxy search.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom typing import Any\n\nfrom material_taxonomy import classify_material, process_compatibility\n\nTECHNICAL_EQUIVALENCE_VERSION = "1.1-production-compatibility-filter"\n\nTECHNICAL_EQUIVALENCE_SYSTEM_PROMPT = """You are a construction-product terminology planner for evidence retrieval.\n\nYour task is ONLY to propose alternative technical names that may be used by EPDs,\nLCA studies, standards, or manufacturers for the SAME construction-product family.\nDo not provide any environmental factor, density, thickness, mass, unit conversion,\nprice, source, citation, URL, publication, manufacturer, or numerical property.\n\nRules:\n1. Preserve the requested product\'s dominant material chemistry, manufacturing route,\n   physical form, and construction function.\n2. Different wording is allowed. A broader product description is allowed only when\n   it remains in the same technical product family and is a defensible relaxed Class-3 proxy.\n3. Do not jump to a constituent, downstream product, or unrelated material family.\n4. Return concise search terminology, not explanations or sources.\n5. Return JSON only with exactly these keys: normalized_product, search_terms.\n6. search_terms must be a list of objects with exactly: term, equivalence_basis.\n"""\n\n\ndef _parse_json(raw: str) -> dict[str, Any] | None:\n    try:\n        obj = json.loads((raw or "").strip())\n        return obj if isinstance(obj, dict) else None\n    except Exception:\n        m = re.search(r"\\{.*\\}", raw or "", flags=re.S)\n        if not m:\n            return None\n        try:\n            obj = json.loads(m.group(0))\n            return obj if isinstance(obj, dict) else None\n        except Exception:\n            return None\n\n\ndef infer_technical_equivalents(matcher, *, material: str, target_context: str) -> dict[str, Any] | None:\n    payload = {\n        "material": material,\n        "target_context": target_context,\n        "purpose": "relaxed Class-3 external-verified EPD/LCA search terminology only",\n    }\n    try:\n        raw = matcher.generate_with_system(\n            TECHNICAL_EQUIVALENCE_SYSTEM_PROMPT, payload, max_new_tokens_override=420\n        )\n    except TypeError:\n        raw = matcher.generate_with_system(TECHNICAL_EQUIVALENCE_SYSTEM_PROMPT, payload)\n    obj = _parse_json(raw)\n    if not isinstance(obj, dict) or set(obj.keys()) != {"normalized_product", "search_terms"}:\n        return None\n    normalized = str(obj.get("normalized_product") or "").strip()\n    terms = obj.get("search_terms")\n    if not normalized or not isinstance(terms, list):\n        return None\n\n    requested_family = classify_material(material)\n    cleaned = []\n    seen = set()\n    for rec in terms:\n        if not isinstance(rec, dict) or set(rec.keys()) != {"term", "equivalence_basis"}:\n            continue\n        term = str(rec.get("term") or "").strip()\n        basis = str(rec.get("equivalence_basis") or "").strip()\n        key = term.lower()\n        if not term or not basis or key in seen:\n            continue\n        # Known materials may use a terminology/proxy phrase that is broader than\n        # the taxonomy label as long as the existing deterministic production\n        # compatibility gate still considers it technically defensible.  This is\n        # semantic validation only; no emission factor or property is encoded.\n        if requested_family == "UNKNOWN":\n            continue\n        compatible, _ = process_compatibility(material, term)\n        if not compatible:\n            continue\n        seen.add(key)\n        cleaned.append({"term": term, "equivalence_basis": basis})\n    if not cleaned:\n        return None\n    return {\n        "normalized_product": normalized,\n        "search_terms": cleaned,\n        "raw_model_output": raw,\n        "version": TECHNICAL_EQUIVALENCE_VERSION,\n    }\n', 'evidence_cache.py': '"""Runtime evidence cache for retrieved Class-3 strict/relaxed external evidence.\n\nThe cache is deliberately empty in the repository and is populated only from\nsuccessfully resolved live evidence during a run. It contains no predefined GWP,\ndensity, thickness, mass-per-item value, source URL, or material-to-analog mapping.\n\nCache keys include the target geography so a result previously accepted for one\nstudy geography cannot silently become Class 3 in another geography.\n"""\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nimport json\nimport os\nfrom pathlib import Path\nimport re\nfrom typing import Any\n\nCACHE_VERSION = "2.0-policy-versioned-runtime-evidence"\n\n\ndef _norm(text: Any) -> str:\n    return re.sub(r"\\s+", " ", str(text or "").strip().lower())\n\n\nclass RuntimeEvidenceCache:\n    def __init__(self, path: str | os.PathLike | None = None):\n        default = os.environ.get("LLM_LCA_EVIDENCE_CACHE", "")\n        self.path = Path(path or default) if (path or default) else None\n        self._records: dict[str, dict[str, Any]] = {}\n        if self.path:\n            self.path.parent.mkdir(parents=True, exist_ok=True)\n            self._load()\n\n    def _load(self) -> None:\n        if not self.path or not self.path.exists():\n            return\n        try:\n            obj = json.loads(self.path.read_text(encoding="utf-8"))\n            # Never reuse evidence accepted under an older validation policy.\n            # A code update can tighten indicator/product-identity rules, so stale\n            # cached rows must be re-resolved rather than silently bypassing them.\n            if not isinstance(obj, dict) or obj.get("cache_version") != CACHE_VERSION:\n                self._records = {}\n                return\n            if isinstance(obj.get("records"), dict):\n                self._records = obj["records"]\n        except Exception:\n            # A damaged cache must never stop a calculation.\n            self._records = {}\n\n    def _save(self) -> None:\n        if not self.path:\n            return\n        payload = {\n            "cache_version": CACHE_VERSION,\n            "updated_at_utc": datetime.now(timezone.utc).isoformat(),\n            "records": self._records,\n        }\n        tmp = self.path.with_suffix(self.path.suffix + ".tmp")\n        def _default(obj):\n            if hasattr(obj, "item"):\n                try:\n                    return obj.item()\n                except Exception:\n                    pass\n            if isinstance(obj, Path):\n                return str(obj)\n            return str(obj)\n        tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2, default=_default), encoding="utf-8")\n        tmp.replace(self.path)\n\n    @staticmethod\n    def key(*, category: str, material: str, target_geography: str, property_kind: str = "") -> str:\n        return "|".join([\n            _norm(category), _norm(target_geography), _norm(material), _norm(property_kind)\n        ])\n\n    def get(self, *, category: str, material: str, target_geography: str, property_kind: str = "") -> dict[str, Any] | None:\n        k = self.key(category=category, material=material, target_geography=target_geography, property_kind=property_kind)\n        rec = self._records.get(k)\n        return dict(rec.get("resolved", {})) if isinstance(rec, dict) and isinstance(rec.get("resolved"), dict) else None\n\n    def put(self, *, category: str, material: str, target_geography: str, resolved: dict[str, Any], property_kind: str = "") -> None:\n        k = self.key(category=category, material=material, target_geography=target_geography, property_kind=property_kind)\n        self._records[k] = {\n            "saved_at_utc": datetime.now(timezone.utc).isoformat(),\n            "category": category,\n            "target_geography": target_geography,\n            "material": material,\n            "property_kind": property_kind,\n            "resolved": dict(resolved),\n        }\n        self._save()\n\n    def count(self) -> int:\n        return len(self._records)\n', 'qwen_matcher.py': '"""Qwen-only material normalization and ELCD/openLCA process matching.\n\nThe raw ELCD matching stage is benchmark-locked and model-led. A deterministic\nTF-IDF retriever uses the exact benchmark algorithm on the final frozen ELCD snapshot,\nand Qwen alone returns the benchmarked Direct, Proxy, or Review Required label.\nThe raw Qwen fields are never rewritten by calculation, density, or fallback logic.\n\nPython applies the exact benchmark v2.3.0 schema/candidate validation. The ELCD data may be freshly exported once and hash-frozen; all matching-protocol settings remain identical. Production\nthen has a separate post-Qwen product-family veto that may reject an obviously\nincompatible selected process for numerical use; this affects only production_*\nfields and never changes the raw benchmark decision. The matching class performs\nno LCIA. External evidence and fallback resolution occur afterward.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport random\nimport re\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.feature_extraction.text import TfidfVectorizer\n\nfrom material_taxonomy import MATERIAL_TAXONOMY_VERSION, process_compatibility\nfrom catalog_lock import verify_lock\n\nMODEL_ID = "Qwen/Qwen2.5-7B-Instruct"\nMODEL_REVISION = "a09a35458c702b33eeacc393d103063234e8bc28"\nPRODUCTION_PROMPT_VERSION = "4.0-exact-benchmark-protocol"\nBENCHMARK_SCRIPT_VERSION = "2.3.0"\nBENCHMARK_SEED = 42\nBENCHMARK_CANDIDATE_POOL_SIZE = 5\nBENCHMARK_TOP_K = 3\nBENCHMARK_MAX_NEW_TOKENS = 256\nHISTORICAL_BENCHMARK_CATALOG_CONTENT_SHA256 = "ffd076b115f91042921f82130e426da9d29d684b23ff102ef3e185b34c83d5eb"\nBENCHMARK_SYSTEM_PROMPT_SHA256 = "e0ae559d973576c0fb625723f4fec6d75575c791d24f34bea7a073c51790ac70"\n# Qwen\'s raw benchmark decision is preserved unchanged. This downstream gate may\n# veto a clearly incompatible product family, but it never rewrites the raw Qwen\n# Direct/Proxy/Review Required fields or chooses a replacement process.\nSAFETY_GATE_VERSION = "post-qwen-family-veto-2.0"\nREFERENCE_MAP_VERSION = "1.0"\n\nSYSTEM_PROMPT = """You are an LCA material-normalization and ELCD process-matching evaluator for A1-A3 screening.\n\nYour task is limited to material interpretation and process matching. Do NOT calculate embodied carbon and do NOT generate emission factors, GWP values, EPDs, citations, or process UUIDs. Use only the supplied candidate UUIDs.\n\nStudy definitions:\n- direct: a supplied ELCD process sufficiently represents the BOM material/product.\n- proxy: a supplied ELCD process is the best technically defensible substitute when an exact/direct representation is unavailable.\n- review_required: none of the supplied ELCD candidates is defensible enough to select. Use this only for an unmatched material.\n\nRules:\n1. Normalize the BOM description to a concise engineering material name.\n2. Rank at most the requested number of candidate UUIDs, best first.\n3. For direct or proxy, ranked_process_uuids must contain at least one supplied UUID; the first UUID is the final selected process.\n4. For review_required, ranked_process_uuids must be an empty list.\n5. Do not return process names, rationales, confidence scores, environmental data, or extra keys.\n6. Return JSON only, with no Markdown and no text outside the JSON object.\n7. Keep the response compact. Do not repeat the BOM description or candidate process names.\n\nRequired JSON schema:\n{\n  "normalized_material": "string",\n  "ranked_process_uuids": ["uuid1", "uuid2"],\n  "match_type": "direct or proxy or review_required"\n}\n"""\n\n\n@dataclass\nclass MatchResult:\n    item_id: str\n    original_material: str\n    quantity: float | None\n    unit: str | None\n    density_kg_m3: float | None\n    thickness_mm: float | None\n    mass_per_item_kg: float | None\n    conversion_factor_to_ref_unit: float | None\n    notes: str | None\n\n    # Raw Qwen output (preserved exactly for audit)\n    normalized_material: str | None\n    match_type: str\n    selected_process_uuid: str | None\n    selected_process_name: str | None\n    selected_process_location: str | None\n    selected_process_ref_unit: str | None\n\n    # Separate production-use fields; downstream veto never rewrites raw Qwen fields\n    safety_status: str\n    safety_reason: str | None\n    production_approved: bool\n    production_match_type: str\n    production_selected_process_uuid: str | None\n    production_selected_process_name: str | None\n    production_selected_process_location: str | None\n    production_selected_process_ref_unit: str | None\n\n    candidate_pool_uuids: str\n    candidate_pool_names: str\n    candidate_pool_locations: str\n    candidate_pool_scores: str\n    presented_candidate_uuids: str\n    parse_status: str\n    structured_output_valid: bool\n    usable_response: bool\n    raw_model_output: str\n    generation_attempts: int\n    structured_output_recovered: bool\n    first_parse_status: str | None\n    catalog_content_sha256: str\n    reference_map_sha256: str | None\n    model_id: str\n    model_revision: str\n    production_prompt_version: str\n    benchmark_script_version: str\n    benchmark_seed: int\n    benchmark_system_prompt_sha256: str\n    safety_gate_version: str\n    material_taxonomy_version: str\n\n\ndef _clean(v: Any) -> str:\n    return "" if v is None else str(v).strip()\n\n\ndef _norm_text(v: Any) -> str:\n    s = _clean(v).lower()\n    s = re.sub(r"[^a-z0-9]+", " ", s)\n    return " ".join(s.split())\n\n\ndef _has_any(text: str, terms: tuple[str, ...] | list[str]) -> bool:\n    return any(term in text for term in terms)\n\n\ndef _retrieval_normalize(value: Any) -> str:\n    """Match the frozen four-model benchmark TF-IDF text normalization exactly."""\n    if value is None:\n        return ""\n    text = str(value).strip().lower()\n    text = re.sub(r"\\s+", " ", text)\n    text = re.sub(r"[^a-z0-9.%+\\-/ ]", "", text)\n    return text.strip()\n\n\ndef _search_text(row: dict[str, Any]) -> str:\n    raw = (\n        f"{_clean(row.get(\'process_name\'))} | "\n        f"{_clean(row.get(\'category\'))} | "\n        f"{_clean(row.get(\'location\'))}"\n    )\n    return _retrieval_normalize(raw)\n\n\ndef _safe_value(value: Any) -> Any:\n    if value is None or (isinstance(value, float) and np.isnan(value)):\n        return ""\n    return value\n\n\ndef _canonical_uuid(value: Any) -> str:\n    if value is None or (isinstance(value, float) and np.isnan(value)):\n        return ""\n    return str(value).strip().lower()\n\n\ndef _canonical_match_type(value: Any) -> str:\n    text = _retrieval_normalize(value).replace("-", " ").replace("_", " ")\n    text = re.sub(r"\\s+", " ", text).strip()\n    if text in {"direct", "direct match", "exact", "exact match"}:\n        return "direct"\n    if text in {"proxy", "proxy match", "documented proxy"}:\n        return "proxy"\n    if text in {\n        "review required", "reviewrequired", "review", "unresolved",\n        "no match", "no defensible match",\n    }:\n        return "review_required"\n    return ""\n\n\ndef load_catalog(path: str | Path) -> list[dict[str, Any]]:\n    """Load the final frozen ELCD catalog from XLSX (preferred) or JSON.\n\n    The XLSX uses the same ``Processes`` sheet and descriptor fields as the\n    four-model benchmark exporter. The final production catalog may be freshly\n    regenerated once, then its semantic hash is locked before Qwen inference.\n    """\n    path = Path(path)\n    benchmark_cols = [\n        "process_uuid", "process_name", "category", "location",\n        "library", "process_type",\n    ]\n    if path.suffix.lower() in {".xlsx", ".xlsm", ".xls"}:\n        df = pd.read_excel(path, sheet_name="Processes")\n        required = {"process_uuid", "process_name"}\n        missing = required.difference(df.columns)\n        if missing:\n            raise ValueError(f"Catalog is missing required columns: {sorted(missing)}")\n        for col in benchmark_cols:\n            if col not in df.columns:\n                df[col] = ""\n            df[col] = df[col].fillna("").astype(str).str.strip()\n        df = df[df["process_uuid"].ne("") & df["process_name"].ne("")].copy()\n        if df["process_uuid"].duplicated().any():\n            dupes = df.loc[df["process_uuid"].duplicated(), "process_uuid"].head(5).tolist()\n            raise ValueError(f"Catalog contains duplicate process UUIDs, e.g. {dupes}")\n        rows = df[benchmark_cols].to_dict(orient="records")\n    else:\n        rows = json.loads(path.read_text(encoding="utf-8"))\n        if not isinstance(rows, list) or not rows:\n            raise ValueError("Catalog JSON is empty or invalid.")\n        for r in rows:\n            if not {"process_uuid", "process_name"}.issubset(r):\n                raise ValueError("Catalog JSON is missing process_uuid/process_name.")\n            for col in benchmark_cols:\n                r[col] = "" if r.get(col) is None else str(r.get(col, "")).strip()\n    return rows\n\n\ndef content_hash(rows: list[dict[str, Any]]) -> str:\n    """Exact semantic catalog hash used by benchmark script v2.3.0."""\n    cols = [\n        "process_uuid", "process_name", "category", "location",\n        "library", "process_type",\n    ]\n    records = []\n    for r in sorted(rows, key=lambda x: _canonical_uuid(x.get("process_uuid"))):\n        records.append({col: _safe_value(r.get(col, "")) for col in cols})\n    payload = json.dumps(\n        records, ensure_ascii=False, sort_keys=True, separators=(",", ":")\n    )\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\nclass Retriever:\n    def __init__(self, rows: list[dict[str, Any]], pool_size: int = 5):\n        self.rows = rows\n        self.pool_size = pool_size\n        self.vectorizer = TfidfVectorizer(\n            analyzer="char_wb",\n            ngram_range=(3, 5),\n            lowercase=False,\n            sublinear_tf=True,\n            norm="l2",\n        )\n        self.matrix = self.vectorizer.fit_transform(\n            [_search_text(r) for r in rows]\n        )\n\n    def retrieve(self, query: str) -> list[dict[str, Any]]:\n        qv = self.vectorizer.transform([_retrieval_normalize(query)])\n        # TF-IDF vectors are L2-normalized, so the sparse dot product is cosine\n        # similarity. Tie-breaking matches the frozen benchmark exactly.\n        scores = (self.matrix @ qv.T).toarray().ravel()\n        order = sorted(\n            range(len(self.rows)),\n            key=lambda i: (\n                -float(scores[i]),\n                str(self.rows[i].get("process_name", "")).lower(),\n                str(self.rows[i].get("process_uuid", "")).strip().lower(),\n            ),\n        )[: self.pool_size]\n        out = []\n        for i in order:\n            r = dict(self.rows[int(i)])\n            r["retrieval_score"] = float(scores[int(i)])\n            out.append(r)\n        return out\n\n\n\n\nFORMAL_CASE_STUDY_PREFIXES = (\n    ("attic", "A"),\n    ("stonecrete", "S"),\n    ("bamboo", "B"),\n)\n\n\ndef infer_formal_case_study_prefix(source_name: str | None) -> str | None:\n    """Infer the frozen benchmark case-study ID prefix from a formal BOM filename.\n\n    This does not affect retrieval or ELCD selection. It only preserves the same\n    deterministic candidate-presentation seed used in the frozen benchmark\n    (S01..., B01..., A01...) when legacy case-study BOMs contain numeric IDs.\n    """\n    text = str(source_name or "").strip().lower()\n    for token, prefix in FORMAL_CASE_STUDY_PREFIXES:\n        if token in text:\n            return prefix\n    return None\n\n\ndef _numeric_id(value: Any) -> int | None:\n    """Return a positive integer for integer-like spreadsheet IDs."""\n    if value is None:\n        return None\n    if isinstance(value, float) and np.isnan(value):\n        return None\n    text = str(value).strip()\n    if not text or text.lower() == "nan":\n        return None\n    try:\n        number = float(text)\n    except Exception:\n        return None\n    if not np.isfinite(number) or number <= 0 or not float(number).is_integer():\n        return None\n    return int(number)\n\n\ndef align_formal_case_study_ids(\n    df: pd.DataFrame,\n    source_name: str | None,\n) -> tuple[pd.DataFrame, dict[str, Any]]:\n    """Align legacy numeric IDs to the frozen benchmark IDs for formal cases.\n\n    Examples: Bamboo ``2`` -> ``B02``; Stonecrete ``7`` -> ``S07``; Attic\n    ``1`` -> ``A01``. Existing formal IDs are normalized/preserved. Custom\n    nonnumeric IDs are never overwritten. Blank IDs use the row position only\n    for a recognized formal case study.\n\n    The function intentionally changes *only* the identifier used as the\n    deterministic candidate-presentation seed. Material text, retrieval scores,\n    candidate pools, Qwen prompt definitions, and Direct/Proxy decisions are not\n    altered.\n    """\n    out = df.copy()\n    prefix = infer_formal_case_study_prefix(source_name)\n    info: dict[str, Any] = {\n        "source_name": str(source_name or ""),\n        "prefix": prefix,\n        "changed": 0,\n        "aligned": 0,\n        "custom_preserved": 0,\n    }\n    if prefix is None:\n        return out, info\n\n    if "ID" not in out.columns:\n        out["ID"] = None\n\n    formal_re = re.compile(rf"^{re.escape(prefix)}\\s*0*(\\d+)$", flags=re.I)\n    new_ids: list[str] = []\n    for row_pos, raw in enumerate(out["ID"].tolist(), start=1):\n        text = _clean(raw)\n        formal_match = formal_re.match(text) if text else None\n        if formal_match:\n            n = int(formal_match.group(1))\n            new = f"{prefix}{n:02d}"\n            info["aligned"] += 1\n        else:\n            n = _numeric_id(raw)\n            if n is not None:\n                new = f"{prefix}{n:02d}"\n                info["aligned"] += 1\n            elif not text:\n                new = f"{prefix}{row_pos:02d}"\n                info["aligned"] += 1\n            else:\n                new = text\n                info["custom_preserved"] += 1\n        if new != text:\n            info["changed"] += 1\n        new_ids.append(new)\n\n    if len(set(new_ids)) != len(new_ids):\n        duplicates = sorted({x for x in new_ids if new_ids.count(x) > 1})\n        raise ValueError(\n            "Duplicate BOM IDs after formal case-study alignment: "\n            + ", ".join(duplicates)\n        )\n    out["ID"] = new_ids\n    return out, info\n\n\ndef deterministic_present(\n    candidates: list[dict[str, Any]],\n    item_id: str,\n) -> list[dict[str, Any]]:\n    return sorted(\n        candidates,\n        key=lambda r: hashlib.sha256(\n            (\n                "candidate-presentation-v1|"\n                f"{str(item_id).strip()}|"\n                f"{str(r.get(\'process_uuid\', \'\')).strip().lower()}"\n            ).encode("utf-8")\n        ).hexdigest(),\n    )\n\n\ndef build_benchmark_user_prompt(\n    item_id: str,\n    material: str,\n    quantity: Any,\n    unit: Any,\n    presented_candidates: list[dict[str, Any]],\n) -> str:\n    """Exact user-prompt construction used by benchmark script v2.3.0."""\n    def payload_value(value: Any) -> Any:\n        if value is None or (isinstance(value, float) and np.isnan(value)):\n            return ""\n        return value\n\n    material_payload = {\n        "sample_id": str(item_id),\n        "material_description": str(material),\n        "quantity": payload_value(quantity),\n        "unit": payload_value(unit),\n    }\n    compact_candidates = [\n        {\n            "process_uuid": r["process_uuid"],\n            "process_name": r["process_name"],\n            "category": r.get("category") or "",\n            "location": r.get("location") or "",\n            "process_type": r.get("process_type") or "",\n        }\n        for r in presented_candidates\n    ]\n    payload = {\n        "requested_top_k": BENCHMARK_TOP_K,\n        "material": material_payload,\n        "candidate_processes": compact_candidates,\n    }\n    return (\n        "Evaluate this material using only the supplied candidate UUIDs. "\n        "The candidate list is an unordered presentation; do not infer quality from position. "\n        "Return exactly the required three-field JSON object.\\n\\n"\n        + json.dumps(payload, ensure_ascii=False, separators=(",", ":"))\n    )\n\n\ndef extract_json(text: str) -> tuple[dict[str, Any] | None, str]:\n    """Exact JSON extraction behavior from benchmark script v2.3.0."""\n    if not text:\n        return None, "empty_response"\n\n    cleaned = text.strip()\n    fenced = re.findall(r"```(?:json)?\\s*(\\{.*?\\})\\s*```", cleaned, flags=re.S | re.I)\n    candidates = fenced + [cleaned]\n\n    first = cleaned.find("{")\n    last = cleaned.rfind("}")\n    if first != -1 and last > first:\n        candidates.append(cleaned[first : last + 1])\n\n    seen: set[str] = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        try:\n            parsed = json.loads(candidate)\n            if isinstance(parsed, dict):\n                return parsed, "ok"\n        except json.JSONDecodeError:\n            continue\n    return None, "json_parse_error"\n\n\ndef validate_prediction(\n    parsed: dict[str, Any] | None,\n    candidates: list[dict[str, Any]],\n    parse_status: str,\n    top_k: int = BENCHMARK_TOP_K,\n) -> dict[str, Any]:\n    """Exact benchmark v2.3.0 field validation/recovery semantics.\n\n    Raw Qwen fields can therefore be compared directly with the four-model\n    workbook.  Production approval is decided separately after this function.\n    """\n    valid_by_uuid = {\n        _canonical_uuid(c["process_uuid"]): c\n        for c in candidates if c.get("process_uuid")\n    }\n    empty = {\n        "parse_status": parse_status,\n        "structured_output_valid": False,\n        "usable_response": False,\n        "normalized_material": "",\n        "normalization_field_valid": False,\n        "match_type": "",\n        "match_type_field_valid": False,\n        "selected_process_uuid": "",\n        "selected_process_name": "",\n        "selection_field_valid": False,\n        "ranked_process_uuids": [],\n        "ranked_process_names": [],\n        "ranking_field_valid": False,\n        "field_recovery_used": False,\n    }\n    if parsed is None:\n        return empty\n\n    normalized_material = str(parsed.get("normalized_material", "")).strip()\n    normalization_valid = bool(normalized_material)\n    match_type = _canonical_match_type(parsed.get("match_type", ""))\n    match_type_valid = match_type in {"direct", "proxy", "review_required"}\n\n    recovery_used = False\n    raw_ranked = parsed.get("ranked_process_uuids", None)\n    ranked_source_valid = isinstance(raw_ranked, list)\n\n    if not isinstance(raw_ranked, list):\n        old_ranked = parsed.get("ranked_candidates", None)\n        if isinstance(old_ranked, list):\n            raw_ranked = [\n                item.get("process_uuid", "") if isinstance(item, dict) else item\n                for item in old_ranked\n            ]\n            recovery_used = True\n        else:\n            selected_old = _canonical_uuid(parsed.get("selected_process_uuid", ""))\n            raw_ranked = [selected_old] if selected_old else []\n            if selected_old:\n                recovery_used = True\n\n    ranked_uuids: list[str] = []\n    invalid_rank_item = False\n    for item in raw_ranked:\n        uid = _canonical_uuid(item)\n        if uid and uid in valid_by_uuid:\n            if uid not in ranked_uuids:\n                ranked_uuids.append(uid)\n        elif uid:\n            invalid_rank_item = True\n        if len(ranked_uuids) >= top_k:\n            break\n\n    ranking_valid = isinstance(raw_ranked, list) and not invalid_rank_item\n    if match_type == "review_required":\n        ranking_valid = ranking_valid and len(ranked_uuids) == 0\n        selected_uuid = ""\n        selection_valid = True\n    elif match_type in {"direct", "proxy"}:\n        selection_valid = len(ranked_uuids) >= 1\n        selected_uuid = ranked_uuids[0] if selection_valid else ""\n        ranking_valid = ranking_valid and len(ranked_uuids) >= 1\n    else:\n        selected_uuid = ranked_uuids[0] if ranked_uuids else ""\n        selection_valid = False\n\n    selected_name = valid_by_uuid[selected_uuid]["process_name"] if selected_uuid in valid_by_uuid else ""\n    ranked_names = [valid_by_uuid[u]["process_name"] for u in ranked_uuids if u in valid_by_uuid]\n\n    exact_keys = {"normalized_material", "ranked_process_uuids", "match_type"}\n    structured_valid = (\n        parse_status == "ok"\n        and set(parsed.keys()) == exact_keys\n        and normalization_valid\n        and match_type_valid\n        and ranked_source_valid\n        and ranking_valid\n        and not recovery_used\n    )\n    usable = normalization_valid and match_type_valid and selection_valid and ranking_valid\n\n    if parse_status != "ok":\n        status = parse_status\n    elif structured_valid:\n        status = "ok"\n    elif recovery_used and usable:\n        status = "field_recovered"\n    elif not normalization_valid:\n        status = "missing_normalized_material"\n    elif not match_type_valid:\n        status = "invalid_match_type"\n    elif not ranking_valid:\n        status = "invalid_ranking"\n    else:\n        status = "schema_mismatch"\n\n    return {\n        "parse_status": status,\n        "structured_output_valid": structured_valid,\n        "usable_response": usable,\n        "normalized_material": normalized_material,\n        "normalization_field_valid": normalization_valid,\n        "match_type": match_type,\n        "match_type_field_valid": match_type_valid,\n        "selected_process_uuid": selected_uuid,\n        "selected_process_name": selected_name,\n        "selection_field_valid": selection_valid,\n        "ranked_process_uuids": ranked_uuids,\n        "ranked_process_names": ranked_names,\n        "ranking_field_valid": ranking_valid,\n        "field_recovery_used": recovery_used,\n    }\n\n\ndef parse_output(text: str, supplied_uuids: set[str]) -> tuple[dict[str, Any] | None, str]:\n    """Compatibility wrapper used by older unit tests.\n\n    New production matching uses :func:`extract_json` + :func:`validate_prediction`\n    so the raw fields match the benchmark\'s validation semantics.\n    """\n    parsed, parse_status = extract_json(text)\n    candidates = [{"process_uuid": u, "process_name": u} for u in supplied_uuids]\n    pred = validate_prediction(parsed, candidates, parse_status, BENCHMARK_TOP_K)\n    if not pred["usable_response"]:\n        return None, pred["parse_status"]\n    return {\n        "normalized_material": pred["normalized_material"],\n        "ranked_process_uuids": pred["ranked_process_uuids"],\n        "match_type": pred["match_type"],\n    }, pred["parse_status"]\n\n\ndef production_safety_gate(\n    original_material: str,\n    normalized_material: str | None,\n    match_type: str,\n    selected_process_name: str | None,\n) -> tuple[str, str | None]:\n    """Post-Qwen family veto; never changes the raw benchmark decision.\n\n    The four-model benchmark ends after Qwen\'s Direct/Proxy/Review Required\n    output.  Production may subsequently reject a clearly incompatible process\n    (e.g. CGI -> corrugated paper board), but that rejection is recorded only in\n    ``production_*`` fields and routes the row to the external/fallback resolver.\n    """\n    if match_type == "review_required" or not selected_process_name:\n        return "NOT_APPLICABLE", None\n    material_for_check = original_material or normalized_material or ""\n    compatible, reason = process_compatibility(material_for_check, selected_process_name)\n    if not compatible:\n        return "VETO", reason\n    return "PASS", "Post-Qwen product-family compatibility check passed."\n\n\nclass QwenMatcher:\n    def __init__(\n        self,\n        catalog_path: str | Path,\n        pool_size: int = BENCHMARK_CANDIDATE_POOL_SIZE,\n        max_new_tokens: int = BENCHMARK_MAX_NEW_TOKENS,\n        max_input_tokens: int = 3072,\n        reference_map_path: str | Path | None = None,\n    ):\n        if int(pool_size) != BENCHMARK_CANDIDATE_POOL_SIZE:\n            raise ValueError(\n                f"Benchmark-locked production requires candidate pool size "\n                f"{BENCHMARK_CANDIDATE_POOL_SIZE}; got {pool_size}."\n            )\n        if int(max_new_tokens) != BENCHMARK_MAX_NEW_TOKENS:\n            raise ValueError(\n                f"Benchmark-locked production requires max_new_tokens "\n                f"{BENCHMARK_MAX_NEW_TOKENS}; got {max_new_tokens}."\n            )\n        actual_prompt_hash = hashlib.sha256(SYSTEM_PROMPT.encode("utf-8")).hexdigest()\n        if actual_prompt_hash != BENCHMARK_SYSTEM_PROMPT_SHA256:\n            raise RuntimeError(\n                "Qwen matching prompt drift detected. The production prompt no longer "\n                "matches benchmark script v2.3.0."\n            )\n        self.catalog = load_catalog(catalog_path)\n        # The ELCD data snapshot may be freshly regenerated for the final production\n        # run, but it is frozen immediately afterward.  All model/prompt/retrieval\n        # settings remain identical to the four-model benchmark.\n        self.catalog_hash = content_hash(self.catalog)\n        catalog_path_obj = Path(catalog_path)\n        lock_path = catalog_path_obj.with_name("ELCD_Catalog_Lock.json")\n        protocol = {\n            "benchmark_script_version": BENCHMARK_SCRIPT_VERSION,\n            "model_id": MODEL_ID,\n            "model_revision": MODEL_REVISION,\n            "system_prompt_sha256": BENCHMARK_SYSTEM_PROMPT_SHA256,\n            "seed": BENCHMARK_SEED,\n            "candidate_pool_size": BENCHMARK_CANDIDATE_POOL_SIZE,\n            "reported_top_k": BENCHMARK_TOP_K,\n            "max_new_tokens": BENCHMARK_MAX_NEW_TOKENS,\n            "temperature": 0,\n            "decoding": "greedy",\n            "do_sample": False,\n            "quantization": "4-bit NF4",\n            "retrieval_method": "character n-gram TF-IDF",\n            "retrieval_analyzer": "char_wb",\n            "retrieval_ngram_range": "3-5",\n            "retrieval_query_source": "original BOM description only",\n            "candidate_presentation": "deterministic SHA-256 shuffle by sample_id + process_uuid",\n            "retrieval_rank_visible_to_llm": False,\n            "retrieval_score_visible_to_llm": False,\n        }\n        self.catalog_lock = verify_lock(\n            catalog_path_obj, lock_path, expected_matching_protocol=protocol\n        )\n        if str(self.catalog_lock.get("catalog_content_sha256")) != self.catalog_hash:\n            raise RuntimeError("Frozen ELCD catalog lock verification failed.")\n        self.reference_map_sha256 = None\n        if reference_map_path is not None and Path(reference_map_path).exists():\n            raw_bytes = Path(reference_map_path).read_bytes()\n            self.reference_map_sha256 = hashlib.sha256(raw_bytes).hexdigest()\n            ref_map = json.loads(raw_bytes.decode("utf-8"))\n            for r in self.catalog:\n                meta = ref_map.get(r["process_uuid"], {})\n                if meta.get("ref_unit"):\n                    r["ref_unit"] = meta.get("ref_unit")\n                if meta.get("qref_flow_name"):\n                    r["qref_flow_name"] = meta.get("qref_flow_name")\n                if meta.get("qref_amount") is not None:\n                    r["qref_amount"] = meta.get("qref_amount")\n        self.by_uuid = {\n            r["process_uuid"]: r for r in self.catalog\n        }\n        self.retriever = Retriever(\n            self.catalog,\n            pool_size=pool_size,\n        )\n        self.max_new_tokens = max_new_tokens\n        self.max_input_tokens = max_input_tokens\n        self.tokenizer = None\n        self.model = None\n\n    @staticmethod\n    def _set_benchmark_reproducibility() -> None:\n        """Mirror benchmark script v2.3.0 seed/determinism settings exactly."""\n        import torch\n        random.seed(BENCHMARK_SEED)\n        np.random.seed(BENCHMARK_SEED)\n        torch.manual_seed(BENCHMARK_SEED)\n        if torch.cuda.is_available():\n            torch.cuda.manual_seed_all(BENCHMARK_SEED)\n        if hasattr(torch.backends, "cudnn"):\n            torch.backends.cudnn.benchmark = False\n            torch.backends.cudnn.deterministic = True\n\n    def load_model(self):\n        import torch\n        from transformers import (\n            AutoModelForCausalLM,\n            AutoTokenizer,\n            BitsAndBytesConfig,\n        )\n\n        if not torch.cuda.is_available():\n            raise RuntimeError(\n                "CUDA GPU is not available. In Colab choose "\n                "Runtime > Change runtime type > T4 GPU."\n            )\n\n        qconf = BitsAndBytesConfig(\n            load_in_4bit=True,\n            bnb_4bit_quant_type="nf4",\n            bnb_4bit_use_double_quant=True,\n            bnb_4bit_compute_dtype=torch.float16,\n        )\n\n        self._set_benchmark_reproducibility()\n        self.tokenizer = AutoTokenizer.from_pretrained(\n            MODEL_ID,\n            revision=MODEL_REVISION,\n            use_fast=True,\n            trust_remote_code=False,\n        )\n        if self.tokenizer.pad_token_id is None and self.tokenizer.eos_token_id is not None:\n            self.tokenizer.pad_token = self.tokenizer.eos_token\n        self.model = AutoModelForCausalLM.from_pretrained(\n            MODEL_ID,\n            revision=MODEL_REVISION,\n            quantization_config=qconf,\n            device_map="auto",\n            torch_dtype=torch.float16,\n            trust_remote_code=False,\n            low_cpu_mem_usage=True,\n        )\n        self.model.eval()\n        loaded_revision = str(getattr(self.model.config, "_commit_hash", "") or "")\n        if loaded_revision and loaded_revision != MODEL_REVISION:\n            raise RuntimeError(\n                f"Qwen model revision drift: loaded {loaded_revision}, expected {MODEL_REVISION}."\n            )\n        return self\n\n    def generate_with_system(\n        self,\n        system_prompt: str,\n        user_payload: dict[str, Any],\n        *,\n        max_new_tokens_override: int | None = None,\n    ) -> str:\n        import torch\n\n        messages = [\n            {"role": "system", "content": system_prompt},\n            {\n                "role": "user",\n                "content": json.dumps(\n                    user_payload,\n                    ensure_ascii=False,\n                ),\n            },\n        ]\n        text = self.tokenizer.apply_chat_template(\n            messages,\n            tokenize=False,\n            add_generation_prompt=True,\n        )\n        inputs = self.tokenizer(\n            text,\n            return_tensors="pt",\n            truncation=True,\n            max_length=self.max_input_tokens,\n        ).to(self.model.device)\n\n        try:\n            with torch.inference_mode():\n                out = self.model.generate(\n                    **inputs,\n                    max_new_tokens=(\n                        int(max_new_tokens_override)\n                        if max_new_tokens_override is not None\n                        else self.max_new_tokens\n                    ),\n                    do_sample=False,\n                    use_cache=True,\n                    pad_token_id=self.tokenizer.eos_token_id,\n                )\n\n            generated = out[0][inputs["input_ids"].shape[1]:]\n            decoded = self.tokenizer.decode(\n                generated,\n                skip_special_tokens=True,\n            ).strip()\n            return decoded\n        finally:\n            # Release per-generation tensors promptly. This does not unload the model.\n            try:\n                del inputs\n                if "out" in locals():\n                    del out\n                if "generated" in locals():\n                    del generated\n            except Exception:\n                pass\n            torch.cuda.empty_cache()\n\n    def _generate_matching_prompt(\n        self,\n        system_prompt: str,\n        user_prompt: str,\n        *,\n        max_new_tokens_override: int | None = None,\n    ) -> str:\n        """Generate ELCD matching output using the frozen benchmark chat format.\n\n        The four-model benchmark used one user-role message containing the system\n        instruction followed by the serialized benchmark payload. Production uses\n        the same format here so the selected Qwen sees the same matching protocol.\n        Other downstream resolver prompts continue to use ``generate_with_system``.\n        """\n        import torch\n\n        self._set_benchmark_reproducibility()\n        messages = [{"role": "user", "content": system_prompt + "\\n\\n" + user_prompt}]\n        input_ids = self.tokenizer.apply_chat_template(\n            messages,\n            tokenize=True,\n            add_generation_prompt=True,\n            return_tensors="pt",\n        )\n        try:\n            device = self.model.get_input_embeddings().weight.device\n        except Exception:\n            device = next(self.model.parameters()).device\n        input_ids = input_ids.to(device)\n        attention_mask = torch.ones_like(input_ids)\n        try:\n            with torch.inference_mode():\n                out = self.model.generate(\n                    input_ids=input_ids,\n                    attention_mask=attention_mask,\n                    max_new_tokens=(\n                        int(max_new_tokens_override)\n                        if max_new_tokens_override is not None\n                        else self.max_new_tokens\n                    ),\n                    do_sample=False,\n                    use_cache=True,\n                    pad_token_id=self.tokenizer.pad_token_id,\n                    eos_token_id=self.tokenizer.eos_token_id,\n                )\n            generated = out[0, input_ids.shape[-1]:]\n            return self.tokenizer.decode(generated, skip_special_tokens=True).strip()\n        finally:\n            try:\n                del input_ids\n                del attention_mask\n                if "out" in locals():\n                    del out\n                if "generated" in locals():\n                    del generated\n            except Exception:\n                pass\n            torch.cuda.empty_cache()\n\n    def _generate(self, user_prompt: str) -> str:\n        return self._generate_matching_prompt(SYSTEM_PROMPT, user_prompt)\n\n    def match_item(self, item: dict[str, Any]) -> MatchResult:\n        item_id = _clean(\n            item.get("ID")\n            or item.get("item_id")\n            or item.get("id")\n            or "ITEM"\n        )\n        material = _clean(\n            item.get("Material") or item.get("material")\n        )\n        if not material:\n            raise ValueError("Material is required.")\n\n        candidates = self.retriever.retrieve(material)\n        presented = deterministic_present(\n            candidates,\n            item_id,\n        )\n\n        user_prompt = build_benchmark_user_prompt(\n            item_id, material, item.get("Quantity"), item.get("Unit"), presented\n        )\n\n        # Exact benchmark inference protocol: one generation, no production-only\n        # repair prompt.  Raw fields are validated with the same v2.3.0 logic used\n        # in the four-model workbook.\n        raw = self._generate(user_prompt)\n        parsed_obj, json_status = extract_json(raw)\n        prediction = validate_prediction(\n            parsed_obj, presented, json_status, BENCHMARK_TOP_K\n        )\n\n        normalized = prediction["normalized_material"] or None\n        match_type = prediction["match_type"] or "review_required"\n        selected_uuid = prediction["selected_process_uuid"] or None\n        selected = self.by_uuid.get(selected_uuid) if selected_uuid else None\n        selected_name = selected.get("process_name") if selected else None\n        selected_location = selected.get("location") if selected else None\n        selected_ref_unit = selected.get("ref_unit") if selected else None\n\n        structured_valid = bool(prediction["structured_output_valid"])\n        usable_response = bool(prediction["usable_response"])\n        status = str(prediction["parse_status"])\n\n        safety_status, safety_reason = production_safety_gate(\n            original_material=material,\n            normalized_material=normalized,\n            match_type=match_type,\n            selected_process_name=selected_name,\n        )\n\n        # The raw Qwen fields above are never rewritten. Production acceptance is\n        # a separate downstream decision. For manuscript-grade traceability we\n        # require the exact benchmark schema to be valid and the family gate to\n        # pass before an ELCD factor is used.\n        production_approved = (\n            structured_valid\n            and usable_response\n            and match_type in {"direct", "proxy"}\n            and bool(selected_uuid)\n            and safety_status == "PASS"\n        )\n\n        if production_approved:\n            production_match_type = match_type\n            production_uuid = selected_uuid\n            production_name = selected_name\n            production_location = selected_location\n            production_ref_unit = selected_ref_unit\n        else:\n            production_match_type = "review_required"\n            production_uuid = None\n            production_name = None\n            production_location = None\n            production_ref_unit = None\n\n        generation_attempts = 1\n        structured_output_recovered = False\n        first_parse_status = status\n\n        def num(name: str):\n            v = item.get(name)\n            if (\n                v is None\n                or (\n                    isinstance(v, float)\n                    and np.isnan(v)\n                )\n                or _clean(v) == ""\n            ):\n                return None\n            try:\n                return float(v)\n            except Exception:\n                return None\n\n        return MatchResult(\n            item_id=item_id,\n            original_material=material,\n            quantity=num("Quantity"),\n            unit=_clean(item.get("Unit")) or None,\n            density_kg_m3=num("Density_kg_m3"),\n            thickness_mm=num("Thickness_mm"),\n            mass_per_item_kg=num("Mass_per_item_kg"),\n            conversion_factor_to_ref_unit=num(\n                "Conversion_factor_to_ref_unit"\n            ),\n            notes=_clean(item.get("Notes")) or None,\n\n            normalized_material=normalized,\n            match_type=match_type,\n            selected_process_uuid=selected_uuid,\n            selected_process_name=selected_name,\n            selected_process_location=selected_location,\n            selected_process_ref_unit=selected_ref_unit,\n\n            safety_status=safety_status,\n            safety_reason=safety_reason,\n            production_approved=production_approved,\n            production_match_type=production_match_type,\n            production_selected_process_uuid=production_uuid,\n            production_selected_process_name=production_name,\n            production_selected_process_location=production_location,\n            production_selected_process_ref_unit=production_ref_unit,\n\n            candidate_pool_uuids=json.dumps(\n                [r["process_uuid"] for r in candidates]\n            ),\n            candidate_pool_names=json.dumps(\n                [r["process_name"] for r in candidates],\n                ensure_ascii=False,\n            ),\n            candidate_pool_locations=json.dumps(\n                [r.get("location") for r in candidates],\n                ensure_ascii=False,\n            ),\n            candidate_pool_scores=json.dumps(\n                [\n                    round(r["retrieval_score"], 8)\n                    for r in candidates\n                ]\n            ),\n            presented_candidate_uuids=json.dumps(\n                [r["process_uuid"] for r in presented]\n            ),\n            parse_status=status,\n            structured_output_valid=structured_valid,\n            usable_response=usable_response,\n            raw_model_output=raw,\n            generation_attempts=generation_attempts,\n            structured_output_recovered=structured_output_recovered,\n            first_parse_status=first_parse_status,\n            catalog_content_sha256=self.catalog_hash,\n            reference_map_sha256=self.reference_map_sha256,\n            model_id=MODEL_ID,\n            model_revision=MODEL_REVISION,\n            production_prompt_version=PRODUCTION_PROMPT_VERSION,\n            benchmark_script_version=BENCHMARK_SCRIPT_VERSION,\n            benchmark_seed=BENCHMARK_SEED,\n            benchmark_system_prompt_sha256=BENCHMARK_SYSTEM_PROMPT_SHA256,\n            safety_gate_version=SAFETY_GATE_VERSION,\n            material_taxonomy_version=MATERIAL_TAXONOMY_VERSION,\n        )\n\n    def match_many(self, df: pd.DataFrame) -> pd.DataFrame:\n        required = {"Material", "Quantity", "Unit"}\n        missing = sorted(required - set(df.columns))\n        if missing:\n            raise ValueError(\n                f"BOM is missing required columns: {missing}"\n            )\n\n        rows = []\n        for i, rec in enumerate(\n            df.to_dict(orient="records"),\n            start=1,\n        ):\n            if not _clean(rec.get("ID")):\n                rec["ID"] = f"ITEM-{i:03d}"\n            rows.append(asdict(self.match_item(rec)))\n\n        return pd.DataFrame(rows)\n\n\ndef write_selection_excel(\n    df: pd.DataFrame,\n    path: str | Path,\n    property_evidence: pd.DataFrame | None = None,\n    external_ef_evidence: pd.DataFrame | None = None,\n) -> Path:\n    path = Path(path)\n    path.parent.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    with pd.ExcelWriter(\n        path,\n        engine="openpyxl",\n    ) as writer:\n        df.to_excel(\n            writer,\n            sheet_name="Selections",\n            index=False,\n        )\n\n        summary = pd.DataFrame(\n            [\n                ["n_items", len(df)],\n                [\n                    "structured_output_valid",\n                    int(df["structured_output_valid"].sum()),\n                ],\n                [\n                    "structured_output_recovered_after_retry",\n                    int(df.get("structured_output_recovered", pd.Series(False, index=df.index)).fillna(False).astype(bool).sum()),\n                ],\n                [\n                    "qwen_direct_raw",\n                    int((df["match_type"] == "direct").sum()),\n                ],\n                [\n                    "qwen_proxy_raw",\n                    int((df["match_type"] == "proxy").sum()),\n                ],\n                [\n                    "qwen_review_required_raw",\n                    int(\n                        (\n                            df["match_type"]\n                            == "review_required"\n                        ).sum()\n                    ),\n                ],\n                [\n                    "safety_flagged",\n                    int(\n                        (\n                            df["safety_status"].isin({"VETO", "FLAGGED"})\n                        ).sum()\n                    ),\n                ],\n                [\n                    "production_approved",\n                    int(df["production_approved"].sum()),\n                ],\n                [\n                    "production_direct",\n                    int(\n                        (\n                            df["production_match_type"]\n                            == "direct"\n                        ).sum()\n                    ),\n                ],\n                [\n                    "production_proxy",\n                    int(\n                        (\n                            df["production_match_type"]\n                            == "proxy"\n                        ).sum()\n                    ),\n                ],\n                [\n                    "production_review_required",\n                    int(\n                        (\n                            df["production_match_type"]\n                            == "review_required"\n                        ).sum()\n                    ),\n                ],\n                [\n                    "catalog_content_sha256",\n                    df["catalog_content_sha256"].iloc[0]\n                    if len(df)\n                    else None,\n                ],\n                ["model_id", MODEL_ID],\n                ["model_revision", MODEL_REVISION],\n                [\n                    "production_prompt_version",\n                    PRODUCTION_PROMPT_VERSION,\n                ],\n                [\n                    "safety_gate_version",\n                    SAFETY_GATE_VERSION,\n                ],\n                [\n                    "material_taxonomy_version",\n                    MATERIAL_TAXONOMY_VERSION,\n                ],\n            ],\n            columns=["field", "value"],\n        )\n\n        # External-EF metadata are appended only when the resolver ran.\n        if "external_ef_resolution_status" in df.columns:\n            ef_rows = pd.DataFrame([\n                ["external_ef_resolver_version", df["external_ef_resolver_version"].dropna().iloc[0] if df["external_ef_resolver_version"].notna().any() else None],\n                ["external_ef_verified", int((df["external_ef_resolution_status"] == "RESOLVED_EXTERNAL_VERIFIED").sum())],\n                ["external_ef_verified_relaxed_phase", int((df.get("external_ef_verification_tier", pd.Series(index=df.index, dtype=str)) == "RELAXED").sum())],\n                ["external_ef_unresolved", int((df["external_ef_resolution_status"] == "UNRESOLVED").sum())],\n                ["external_ef_not_applicable", int((df["external_ef_resolution_status"] == "NOT_APPLICABLE_ELCD_APPROVED").sum())],\n            ], columns=["field", "value"])\n            summary = pd.concat([summary, ef_rows], ignore_index=True)\n\n        # Property-resolution metadata are appended only when the property resolver ran.\n        if "property_resolution_status" in df.columns:\n            prop_rows = pd.DataFrame([\n                ["property_resolver_version", df["property_resolver_version"].dropna().iloc[0] if df["property_resolver_version"].notna().any() else None],\n                ["property_traceable_web", int((df["property_resolution_status"] == "RESOLVED_TRACEABLE_WEB").sum())],\n                ["property_traceable_web_relaxed", int((df["property_resolution_status"] == "RESOLVED_TRACEABLE_WEB_RELAXED").sum())],\n                ["property_unresolved", int((df["property_resolution_status"] == "UNRESOLVED").sum())],\n                ["property_not_needed", int((df["property_resolution_status"] == "NOT_NEEDED").sum())],\n            ], columns=["field", "value"])\n            summary = pd.concat([summary, prop_rows], ignore_index=True)\n\n        summary.to_excel(\n            writer,\n            sheet_name="Run_Metadata",\n            index=False,\n        )\n\n        if property_evidence is not None and not property_evidence.empty:\n            property_evidence.to_excel(\n                writer,\n                sheet_name="Property_Evidence",\n                index=False,\n            )\n\n        if external_ef_evidence is not None and not external_ef_evidence.empty:\n            external_ef_evidence.to_excel(\n                writer,\n                sheet_name="External_EF_Evidence",\n                index=False,\n            )\n\n    return path\n', 'catalog_lock.py': '"""Freeze and verify the active ELCD retrieval catalog.\n\nThe matching protocol is benchmark-locked, while the ELCD catalog may be freshly\nexported once for the final production run.  Immediately after export, its\nsemantic content hash is written to ``ELCD_Catalog_Lock.json``.  Production then\nrefuses to run if that catalog changes.\n\nThe semantic hash uses the exact six descriptor fields and sort rule used by the\nfour-model benchmark metadata, so XLSX timestamps/formatting do not affect it.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport pandas as pd\n\nCATALOG_LOCK_SCHEMA_VERSION = "1.0"\nCATALOG_COLUMNS = [\n    "process_uuid", "process_name", "category", "location", "library", "process_type"\n]\n\n\ndef _safe_value(value: Any) -> Any:\n    if value is None or (isinstance(value, float) and pd.isna(value)):\n        return ""\n    return value\n\n\ndef catalog_dataframe(path: str | Path) -> pd.DataFrame:\n    path = Path(path)\n    df = pd.read_excel(path, sheet_name="Processes")\n    required = {"process_uuid", "process_name"}\n    missing = required.difference(df.columns)\n    if missing:\n        raise ValueError(f"Catalog is missing required columns: {sorted(missing)}")\n    for col in CATALOG_COLUMNS:\n        if col not in df.columns:\n            df[col] = ""\n        df[col] = df[col].fillna("").astype(str).str.strip()\n    df = df[df["process_uuid"].ne("") & df["process_name"].ne("")].copy()\n    if df["process_uuid"].duplicated().any():\n        dupes = df.loc[df["process_uuid"].duplicated(), "process_uuid"].head(5).tolist()\n        raise ValueError(f"Catalog contains duplicate process UUIDs, e.g. {dupes}")\n    return df[CATALOG_COLUMNS].copy()\n\n\ndef semantic_catalog_hash(path: str | Path) -> str:\n    df = catalog_dataframe(path)\n    use = df.copy().sort_values(["process_uuid"], kind="mergesort").reset_index(drop=True)\n    records = []\n    for _, row in use.iterrows():\n        records.append({col: _safe_value(row[col]) for col in CATALOG_COLUMNS})\n    payload = json.dumps(records, ensure_ascii=False, sort_keys=True, separators=(",", ":"))\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\ndef file_sha256(path: str | Path) -> str:\n    h = hashlib.sha256()\n    with Path(path).open("rb") as f:\n        for chunk in iter(lambda: f.read(1024 * 1024), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef build_lock(\n    catalog_path: str | Path,\n    lock_path: str | Path,\n    *,\n    database_label: str,\n    matching_protocol: dict[str, Any],\n    historical_benchmark_catalog_hash: str | None = None,\n) -> dict[str, Any]:\n    catalog_path = Path(catalog_path)\n    lock_path = Path(lock_path)\n    df = catalog_dataframe(catalog_path)\n    semantic_hash = semantic_catalog_hash(catalog_path)\n    lock = {\n        "schema_version": CATALOG_LOCK_SCHEMA_VERSION,\n        "frozen_at_utc": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),\n        "database_label_user_supplied": str(database_label),\n        "catalog_file": catalog_path.name,\n        "catalog_process_count": int(len(df)),\n        "catalog_content_sha256": semantic_hash,\n        "catalog_file_sha256": file_sha256(catalog_path),\n        "historical_benchmark_catalog_content_sha256": historical_benchmark_catalog_hash or "",\n        "same_as_historical_benchmark_catalog": bool(\n            historical_benchmark_catalog_hash and semantic_hash == historical_benchmark_catalog_hash\n        ),\n        "matching_protocol": matching_protocol,\n        "freeze_rule": (\n            "This ELCD catalog is the final production retrieval snapshot. Regenerating or editing "\n            "the catalog requires creating a new lock and constitutes a new production data snapshot."\n        ),\n    }\n    lock_path.parent.mkdir(parents=True, exist_ok=True)\n    lock_path.write_text(json.dumps(lock, indent=2, ensure_ascii=False), encoding="utf-8")\n    return lock\n\n\ndef verify_lock(\n    catalog_path: str | Path,\n    lock_path: str | Path,\n    *,\n    expected_matching_protocol: dict[str, Any],\n) -> dict[str, Any]:\n    catalog_path = Path(catalog_path)\n    lock_path = Path(lock_path)\n    if not lock_path.exists():\n        raise RuntimeError(\n            f"Frozen ELCD catalog lock is missing: {lock_path}. Run `python main.py export ...` "\n            "or `python scripts/freeze_elcd_catalog.py ...` after generating the final catalog."\n        )\n    lock = json.loads(lock_path.read_text(encoding="utf-8"))\n    if str(lock.get("schema_version")) != CATALOG_LOCK_SCHEMA_VERSION:\n        raise RuntimeError("Unsupported ELCD catalog lock schema version.")\n    current = semantic_catalog_hash(catalog_path)\n    frozen = str(lock.get("catalog_content_sha256") or "")\n    if current != frozen:\n        raise RuntimeError(\n            "Frozen ELCD catalog drift detected. "\n            f"Lock={frozen}; current={current}. Regenerate/freeze intentionally before continuing."\n        )\n    if int(lock.get("catalog_process_count") or -1) != len(catalog_dataframe(catalog_path)):\n        raise RuntimeError("Frozen ELCD catalog process count does not match the lock.")\n    recorded = lock.get("matching_protocol") or {}\n    mismatches = {\n        key: (recorded.get(key), expected)\n        for key, expected in expected_matching_protocol.items()\n        if recorded.get(key) != expected\n    }\n    if mismatches:\n        raise RuntimeError(\n            "Matching-protocol drift detected in ELCD catalog lock: "\n            + "; ".join(f"{k}: lock={a!r}, expected={b!r}" for k, (a, b) in mismatches.items())\n        )\n    return lock\n'}

